INSERT INTO `prod_v2_apis` (`apiId`, `title`, `script`, `active`) VALUES
(1, 'Platform Global', 'function setStartTime() {\r\n  window.startTime = new Date().getTime();\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getElapsedTime() {\r\n  return new Date().getTime() - window.startTime;\r\n}\r\n// -------------------------------------------------------- //\r\nasync function startTestActions() {\r\n  setStartTime();\r\n}\r\n// -------------------------------------------------------- //\r\nasync function passTestActions() {\r\n  if (typeof passTest === \'function\') {\r\n    await passTest();\r\n  }\r\n}\r\n// -------------------------------------------------------- //\r\nasync function failTestActions(err) {\r\n  console.log(\'failTestActions\', err);\r\n\r\n  if (typeof failTest === \'function\') {\r\n    await failTest(err);\r\n  }\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getMacAddress() {\r\n  const networkInterfaces = await window.networkInterfaces();\r\n  for (let key in networkInterfaces) {\r\n    const networkInterfaceType = networkInterfaces[key];\r\n    for (let i = 0; i < networkInterfaceType.length; i++) {\r\n      const networkInterface = networkInterfaceType[i];\r\n      if (networkInterface.mac && networkInterface.mac !== \'00:00:00:00:00:00\') {\r\n        return networkInterface.mac;\r\n      }\r\n    }\r\n  }\r\n  return \'unknown\';\r\n}\r\n// -------------------------------------------------------- //\r\nasync function promptUser(msg) {\r\n  window.Dialog.create({\r\n    title: \'Alert\',\r\n    message: msg\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function userDecisionPrompt(msg, failReason) {\r\n  return `\r\n    <div id=\"userDecisionPromptWrapper\">\r\n      <div class=\"dialog\">${msg}</div>\r\n      <div class=\"dialog-buttons\" style=\"padding-top:10px;\">\r\n        <button class=\"dialog-button\" style=\"padding:0 40px; margin-right: 40px;\" onclick=\"(async () => { \r\n          failTestActions(\'${failReason}\');\r\n          document.getElementById(\'userDecisionPromptWrapper\').remove();\r\n        })();\">No</button>\r\n        <button class=\"dialog-button\" style=\"padding:0 40px; \" onclick=\"(async () => { \r\n          passTestActions();\r\n          document.getElementById(\'userDecisionPromptWrapper\').remove();\r\n        })();\">Yes</button>\r\n      </div>\r\n    </div>\r\n  `;\r\n}\r\n// -------------------------------------------------------- //', 1),
(2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function resetScanner () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.api6100.resetScanner();\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 8000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Write firmware to scanner\r\n      await window.api6100.cortexUpdateFirmware(blob, md5);\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 6000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function setCalibrationTable (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull calibration from server\r\n      const calibrationData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([calibrationData.data], { type: \'application/*\' });\r\n\r\n      // Write calibration to scanner\r\n      await window.api6100.setCalibrationTable(blob.size, blob);\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function waitForDocumentLoad (isCheck, prompt) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let waitCountdown = 300; // In 10ths of a second\r\n\r\n      // Prompt user to load document\r\n      if (prompt) {\r\n        window.Loading.show({ message: prompt });\r\n      } else {\r\n        window.Loading.show({\r\n          message: \'Please load \' + (isCheck ? \'check face down with routing codeline on the right\' : \'card\') + \' into scanner.\'\r\n        });\r\n      }\r\n\r\n      await window.api6100.controlLEDBlink(0, 1);\r\n\r\n      const checkTimer = setInterval(async () => {\r\n        let status = await window.api6100.getStatus();\r\n        if((isCheck && status.ub_sens === 1) || (!isCheck && status.ub_sens === 4)) {\r\n          clearInterval(checkTimer);\r\n          await window.api6100.controlLEDBlink(0, 0);\r\n          window.Loading.hide();\r\n          resolve();\r\n        }\r\n\r\n        waitCountdown--;\r\n        if (waitCountdown === 0) {\r\n          clearInterval(checkTimer);\r\n          await window.api6100.controlLEDBlink(0, 0);\r\n          window.Loading.hide();\r\n          reject(\'Timeout waiting for document load\');\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      await window.api6100.controlLEDBlink(0, 0);\r\n      window.Loading.hide();\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function uploadFile (fileBlob, filename) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const formData = new FormData();\r\n      formData.append(\'file\', fileBlob, filename);\r\n      formData.append(\'filename\', filename);\r\n      formData.append(\'dataset\', \'scanner6100\');\r\n      formData.append(\'action\', \'uploadFile\');\r\n\r\n\r\n      const uploadResponse = await window.axios.post(window.selectedProduct.serverUrl, formData, {\r\n        headers: {\r\n          \'Content-Type\': \'multipart/form-data\'\r\n        }\r\n      });\r\n\r\n      if (uploadResponse.data.success) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to upload file\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction matchMICR (validValue, testValue) {\r\n  var splitTestValue = testValue.split(\"\");\r\n  var splitValidValue = validValue.split(\"\");\r\n  if(splitTestValue.length == splitValidValue.length){\r\n      var passTest = true;\r\n      for(var i =0; i < splitValidValue.length; i++){\r\n          if(splitValidValue[i]!=\"*\" && splitTestValue[i]!=splitValidValue[i]){\r\n              passTest = false;\r\n              break;\r\n          }\r\n      }\r\n      \r\n      return passTest;\r\n  } else {\r\n      return false;\r\n  }\r\n}\r\n// -------------------------------------------------------- //', 1),
(3, 'Empty', ' ', 1),
(4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1B, 0x47]);\r\n      const response = await window.genericUSB.getBytes(11);\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Enter Boot Mode\r\n      await window.genericUSB.sendBytes([0x1B, 0x7E, 0x7D]);\r\n      await window.genericUSB.disconnect();\r\n\r\n      // Wait for device to enter boot mode\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n\r\n      // Connect to device in boot mode\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes([0x1D, 0x0E]); //Boot Erase\r\n      await window.genericUSB.sendBytes([0x1D, 0x11, 0x00, 0x00, 0x00, 0x00]); //Enter Firmware download\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      if(response[0] === 0x06 || response[0] === 0x50) {\r\n        const fwVersion = await getFirmwareVersionUsb();\r\n        resolve(fwVersion);\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x1B, 0x41]); // Printer Status\r\n                    \r\n            let response = await window.genericRS232.getBytes(2);\r\n            if (response.length == 2) {\r\n              printerCom = validComPorts[i];\r\n              foundPrinter = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSecurityBytesSerial (requestType) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x1B, 0x58]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: requestType,\r\n            token: response\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSecurityBytesUsb (requestType) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1B, 0x58]);\r\n      const response = await window.genericUSB.getBytes(2);\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: requestType,\r\n            token: response\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printStringViaSerial (textLine) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let byteArray = [];\r\n\r\n      for(let i = 0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      \r\n      await window.genericRS232.sendBytes(byteArray)\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printStringViaUsb (textLine) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let byteArray = [];\r\n\r\n      for(let i = 0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      \r\n      await window.genericUSB.sendBytes(byteArray)\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x1B, 0x47]);\r\n      const response = await window.genericRS232.getBytes(11);\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFormattedConfigSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let config = {};\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x59]);\r\n      const response = await window.genericRS232.getBytes(128);\r\n      \r\n      config.fct = response[0];\r\n      config.acCoupledBarcodeEnabled = response[1];\r\n      config.bursterSensorCfg = response[2];\r\n      config.printLineOffset = response[4];\r\n      config.burstSearchMaxDistance = response[8] + (response[9] << 8);\r\n      config.burstMarkToPerforation = response[10] + (response[11] << 8);\r\n      config.wideVaultEnabled = response[12];\r\n      config.designLevel = response[13];\r\n      config.flashWriteProtect = response[127];\r\n\r\n      resolve(config);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFormattedConfigUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let config = {};\r\n\r\n      await window.genericUSB.sendBytes([0x1B, 0x59]);\r\n      const response = await window.genericUSB.getBytes(128);\r\n      \r\n      config.fct = response[0];\r\n      config.acCoupledBarcodeEnabled = response[1];\r\n      config.bursterSensorCfg = response[2];\r\n      config.printLineOffset = response[4];\r\n      config.burstSearchMaxDistance = response[8] + (response[9] << 8);\r\n      config.burstMarkToPerforation = response[10] + (response[11] << 8);\r\n      config.wideVaultEnabled = response[12];\r\n      config.designLevel = response[13];\r\n      config.flashWriteProtect = response[127];\r\n\r\n      resolve(config);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction translateTallies (dataArray, startIndex) {\r\n  let response = \'\';\r\n  for(let i = startIndex; i < startIndex + 10; i++) {\r\n    response += String.fromCharCode(dataArray[i]);\r\n  }\r\n  return response;\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getTalliesSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let tallies = {};\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x74, 0x00]);\r\n      const response = await window.genericRS232.getBytes(121);\r\n      \r\n      tallies.dotCount = translateTallies(response, 0);\r\n      tallies.formCount = translateTallies(response, 11);\r\n      tallies.voidCount = translateTallies(response, 22);\r\n      tallies.burstCount = translateTallies(response, 33);\r\n      tallies.vaultInstalledCount = translateTallies(response, 44);\r\n      tallies.timeOn = translateTallies(response, 55);\r\n      tallies.resetsCount = translateTallies(response, 66);\r\n      tallies.firmwareUpdatesCount = translateTallies(response, 77);\r\n      tallies.extSheetsLoadedCount = translateTallies(response, 88);\r\n      tallies.ribbonsCount = translateTallies(response, 99);\r\n      tallies.ribbonDotCount = translateTallies(response, 110);\r\n\r\n      resolve(tallies);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getTalliesUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let tallies = {};\r\n\r\n      await window.genericUSB.sendBytes([0x1B, 0x74, 0x00]);\r\n      const response = await window.genericUSB.getBytes(121);\r\n      \r\n      tallies.dotCount = translateTallies(response, 0);\r\n      tallies.formCount = translateTallies(response, 11);\r\n      tallies.voidCount = translateTallies(response, 22);\r\n      tallies.burstCount = translateTallies(response, 33);\r\n      tallies.vaultInstalledCount = translateTallies(response, 44);\r\n      tallies.timeOn = translateTallies(response, 55);\r\n      tallies.resetsCount = translateTallies(response, 66);\r\n      tallies.firmwareUpdatesCount = translateTallies(response, 77);\r\n      tallies.extSheetsLoadedCount = translateTallies(response, 88);\r\n      tallies.ribbonsCount = translateTallies(response, 99);\r\n      tallies.ribbonDotCount = translateTallies(response, 110);\r\n\r\n      resolve(tallies);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getExtendedStatusUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let status = {\r\n        carriageHomeSensorInError: false,\r\n        bursterHomeSensorInError: false,\r\n        paperOut: false,\r\n        paperLoadingError: false,\r\n        failedTopOfFormMark: false,\r\n        burstError: false,\r\n        checksumError: false,\r\n        feederNotPresent: false,\r\n        burstSensorDefective: false,\r\n        printerWasReset: false,\r\n        printerWasResetWithFormLoaded: false,\r\n        ejectFailed: false\r\n      }\r\n\r\n      await window.genericUSB.sendBytes([0x1B, 0x2B]);\r\n      const response = await window.genericUSB.getBytes(6);\r\n\r\n      if(response[0] & 0b1) {\r\n        status.carriageHomeSensorInError = true;\r\n      }\r\n      if(response[0] & 0b10) {\r\n        status.bursterHomeSensorInError = true;\r\n      }\r\n      if(response[0] & 0b100) {\r\n        status.paperOut = true;\r\n      }\r\n      if(response[0] & 0b1000) {\r\n        status.paperLoadingError = true;\r\n      }\r\n      if(response[0] & 0b10000) {\r\n        status.failedTopOfFormMark = true;\r\n      }\r\n      if(response[0] & 0b100000) {\r\n        status.burstError = true;\r\n      }\r\n      if(response[0] & 0b1000000) {\r\n        status.checksumError = true;\r\n      }\r\n      if(response[0] & 0b10000000) {\r\n        status.feederNotPresent = true;\r\n      }\r\n\r\n      if(response[1] & 0b1) {\r\n        status.burstSensorDefective = true;\r\n      }\r\n      if(response[1] & 0b10) {\r\n        status.printerWasReset = true;\r\n      }\r\n      if(response[1] & 0b100) {\r\n        status.printerWasResetWithFormLoaded = true;\r\n      }\r\n      if(response[1] & 0b1000) {\r\n        status.ejectFailed = true;\r\n      }\r\n\r\n      resolve(status);\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getExtendedStatusSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let status = {\r\n        carriageHomeSensorInError: false,\r\n        bursterHomeSensorInError: false,\r\n        paperOut: false,\r\n        paperLoadingError: false,\r\n        failedTopOfFormMark: false,\r\n        burstError: false,\r\n        checksumError: false,\r\n        feederNotPresent: false,\r\n        burstSensorDefective: false,\r\n        printerWasReset: false,\r\n        printerWasResetWithFormLoaded: false,\r\n        ejectFailed: false\r\n      }\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x2B]);\r\n      const response = await window.genericRS232.getBytes(6);\r\n\r\n      if(response[0] & 0b1) {\r\n        status.carriageHomeSensorInError = true;\r\n      }\r\n      if(response[0] & 0b10) {\r\n        status.bursterHomeSensorInError = true;\r\n      }\r\n      if(response[0] & 0b100) {\r\n        status.paperOut = true;\r\n      }\r\n      if(response[0] & 0b1000) {\r\n        status.paperLoadingError = true;\r\n      }\r\n      if(response[0] & 0b10000) {\r\n        status.failedTopOfFormMark = true;\r\n      }\r\n      if(response[0] & 0b100000) {\r\n        status.burstError = true;\r\n      }\r\n      if(response[0] & 0b1000000) {\r\n        status.checksumError = true;\r\n      }\r\n      if(response[0] & 0b10000000) {\r\n        status.feederNotPresent = true;\r\n      }\r\n\r\n      if(response[1] & 0b1) {\r\n        status.burstSensorDefective = true;\r\n      }\r\n      if(response[1] & 0b10) {\r\n        status.printerWasReset = true;\r\n      }\r\n      if(response[1] & 0b100) {\r\n        status.printerWasResetWithFormLoaded = true;\r\n      }\r\n      if(response[1] & 0b1000) {\r\n        status.ejectFailed = true;\r\n      }\r\n\r\n      resolve(status);\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function waitForDocumentLoad (isCheck, prompt) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let waitCountdown = 300; // In 10ths of a second\r\n\r\n      // Prompt user to load document\r\n      if (prompt) {\r\n        window.Loading.show({ message: prompt });\r\n      } else {\r\n        window.Loading.show({\r\n          message: \'Please load \' + (isCheck ? \'checklist\' : \'card\') + \' into scanner.\'\r\n        });\r\n      }\r\n\r\n      await window.api6100.controlLEDBlink(0, 1);\r\n\r\n      const checkTimer = setInterval(async () => {\r\n        let status = await window.api6100.getStatus();\r\n        if((isCheck && status.ub_sens === 1) || (!isCheck && status.ub_sens === 4)) {\r\n          clearInterval(checkTimer);\r\n          await window.api6100.controlLEDBlink(0, 0);\r\n          window.Loading.hide();\r\n          resolve();\r\n        }\r\n\r\n        waitCountdown--;\r\n        if (waitCountdown === 0) {\r\n          clearInterval(checkTimer);\r\n          await window.api6100.controlLEDBlink(0, 0);\r\n          window.Loading.hide();\r\n          reject(\'Timeout waiting for document load\');\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      await window.api6100.controlLEDBlink(0, 0);\r\n      window.Loading.hide();\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function uploadFile (fileBlob, filename) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const formData = new FormData();\r\n      formData.append(\'file\', fileBlob, filename);\r\n      formData.append(\'filename\', filename);\r\n      formData.append(\'dataset\', \'printer7680\');\r\n      formData.append(\'action\', \'uploadFile\');\r\n\r\n\r\n      const uploadResponse = await window.axios.post(window.selectedProduct.serverUrl, formData, {\r\n        headers: {\r\n          \'Content-Type\': \'multipart/form-data\'\r\n        }\r\n      });\r\n\r\n      if (uploadResponse.data.success) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to upload file\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(5, 'Print Labels', 'async function deleteOldLabel() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      const filename = \'label.pdf\';\r\n      if (window.fs.existsSync(\'./\' + filename)) {\r\n        window.fs.unlinkSync(\'./\' + filename, (err) => {\r\n          if (err) {\r\n            console.error(err);\r\n            reject(err);\r\n          } else {\r\n            resolve();\r\n          }\r\n        });\r\n      } else {\r\n        resolve();\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function generate4x6Landscape() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.pdf.create({\r\n        margin: 18,\r\n        layout: \'landscape\',\r\n        size: [288, 432]\r\n      })\r\n      await window.pdf.pipe(\'label.pdf\');\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function generate4x6Portrait() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.pdf.create({\r\n        margin: 18,\r\n        size: [288, 432]\r\n      })\r\n      await window.pdf.pipe(\'label.pdf\');\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function generate4x5Landscape() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.pdf.create({\r\n        margin: 18,\r\n        layout: \'landscape\',\r\n        size: [288, 360]\r\n      })\r\n      await window.pdf.pipe(\'label.pdf\');\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function generate4x5Portrait() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.pdf.create({\r\n        margin: 18,\r\n        size: [288, 360]\r\n      })\r\n      await window.pdf.pipe(\'label.pdf\');\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function performPrint() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      setTimeout(() => {\r\n        window.exec(\r\n          \'lp -o page-ranges=1 -o orientation-requested=4 -o resolution=203dpi label.pdf\', (e) => {\r\n            if (e) {\r\n              reject(e);\r\n            }\r\n\r\n            resolve();\r\n          }\r\n        );\r\n      }, 500);\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function performPrintWithQty(quantity) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      setTimeout(() => {\r\n        window.exec(\r\n          \'lp -n \' + quantity + \' -o page-ranges=1 -o orientation-requested=4 -o resolution=203dpi label.pdf\', (e) => {\r\n            if (e) {\r\n              reject(e);\r\n            }\r\n\r\n            resolve();\r\n          }\r\n        );\r\n      }, 500);\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1),
(6, 'VCSEL Fixture', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I2C_H_400KHZ, 2 analog inputs\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x70, 0x0F]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isBoardConnected () {\r\n  // Verify a response happens when requesting digital pot value as verification that board is connected\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let boardConnected = false;\r\n\r\n      const collectorValue = await getCollectorPotNV();\r\n      if (collectorValue != 1023) {\r\n        boardConnected = true;\r\n      }\r\n      \r\n      resolve({\r\n        boardConnected: boardConnected,\r\n        collectorValue: collectorValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorPotNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5F, 0x2C, 0x02]); // 0x5F = read at collector address, 0x2C = read NV Wiper 0, 0x02 = Bytes to read\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const calcVal = ((response[0] & 0x03) << 8) + response[1];\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getTransmitterPotNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5D, 0x2C, 0x02]); // 0x5D = read at transmitter address, 0x2C = read NV Wiper 0, 0x02 = Bytes to read\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const calcVal = ((response[0] & 0x03) << 8) + response[1];\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction setCollectorPot (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x00, 0x01, valueToSet]); // 0x5E = write at collector address, 0x00 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });   \r\n}\r\n// -------------------------------------------------------- //\r\nfunction setTransmitterPot (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5C, 0x00, 0x01, valueToSet]); // 0x5C = write at transmitter address, 0x00 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });  \r\n}\r\n// -------------------------------------------------------- //\r\nfunction setCollectorPotNV (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x20, 0x01, valueToSet]); // 0x5E = write at collector address, 0x20 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });   \r\n}\r\n// -------------------------------------------------------- //\r\nfunction setTransmitterPotNV (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5C, 0x20, 0x01, valueToSet]); // 0x5C = write at transmitter address, 0x20 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });  \r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const highByte = await getRegisterValue(6);\r\n      const middleByte = await getRegisterValue(7);\r\n      const lowByte = await getRegisterValue(8);\r\n      resolve(((highByte & 0xFF) << 16) + ((middleByte & 0xFF) << 8) + (lowByte & 0xFF));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction setSerialNumber (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const highByte = (valueToSet >> 16) & 0xFF;\r\n      const middleByte = (valueToSet >> 8) & 0xFF;\r\n      const lowByte = valueToSet & 0xFF;\r\n\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x60, 0x01, highByte]); // 0x5E = write at collector address, 0x06 = write Data Eprom 0, 0x01 = Bytes to write\r\n// wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x70, 0x01, middleByte]); // 0x5E = write at collector address, 0x06 = write Data Eprom 0, 0x01 = Bytes to write\r\n\r\n// wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x80, 0x01, lowByte]); // 0x5E = write at collector address, 0x06 = write Data Eprom 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve(); \r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getRegisterValue (registerToRead) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x57, 0x01, 0x31, 0x5E, 0x0C | (registerToRead << 4), 0x02, 0x30, 0x5F, 0x20, 0x04, 0x20, 0x03]);\r\n      const response = await window.genericRS232.getBytes(4);\r\n      resolve(((response[2] & 0x01) << 8) + response[3]);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCurrentCollectorValue (registerToRead) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      resolve(await getRegisterValue(0));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCurrentTransmitterValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x57, 0x01, 0x31, 0x5C, 0x0C, 0x02, 0x30, 0x5D, 0x20, 0x04, 0x20, 0x03]);\r\n      const response = await window.genericRS232.getBytes(4);\r\n      resolve(((response[2] & 0x01) << 8) + response[3]);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorVoltage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x02, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      resolve((reading * 3.3) / 1023);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawGauge (emitter, collector, voltage) {\r\n  return `\r\n    <div style=\"text-align:center; margin-top:50px;\">1.65v</div>\r\n    <div style=\"border-right:1px solid #aaa; height:10px; width:50%;\"></div>\r\n    <div style=\"border:1px solid #aaa; height:30px;\">\r\n        <div style=\"background-color:#789; text-align:center; color:#fff; font-weight:bold; line-height: 30px; height:30px; width:${(voltage * 100) / 3.3}%;\">${voltage.toFixed(2)}v</div>\r\n    </div>\r\n    <div style=\"float:left; width:48%;\">\r\n        <div style=\"text-align:center;\">Emitter</div>\r\n        <div style=\"border:1px solid #aaa; height:20px;\">\r\n            <div style=\"background-color:#999; text-align:center; color:#fff; font-weight:bold; line-height: 20px; height:20px; width:${(emitter * 100) / 128}%;\">${emitter}</div>\r\n        </div>\r\n    </div>\r\n    <div style=\"float:right; width:48%;\">\r\n        <div style=\"text-align:center;\">Collector</div>\r\n        <div style=\"border:1px solid #aaa; height:20px;\">\r\n            <div style=\"background-color:#999; text-align:center; color:#fff; font-weight:bold; line-height: 20px; height:20px; width:${(collector * 100) / 128}%;\">${collector}</div>\r\n        </div>\r\n    </div>\r\n    <div style=\"clear:both;\"></div>\r\n  `;\r\n}\r\n// -------------------------------------------------------- //\r\nfunction waitForReadingToStabilize (countOfMatchesRequired) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let lastValue = 0;\r\n      let countOfMatches = 0;\r\n      while (countOfMatches < countOfMatchesRequired) {\r\n        const currentValue = await getCollectorVoltage();\r\n        if (currentValue.toFixed(3) === lastValue) {\r\n          countOfMatches++;\r\n        } else {\r\n          countOfMatches = 0;\r\n        }\r\n        lastValue = currentValue.toFixed(3);\r\n\r\n        // wait for 50ms\r\n        await new Promise(resolve => setTimeout(resolve, 50));\r\n      }\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n', 1),
(7, 'Burster Home Fixture', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I/O Mode, 3 analog inputs (IO2, IO3, IO4), 1 digital input (IO1)\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x00, 0xFE]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction checkForVoltageIssues () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Check that fixture is properly communicating\r\n      await window.genericRS232.sendBytes([0x65, 0x04, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      if (calcVal != 5) {\r\n        reject(\'Fixture voltage reading is not correct (5V expected, \' + calcVal + \'V received)\')\r\n      } else {\r\n        resolve(calcVal);\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getLedValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x03, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x02, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isSensorConnected () {\r\n  // Look for LED reading to drop to 1.2-1.6v as verification that sensor is connected\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let sensorConnected = false;\r\n\r\n      const ledValue = await getLedValue();\r\n      if (ledValue >= 1.2 && ledValue <= 1.6) {\r\n        sensorConnected = true;\r\n      }\r\n      \r\n      resolve({\r\n        sensorConnected: sensorConnected,\r\n        ledValue: ledValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isSensorBlocked () {\r\n  // Look for collector reading to be greater than 4.2v as verification that sensor is blocked\r\n  // If reading is less than 0.5v, then sensor is not blocked\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let sensorBlocked = false;\r\n      let sensorNotBlocked = false;\r\n\r\n      const collectorValue = await getCollectorValue();\r\n      if (collectorValue > 4.2) {\r\n        sensorBlocked = true;\r\n      } else if (collectorValue < 0.5) {\r\n        sensorNotBlocked = true;\r\n      }\r\n      \r\n      resolve({\r\n        sensorBlocked: sensorBlocked,\r\n        sensorNotBlocked: sensorNotBlocked,\r\n        collectorValue: collectorValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis` (`apiId`, `title`, `script`, `active`) VALUES
(8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        console.log(response);\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaSerial (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericRS232.sendBytes(alignmentArray);\r\n      await window.genericRS232.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configureCarriageColumnAlignmentUsb (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA7, alignmentValue, alignmentValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function rebootAclUsb (reconnect = true) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x10, 0x40]);\r\n      await disconnectFromUsb();\r\n\r\n      // Wait 8 seconds for device to reboot\r\n      await new Promise(resolve => setTimeout(resolve, 8000));\r\n      if (reconnect) {\r\n        await connectToUsb();\r\n      }\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToSubMode3Usb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x04]);\r\n      await rebootAclUsb(false);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToA470Usb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x01]);\r\n      await rebootAclUsb(false);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470ClampDefaultSerial (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x08, 0x03, 0xA0, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470PitchDefaultSerial (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x08, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470ClampDefault (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x08, 0x03, 0xA0, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470PitchDefault (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x08, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}', 1);
