(27, '2022-10-03 17:05:45', 1, 'Platform Global', 'function setStartTime() {\r\n  window.startTime = new Date().getTime();\r\n}\r\n\r\nfunction getElapsedTime() {\r\n  return new Date().getTime() - window.startTime;\r\n}\r\n\r\nasync function startTestActions() {\r\n  setStartTime();\r\n}\r\n\r\nasync function passTestActions() {\r\n  if (typeof passTest === \'function\') {\r\n    await passTest();\r\n  }\r\n}\r\n\r\nasync function failTestActions(err) {\r\n  console.log(\'failTestActions\', err);\r\n\r\n  if (typeof failTest === \'function\') {\r\n    await failTest(err);\r\n  }\r\n}\r\n\r\nasync function getMacAddress() {\r\n  const networkInterfaces = await window.networkInterfaces();\r\n  for (let key in networkInterfaces) {\r\n    const networkInterfaceType = networkInterfaces[key];\r\n    for (let i = 0; i < networkInterfaceType.length; i++) {\r\n      const networkInterface = networkInterfaceType[i];\r\n      if (networkInterface.mac && networkInterface.mac !== \'00:00:00:00:00:00\') {\r\n        return networkInterface.mac;\r\n      }\r\n    }\r\n  }\r\n  return \'unknown\';\r\n}\r\n\r\nasync function promptUser(msg) {\r\n  window.Dialog.create({\r\n    title: \'Alert\',\r\n    message: msg\r\n  });\r\n}', 1),
(28, '2022-10-04 17:31:46', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const version = await this.api6100.xfn(71);\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}', 1),
