(31, '2022-10-04 19:04:46', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (filename, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      console.log(filename, md5);\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}', 1),
(32, '2022-10-04 19:06:46', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      console.log(downloadPath, md5);\r\n      console.log(window.selectedProduct);\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}', 1),
(33, '2022-10-04 19:14:37', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      console.log(downloadPath, md5);\r\n      console.log(window.selectedProduct);\r\n\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\',\r\n        onDownloadProgress: (progressEvent) => {\r\n          const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);\r\n          console.log(percentCompleted);\r\n        }\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      resolve(blob);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}', 1),
(34, '2022-10-04 19:18:38', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\',\r\n        onDownloadProgress: (progressEvent) => {\r\n          const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);\r\n          console.log(percentCompleted);\r\n        }\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Write firmware to scanner\r\n      await window.api6100.cortexUpdateFirmware(blob, md5);\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 6000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}', 1),
