(38, '2022-10-04 20:20:36', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Write firmware to scanner\r\n      await window.api6100.cortexUpdateFirmware(blob, md5);\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 6000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function setCalibrationTable (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull calibration from server\r\n      const calibrationData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([calibrationData.data], { type: \'application/*\' });\r\n\r\n      // Write calibration to scanner\r\n      await window.api6100.setCalibrationTable(blob.size, blob);\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function waitForDocumentLoad (isCheck) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let waitCountdown = 300; // In 10ths of a second\r\n\r\n      const checkTimer = setInterval(async () => {\r\n        let status = await window.api6100.getStatus();\r\n        console.log(status);\r\n\r\n        waitCountdown--;\r\n        if (waitCountdown === 0) {\r\n          clearInterval(checkTimer);\r\n          reject(\'Timeout waiting for document load\');\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(39, '2022-10-04 20:28:28', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Write firmware to scanner\r\n      await window.api6100.cortexUpdateFirmware(blob, md5);\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 6000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function setCalibrationTable (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull calibration from server\r\n      const calibrationData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([calibrationData.data], { type: \'application/*\' });\r\n\r\n      // Write calibration to scanner\r\n      await window.api6100.setCalibrationTable(blob.size, blob);\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function waitForDocumentLoad (isCheck) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let waitCountdown = 300; // In 10ths of a second\r\n\r\n      // Prompt user to load document\r\n      window.Loading.show({\r\n        message: \'Please load \' + (isCheck ? \'check\' : \'card\') + \' into scanner.\'\r\n      });\r\n\r\n      const checkTimer = setInterval(async () => {\r\n        let status = await window.api6100.getStatus();\r\n        if((isCheck && status.ub_sens === 1)) {\r\n          clearInterval(checkTimer);\r\n          window.Loading.hide();\r\n          resolve();\r\n        }\r\n\r\n        waitCountdown--;\r\n        if (waitCountdown === 0) {\r\n          clearInterval(checkTimer);\r\n          window.Loading.hide();\r\n          reject(\'Timeout waiting for document load\');\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(40, '2022-10-04 20:29:24', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Write firmware to scanner\r\n      await window.api6100.cortexUpdateFirmware(blob, md5);\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 6000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function setCalibrationTable (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull calibration from server\r\n      const calibrationData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([calibrationData.data], { type: \'application/*\' });\r\n\r\n      // Write calibration to scanner\r\n      await window.api6100.setCalibrationTable(blob.size, blob);\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function waitForDocumentLoad (isCheck) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let waitCountdown = 300; // In 10ths of a second\r\n\r\n      // Prompt user to load document\r\n      window.Loading.show({\r\n        message: \'Please load \' + (isCheck ? \'check\' : \'card\') + \' into scanner.\'\r\n      });\r\n\r\n      const checkTimer = setInterval(async () => {\r\n        let status = await window.api6100.getStatus();\r\n        console.log(status.ub_sens);\r\n        if((isCheck && status.ub_sens === 1)) {\r\n          clearInterval(checkTimer);\r\n          window.Loading.hide();\r\n          resolve();\r\n        }\r\n\r\n        waitCountdown--;\r\n        if (waitCountdown === 0) {\r\n          clearInterval(checkTimer);\r\n          window.Loading.hide();\r\n          reject(\'Timeout waiting for document load\');\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(41, '2022-10-04 20:32:59', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Write firmware to scanner\r\n      await window.api6100.cortexUpdateFirmware(blob, md5);\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 6000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function setCalibrationTable (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull calibration from server\r\n      const calibrationData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([calibrationData.data], { type: \'application/*\' });\r\n\r\n      // Write calibration to scanner\r\n      await window.api6100.setCalibrationTable(blob.size, blob);\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function waitForDocumentLoad (isCheck) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let waitCountdown = 300; // In 10ths of a second\r\n\r\n      // Prompt user to load document\r\n      window.Loading.show({\r\n        message: \'Please load \' + (isCheck ? \'check\' : \'card\') + \' into scanner.\'\r\n      });\r\n\r\n      await window.api6100.controlLEDBlink(0, 1);\r\n\r\n      const checkTimer = setInterval(async () => {\r\n        let status = await window.api6100.getStatus();\r\n        if((isCheck && status.ub_sens === 1) || (!isCheck && status.ub_sens === 4)) {\r\n          clearInterval(checkTimer);\r\n          await window.api6100.controlLEDBlink(0, 0);\r\n          window.Loading.hide();\r\n          resolve();\r\n        }\r\n\r\n        waitCountdown--;\r\n        if (waitCountdown === 0) {\r\n          clearInterval(checkTimer);\r\n          await window.api6100.controlLEDBlink(0, 0);\r\n          window.Loading.hide();\r\n          reject(\'Timeout waiting for document load\');\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      await window.api6100.controlLEDBlink(0, 0);\r\n      window.Loading.hide();\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(42, '2022-10-04 21:27:36', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Write firmware to scanner\r\n      await window.api6100.cortexUpdateFirmware(blob, md5);\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 6000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function setCalibrationTable (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull calibration from server\r\n      const calibrationData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([calibrationData.data], { type: \'application/*\' });\r\n\r\n      // Write calibration to scanner\r\n      await window.api6100.setCalibrationTable(blob.size, blob);\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function waitForDocumentLoad (isCheck) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let waitCountdown = 300; // In 10ths of a second\r\n\r\n      // Prompt user to load document\r\n      window.Loading.show({\r\n        message: \'Please load \' + (isCheck ? \'check face down with routing codeline on the right\' : \'card\') + \' into scanner.\'\r\n      });\r\n\r\n      await window.api6100.controlLEDBlink(0, 1);\r\n\r\n      const checkTimer = setInterval(async () => {\r\n        let status = await window.api6100.getStatus();\r\n        if((isCheck && status.ub_sens === 1) || (!isCheck && status.ub_sens === 4)) {\r\n          clearInterval(checkTimer);\r\n          await window.api6100.controlLEDBlink(0, 0);\r\n          window.Loading.hide();\r\n          resolve();\r\n        }\r\n\r\n        waitCountdown--;\r\n        if (waitCountdown === 0) {\r\n          clearInterval(checkTimer);\r\n          await window.api6100.controlLEDBlink(0, 0);\r\n          window.Loading.hide();\r\n          reject(\'Timeout waiting for document load\');\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      await window.api6100.controlLEDBlink(0, 0);\r\n      window.Loading.hide();\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(43, '2022-10-04 21:47:50', 1, 'Platform Global', 'function setStartTime() {\r\n  window.startTime = new Date().getTime();\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getElapsedTime() {\r\n  return new Date().getTime() - window.startTime;\r\n}\r\n// -------------------------------------------------------- //\r\nasync function startTestActions() {\r\n  setStartTime();\r\n}\r\n// -------------------------------------------------------- //\r\nasync function passTestActions() {\r\n  if (typeof passTest === \'function\') {\r\n    await passTest();\r\n  }\r\n}\r\n// -------------------------------------------------------- //\r\nasync function failTestActions(err) {\r\n  console.log(\'failTestActions\', err);\r\n\r\n  if (typeof failTest === \'function\') {\r\n    await failTest(err);\r\n  }\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getMacAddress() {\r\n  const networkInterfaces = await window.networkInterfaces();\r\n  for (let key in networkInterfaces) {\r\n    const networkInterfaceType = networkInterfaces[key];\r\n    for (let i = 0; i < networkInterfaceType.length; i++) {\r\n      const networkInterface = networkInterfaceType[i];\r\n      if (networkInterface.mac && networkInterface.mac !== \'00:00:00:00:00:00\') {\r\n        return networkInterface.mac;\r\n      }\r\n    }\r\n  }\r\n  return \'unknown\';\r\n}\r\n// -------------------------------------------------------- //\r\nasync function promptUser(msg) {\r\n  window.Dialog.create({\r\n    title: \'Alert\',\r\n    message: msg\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function userDecisionPrompt(msg, passAction, failAction) {\r\n  return `\r\n    <div class=\"dialog\">${msg}</div>\r\n    <div class=\"dialog-buttons\">\r\n      <button class=\"dialog-button\" onclick=\"failAction()\">No</button>\r\n      <button class=\"dialog-button\" onclick=\"passAction()\">Yes</button>\r\n    </div>\r\n  `;\r\n}\r\n// -------------------------------------------------------- //', 1),
(44, '2022-10-04 21:55:08', 1, 'Platform Global', 'function setStartTime() {\r\n  window.startTime = new Date().getTime();\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getElapsedTime() {\r\n  return new Date().getTime() - window.startTime;\r\n}\r\n// -------------------------------------------------------- //\r\nasync function startTestActions() {\r\n  setStartTime();\r\n}\r\n// -------------------------------------------------------- //\r\nasync function passTestActions() {\r\n  if (typeof passTest === \'function\') {\r\n    await passTest();\r\n  }\r\n}\r\n// -------------------------------------------------------- //\r\nasync function failTestActions(err) {\r\n  console.log(\'failTestActions\', err);\r\n\r\n  if (typeof failTest === \'function\') {\r\n    await failTest(err);\r\n  }\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getMacAddress() {\r\n  const networkInterfaces = await window.networkInterfaces();\r\n  for (let key in networkInterfaces) {\r\n    const networkInterfaceType = networkInterfaces[key];\r\n    for (let i = 0; i < networkInterfaceType.length; i++) {\r\n      const networkInterface = networkInterfaceType[i];\r\n      if (networkInterface.mac && networkInterface.mac !== \'00:00:00:00:00:00\') {\r\n        return networkInterface.mac;\r\n      }\r\n    }\r\n  }\r\n  return \'unknown\';\r\n}\r\n// -------------------------------------------------------- //\r\nasync function promptUser(msg) {\r\n  window.Dialog.create({\r\n    title: \'Alert\',\r\n    message: msg\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function userDecisionPrompt(msg, passAction, failAction, failReason) {\r\n  return `\r\n    <div class=\"dialog\">${msg}</div>\r\n    <div class=\"dialog-buttons\">\r\n      <button class=\"dialog-button\" onclick=\"${failAction}(\'${failReason}\')\">No</button>\r\n      <button class=\"dialog-button\" onclick=\"${passAction}()\">Yes</button>\r\n    </div>\r\n  `;\r\n}\r\n// -------------------------------------------------------- //', 1);
