(51, '2022-10-11 22:29:30', 2, '6100 Scanner', 'async function getFirmwareVersion () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      const scannerResponse = await this.api6100.xfn(71);\r\n      const version = scannerResponse.xfn;\r\n      const firmwareArray = version.split(\',\');\r\n      const firmwareString = firmwareArray[1].replace(\"Main: \", \"\");\r\n      const firmwareDots = firmwareString.split(\'.\');\r\n      const finalFirmware = (firmwareDots[0] + \'.\' + firmwareDots[1] + \'.\' + firmwareDots[2] + \'.\' + firmwareDots[3]).trim();\r\n\r\n      resolve(finalFirmware);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath, md5) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Write firmware to scanner\r\n      await window.api6100.cortexUpdateFirmware(blob, md5);\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 6000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function setCalibrationTable (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull calibration from server\r\n      const calibrationData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([calibrationData.data], { type: \'application/*\' });\r\n\r\n      // Write calibration to scanner\r\n      await window.api6100.setCalibrationTable(blob.size, blob);\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function waitForDocumentLoad (isCheck, prompt) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let waitCountdown = 300; // In 10ths of a second\r\n\r\n      // Prompt user to load document\r\n      if (prompt) {\r\n        window.Loading.show({ message: prompt });\r\n      } else {\r\n        window.Loading.show({\r\n          message: \'Please load \' + (isCheck ? \'check face down with routing codeline on the right\' : \'card\') + \' into scanner.\'\r\n        });\r\n      }\r\n\r\n      await window.api6100.controlLEDBlink(0, 1);\r\n\r\n      const checkTimer = setInterval(async () => {\r\n        let status = await window.api6100.getStatus();\r\n        if((isCheck && status.ub_sens === 1) || (!isCheck && status.ub_sens === 4)) {\r\n          clearInterval(checkTimer);\r\n          await window.api6100.controlLEDBlink(0, 0);\r\n          window.Loading.hide();\r\n          resolve();\r\n        }\r\n\r\n        waitCountdown--;\r\n        if (waitCountdown === 0) {\r\n          clearInterval(checkTimer);\r\n          await window.api6100.controlLEDBlink(0, 0);\r\n          window.Loading.hide();\r\n          reject(\'Timeout waiting for document load\');\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      await window.api6100.controlLEDBlink(0, 0);\r\n      window.Loading.hide();\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
