esolve, reject) => {\r\n    try {\r\n      await window.pdf.create({\r\n        margin: 18,\r\n        size: [288, 360]\r\n      })\r\n      await window.pdf.pipe(\'label.pdf\');\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function performPrint() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.exec(\r\n        \'lp -o page-ranges=1 -o orientation-requested=4 -o resolution=203dpi label.pdf\', (e) => {\r\n          if (e) {\r\n            reject(e);\r\n          }\r\n\r\n          resolve();\r\n        }\r\n      );\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1),
(71, '2022-10-17 15:14:27', 4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(72, '2022-10-17 15:18:15', 4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(73, '2022-10-17 15:30:33', 4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 4000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(74, '2022-10-17 15:34:52', 4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Enter Boot Mode\r\n      await window.genericUSB.sendBytes([0x1B, 0x7E, 0x7D]);\r\n      await window.genericUSB.disconnect();\r\n\r\n      // Wait for device to enter boot mode\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n\r\n      // Connect to device in boot mode\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 4000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(75, '2022-10-17 15:38:35', 4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Enter Boot Mode\r\n      await window.genericUSB.sendBytes([0x1B, 0x7E, 0x7D]);\r\n      await window.genericUSB.disconnect();\r\n\r\n      // Wait for device to enter boot mode\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n\r\n      // Connect to device in boot mode\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = Buffer.from(contentBuffer);\r\n      console.log(\'pre send fw dl cmd\');\r\n      await window.genericUSB.sendBytes([0x1D, 0x0E]); //Boot Erase\r\n      await window.genericUSB.sendBytes([0x1D, 0x11, 0x00, 0x00, 0x00, 0x00]); //Enter Firmware download\r\n      console.log(\'pre send fw bytes\');\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      console.log(\'pre get resp\');\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n\r\n      if(response[0] === 0x06 || response[0] === 0x50) {\r\n        console.log(\'success\', response[0]);\r\n      }\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 4000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(76, '2022-10-17 15:41:02', 4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n//---------------------------------------------------------------------------------------------------------------\r\nasync function updateFirmware (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Enter Boot Mode\r\n      await window.genericUSB.sendBytes([0x1B, 0x7E, 0x7D]);\r\n      await window.genericUSB.disconnect();\r\n\r\n      // Wait for device to enter boot mode\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n\r\n      // Connect to device in boot mode\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = Buffer.from(contentBuffer);\r\n      console.log(\'pre send fw dl cmd\');\r\n      await window.genericUSB.sendBytes([0x1D, 0x0E]); //Boot Erase\r\n      await window.genericUSB.sendBytes([0x1D, 0x11, 0x00, 0x00, 0x00, 0x00]); //Enter Firmware download\r\n      console.log(\'pre send fw bytes\');\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      console.log(\'pre get resp\');\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n\r\n      if(response[0] === 0x06 || response[0] === 0x50) {\r\n        console.log(\'success\', response[0]);\r\n      }\r\n\r\n      setTimeout(async () => {\r\n        resolve();\r\n      }, 4000);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
