verResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printStringViaSerial (textLine) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let byteArray = [];\r\n\r\n      for(let i = 0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      \r\n      await window.genericRS232.sendBytes(byteArray)\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1),
