(119, '2022-10-20 10:29:58', 7, 'Burster Home API', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response.length == 3 && response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      let response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1),
(120, '2022-10-20 10:34:35', 7, 'Burster Home API', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      let response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I/O Mode, 3 analog inputs (IO2, IO3, IO4), 1 digital input (IO1)\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x00, 0xFE]);\r\n      let response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1),
(121, '2022-10-20 10:55:31', 7, 'Burster Home API', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      let response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I/O Mode, 3 analog inputs (IO2, IO3, IO4), 1 digital input (IO1)\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x00, 0xFE]);\r\n      let response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n\r\n        // Check that fixture is properly communicating\r\n        await window.genericRS232.sendBytes([0x65, 0x04, 0x0A]);\r\n        response = await window.genericRS232.getBytes(2);\r\n        const reading = (response[0] << 8) + response[1];\r\n        const calcVal = (reading * 5) / 1023;\r\n        if (calcVal != 5) {\r\n          reject(\'Fixture voltage reading is not correct (5V expected, \' + calcVal + \'V received)\')\r\n        } else {\r\n          resolve(calcVal);\r\n        }\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(122, '2022-10-20 10:57:49', 7, 'Burster Home API', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      let response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I/O Mode, 3 analog inputs (IO2, IO3, IO4), 1 digital input (IO1)\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x00, 0xFE]);\r\n      let response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction checkForVoltageIssues () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Check that fixture is properly communicating\r\n      await window.genericRS232.sendBytes([0x65, 0x04, 0x0A]);\r\n      let response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      if (calcVal != 5) {\r\n        reject(\'Fixture voltage reading is not correct (5V expected, \' + calcVal + \'V received)\')\r\n      } else {\r\n        resolve(calcVal);\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1),
(123, '2022-10-20 11:15:47', 7, 'Burster Home API', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I/O Mode, 3 analog inputs (IO2, IO3, IO4), 1 digital input (IO1)\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x00, 0xFE]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction checkForVoltageIssues () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Check that fixture is properly communicating\r\n      await window.genericRS232.sendBytes([0x65, 0x04, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      if (calcVal != 5) {\r\n        reject(\'Fixture voltage reading is not correct (5V expected, \' + calcVal + \'V received)\')\r\n      } else {\r\n        resolve(calcVal);\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getLedValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x03, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isSensorConnected () {\r\n  // Look for LED reading to drop to 1.2-1.6v as verification that sensor is connected\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let sensorConnected = false;\r\n\r\n      const ledValue = await getLedValue();\r\n      if (ledValue >= 1.2 && ledValue <= 1.6) {\r\n        sensorConnected = true;\r\n      }\r\n      \r\n      resolve(sensorConnected);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1),
(124, '2022-10-20 12:45:28', 7, 'Burster Home API', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I/O Mode, 3 analog inputs (IO2, IO3, IO4), 1 digital input (IO1)\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x00, 0xFE]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction checkForVoltageIssues () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Check that fixture is properly communicating\r\n      await window.genericRS232.sendBytes([0x65, 0x04, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      if (calcVal != 5) {\r\n        reject(\'Fixture voltage reading is not correct (5V expected, \' + calcVal + \'V received)\')\r\n      } else {\r\n        resolve(calcVal);\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getLedValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x03, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x02, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isSensorConnected () {\r\n  // Look for LED reading to drop to 1.2-1.6v as verification that sensor is connected\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let sensorConnected = false;\r\n\r\n      const ledValue = await getLedValue();\r\n      if (ledValue >= 1.2 && ledValue <= 1.6) {\r\n        sensorConnected = true;\r\n      }\r\n      \r\n      resolve({\r\n        sensorConnected: sensorConnected,\r\n        ledValue: ledValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isSensorBlocked () {\r\n  // Look for collector reading to be greater than 4.2v as verification that sensor is blocked\r\n  // If reading is less than 0.5v, then sensor is not blocked\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let sensorBlocked = false;\r\n      let sensorNotBlocked = false;\r\n\r\n      const collectorValue = await getCollectorValue();\r\n      if (collectorValue > 4.2) {\r\n        sensorBlocked = true;\r\n      } else if (collectorValue < 0.5) {\r\n        sensorNotBlocked = true;\r\n      }\r\n      \r\n      resolve({\r\n        sensorBlocked: sensorBlocked,\r\n        sensorNotBlocked: sensorNotBlocked,\r\n        collectorValue: collectorValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1),
(125, '2022-10-20 15:08:55', 4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n//---------------------------------------------------------------------------------------------------------------\r\nasync function getFirmwareVersionUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1B, 0x47]);\r\n      const response = await window.genericUSB.getBytes(11);\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n//---------------------------------------------------------------------------------------------------------------\r\nasync function updateFirmware (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Enter Boot Mode\r\n      await window.genericUSB.sendBytes([0x1B, 0x7E, 0x7D]);\r\n      await window.genericUSB.disconnect();\r\n\r\n      // Wait for device to enter boot mode\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n\r\n      // Connect to device in boot mode\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes([0x1D, 0x0E]); //Boot Erase\r\n      await window.genericUSB.sendBytes([0x1D, 0x11, 0x00, 0x00, 0x00, 0x00]); //Enter Firmware download\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      if(response[0] === 0x06 || response[0] === 0x50) {\r\n        const fwVersion = await getFirmwareVersionUsb();\r\n        resolve(fwVersion);\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x1B, 0x41]); // Printer Status\r\n                    \r\n            let response = await window.genericRS232.getBytes(2);\r\n            if (response.length == 2) {\r\n              printerCom = validComPorts[i];\r\n              foundPrinter = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSecurityBytesSerial (requestType) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x1B, 0x58]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: requestType,\r\n            token: response\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSecurityBytesUsb (requestType) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1B, 0x58]);\r\n      const response = await window.genericUSB.getBytes(2);\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: requestType,\r\n            token: response\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printStringViaSerial (textLine) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let byteArray = [];\r\n\r\n      for(let i = 0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      \r\n      await window.genericRS232.sendBytes(byteArray)\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x1B, 0x47]);\r\n      const response = await window.genericRS232.getBytes(11);\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n//---------------------------------------------------------------------------------------------------------------', 1),
(126, '2022-10-20 16:06:18', 4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1B, 0x47]);\r\n      const response = await window.genericUSB.getBytes(11);\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Enter Boot Mode\r\n      await window.genericUSB.sendBytes([0x1B, 0x7E, 0x7D]);\r\n      await window.genericUSB.disconnect();\r\n\r\n      // Wait for device to enter boot mode\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n\r\n      // Connect to device in boot mode\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes([0x1D, 0x0E]); //Boot Erase\r\n      await window.genericUSB.sendBytes([0x1D, 0x11, 0x00, 0x00, 0x00, 0x00]); //Enter Firmware download\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      if(response[0] === 0x06 || response[0] === 0x50) {\r\n        const fwVersion = await getFirmwareVersionUsb();\r\n        resolve(fwVersion);\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x1B, 0x41]); // Printer Status\r\n                    \r\n            let response = await window.genericRS232.getBytes(2);\r\n            if (response.length == 2) {\r\n              printerCom = validComPorts[i];\r\n              foundPrinter = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSecurityBytesSerial (requestType) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x1B, 0x58]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: requestType,\r\n            token: response\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSecurityBytesUsb (requestType) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1B, 0x58]);\r\n      const response = await window.genericUSB.getBytes(2);\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: requestType,\r\n            token: response\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printStringViaSerial (textLine) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let byteArray = [];\r\n\r\n      for(let i = 0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      \r\n      await window.genericRS232.sendBytes(byteArray)\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printStringViaUsb (textLine) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let byteArray = [];\r\n\r\n      for(let i = 0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      \r\n      await window.genericUSB.sendBytes(byteArray)\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x1B, 0x47]);\r\n      const response = await window.genericRS232.getBytes(11);\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(127, '2022-10-24 10:18:01', 7, 'Burster Home Fixture', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I/O Mode, 3 analog inputs (IO2, IO3, IO4), 1 digital input (IO1)\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x00, 0xFE]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction checkForVoltageIssues () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Check that fixture is properly communicating\r\n      await window.genericRS232.sendBytes([0x65, 0x04, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      if (calcVal != 5) {\r\n        reject(\'Fixture voltage reading is not correct (5V expected, \' + calcVal + \'V received)\')\r\n      } else {\r\n        resolve(calcVal);\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getLedValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x03, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x02, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      const calcVal = (reading * 5) / 1023;\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isSensorConnected () {\r\n  // Look for LED reading to drop to 1.2-1.6v as verification that sensor is connected\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let sensorConnected = false;\r\n\r\n      const ledValue = await getLedValue();\r\n      if (ledValue >= 1.2 && ledValue <= 1.6) {\r\n        sensorConnected = true;\r\n      }\r\n      \r\n      resolve({\r\n        sensorConnected: sensorConnected,\r\n        ledValue: ledValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isSensorBlocked () {\r\n  // Look for collector reading to be greater than 4.2v as verification that sensor is blocked\r\n  // If reading is less than 0.5v, then sensor is not blocked\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let sensorBlocked = false;\r\n      let sensorNotBlocked = false;\r\n\r\n      const collectorValue = await getCollectorValue();\r\n      if (collectorValue > 4.2) {\r\n        sensorBlocked = true;\r\n      } else if (collectorValue < 0.5) {\r\n        sensorNotBlocked = true;\r\n      }\r\n      \r\n      resolve({\r\n        sensorBlocked: sensorBlocked,\r\n        sensorNotBlocked: sensorNotBlocked,\r\n        collectorValue: collectorValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1),
(128, '2022-10-24 10:21:44', 6, 'VCSEL Fixture', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I2C_H_400KHZ, 2 analog inputs\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x70, 0x0F]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n', 1),
(129, '2022-10-24 10:35:07', 6, 'VCSEL Fixture', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I2C_H_400KHZ, 2 analog inputs\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x70, 0x0F]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isBoardConnected () {\r\n  // Verify a response happens when requesting digital pot value as verification that board is connected\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let boardConnected = false;\r\n\r\n      const collectorValue = await getCollectorPotNV();\r\n      if (collectorValue != 1023) {\r\n        boardConnected = true;\r\n      }\r\n      \r\n      resolve({\r\n        boardConnected: boardConnected,\r\n        ledValue: ledValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorPotNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5F, 0x2C, 0x02]); // 0x5F = read at collector address, 0x2C = read NV Wiper 0, 0x02 = Bytes to read\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const calcVal = ((response[0] & 0x03) << 8) + response[1];\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(130, '2022-10-24 10:40:48', 6, 'VCSEL Fixture', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I2C_H_400KHZ, 2 analog inputs\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x70, 0x0F]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isBoardConnected () {\r\n  // Verify a response happens when requesting digital pot value as verification that board is connected\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let boardConnected = false;\r\n\r\n      const collectorValue = await getCollectorPotNV();\r\n      if (collectorValue != 1023) {\r\n        boardConnected = true;\r\n      }\r\n      \r\n      resolve({\r\n        boardConnected: boardConnected,\r\n        collectorValue: collectorValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorPotNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5F, 0x2C, 0x02]); // 0x5F = read at collector address, 0x2C = read NV Wiper 0, 0x02 = Bytes to read\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const calcVal = ((response[0] & 0x03) << 8) + response[1];\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n', 1),
