  } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorVoltage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x02, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      resolve((reading * 3.3) / 1023);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n', 1),
(134, '2022-10-24 12:49:16', 6, 'VCSEL Fixture', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I2C_H_400KHZ, 2 analog inputs\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x70, 0x0F]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isBoardConnected () {\r\n  // Verify a response happens when requesting digital pot value as verification that board is connected\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let boardConnected = false;\r\n\r\n      const collectorValue = await getCollectorPotNV();\r\n      if (collectorValue != 1023) {\r\n        boardConnected = true;\r\n      }\r\n      \r\n      resolve({\r\n        boardConnected: boardConnected,\r\n        collectorValue: collectorValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorPotNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5F, 0x2C, 0x02]); // 0x5F = read at collector address, 0x2C = read NV Wiper 0, 0x02 = Bytes to read\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const calcVal = ((response[0] & 0x03) << 8) + response[1];\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getTransmitterPotNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5D, 0x2C, 0x02]); // 0x5D = read at transmitter address, 0x2C = read NV Wiper 0, 0x02 = Bytes to read\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const calcVal = ((response[0] & 0x03) << 8) + response[1];\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const highByte = await getRegisterValue(6);\r\n      const middleByte = await getRegisterValue(7);\r\n      const lowByte = await getRegisterValue(8);\r\n      resolve(((highByte & 0xFF) << 16) + ((middleByte & 0xFF) << 8) + (lowByte & 0xFF));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getRegisterValue (registerToRead) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x57, 0x01, 0x31, 0x5E, 0x0C | (registerToRead << 4), 0x02, 0x30, 0x5F, 0x20, 0x04, 0x20, 0x03]);\r\n      const response = await window.genericRS232.getBytes(4);\r\n      resolve(((response[2] & 0x01) << 8) + response[3]);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCurrentCollectorValue (registerToRead) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      resolve(await getRegisterValue(0));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCurrentTransmitterValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x57, 0x01, 0x31, 0x5C, 0x0C, 0x02, 0x30, 0x5D, 0x20, 0x04, 0x20, 0x03]);\r\n      const response = await window.genericRS232.getBytes(4);\r\n      resolve(((response[2] & 0x01) << 8) + response[3]);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorVoltage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x02, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      resolve((reading * 3.3) / 1023);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n', 1),
