\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCurrentCollectorValue (registerToRead) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      resolve(await getRegisterValue(0));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCurrentTransmitterValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x57, 0x01, 0x31, 0x5C, 0x0C, 0x02, 0x30, 0x5D, 0x20, 0x04, 0x20, 0x03]);\r\n      const response = await window.genericRS232.getBytes(4);\r\n      resolve(((response[2] & 0x01) << 8) + response[3]);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorVoltage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x02, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      resolve((reading * 3.3) / 1023);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawGauge (emitter, collector, voltage) {\r\n  return `\r\n    <div style=\"text-align:center; margin-top:50px;\">1.65v</div>\r\n    <div style=\"border-right:1px solid #aaa; height:10px; width:50%;\"></div>\r\n    <div style=\"border:1px solid #aaa; height:30px;\">\r\n        <div style=\"background-color:#789; text-align:center; color:#fff; font-weight:bold; line-height: 30px; height:30px; width:${(voltage * 100) / 3.3}%;\">${voltage.toFixed(2)}v</div>\r\n    </div>\r\n    <div style=\"float:left; width:48%;\">\r\n        <div style=\"text-align:center;\">Emitter</div>\r\n        <div style=\"border:1px solid #aaa; height:20px;\">\r\n            <div style=\"background-color:#999; text-align:center; color:#fff; font-weight:bold; line-height: 20px; height:20px; width:${(emitter * 100) / 128}%;\">${emitter}</div>\r\n        </div>\r\n    </div>\r\n    <div style=\"float:right; width:48%;\">\r\n        <div style=\"text-align:center;\">Collector</div>\r\n        <div style=\"border:1px solid #aaa; height:20px;\">\r\n            <div style=\"background-color:#999; text-align:center; color:#fff; font-weight:bold; line-height: 20px; height:20px; width:${(collector * 100) / 128}%;\">${collector}</div>\r\n        </div>\r\n    </div>\r\n    <div style=\"clear:both;\"></div>\r\n  `;\r\n}\r\n// -------------------------------------------------------- //\r\nfunction waitForReadingToStabilize (countOfMatchesRequired) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let lastValue = 0;\r\n      let countOfMatches = 0;\r\n      while (countOfMatches < countOfMatchesRequired) {\r\n        const currentValue = await getCollectorVoltage();\r\n        if (currentValue.toFixed(3) === lastValue) {\r\n          countOfMatches++;\r\n        } else {\r\n          countOfMatches = 0;\r\n        }\r\n        lastValue = currentValue.toFixed(3);\r\n\r\n        // wait for 50ms\r\n        await new Promise(resolve => setTimeout(resolve, 50));\r\n      }\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n', 1),
(142, '2022-10-24 14:54:04', 6, 'VCSEL Fixture', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I2C_H_400KHZ, 2 analog inputs\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x70, 0x0F]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isBoardConnected () {\r\n  // Verify a response happens when requesting digital pot value as verification that board is connected\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let boardConnected = false;\r\n\r\n      const collectorValue = await getCollectorPotNV();\r\n      if (collectorValue != 1023) {\r\n        boardConnected = true;\r\n      }\r\n      \r\n      resolve({\r\n        boardConnected: boardConnected,\r\n        collectorValue: collectorValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorPotNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5F, 0x2C, 0x02]); // 0x5F = read at collector address, 0x2C = read NV Wiper 0, 0x02 = Bytes to read\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const calcVal = ((response[0] & 0x03) << 8) + response[1];\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getTransmitterPotNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5D, 0x2C, 0x02]); // 0x5D = read at transmitter address, 0x2C = read NV Wiper 0, 0x02 = Bytes to read\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const calcVal = ((response[0] & 0x03) << 8) + response[1];\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction setCollectorPot (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x00, 0x01, valueToSet]); // 0x5E = write at collector address, 0x00 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });   \r\n}\r\n// -------------------------------------------------------- //\r\nfunction setTransmitterPot (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5C, 0x00, 0x01, valueToSet]); // 0x5C = write at transmitter address, 0x00 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });  \r\n}\r\n// -------------------------------------------------------- //\r\nfunction setCollectorPotNV (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x20, 0x01, valueToSet]); // 0x5E = write at collector address, 0x20 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });   \r\n}\r\n// -------------------------------------------------------- //\r\nfunction setTransmitterPotNV (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5C, 0x20, 0x01, valueToSet]); // 0x5C = write at transmitter address, 0x20 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });  \r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const highByte = await getRegisterValue(6);\r\n      const middleByte = await getRegisterValue(7);\r\n      const lowByte = await getRegisterValue(8);\r\n      resolve(((highByte & 0xFF) << 16) + ((middleByte & 0xFF) << 8) + (lowByte & 0xFF));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction setSerialNumber (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const highByte = (valueToSet >> 16) & 0xFF;\r\n      const middleByte = (valueToSet >> 8) & 0xFF;\r\n      const lowByte = valueToSet & 0xFF;\r\n\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x60, 0x01, highByte]); // 0x5E = write at collector address, 0x06 = write Data Eprom 0, 0x01 = Bytes to write\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x70, 0x01, middleByte]); // 0x5E = write at collector address, 0x06 = write Data Eprom 0, 0x01 = Bytes to write\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x80, 0x01, lowByte]); // 0x5E = write at collector address, 0x06 = write Data Eprom 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve(); \r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getRegisterValue (registerToRead) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x57, 0x01, 0x31, 0x5E, 0x0C | (registerToRead << 4), 0x02, 0x30, 0x5F, 0x20, 0x04, 0x20, 0x03]);\r\n      const response = await window.genericRS232.getBytes(4);\r\n      resolve(((response[2] & 0x01) << 8) + response[3]);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCurrentCollectorValue (registerToRead) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      resolve(await getRegisterValue(0));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCurrentTransmitterValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x57, 0x01, 0x31, 0x5C, 0x0C, 0x02, 0x30, 0x5D, 0x20, 0x04, 0x20, 0x03]);\r\n      const response = await window.genericRS232.getBytes(4);\r\n      resolve(((response[2] & 0x01) << 8) + response[3]);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorVoltage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x02, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      resolve((reading * 3.3) / 1023);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawGauge (emitter, collector, voltage) {\r\n  return `\r\n    <div style=\"text-align:center; margin-top:50px;\">1.65v</div>\r\n    <div style=\"border-right:1px solid #aaa; height:10px; width:50%;\"></div>\r\n    <div style=\"border:1px solid #aaa; height:30px;\">\r\n        <div style=\"background-color:#789; text-align:center; color:#fff; font-weight:bold; line-height: 30px; height:30px; width:${(voltage * 100) / 3.3}%;\">${voltage.toFixed(2)}v</div>\r\n    </div>\r\n    <div style=\"float:left; width:48%;\">\r\n        <div style=\"text-align:center;\">Emitter</div>\r\n        <div style=\"border:1px solid #aaa; height:20px;\">\r\n            <div style=\"background-color:#999; text-align:center; color:#fff; font-weight:bold; line-height: 20px; height:20px; width:${(emitter * 100) / 128}%;\">${emitter}</div>\r\n        </div>\r\n    </div>\r\n    <div style=\"float:right; width:48%;\">\r\n        <div style=\"text-align:center;\">Collector</div>\r\n        <div style=\"border:1px solid #aaa; height:20px;\">\r\n            <div style=\"background-color:#999; text-align:center; color:#fff; font-weight:bold; line-height: 20px; height:20px; width:${(collector * 100) / 128}%;\">${collector}</div>\r\n        </div>\r\n    </div>\r\n    <div style=\"clear:both;\"></div>\r\n  `;\r\n}\r\n// -------------------------------------------------------- //\r\nfunction waitForReadingToStabilize (countOfMatchesRequired) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let lastValue = 0;\r\n      let countOfMatches = 0;\r\n      while (countOfMatches < countOfMatchesRequired) {\r\n        const currentValue = await getCollectorVoltage();\r\n        if (currentValue.toFixed(3) === lastValue) {\r\n          countOfMatches++;\r\n        } else {\r\n          countOfMatches = 0;\r\n        }\r\n        lastValue = currentValue.toFixed(3);\r\n\r\n        // wait for 50ms\r\n        await new Promise(resolve => setTimeout(resolve, 50));\r\n      }\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n', 1),
(143, '2022-10-25 09:48:38', 4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1B, 0x47]);\r\n      const response = await window.genericUSB.getBytes(11);\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Enter Boot Mode\r\n      await window.genericUSB.sendBytes([0x1B, 0x7E, 0x7D]);\r\n      await window.genericUSB.disconnect();\r\n\r\n      // Wait for device to enter boot mode\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n\r\n      // Connect to device in boot mode\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes([0x1D, 0x0E]); //Boot Erase\r\n      await window.genericUSB.sendBytes([0x1D, 0x11, 0x00, 0x00, 0x00, 0x00]); //Enter Firmware download\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      if(response[0] === 0x06 || response[0] === 0x50) {\r\n        const fwVersion = await getFirmwareVersionUsb();\r\n        resolve(fwVersion);\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x1B, 0x41]); // Printer Status\r\n                    \r\n            let response = await window.genericRS232.getBytes(2);\r\n            if (response.length == 2) {\r\n              printerCom = validComPorts[i];\r\n              foundPrinter = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSecurityBytesSerial (requestType) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x1B, 0x58]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: requestType,\r\n            token: response\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSecurityBytesUsb (requestType) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1B, 0x58]);\r\n      const response = await window.genericUSB.getBytes(2);\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: requestType,\r\n            token: response\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printStringViaSerial (textLine) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let byteArray = [];\r\n\r\n      for(let i = 0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      \r\n      await window.genericRS232.sendBytes(byteArray)\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printStringViaUsb (textLine) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let byteArray = [];\r\n\r\n      for(let i = 0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      \r\n      await window.genericUSB.sendBytes(byteArray)\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x1B, 0x47]);\r\n      const response = await window.genericRS232.getBytes(11);\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getExtendedStatusUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let status = {\r\n        carriageHomeSensorInError: false,\r\n        bursterHomeSensorInError: false,\r\n        paperOut: false,\r\n        paperLoadingError: false,\r\n        failedTopOfFormMark: false,\r\n        burstError: false,\r\n        checksumError: false,\r\n        feederNotPresent: false,\r\n        burstSensorDefective: false,\r\n        printerWasReset: false,\r\n        printerWasResetWithFormLoaded: false,\r\n        ejectFailed: false\r\n      }\r\n\r\n      await window.genericUSB.sendBytes([0x1B, 0x2B]);\r\n      const response = await window.genericUSB.getBytes(6);\r\n\r\n      if(response[0] & 0b1) {\r\n        status.carriageHomeSensorInError = true;\r\n      }\r\n      if(response[0] & 0b10) {\r\n        status.bursterHomeSensorInError = true;\r\n      }\r\n      if(response[0] & 0b100) {\r\n        status.paperOut = true;\r\n      }\r\n      if(response[0] & 0b1000) {\r\n        status.paperLoadingError = true;\r\n      }\r\n      if(response[0] & 0b10000) {\r\n        status.failedTopOfFormMark = true;\r\n      }\r\n      if(response[0] & 0b100000) {\r\n        status.burstError = true;\r\n      }\r\n      if(response[0] & 0b1000000) {\r\n        status.checksumError = true;\r\n      }\r\n      if(response[0] & 0b10000000) {\r\n        status.feederNotPresent = true;\r\n      }\r\n\r\n      if(response[1] & 0b1) {\r\n        status.burstSensorDefective = true;\r\n      }\r\n      if(response[1] & 0b10) {\r\n        status.printerWasReset = true;\r\n      }\r\n      if(response[1] & 0b100) {\r\n        status.printerWasResetWithFormLoaded = true;\r\n      }\r\n      if(response[1] & 0b1000) {\r\n        status.ejectFailed = true;\r\n      }\r\n\r\n      resolve(status);\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1),
(144, '2022-10-25 13:39:50', 4, '7680 API', 'async function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1B, 0x47]);\r\n      const response = await window.genericUSB.getBytes(11);\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmware (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      // Enter Boot Mode\r\n      await window.genericUSB.sendBytes([0x1B, 0x7E, 0x7D]);\r\n      await window.genericUSB.disconnect();\r\n\r\n      // Wait for device to enter boot mode\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n\r\n      // Connect to device in boot mode\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes([0x1D, 0x0E]); //Boot Erase\r\n      await window.genericUSB.sendBytes([0x1D, 0x11, 0x00, 0x00, 0x00, 0x00]); //Enter Firmware download\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await window.genericUSB.connect(0x1431, 0x7680, 0, 2, 130);\r\n\r\n      if(response[0] === 0x06 || response[0] === 0x50) {\r\n        const fwVersion = await getFirmwareVersionUsb();\r\n        resolve(fwVersion);\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x1B, 0x41]); // Printer Status\r\n                    \r\n            let response = await window.genericRS232.getBytes(2);\r\n            if (response.length == 2) {\r\n              printerCom = validComPorts[i];\r\n              foundPrinter = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSecurityBytesSerial (requestType) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x1B, 0x58]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: requestType,\r\n            token: response\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSecurityBytesUsb (requestType) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1B, 0x58]);\r\n      const response = await window.genericUSB.getBytes(2);\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: requestType,\r\n            token: response\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        resolve(serverResponse.data.securitySeed);\r\n      } else {\r\n        reject(\'Failed to get security seeds.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printStringViaSerial (textLine) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let byteArray = [];\r\n\r\n      for(let i = 0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      \r\n      await window.genericRS232.sendBytes(byteArray)\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printStringViaUsb (textLine) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let byteArray = [];\r\n\r\n      for(let i = 0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      \r\n      await window.genericUSB.sendBytes(byteArray)\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x1B, 0x47]);\r\n      const response = await window.genericRS232.getBytes(11);\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getExtendedStatusUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let status = {\r\n        carriageHomeSensorInError: false,\r\n        bursterHomeSensorInError: false,\r\n        paperOut: false,\r\n        paperLoadingError: false,\r\n        failedTopOfFormMark: false,\r\n        burstError: false,\r\n        checksumError: false,\r\n        feederNotPresent: false,\r\n        burstSensorDefective: false,\r\n        printerWasReset: false,\r\n        printerWasResetWithFormLoaded: false,\r\n        ejectFailed: false\r\n      }\r\n\r\n      await window.genericUSB.sendBytes([0x1B, 0x2B]);\r\n      const response = await window.genericUSB.getBytes(6);\r\n\r\n      if(response[0] & 0b1) {\r\n        status.carriageHomeSensorInError = true;\r\n      }\r\n      if(response[0] & 0b10) {\r\n        status.bursterHomeSensorInError = true;\r\n      }\r\n      if(response[0] & 0b100) {\r\n        status.paperOut = true;\r\n      }\r\n      if(response[0] & 0b1000) {\r\n        status.paperLoadingError = true;\r\n      }\r\n      if(response[0] & 0b10000) {\r\n        status.failedTopOfFormMark = true;\r\n      }\r\n      if(response[0] & 0b100000) {\r\n        status.burstError = true;\r\n      }\r\n      if(response[0] & 0b1000000) {\r\n        status.checksumError = true;\r\n      }\r\n      if(response[0] & 0b10000000) {\r\n        status.feederNotPresent = true;\r\n      }\r\n\r\n      if(response[1] & 0b1) {\r\n        status.burstSensorDefective = true;\r\n      }\r\n      if(response[1] & 0b10) {\r\n        status.printerWasReset = true;\r\n      }\r\n      if(response[1] & 0b100) {\r\n        status.printerWasResetWithFormLoaded = true;\r\n      }\r\n      if(response[1] & 0b1000) {\r\n        status.ejectFailed = true;\r\n      }\r\n\r\n      resolve(status);\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getExtendedStatusSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let status = {\r\n        carriageHomeSensorInError: false,\r\n        bursterHomeSensorInError: false,\r\n        paperOut: false,\r\n        paperLoadingError: false,\r\n        failedTopOfFormMark: false,\r\n        burstError: false,\r\n        checksumError: false,\r\n        feederNotPresent: false,\r\n        burstSensorDefective: false,\r\n        printerWasReset: false,\r\n        printerWasResetWithFormLoaded: false,\r\n        ejectFailed: false\r\n      }\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x2B]);\r\n      const response = await window.genericRS232.getBytes(6);\r\n\r\n      if(response[0] & 0b1) {\r\n        status.carriageHomeSensorInError = true;\r\n      }\r\n      if(response[0] & 0b10) {\r\n        status.bursterHomeSensorInError = true;\r\n      }\r\n      if(response[0] & 0b100) {\r\n        status.paperOut = true;\r\n      }\r\n      if(response[0] & 0b1000) {\r\n        status.paperLoadingError = true;\r\n      }\r\n      if(response[0] & 0b10000) {\r\n        status.failedTopOfFormMark = true;\r\n      }\r\n      if(response[0] & 0b100000) {\r\n        status.burstError = true;\r\n      }\r\n      if(response[0] & 0b1000000) {\r\n        status.checksumError = true;\r\n      }\r\n      if(response[0] & 0b10000000) {\r\n        status.feederNotPresent = true;\r\n      }\r\n\r\n      if(response[1] & 0b1) {\r\n        status.burstSensorDefective = true;\r\n      }\r\n      if(response[1] & 0b10) {\r\n        status.printerWasReset = true;\r\n      }\r\n      if(response[1] & 0b100) {\r\n        status.printerWasResetWithFormLoaded = true;\r\n      }\r\n      if(response[1] & 0b1000) {\r\n        status.ejectFailed = true;\r\n      }\r\n\r\n      resolve(status);\r\n    } catch (e) {\r\n      reject(e)\r\n    } \r\n  });\r\n}\r\n// -------------------------------------------------------- //', 1);
