(154, '2022-11-02 09:55:29', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      resolve(\'usb\');\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        resolve(\'boot\');\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          await connectToVirtualCom();\r\n          resolve(\'virtualCom\');\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await isPrinterOnVirtualCom();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve();\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(155, '2022-11-02 09:58:16', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve(\'usb\');\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve(\'boot\');\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          await connectToVirtualCom();\r\n          resolve(\'virtualCom\');\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await isPrinterOnVirtualCom();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve();\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(156, '2022-11-02 10:03:34', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await isPrinterOnVirtualCom();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(157, '2022-11-02 10:25:09', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await isPrinterOnVirtualCom();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(158, '2022-11-02 10:46:03', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await isPrinterOnVirtualCom();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.send([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.receive(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.send([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.receive(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
