rtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(175, '2022-11-02 14:59:13', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(176, '2022-11-02 15:06:55', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(177, '2022-11-02 15:37:46', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(178, '2022-11-02 16:17:12', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(179, '2022-11-02 16:23:57', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(180, '2022-11-03 08:01:38', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            console.log(response[0])\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(181, '2022-11-03 08:14:58', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            console.log(response[0])\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(182, '2022-11-03 09:00:11', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            console.log(response[0])\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(183, '2022-11-03 09:14:38', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(184, '2022-11-03 09:33:42', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaSerial (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericRS232.sendBytes(alignmentArray);\r\n      await window.genericRS232.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(185, '2022-11-07 07:44:47', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaSerial (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericRS232.sendBytes(alignmentArray);\r\n      await window.genericRS232.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configureCarriageColumnAlignmentUsb (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA7, alignmentValue, alignmentValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(186, '2022-11-07 08:44:31', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaSerial (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericRS232.sendBytes(alignmentArray);\r\n      await window.genericRS232.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configureCarriageColumnAlignmentUsb (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA7, alignmentValue, alignmentValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function rebootAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x10, 0x40]);\r\n      await disconnectFromUsb();\r\n\r\n      // Wait 8 seconds for device to reboot\r\n      await new Promise(resolve => setTimeout(resolve, 8000));\r\n      await connectToUsb();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(187, '2022-11-07 09:07:14', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaSerial (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericRS232.sendBytes(alignmentArray);\r\n      await window.genericRS232.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configureCarriageColumnAlignmentUsb (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA7, alignmentValue, alignmentValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function rebootAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x10, 0x40]);\r\n      await disconnectFromUsb();\r\n\r\n      // Wait 8 seconds for device to reboot\r\n      await new Promise(resolve => setTimeout(resolve, 8000));\r\n      await connectToUsb();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToSubMode3 () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x04]);\r\n      await rebootAclUsb();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(188, '2022-11-07 09:14:30', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaSerial (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericRS232.sendBytes(alignmentArray);\r\n      await window.genericRS232.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configureCarriageColumnAlignmentUsb (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA7, alignmentValue, alignmentValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function rebootAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x10, 0x40]);\r\n      await disconnectFromUsb();\r\n\r\n      // Wait 8 seconds for device to reboot\r\n      await new Promise(resolve => setTimeout(resolve, 8000));\r\n      await connectToUsb();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToSubMode3Usb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x04]);\r\n      await rebootAclUsb();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToA470Usb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x01]);\r\n      await rebootAclUsb();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1),
(189, '2022-11-07 09:17:17', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaSerial (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericRS232.sendBytes(alignmentArray);\r\n      await window.genericRS232.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configureCarriageColumnAlignmentUsb (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA7, alignmentValue, alignmentValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function rebootAclUsb (reconnect = true) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x10, 0x40]);\r\n      await disconnectFromUsb();\r\n\r\n      // Wait 8 seconds for device to reboot\r\n      await new Promise(resolve => setTimeout(resolve, 8000));\r\n      if (reconnect) {\r\n        await connectToUsb();\r\n      }\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToSubMode3Usb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x04]);\r\n      await rebootAclUsb(false);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToA470Usb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x01]);\r\n      await rebootAclUsb(false);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(190, '2022-11-07 09:26:37', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaSerial (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericRS232.sendBytes(alignmentArray);\r\n      await window.genericRS232.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configureCarriageColumnAlignmentUsb (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA7, alignmentValue, alignmentValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function rebootAclUsb (reconnect = true) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x10, 0x40]);\r\n      await disconnectFromUsb();\r\n\r\n      // Wait 8 seconds for device to reboot\r\n      await new Promise(resolve => setTimeout(resolve, 8000));\r\n      if (reconnect) {\r\n        await connectToUsb();\r\n      }\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToSubMode3Usb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x04]);\r\n      await rebootAclUsb(false);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToA470Usb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x01]);\r\n      await rebootAclUsb(false);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470ClampDefaultSerial (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x08, 0x03, 0xA0, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470PitchDefaultSerial (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x08, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470ClampDefault (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x08, 0x03, 0xA0, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470PitchDefault (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x08, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}', 1),
(191, '2022-11-07 10:27:57', 8, '5300 Printer', 'async function determineUsbMode () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // try to connect to the device via standard usb\r\n      await connectToUsb();\r\n      await disconnectFromUsb();\r\n      resolve({\r\n        mode: \'usb\'\r\n      });\r\n    } catch (e) {\r\n      // if this fails, try to connect to boot mode\r\n      try {\r\n        await connectToUsbInBoot();\r\n        await disconnectFromUsb();\r\n        resolve({\r\n          mode: \'boot\'\r\n        });\r\n      } catch (e) {\r\n        // if that fails, try to connect to the device via usb virtual com port\r\n        try {\r\n          const printerCom = await connectToVirtualCom();\r\n          resolve({\r\n            mode: \'virtualCom\',\r\n            printerCom: printerCom\r\n          });\r\n        } catch (e) {\r\n          reject(e)\r\n        }\r\n      }\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x5300, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function disconnectFromUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.disconnect(true);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToUsbInBoot () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.connect(0x1431, 0x53FF, 0, 2, 130);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function connectToVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const response = await isPrinterOnVirtualCom();\r\n      resolve(response);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnVirtualCom () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer == \'Pertech Industries\') {\r\n          validComPorts.push(ports[i]);\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      if(foundPrinter) {\r\n        resolve(printerCom);\r\n      } else {\r\n        reject(\'No printer found on virtual com port\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function isPrinterOnSerialAcl () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPrinter = false;\r\n      let printerCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if(!(ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 57600, 8, 1, \'none\', true, false, false);\r\n            await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n            const response = await window.genericRS232.getBytes(1);\r\n            if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n              foundPrinter = true;\r\n              printerCom = validComPorts[i];\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundPrinter: foundPrinter,\r\n        printerCom: printerCom\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 57600, 8, 1, \'none\', true, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction disconnectFromSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.disconnect();\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineUsbLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericUSB.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericUSB.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function determineVirtualComLanguage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Attempt ACL first\r\n      try {\r\n        await window.genericRS232.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve(\'acl\');\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // If ACL fails, try to connect to the device via A470\r\n        await window.genericRS232.sendBytes([0x1B,0x05]); // A470 printer status\r\n        const response = await window.genericRS232.getBytes(1);\r\n        if(response[0] & 128) {\r\n          //Our expected response\r\n          resolve(\'a470\');\r\n        } else {\r\n          throw new Error(\'Printer status response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function getFirmwareVersionAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1D,0x49,0xA3]);\r\n      let response = await window.genericUSB.getBytes(14);\r\n      response.shift();\r\n      response.pop();\r\n      const byteArray = new Uint8Array(response);\r\n      const decoder = new TextDecoder(\'UTF-8\');\r\n      resolve(decoder.decode(byteArray));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nreadFileAsync = (fwBytes) => {\r\n  return new Promise((resolve, reject) => {\r\n      let arrayBuffer;\r\n      let reader = new FileReader();\r\n\r\n      reader.onload = (event) => {\r\n          arrayBuffer = event.target.result;\r\n      };\r\n\r\n      reader.readAsArrayBuffer(fwBytes);\r\n      reader.onloadend = (event) => {\r\n          resolve(reader.result);\r\n      };\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function updateFirmwareFromBootUsb (downloadPath) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Pull firmware from server\r\n      const firmwareData = await window.axios.get(downloadPath, {\r\n        responseType: \'blob\'\r\n      });\r\n\r\n      const blob = new Blob([firmwareData.data], { type: \'application/*\' });\r\n\r\n      const contentBuffer = await readFileAsync(blob);\r\n      const curBuf = new Uint8Array(contentBuffer);\r\n\r\n      await window.genericUSB.sendBytes(curBuf); //Send firmware\r\n\r\n      let response = await window.genericUSB.getBytes(1);\r\n      await window.genericUSB.disconnect();\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsb();\r\n\r\n      if(response[0] === 0x50) {\r\n        resolve();\r\n      } else {\r\n        console.log(response);\r\n        reject(\'Failed to update firmware\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToAclUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      try {\r\n        await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n        let response = await window.genericUSB.getBytes(1);\r\n        if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n          resolve();\r\n        } else {\r\n          throw new Error(\'ACL printer status response not recognized\');\r\n        }\r\n      } catch (e) {\r\n        // Assume in A470 mode\r\n        await window.genericUSB.sendBytes([0x08,0x03,0x07,0x00]); // A470 command to switch to ACL\r\n        let response = await window.app.genericUSB.getBytes(1);\r\n        if(response[0]==0x06) { //0x06 == ACK\r\n          //Reboot\r\n          await window.genericUSB.sendBytes([0x1B,0x00]); // A470 command to reboot\r\n          await window.genericUSB.disconnect();\r\n          await new Promise(resolve => setTimeout(resolve, 4000));\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x10,0x04,0x01]); // ACL printer status\r\n          let response = await window.genericUSB.getBytes(1);\r\n          if(response[0] == 22 || response[0] == 18 || response[0] == 54 || response[0] == 50) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'ACL printer status response not recognized\');\r\n          }\r\n        } else {\r\n          throw new Error(\'ACL switch response not recognized\');\r\n        }\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCarriageReturnUsage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x93, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configSoftFaultRecovery (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x90, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFont (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontQuality (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA9, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultInternationalCharacterSubstitution (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9F, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultFontLarge (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAC, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultCodePage (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x80, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultLpi (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x94, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configCommunications (baud, stopBits, parityType, parity, flowControl, driverClass, descriptor, deviceId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x02, 0x00, baud | stopBits, parity | descriptor, parityType, flowControl | driverClass, 0x00]);\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xB0, deviceId]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configMechType (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x8B, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configOptionalFormTakenSensor (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAF, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configFormInsertionWaitTime (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x9D, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configDefaultClampDelay (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAD, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configWidePrintField (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAE, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configInkjetDotCountReset (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA8, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configVirtualDocumentStop (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xAA, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaUsb (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericUSB.sendBytes(alignmentArray);\r\n      await window.genericUSB.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function printLineViaSerial (textLine, justification = \'left\') {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let alignmentArray = [0x1B, 0x61];\r\n      switch(justification) {\r\n        case \'right\':\r\n          alignmentArray.push(0x02);\r\n        break;\r\n\r\n        case \'center\':\r\n          alignmentArray.push(0x01);\r\n        break;\r\n\r\n        default:\r\n          alignmentArray.push(0x00);\r\n        break;\r\n      }\r\n\r\n      let byteArray = [];\r\n      for(var i=0; i < textLine.length; i++) {\r\n        byteArray.push(textLine.charCodeAt(i));\r\n      }\r\n      byteArray.push(0x0A);\r\n\r\n      await window.genericRS232.sendBytes(alignmentArray);\r\n      await window.genericRS232.sendBytes(byteArray);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configureCarriageColumnAlignmentUsb (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0xA7, alignmentValue, alignmentValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function rebootAclUsb (reconnect = true) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x10, 0x40]);\r\n      await disconnectFromUsb();\r\n\r\n      // Wait 8 seconds for device to reboot\r\n      await new Promise(resolve => setTimeout(resolve, 8000));\r\n      if (reconnect) {\r\n        await connectToUsb();\r\n      }\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToSubMode3Usb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x04]);\r\n      await rebootAclUsb(false);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function switchToA470Usb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x1F, 0x03, 0x07, 0x01]);\r\n      await rebootAclUsb(false);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470ClampDefaultSerial (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x08, 0x03, 0xA0, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470PitchDefaultSerial (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x08, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470ClampDefault (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x08, 0x03, 0xA0, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nasync function configA470PitchDefault (cfgValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericUSB.sendBytes([0x08, 0x03, 0x15, cfgValue]);\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}', 1);
INSERT INTO `prod_v2_apis_archive` (`archiveId`, `generatedDateTime`, `apiId`, `title`, `script`, `active`) VALUES
(192, '2022-11-08 11:28:24', 6, 'VCSEL Fixture', 'async function isFixtureOnSerial () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundFixture = false;\r\n      let fixtureCom = \'\';\r\n\r\n      // Filter out ports that are not valid to check (looking for specific VID/PID)\r\n      let validComPorts = [];\r\n      const ports = await window.genericRS232.getDeviceList();\r\n      for(let i=0; i<ports.length; i++) {\r\n        if(ports[i].manufacturer != null) {\r\n          if((ports[i].vendorId == \"04d8\" && ports[i].productId == \"ffee\")) {\r\n            validComPorts.push(ports[i]);\r\n          }\r\n        }\r\n      }\r\n\r\n      // Try connecting through each found valid until first success found\r\n      if(validComPorts.length) {\r\n        for(let i = 0; i < validComPorts.length; i++) {\r\n          try {\r\n            await window.genericRS232.connect(validComPorts[i], 9600, 8, 1, \'none\', false, false, false);\r\n            await window.genericRS232.sendBytes([0x5A, 0x01]); // Get Version Info\r\n            let response = await window.genericRS232.getBytes(3);\r\n            if (response[0] == 0x07) {\r\n              fixtureCom = validComPorts[i];\r\n              foundFixture = true;\r\n              break;\r\n            }\r\n          } catch (e) {\r\n            console.log(e);\r\n          }\r\n        }\r\n      }\r\n\r\n      resolve({\r\n        foundFixture: foundFixture,\r\n        fixtureCom: fixtureCom\r\n      })\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction connectToSerial (comPort) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.connect(comPort, 9600, 8, 1, \'none\', false, false, false);\r\n      resolve()\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction stringFromByteArray (byteArray) {\r\n  return String.fromCharCode.apply(null, byteArray);\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getFixtureSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x5A, 0x03]); // Get Serial Number\r\n      const response = await window.genericRS232.getBytes(8);\r\n      resolve(stringFromByteArray(response));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\nfunction configureFixture () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Configure Fixture to: I2C_H_400KHZ, 2 analog inputs\r\n      await window.genericRS232.sendBytes([0x5A, 0x02, 0x70, 0x0F]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      if (response[0] == 0xFF) {\r\n        resolve();\r\n      } else {\r\n        reject(\'Failed to configure fixture\');\r\n      }\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction isBoardConnected () {\r\n  // Verify a response happens when requesting digital pot value as verification that board is connected\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let boardConnected = false;\r\n\r\n      const collectorValue = await getCollectorPotNV();\r\n      if (collectorValue != 1023) {\r\n        boardConnected = true;\r\n      }\r\n      \r\n      resolve({\r\n        boardConnected: boardConnected,\r\n        collectorValue: collectorValue\r\n      });\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorPotNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5F, 0x2C, 0x02]); // 0x5F = read at collector address, 0x2C = read NV Wiper 0, 0x02 = Bytes to read\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const calcVal = ((response[0] & 0x03) << 8) + response[1];\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getTransmitterPotNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5D, 0x2C, 0x02]); // 0x5D = read at transmitter address, 0x2C = read NV Wiper 0, 0x02 = Bytes to read\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const calcVal = ((response[0] & 0x03) << 8) + response[1];\r\n      resolve(calcVal);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction setCollectorPot (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x00, 0x01, valueToSet]); // 0x5E = write at collector address, 0x00 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });   \r\n}\r\n// -------------------------------------------------------- //\r\nfunction setTransmitterPot (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5C, 0x00, 0x01, valueToSet]); // 0x5C = write at transmitter address, 0x00 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });  \r\n}\r\n// -------------------------------------------------------- //\r\nfunction setCollectorPotNV (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x20, 0x01, valueToSet]); // 0x5E = write at collector address, 0x20 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });   \r\n}\r\n// -------------------------------------------------------- //\r\nfunction setTransmitterPotNV (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x55, 0x5C, 0x20, 0x01, valueToSet]); // 0x5C = write at transmitter address, 0x20 = write Wiper 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });  \r\n}\r\n// -------------------------------------------------------- //\r\nfunction getSerialNumber () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const highByte = await getRegisterValue(6);\r\n      const middleByte = await getRegisterValue(7);\r\n      const lowByte = await getRegisterValue(8);\r\n      resolve(((highByte & 0xFF) << 16) + ((middleByte & 0xFF) << 8) + (lowByte & 0xFF));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction setSerialNumber (valueToSet) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const highByte = (valueToSet >> 16) & 0xFF;\r\n      const middleByte = (valueToSet >> 8) & 0xFF;\r\n      const lowByte = valueToSet & 0xFF;\r\n\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x60, 0x01, highByte]); // 0x5E = write at collector address, 0x06 = write Data Eprom 0, 0x01 = Bytes to write\r\n// wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x70, 0x01, middleByte]); // 0x5E = write at collector address, 0x06 = write Data Eprom 0, 0x01 = Bytes to write\r\n\r\n// wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n      await window.genericRS232.sendBytes([0x55, 0x5E, 0x80, 0x01, lowByte]); // 0x5E = write at collector address, 0x06 = write Data Eprom 0, 0x01 = Bytes to write\r\n\r\n      // wait 100ms for write to complete\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      resolve(); \r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getRegisterValue (registerToRead) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x57, 0x01, 0x31, 0x5E, 0x0C | (registerToRead << 4), 0x02, 0x30, 0x5F, 0x20, 0x04, 0x20, 0x03]);\r\n      const response = await window.genericRS232.getBytes(4);\r\n      resolve(((response[2] & 0x01) << 8) + response[3]);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCurrentCollectorValue (registerToRead) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      resolve(await getRegisterValue(0));\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCurrentTransmitterValue () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x57, 0x01, 0x31, 0x5C, 0x0C, 0x02, 0x30, 0x5D, 0x20, 0x04, 0x20, 0x03]);\r\n      const response = await window.genericRS232.getBytes(4);\r\n      resolve(((response[2] & 0x01) << 8) + response[3]);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction getCollectorVoltage () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await window.genericRS232.sendBytes([0x65, 0x02, 0x0A]);\r\n      const response = await window.genericRS232.getBytes(2);\r\n      const reading = (response[0] << 8) + response[1];\r\n      resolve((reading * 3.3) / 1023);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawGauge (emitter, collector, voltage) {\r\n  return `\r\n    <div style=\"text-align:center; margin-top:50px;\">1.65v</div>\r\n    <div style=\"border-right:1px solid #aaa; height:10px; width:50%;\"></div>\r\n    <div style=\"border:1px solid #aaa; height:30px;\">\r\n        <div style=\"background-color:#789; text-align:center; color:#fff; font-weight:bold; line-height: 30px; height:30px; width:${(voltage * 100) / 3.3}%;\">${voltage.toFixed(2)}v</div>\r\n    </div>\r\n    <div style=\"float:left; width:48%;\">\r\n        <div style=\"text-align:center;\">Emitter</div>\r\n        <div style=\"border:1px solid #aaa; height:20px;\">\r\n            <div style=\"background-color:#999; text-align:center; color:#fff; font-weight:bold; line-height: 20px; height:20px; width:${(emitter * 100) / 128}%;\">${emitter}</div>\r\n        </div>\r\n    </div>\r\n    <div style=\"float:right; width:48%;\">\r\n        <div style=\"text-align:center;\">Collector</div>\r\n        <div style=\"border:1px solid #aaa; height:20px;\">\r\n            <div style=\"background-color:#999; text-align:center; color:#fff; font-weight:bold; line-height: 20px; height:20px; width:${(collector * 100) / 128}%;\">${collector}</div>\r\n        </div>\r\n    </div>\r\n    <div style=\"clear:both;\"></div>\r\n  `;\r\n}\r\n// -------------------------------------------------------- //\r\nfunction waitForReadingToStabilize (countOfMatchesRequired) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let lastValue = 0;\r\n      let countOfMatches = 0;\r\n      while (countOfMatches < countOfMatchesRequired) {\r\n        const currentValue = await getCollectorVoltage();\r\n        if (currentValue.toFixed(3) === lastValue) {\r\n          countOfMatches++;\r\n        } else {\r\n          countOfMatches = 0;\r\n        }\r\n        lastValue = currentValue.toFixed(3);\r\n\r\n        // wait for 50ms\r\n        await new Promise(resolve => setTimeout(resolve, 50));\r\n      }\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n', 1);
