INSERT INTO `prod_v2_templates` (`templateId`, `title`, `codeset`, `script`, `active`) VALUES
(1, 'Generic Show Sub Stages', '', 'async function loadSubStage (subStageId, subStageTitle) {\r\n  window.selectedProduct.subStageId = subStageId;\r\n  window.selectedProduct.subStageTitle = subStageTitle;\r\n  let userSelect = document.querySelector(\'#selectTester\');\r\n  window.selectedProduct.testerId = parseInt(userSelect.value);\r\n  window.global.testerId = parseInt(userSelect.value);\r\n\r\n  // Clear screen\r\n  window.gsap.to(\"#templateWrapper\", { opacity: 0, duration: 0.2, onComplete: async () => {\r\n    document.getElementById(\'templateWrapper\').innerHTML = \'\';\r\n\r\n    // Load template\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"products\",\r\n          action: \"getSubStageTemplate\",\r\n          params: {\r\n            subStageId: subStageId\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      document.getElementById(\"templateWrapper\").innerHTML = response.data.template;\r\n\r\n      window.selectedProduct.subStageInstructions = response.data.instructions;\r\n\r\n      // Destroy self\r\n      const oldScript = document.getElementById(\'templateScript\');\r\n      if (oldScript) {\r\n          oldScript.remove();\r\n      }\r\n\r\n      // Load script\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = response.data.script;\r\n      script.id = \'templateScript\';\r\n      document.body.appendChild(script);\r\n    }\r\n  }});\r\n}\r\n\r\nasync function changeTester (testerId) {\r\n  // Save tester name for display\r\n  const testerList = document.getElementById(\'selectTester\');\r\n  const testerName = testerList.options[testerList.selectedIndex].innerHTML;\r\n  window.selectedProduct.testerName = testerName;\r\n  \r\n  const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n    {\r\n      query: {\r\n        dataset: \"products\",\r\n        action: \"getSubStages\",\r\n        params: {\r\n          productId: window.selectedProduct.productId,\r\n          testerId: testerId\r\n        }\r\n      }\r\n    }, \r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  let preProcess = \'\';\r\n\r\n  if (response.data.success) {\r\n    for (let i = 0; i < response.data.subStages.length; i++) {\r\n      if (response.data.subStages[i].authorized) {\r\n        preProcess += `\r\n          <div class=\"productBtn q-mt-md\" onclick=\"loadSubStage(` + response.data.subStages[i].subStageId + `, \'` + response.data.subStages[i].title + `\')\">\r\n          <img src=\"` + response.data.subStages[i].imgFilename + `\" style=\"width: 90px; height: 90px; object-fit: contain;\" />` + response.data.subStages[i].title + `</div>\r\n        `;\r\n      } else {\r\n        preProcess += `\r\n          <div class=\"productBtn q-mt-md\" style=\"background-color:#700; color:#fff; cursor: not-allowed; \">\r\n          <img src=\"` + response.data.subStages[i].imgFilename + `\" style=\"width: 90px; height: 90px; object-fit: contain; opacity:0.2;\" /><div style=\"float:left; margin-top:-60px; width:110px;\">Requires Training</div>` + response.data.subStages[i].title + `</div>\r\n        `;\r\n      }\r\n      \r\n    }\r\n  }\r\n\r\n  document.getElementById(\'subStages\').innerHTML = preProcess;\r\n}\r\n\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#templateWrapper\", { opacity: 0 });\r\n\r\n    if(!window.global) {\r\n      window.global = {};\r\n    }\r\n\r\n    // Load generic Platform API\r\n    const apiResponse = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 1\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(apiResponse.data.success) {\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = apiResponse.data.script;\r\n      script.id = \'globalApiScript\';\r\n      document.body.appendChild(script);\r\n    \r\n      // Get the product data\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"products\",\r\n            action: \"getProduct\",\r\n            params: {\r\n              productId: window.selectedProduct.productId\r\n            }\r\n          }\r\n        }, \r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      if (response.data.success) {\r\n        document.getElementById(\'toolbarSegment\').innerHTML = response.data.productTitle;\r\n        let preProcess = \'\';\r\n        preProcess += `\r\n          <div class=\"q-pa-md\">\r\n            <label for=\"selectTester\">Tester:</label>\r\n            <select name=\"selectTester\" id=\"selectTester\" onchange=\"changeTester(this.value)\">\r\n              <option value=\"0\">Select Your Name</option>\r\n        `;\r\n\r\n        const testersResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"testers\",\r\n              action: \"getTesters\",\r\n              params: {}\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (testersResponse.data.success) {\r\n          testersResponse.data.testers.forEach(tester => {\r\n            preProcess += \'<option value=\"\' + tester.employeeId + \'\">\' + tester.firstName + \' \' + tester.lastName + \'</option>\';\r\n          });\r\n        }\r\n\r\n        preProcess += `\r\n            </select>\r\n          </div>\r\n          <div id=\"subStages\"></div>\r\n        `;\r\n        \r\n        document.getElementById(\"templateWrapper\").innerHTML = preProcess;\r\n\r\n        // Select drop down element for user\r\n        if (window.global.testerId) {\r\n          document.getElementById(\'selectTester\').value = window.global.testerId;\r\n          changeTester(document.getElementById(\'selectTester\').value);\r\n        }\r\n      }\r\n    }\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(2, 'Generic Multi-Select Test Sets', '<style>\r\n  #testList {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 77px);\r\n  }\r\n  .testSetBtn {\r\n    background-color: rgba(0,0,0,0.1);\r\n    border-top:1px solid rgba(255,255,255,0.5); \r\n    border-bottom: 1px solid rgba(0,0,0,0.5); \r\n    padding:5px; \r\n    cursor:pointer;\r\n    font-size: 90%;\r\n  }\r\n    .testSetBtn:hover {\r\n      background-color: #96c997;\r\n    }\r\n  #testActions{\r\n    text-align: right;\r\n    position: fixed;\r\n    bottom: 10px;\r\n    right: 20px;\r\n    width: calc(100vw - 300px);\r\n  }\r\n  .actionBtn {\r\n    display: inline-block;\r\n    border: 1px solid rgba(0,0,0,0.1);\r\n    border-radius: 10px;\r\n    padding: 10px 15px;\r\n    font-weight: bold;\r\n    background-color:#1976d2;\r\n    color: #fff;\r\n    cursor: pointer;\r\n  }\r\n    .actionBtn:hover {\r\n      background-color: #96c997;\r\n      color:#000;\r\n    }\r\n</style>\r\n<div style=\"float:left; background:rgba(128,128,128,0.4); border-right:1px solid rgba(0,0,0,0.1); width: 260px; height:100%;\">\r\n  <div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Select a Test</div>\r\n  <div id=\"testList\"></div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 280px); height:100%;\">\r\n  <div style=\"border:3px solid rgba(128,128,128,0.4); border-radius:15px; margin:20px 20px 0 0;\">\r\n    <div style=\"margin: 15px;\" id=\"testDescription\">\r\n      <div class=\"text-h5\">Instructions:</div>\r\n      <div id=\"instructions\"></div>\r\n      <div id=\"testDescriptionWrapper\" style=\"opacity: 0;\">\r\n        <div class=\"text-h5\" id=\"testDescriptionHeading\">Test Description:</div>\r\n        <div id=\"testDetails\"></div>\r\n      </div>\r\n      <div id=\"testActions\">\r\n        <div class=\"actionBtn\" onclick=\"loadTestSet()\">Load Test</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>', 'async function selectTestSet (testSetId) {\r\n  window.selectedProduct.selectedTestSet = window.selectedProduct.testSets[testSetId];\r\n  window.gsap.to(\"#testDescriptionWrapper\", { opacity: 0, duration: 0.3, onComplete: () => {\r\n    document.getElementById(\"testDescriptionHeading\").innerHTML = window.selectedProduct.testSets[testSetId].title;\r\n    document.getElementById(\'testDetails\').innerHTML = window.selectedProduct.testSets[testSetId].description;\r\n    window.gsap.to(\"#testDescriptionWrapper\", { opacity: 1, duration: 0.3 });\r\n    window.gsap.to(\"#testActions\", { opacity: 1, duration: 0.3 });\r\n  }});\r\n}\r\n\r\nasync function loadTestSet () {\r\n  // Clear Screen\r\n  window.gsap.to(\"#templateWrapper\", { opacity: 0, duration: 0.2, onComplete: async () => {\r\n    document.getElementById(\'templateWrapper\').innerHTML = \'\';\r\n\r\n    // Load template\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"templates\",\r\n          action: \"getTemplate\",\r\n          params: {\r\n            templateId: window.selectedProduct.selectedTestSet.extTemplateId\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      document.getElementById(\"templateWrapper\").innerHTML = response.data.template;\r\n\r\n      // Get API script if it exists for this test set\r\n      if (window.selectedProduct.selectedTestSet.extApiId && window.selectedProduct.selectedTestSet.extApiId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n          {\r\n            query: {\r\n              dataset: \"apis\",\r\n              action: \"getApi\",\r\n              params: {\r\n                apiId: window.selectedProduct.selectedTestSet.extApiId\r\n              }\r\n            }\r\n          }, \r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if(response.data.success) {\r\n          // Destroy old API if exists\r\n          const oldApiScript = document.getElementById(\'apiScript\');\r\n          if (oldApiScript) {\r\n            oldApiScript.remove();\r\n          }\r\n\r\n          // Create new API script\r\n          const apiScript = document.createElement(\'script\');\r\n          apiScript.id = \'apiScript\';\r\n          apiScript.text = response.data.script;\r\n          apiScript.type = \'text/javascript\';\r\n          document.body.appendChild(apiScript);\r\n        }\r\n      }\r\n\r\n      // Destroy self\r\n      const oldScript = document.getElementById(\'templateScript\');\r\n      if (oldScript) {\r\n          oldScript.remove();\r\n      }\r\n\r\n      // Load script\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = response.data.script;\r\n      script.id = \'templateScript\';\r\n      document.body.appendChild(script);\r\n\r\n    }\r\n  }});\r\n}\r\n\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#testList\", {opacity: 0});\r\n    window.gsap.set(\"#testActions\", {opacity: 0});\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n    document.getElementById(\'instructions\').innerHTML = window.selectedProduct.subStageInstructions;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if (testSetResponse.data.success) {\r\n      window.selectedProduct.testSets = {};\r\n      let preProcess = \'\';\r\n      testSetResponse.data.testSets.forEach(testSet => {\r\n        window.selectedProduct.testSets[testSet.testSetId] = testSet;\r\n        preProcess += \'<div class=\"testSetBtn\" style=\"border-top:1px solid rgba(255,255,255,0.5); border-bottom: 1px solid rgba(0,0,0,0.5); padding:10px; cursor:pointer;\" onclick=\"selectTestSet(\' + testSet.testSetId + \' )\">\' + testSet.title + \'</div>\';\r\n      });\r\n      document.getElementById(\'testList\').innerHTML = preProcess;\r\n      window.gsap.to(\"#testList\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n    position:relative;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.7);\r\n    height: 170px;\r\n    position: absolute;\r\n    top: 30px;\r\n    padding-top:50px;\r\n    font-weight: bold;\r\n    color:#fff;\r\n    display: none;\r\n    width: 198px;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function indicateFailure (index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].failedCalibration = true;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function cleanUpPassing(index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].passedCalibration = true;\r\n\r\n  // Inform tests server that all tests passed\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  // Inform analytics server that all tests passed\r\n  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  try {\r\n    await updateFirmware(index);\r\n    await configureHardware(index);\r\n    await startCalibration(index);\r\n    await cleanUpPassing(index);\r\n  } catch (err) {\r\n    indicateFailure(index);\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].passedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].failedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n\r\n    let container = document.getElementById(`client${index}`);\r\n    container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + \'uploads/calibration-controller/online.png)\';\r\n\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          const barcode = value;\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress,\r\n                        secondarySerialNum: barcode,\r\n                        tla: window.selectedProduct.productConfig.tlaNumber\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId,\r\n                          secondarySerialNum: barcode,\r\n                          tla: window.selectedProduct.productConfig.tlaNumber\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  await loadTests(index);\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  let bgImg = \'no-connection\';\r\n                  if (client.connected) {\r\n                    if (client.scannerOnline) {\r\n                      if (client.isCortex) {\r\n                        if(client.passedCalibration) {\r\n                          bgImg = \'passed\';\r\n                        } else if (client.failedCalibration) {\r\n                          bgImg = \'failed\';\r\n                        } else {\r\n                          bgImg = \'online\';\r\n                        }\r\n                      } else {\r\n                        bgImg = \'zoran\';\r\n                      }\r\n                    } else {\r\n                      bgImg = \'offline\';\r\n                    }\r\n                  }\r\n\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + \'uploads/calibration-controller/\' + bgImg + \'.png)\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].passedCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].failedCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates` (`templateId`, `title`, `codeset`, `script`, `active`) VALUES
(4, 'Generic Tests in Test Set', '<style>\r\n  #testList {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 77px);\r\n  }\r\n    .testStep{\r\n      border-top:1px solid rgba(255,255,255,0.2);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 8px 10px;\r\n      cursor: pointer;\r\n    }\r\n  #testActions{\r\n    text-align: right;\r\n    position: fixed;\r\n    bottom: 10px;\r\n    right: 20px;\r\n    width: calc(100vw - 300px);\r\n  }\r\n  #testSetTitle {\r\n    text-align: right;\r\n    font-size: 120%;\r\n    font-weight: bold;\r\n    color:rgba(0,0,0,0.5);\r\n    padding-right: 20px;\r\n  }\r\n  #testWrapper {\r\n    padding-right: 20px;\r\n  }\r\n  .actionBtn {\r\n    display: inline-block;\r\n    border: 1px solid rgba(0,0,0,0.1);\r\n    border-radius: 10px;\r\n    padding: 10px 15px;\r\n    font-weight: bold;\r\n    background-color:#1976d2;\r\n    color: #fff;\r\n    cursor: pointer;\r\n  }\r\n    .actionBtn:hover {\r\n      background-color: #96c997;\r\n      color:#000;\r\n    }\r\n</style>\r\n<div style=\"float:left; background:rgba(128,128,128,0.4); border-right:1px solid rgba(0,0,0,0.1); width: 260px; height:100%;\">\r\n  <div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Test Steps</div>\r\n  <div id=\"testList\"></div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 280px); height:100%;\">\r\n  <div id=\"testSetTitle\"></div>\r\n  <div id=\"testWrapper\"></div>\r\n  <div id=\"testActions\">\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"individualTestMode()\" id=\"individualTestMode\">Switch to Individual Tests</div>\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"sequentialTestMode()\" id=\"sequentialTestMode\">Switch to Sequential Tests</div>\r\n    <div class=\"actionBtn\" onclick=\"reRunTests()\" id=\"reRunTests\">Test Another Device</div>\r\n    <div class=\"actionBtn\" onclick=\"retryTest()\" id=\"retryTest\">Retry Test</div>\r\n    <div class=\"actionBtn\" onclick=\"startTest()\" id=\"startTest\">Start Test</div>\r\n  </div>\r\n</div>', 'async function startTest () {\r\n  let continueProcessing = true;\r\n\r\n  window.gsap.set(\"#startTest\", {display: \"none\"});\r\n\r\n  // Mark test progress\r\n  await markTestProgress ();\r\n\r\n  // Destroy old test script\r\n  const oldScript = document.getElementById(\'testScript\');\r\n  if (oldScript) {\r\n    oldScript.remove();\r\n  }\r\n\r\n  // Determine if it is the start of a production test and if so, start tracking full test set\r\n  if (window.selectedProduct.currentTestIndex === 0 && !window.selectedProduct.individualTestMode) {\r\n    continueProcessing = false;\r\n    const macAdress = await getMacAddress();\r\n\r\n    // Reset local tracking of production test\r\n    window.selectedProduct.productionId = null;\r\n    window.selectedProduct.analyticsProductionId = null;\r\n    window.selectedProduct.analyticsResults = {};\r\n    window.selectedProduct.productionResults = {};\r\n    window.selectedProduct.productionResults.files = {};\r\n\r\n    // Set up start entry in tests database\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"createInitialTrackingEntry\",\r\n          params: {\r\n            productId: window.selectedProduct.productId,\r\n            testSetId: window.selectedProduct.selectedTestSet.testSetId,\r\n            testerName: window.selectedProduct.testerName,\r\n            macAddress: macAdress\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.productionId = response.data.productionId;\r\n\r\n      // Set up start entry in analytics database\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"createInitialTrackingEntry\",\r\n            params: {\r\n              serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n              productId: window.selectedProduct.productId,\r\n              productTitle: window.selectedProduct.productTitle,\r\n              testSetId: window.selectedProduct.selectedTestSet.testSetId,\r\n              testSetTitle: window.selectedProduct.selectedTestSet.title,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAdress,\r\n              productionId: window.selectedProduct.productionId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n      if (analyticsResponse.data.success) {\r\n        window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n      }\r\n    } else {\r\n      promptUser(\'Failed to create production tracking entry\');\r\n    }\r\n  }\r\n\r\n  // Load script\r\n  if (continueProcessing && window.selectedProduct.tests[window.selectedProduct.currentTestIndex]) {\r\n    const script = document.createElement(\'script\');\r\n    script.type = \'text/javascript\';\r\n    script.text = window.selectedProduct.tests[window.selectedProduct.currentTestIndex].script;\r\n    script.id = \'testScript\';\r\n    document.body.appendChild(script);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function markTestProgress () {\r\n  if (!window.selectedProduct.individualTestMode) {\r\n    window.selectedProduct.tests.forEach((test, index) => {\r\n      if (index < window.selectedProduct.currentTestIndex) {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"#b5f5b9\"});\r\n      } else if (index === window.selectedProduct.currentTestIndex) {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"#f1f5b5\"});\r\n      } else {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"rgba(128,128,128,0)\"});\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clearTestProgress () {\r\n  window.selectedProduct.tests.forEach((test, index) => {\r\n    window.gsap.set(`#testStep${index}`, {backgroundColor: \"rgba(128,128,128,0)\"});\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction loadTemplate () {\r\n  return new Promise(resolve => {\r\n    window.gsap.to(\"#testWrapper\", {opacity: 0, duration: 0.2, onComplete: () => {\r\n      document.getElementById(\'testWrapper\').innerHTML = window.selectedProduct.tests[window.selectedProduct.currentTestIndex].codeset;\r\n      window.gsap.to(\"#testWrapper\", {opacity: 1, duration: 0.2, onComplete: () => {\r\n        resolve();\r\n      }});\r\n    }});\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function individualTestMode() {\r\n  window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n  window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n  window.gsap.set(\"#individualTestMode\", {display: \"none\"});\r\n  window.gsap.set(\"#startTest\", {display: \"none\"});\r\n  window.gsap.set(\"#sequentialTestMode\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#sequentialTestMode\", {opacity: 1, duration: 0.2});\r\n  clearTestProgress();\r\n  window.selectedProduct.individualTestMode = true;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function sequentialTestMode() {\r\n  reRunTests();\r\n  window.gsap.set(\"#sequentialTestMode\", {display: \"none\"});\r\n  window.gsap.set(\"#individualTestMode\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#individualTestMode\", {opacity: 1, duration: 0.2});\r\n  window.gsap.set(\"#startTest\", {display: \"inline-block\"});\r\n  window.selectedProduct.individualTestMode = false;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function runSingleTest (testIndex) {\r\n  if (window.selectedProduct.individualTestMode) {\r\n    window.selectedProduct.currentTestIndex = testIndex;\r\n    await loadTemplate();\r\n    window.gsap.set(\"#startTest\", {display: \"inline-block\", opacity: 0});\r\n    window.gsap.to(\"#startTest\", {opacity: 1, duration: 0.2});\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function saveTestAnalytics (testPassed, failMsg) {\r\n  const macAdress = await getMacAddress();\r\n  const extAnalyticsProductionId = window.selectedProduct.individualTestMode ? 0 : window.selectedProduct.analyticsProductionId;\r\n\r\n  if (window.selectedProduct.customError) {\r\n    customError = window.selectedProduct.customError;\r\n  } else {\r\n    customError = \'\';\r\n  }\r\n\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: getElapsedTime(),\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSet.title,\r\n          testTitle: window.selectedProduct.tests[window.selectedProduct.currentTestIndex].title,\r\n          testId: window.selectedProduct.tests[window.selectedProduct.currentTestIndex].testId,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: failMsg,\r\n          customError: (testPassed ? \'\' : customError)\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  // Save analytics\r\n  await saveTestAnalytics(true,\'\');\r\n\r\n  window.Notify.create({\r\n    message: \'Passed \' + window.selectedProduct.tests[window.selectedProduct.currentTestIndex].title + \' test\',\r\n    position: \'top\',\r\n    color: \'positive\'\r\n  });\r\n\r\n  // Advance Forward if in sequential mode\r\n  if (!window.selectedProduct.individualTestMode) {\r\n    if (window.selectedProduct.currentTestIndex < window.selectedProduct.tests.length - 1) {\r\n      window.selectedProduct.currentTestIndex++;\r\n      await markTestProgress ();\r\n      await loadTemplate();\r\n      startTest();\r\n    } else {\r\n      window.selectedProduct.currentTestIndex++;\r\n      await markTestProgress ();\r\n\r\n      // Inform tests server that all tests passed\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"passProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      // Inform analytics server that all tests passed\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"passProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      // Inform user that all tests passed\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div style=\"text-align: center; margin-top: 50px; border:2px solid #008001; padding: 15px; border-radius:15px; font-weight:bold; font-size:140%; color:#008001; background-color:#dbfadb;\">All Tests Passed!</div>\r\n      `;\r\n\r\n      window.gsap.set(\"#reRunTests\", {display: \"inline-block\"});\r\n    }\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  // Prompt user to select fail reason\r\n  // Get product fail reasons\r\n  const failReasonsResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"products\",\r\n        action: \"getProductFailReasons\",\r\n        params: {\r\n          productId: window.selectedProduct.productId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (failReasonsResponse.data.success) {\r\n    window.Dialog.create({\r\n      title: \'Select Fail Reason\',\r\n      html: true,\r\n      message: `\r\n        <div style=\"color:red; font-weight:bold;\">${err}</div>\r\n        Select a fail reason from the list below:\r\n        <select id=\"failReasonSelect\">\r\n        \r\n          ${failReasonsResponse.data.failReasons.map(failReason => {\r\n            return `<option value=\"${failReason.title}\">${failReason.title}</option>`;\r\n          })}\r\n          <option value=\"other\">Other</option>\r\n        </select>\r\n      `\r\n    }).onOk(async () => {\r\n      window.selectedProduct.customError = document.getElementById(\'failReasonSelect\').value;\r\n\r\n      // Save analytics\r\n      await saveTestAnalytics(false, err);\r\n\r\n      window.gsap.set(\"#retryTest\", {display: \"inline-block\"});\r\n    });\r\n  } else {\r\n    window.selectedProduct.customError = \'Other\';\r\n    await promptUser(err);\r\n\r\n    // Save analytics\r\n    await saveTestAnalytics(false, err);\r\n\r\n    window.gsap.set(\"#retryTest\", {display: \"inline-block\"});\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function retryTest() {\r\n  window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n  await loadTemplate();\r\n  startTest();\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function reRunTests () {\r\n  window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n  window.selectedProduct.currentTestIndex = 0;\r\n  window.selectedProduct.productionResults = {};\r\n  window.selectedProduct.productionResults.files = {};\r\n  await markTestProgress ();\r\n  await loadTemplate();\r\n  window.gsap.set(\"#startTest\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#startTest\", {opacity: 1, duration: 0.2});\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    // Set test set title\r\n    document.getElementById(\'testSetTitle\').innerHTML = window.selectedProduct.selectedTestSet.title;\r\n\r\n    // Hide buttons\r\n    window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n    window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n    window.gsap.set(\"#sequentialTestMode\", {display: \"none\"});\r\n\r\n    // Get product config\r\n    const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getProductConfigForTestSet\",\r\n          params: {\r\n            testSetId: window.selectedProduct.selectedTestSet.testSetId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    // Set product config\r\n    if (productCfgResponse.data.success) {\r\n      window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n      // Get the list of tests\r\n      const testResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"testSets\",\r\n            action: \"getTestsForTestSet\",\r\n            params: {\r\n              testSetId: window.selectedProduct.selectedTestSet.testSetId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      if (testResponse.data.success) {\r\n        window.selectedProduct.tests = testResponse.data.tests;\r\n        window.selectedProduct.currentTestIndex = 0;\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        let preprocess = \'\';\r\n        testResponse.data.tests.forEach((test, index) => {\r\n          preprocess += \'<div class=\"testStep\" id=\"testStep\' + index + \'\" onclick=\"runSingleTest(\' + index + \')\">\' + test.title + \'</div>\';\r\n        });\r\n        document.getElementById(\'testList\').innerHTML = preprocess;\r\n\r\n        // Load first test template but don\'t run script until start is clicked\r\n        document.getElementById(\'testWrapper\').innerHTML = window.selectedProduct.tests[0].codeset;\r\n\r\n        window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n      } else {\r\n        promptUser(\'Failed to get any tests\');\r\n      }\r\n    } else {\r\n      promptUser(\'Failed to get the config for this product\');\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(5, 'Generic: Print Labels', '<style>\r\n  #labelWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n  #testSetTitle {\r\n    text-align: right;\r\n    font-size: 120%;\r\n    font-weight: bold;\r\n    color:rgba(0,0,0,0.5);\r\n    padding-right: 20px;\r\n  }\r\n  #instructions {\r\n    margin:10px;\r\n    border:1px solid rgba(0,0,0,0.5);\r\n    border-radius: 10px;\r\n    padding: 20px;\r\n    font-size: 120%;\r\n    font-weight: bold;\r\n  }\r\n  .instructionsHeader {\r\n    margin: 10px;\r\n  }\r\n</style>\r\n<div id=\"labelWrapper\">\r\n  <div id=\"testSetTitle\"></div>\r\n  <div class=\"text-h4 instructionsHeader\">Instructions:</div>\r\n  <div id=\"instructions\">\r\n\r\n  </div>\r\n</div>', '(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n    document.getElementById(\'testSetTitle\').innerHTML = window.selectedProduct.selectedTestSet.title;\r\n\r\n    // Get API script if it exists for this test set\r\n    if (window.selectedProduct.selectedTestSet.extApiId && window.selectedProduct.selectedTestSet.extApiId > 0) {\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"apis\",\r\n            action: \"getApi\",\r\n            params: {\r\n              apiId: window.selectedProduct.selectedTestSet.extApiId\r\n            }\r\n          }\r\n        }, \r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      if(response.data.success) {\r\n        // Destroy old API if exists\r\n        const oldApiScript = document.getElementById(\'apiScript\');\r\n        if (oldApiScript) {\r\n          oldApiScript.remove();\r\n        }\r\n\r\n        // Create new API script\r\n        const apiScript = document.createElement(\'script\');\r\n        apiScript.id = \'apiScript\';\r\n        apiScript.text = response.data.script;\r\n        apiScript.type = \'text/javascript\';\r\n        document.body.appendChild(apiScript);\r\n      }\r\n    }\r\n\r\n    // Destroy self\r\n    const oldScript = document.getElementById(\'templateScript\');\r\n    if (oldScript) {\r\n        oldScript.remove();\r\n    }\r\n\r\n    // Load script\r\n    const script = document.createElement(\'script\');\r\n    script.type = \'text/javascript\';\r\n    script.text = window.selectedProduct.selectedTestSet.script;\r\n    script.id = \'templateScript\';\r\n    document.body.appendChild(script);\r\n\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates` (`templateId`, `title`, `codeset`, `script`, `active`) VALUES
(6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.9);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n      border-radius: 10px;\r\n      box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n    }\r\n    .selected {\r\n      background-color: #aaa;\r\n    }\r\n    .alignBtns {\r\n      text-align: right;\r\n    }\r\n      .alignBtns button{\r\n        margin: 10px;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setBurstAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.burstAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Burst Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = false;\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.horizontalAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Horizontal Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = false;\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkBurstSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.burstAlignment && window.selectedProduct.productionResults.burstAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkHorizontalSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.horizontalAlignment !== null && window.selectedProduct.productionResults.horizontalAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\" class=\"` + checkBurstSelection(62) + `\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\" class=\"` + checkBurstSelection(63) + `\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\" class=\"` + checkBurstSelection(64) + `\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\" class=\"` + checkBurstSelection(65) + `\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\" class=\"` + checkBurstSelection(66) + `\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\" class=\"` + checkBurstSelection(67) + `\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\" class=\"` + checkBurstSelection(68) + `\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\" class=\"` + checkBurstSelection(69) + `\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\" class=\"` + checkBurstSelection(70) + `\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\" class=\"` + checkBurstSelection(71) + `\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\" class=\"` + checkBurstSelection(72) + `\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\" class=\"` + checkBurstSelection(73) + `\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\" class=\"` + checkBurstSelection(74) + `\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\" class=\"` + checkBurstSelection(75) + `\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\" class=\"` + checkBurstSelection(76) + `\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\" class=\"` + checkBurstSelection(77) + `\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\" class=\"` + checkHorizontalSelection(0) + `\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\" class=\"` + checkHorizontalSelection(1) + `\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\" class=\"` + checkHorizontalSelection(2) + `\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\" class=\"` + checkHorizontalSelection(3) + `\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\" class=\"` + checkHorizontalSelection(4) + `\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\" class=\"` + checkHorizontalSelection(5) + `\">5</button></td>\r\n          </tr>\r\n        </table>\r\n        <div class=\"alignBtns\">\r\n          ` + (window.selectedProduct.alignmentNotAdjusted ? \'<button onclick=\"exitAlignment()\">Cannot Align</button><button onclick=\"exitAlignment()\">Alignment Good</button>\' : \'<button onclick=\"testAlignment()\">Print Again</button>\' ) + `\r\n        </div>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#userPrompt\', { display: \'none\' });\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction exitAlignment () {\r\n  window.gsap.set(\'#actionsBar\', { display: \'block\' });\r\n  window.gsap.set(\'#instructions\', { display: \'block\' });\r\n  window.gsap.set(\'#userPrompt\', { display: \'none\' });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = true;\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(7, '7680 Palletize', '<style>\r\n  #palletizeWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #palletizeWrapper #instructions {\r\n      margin: 20px 20px 10px 20px;\r\n      font-weight: bold;\r\n      font-size: 115%;\r\n    }\r\n    #palletizeWrapper #inputFrm {\r\n      margin: 0px 20px 20px 20px;\r\n    }\r\n    #palletizeWrapper #results {\r\n      margin: 0px 20px 0 20px;\r\n    }\r\n  .progressHeading {\r\n    font-weight: bold;\r\n    font-size: 115%;\r\n    text-align: center;\r\n  }\r\n  .progressBar {\r\n    width: 100%;\r\n    height: 20px;\r\n    background-color: #ddd;\r\n  }\r\n  .progressBar div {\r\n    height: 100%;\r\n    background-color: #4CAF50;\r\n    width: 0%;\r\n  }\r\n  .progressDescription {\r\n    text-align: center;\r\n    margin-bottom: 10px;\r\n  }\r\n  .palletItems {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    justify-content: center;\r\n  }\r\n  .palletItems ul{\r\n    list-style-type: none;\r\n    margin: 0;\r\n    padding: 0;\r\n  }\r\n  .palletItems li {\r\n    margin: 5px;\r\n    padding: 5px;\r\n    border: 1px solid #ddd;\r\n    border-radius: 5px;\r\n    background-color: #f1f1f1;\r\n    text-align: center;\r\n    display: inline-block;\r\n    font-size: 80%;\r\n  }\r\n</style>\r\n<div id=\"palletizeWrapper\">\r\n  <div id=\"instructions\"></div>\r\n  <div id=\"inputFrm\"></div>\r\n  <div id=\"results\"></div>\r\n</div>', '\r\nfunction addItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const mainBarcode = document.getElementById(\'mainBarcode\').value;\r\n      const vaultBarcode = document.getElementById(\'vaultBarcode\').value;\r\n\r\n      // Validate barcode matches format\r\n      let regex = /^7680/;\r\n      if (mainBarcode.length !== 14 || !regex.test(mainBarcode)) {\r\n        document.getElementById(\'mainBarcode\').value = \'\';\r\n        throw new Error(\'Invalid main barcode\');\r\n      }\r\n      regex = /^5785/;\r\n      if (vaultBarcode.length !== 14 || !regex.test(vaultBarcode)) {\r\n        document.getElementById(\'vaultBarcode\').value = \'\';\r\n        throw new Error(\'Invalid vault barcode\');\r\n      }\r\n\r\n      // Add item to pallet\r\n      const macAddress = await getMacAddress();\r\n      const item = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'addItem\',\r\n            params: {\r\n              palletId: palletId,\r\n              primarySerialNum: mainBarcode,\r\n              secondarySerialNum: vaultBarcode,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (item.data.success) {\r\n        // Success\r\n        const audio = new Audio(window.selectedProduct.serverUrl + \'/uploads/audio/chirp.mp3\');\r\n        audio.play();\r\n\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(item.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      // Failed\r\n      const audio = new Audio(window.selectedProduct.serverUrl + \'/uploads/audio/alarm.mp3\');\r\n      audio.play();\r\n\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}  \r\n// ---------------------------------------------------------- //\r\nfunction focusOnVault() {\r\n  document.getElementById(\'vaultBarcode\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction buildProgressReport (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Get pallet data\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'progressReport\',\r\n            params: {\r\n              palletId: palletId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        // Build progress report\r\n        let itemsList = \'\';\r\n        pallet.data.items.forEach(item => {\r\n          itemsList += `<li>${item.primarySerialNum}<br/> ${item.secondarySerialNum}</li>`;\r\n        });\r\n\r\n\r\n        document.getElementById(\'results\').innerHTML = `\r\n          <div class=\"progressHeading\">Order Progress</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.orderCurrentQty * 100 / pallet.data.orderTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.orderCurrentQty} / ${pallet.data.orderTargetQty}</div>\r\n\r\n          <div class=\"progressHeading\">Current Pallet</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.palletCurrentQty * 100 / pallet.data.palletTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.palletCurrentQty} / ${pallet.data.palletTargetQty}</div>\r\n\r\n          <div class=\"palletItems\">\r\n            <ul>\r\n              ${itemsList}\r\n            </ul>\r\n          </div>\r\n        `;\r\n      } else {\r\n        throw new Error(\'Could not build progress report\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan main barcode followed by matching vault barcode.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"focusOnVault(); return false;\">\r\n        <input type=\"text\" id=\"mainBarcode\" class=\"form-control\" placeholder=\"Scan Main Barcode\">\r\n        <button type=\"submit\" id=\"submit\" class=\"btn btn-primary\" style=\"opacity:0;\">Submit</button>\r\n      </form>\r\n      <form id=\"barcode2Frm\" onsubmit=\"addItem(${palletId}); return false;\">\r\n        <input type=\"text\" id=\"vaultBarcode\" class=\"form-control\" placeholder=\"Scan Vault Barcode\">\r\n        <button type=\"submit\" id=\"submit2\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'mainBarcode\').focus();\r\n\r\n      // Build progress report\r\n      await buildProgressReport(palletId);\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new pallet format\r\n      const regex = /^806576/; // (remaining digits are the quantity of items)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new pallet\r\n      const macAddress = await getMacAddress();\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createPallet\',\r\n            params: {\r\n              orderId: orderId,\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(pallet.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items to be place on this pallet.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createPallet(${orderId}); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new order format\r\n      const regex = /^798268/; // (remaining digits are the quantity of items in the order)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new order\r\n      const macAddress = await getMacAddress();\r\n      const newOrder = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createOrder\',\r\n            params: {\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (newOrder.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(\'Could not create new order\');\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items in the order.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createOrder(); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findCurrentStep () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Find where at in the palletizing process we are\r\n      const currentStep = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'getStep\',\r\n            params: {}\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (currentStep.data.success) {\r\n        switch (currentStep.data.currentStep) {\r\n          case \'newOrder\':\r\n            await newOrder();\r\n          break;\r\n          case \'newPallet\':\r\n            await newPallet(currentStep.data.currentId);\r\n          break;\r\n          case \'newItem\':\r\n            await newItem(currentStep.data.currentId);\r\n          break;\r\n        }\r\n      } else {\r\n        throw new Error(\'Could not determine current step\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    await findCurrentStep();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(1, '2022-09-27 13:49:57', 3, 'Calibration Controller', '<div>\r\nCalibration Controller\r\n</div>', 'console.log(\'cal\');', 1),
(2, '2022-09-27 13:52:15', 3, 'Calibration Controller v2', '<div>\r\nCalibration Controller\r\n</div>', 'console.log(\'cal\');', 1),
(3, '2022-09-27 16:14:24', 2, 'Generic Multi-Select Test Suites', '<div style=\"float:left; background:rgba(128,128,128,0.4); width: 200px; height:100%;\">\r\n<div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Select a Test</div>\r\n<div id=\"testList\">list</div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 220px); height:100%;\">\r\n<div style=\"border:3px solid rgba(128,128,128,0.4); border-radius:15px; margin:20px 20px 0 0;\">\r\n<div style=\"margin: 15px;\" id=\"testDescription\">\r\nOther side\r\n</div>\r\n</div>\r\n</div>', 'window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\nconsole.log(window.selectedProduct);\r\ndocument.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\ndocument.getElementById(\'testDescription\').innerHTML = window.selectedProduct.subStageInstructions;', 1),
(4, '2022-09-27 16:16:14', 1, 'Show Sub Tests', '', 'async function loadSubStage (subStageId, subStageTitle, subStageInstructions) {\r\n  window.selectedProduct.subStageId = subStageId;\r\n  window.selectedProduct.subStageTitle = subStageTitle;\r\n  window.selectedProduct.subStageInstructions = subStageInstructions;\r\n  let userSelect = document.querySelector(\'#selectTester\');\r\n  window.selectedProduct.testerId = parseInt(userSelect.value);\r\n\r\n  // Clear screen\r\n  window.gsap.to(\"#templateWrapper\", { opacity: 0, duration: 0.2, onComplete: async () => {\r\n    document.getElementById(\'templateWrapper\').innerHTML = \'\';\r\n\r\n    // Load template\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"products\",\r\n          action: \"getSubStageTemplate\",\r\n          params: {\r\n            subStageId: subStageId\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      document.getElementById(\"templateWrapper\").innerHTML = response.data.template;\r\n\r\n      // Destroy self\r\n      const oldScript = document.getElementById(\'templateScript\');\r\n      if (oldScript) {\r\n          oldScript.remove();\r\n      }\r\n\r\n      // Load script\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = response.data.script;\r\n      script.id = \'testScript\';\r\n      document.body.appendChild(script);\r\n    }\r\n  }});\r\n}\r\n\r\nasync function changeTester (testerId) {\r\n  // Save tester name for display\r\n  const testerList = document.getElementById(\'selectTester\');\r\n  const testerName = testerList.options[testerList.selectedIndex].innerHTML;\r\n  window.selectedProduct.testerName = testerName;\r\n  \r\n  const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n    {\r\n      query: {\r\n        dataset: \"products\",\r\n        action: \"getSubStages\",\r\n        params: {\r\n          productId: window.selectedProduct.productId,\r\n          testerId: testerId\r\n        }\r\n      }\r\n    }, \r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  let preProcess = \'\';\r\n\r\n  if (response.data.success) {\r\n    for (let i = 0; i < response.data.subStages.length; i++) {\r\n      if (response.data.subStages[i].authorized) {\r\n        preProcess += `\r\n          <div class=\"productBtn q-mt-md\" onclick=\"loadSubStage(` + response.data.subStages[i].subStageId + `, \'` + response.data.subStages[i].title + `, \'` + response.data.subStages[i].instructions + `\')\">\r\n          <img src=\"` + response.data.subStages[i].imgFilename + `\" style=\"width: 90px; height: 90px; object-fit: contain;\" />` + response.data.subStages[i].title + `</div>\r\n        `;\r\n      } else {\r\n        preProcess += `\r\n          <div class=\"productBtn q-mt-md\" style=\"background-color:#700; color:#fff; cursor: not-allowed; \">\r\n          <img src=\"` + response.data.subStages[i].imgFilename + `\" style=\"width: 90px; height: 90px; object-fit: contain; opacity:0.2;\" /><div style=\"float:left; margin-top:-60px; width:110px;\">Requires Training</div>` + response.data.subStages[i].title + `</div>\r\n        `;\r\n      }\r\n      \r\n    }\r\n  }\r\n\r\n  document.getElementById(\'subStages\').innerHTML = preProcess;\r\n}\r\n\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#templateWrapper\", { opacity: 0 });\r\n\r\n    // Load generic Platform API\r\n    const apiResponse = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 1\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(apiResponse.data.success) {\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = apiResponse.data.script;\r\n      script.id = \'globalApiScript\';\r\n      document.body.appendChild(script);\r\n    \r\n      // Get the product data\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"products\",\r\n            action: \"getProduct\",\r\n            params: {\r\n              productId: window.selectedProduct.productId\r\n            }\r\n          }\r\n        }, \r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      if (response.data.success) {\r\n        document.getElementById(\'toolbarSegment\').innerHTML = response.data.productTitle;\r\n        let preProcess = \'\';\r\n        preProcess += `\r\n          <div class=\"q-pa-md\">\r\n            <label for=\"selectTester\">Tester:</label>\r\n            <select name=\"selectTester\" id=\"selectTester\" onchange=\"changeTester(this.value)\">\r\n              <option value=\"0\">Select Your Name</option>\r\n        `;\r\n\r\n        const testersResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"testers\",\r\n              action: \"getTesters\",\r\n              params: {}\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (testersResponse.data.success) {\r\n          testersResponse.data.testers.forEach(tester => {\r\n            preProcess += \'<option value=\"\' + tester.employeeId + \'\">\' + tester.firstName + \' \' + tester.lastName + \'</option>\';\r\n          });\r\n        }\r\n\r\n        preProcess += `\r\n            </select>\r\n          </div>\r\n          <div id=\"subStages\"></div>\r\n        `;\r\n        \r\n        document.getElementById(\"templateWrapper\").innerHTML = preProcess;\r\n      }\r\n    }\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n\r\n  } catch (err) {\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
