(19, '2022-09-28 14:49:13', 1, 'Generic Show Sub Tests', '', 'async function loadSubStage (subStageId, subStageTitle) {\r\n  window.selectedProduct.subStageId = subStageId;\r\n  window.selectedProduct.subStageTitle = subStageTitle;\r\n  let userSelect = document.querySelector(\'#selectTester\');\r\n  window.selectedProduct.testerId = parseInt(userSelect.value);\r\n\r\n  // Clear screen\r\n  window.gsap.to(\"#templateWrapper\", { opacity: 0, duration: 0.2, onComplete: async () => {\r\n    document.getElementById(\'templateWrapper\').innerHTML = \'\';\r\n\r\n    // Load template\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"products\",\r\n          action: \"getSubStageTemplate\",\r\n          params: {\r\n            subStageId: subStageId\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      document.getElementById(\"templateWrapper\").innerHTML = response.data.template;\r\n\r\n      window.selectedProduct.subStageInstructions = response.data.instructions;\r\n\r\n      // Destroy self\r\n      const oldScript = document.getElementById(\'templateScript\');\r\n      if (oldScript) {\r\n          oldScript.remove();\r\n      }\r\n\r\n      // Load script\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = response.data.script;\r\n      script.id = \'testScript\';\r\n      document.body.appendChild(script);\r\n    }\r\n  }});\r\n}\r\n\r\nasync function changeTester (testerId) {\r\n  // Save tester name for display\r\n  const testerList = document.getElementById(\'selectTester\');\r\n  const testerName = testerList.options[testerList.selectedIndex].innerHTML;\r\n  window.selectedProduct.testerName = testerName;\r\n  \r\n  const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n    {\r\n      query: {\r\n        dataset: \"products\",\r\n        action: \"getSubStages\",\r\n        params: {\r\n          productId: window.selectedProduct.productId,\r\n          testerId: testerId\r\n        }\r\n      }\r\n    }, \r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  let preProcess = \'\';\r\n\r\n  if (response.data.success) {\r\n    for (let i = 0; i < response.data.subStages.length; i++) {\r\n      if (response.data.subStages[i].authorized) {\r\n        preProcess += `\r\n          <div class=\"productBtn q-mt-md\" onclick=\"loadSubStage(` + response.data.subStages[i].subStageId + `, \'` + response.data.subStages[i].title + `\')\">\r\n          <img src=\"` + response.data.subStages[i].imgFilename + `\" style=\"width: 90px; height: 90px; object-fit: contain;\" />` + response.data.subStages[i].title + `</div>\r\n        `;\r\n      } else {\r\n        preProcess += `\r\n          <div class=\"productBtn q-mt-md\" style=\"background-color:#700; color:#fff; cursor: not-allowed; \">\r\n          <img src=\"` + response.data.subStages[i].imgFilename + `\" style=\"width: 90px; height: 90px; object-fit: contain; opacity:0.2;\" /><div style=\"float:left; margin-top:-60px; width:110px;\">Requires Training</div>` + response.data.subStages[i].title + `</div>\r\n        `;\r\n      }\r\n      \r\n    }\r\n  }\r\n\r\n  document.getElementById(\'subStages\').innerHTML = preProcess;\r\n}\r\n\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#templateWrapper\", { opacity: 0 });\r\n\r\n    // Load generic Platform API\r\n    const apiResponse = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 1\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(apiResponse.data.success) {\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = apiResponse.data.script;\r\n      script.id = \'globalApiScript\';\r\n      document.body.appendChild(script);\r\n    \r\n      // Get the product data\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"products\",\r\n            action: \"getProduct\",\r\n            params: {\r\n              productId: window.selectedProduct.productId\r\n            }\r\n          }\r\n        }, \r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      if (response.data.success) {\r\n        document.getElementById(\'toolbarSegment\').innerHTML = response.data.productTitle;\r\n        let preProcess = \'\';\r\n        preProcess += `\r\n          <div class=\"q-pa-md\">\r\n            <label for=\"selectTester\">Tester:</label>\r\n            <select name=\"selectTester\" id=\"selectTester\" onchange=\"changeTester(this.value)\">\r\n              <option value=\"0\">Select Your Name</option>\r\n        `;\r\n\r\n        const testersResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"testers\",\r\n              action: \"getTesters\",\r\n              params: {}\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (testersResponse.data.success) {\r\n          testersResponse.data.testers.forEach(tester => {\r\n            preProcess += \'<option value=\"\' + tester.employeeId + \'\">\' + tester.firstName + \' \' + tester.lastName + \'</option>\';\r\n          });\r\n        }\r\n\r\n        preProcess += `\r\n            </select>\r\n          </div>\r\n          <div id=\"subStages\"></div>\r\n        `;\r\n        \r\n        document.getElementById(\"templateWrapper\").innerHTML = preProcess;\r\n\r\n        // Select drop down element for user\r\n        if (window.selectedProduct.testerId) {\r\n          document.getElementById(\'selectTester\').value = window.selectedProduct.testerId;\r\n        }\r\n      }\r\n    }\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n\r\n  } catch (err) {\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
