rs: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(apiResponse.data.success) {\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = apiResponse.data.script;\r\n      script.id = \'globalApiScript\';\r\n      document.body.appendChild(script);\r\n    \r\n      // Get the product data\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"products\",\r\n            action: \"getProduct\",\r\n            params: {\r\n              productId: window.selectedProduct.productId\r\n            }\r\n          }\r\n        }, \r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      if (response.data.success) {\r\n        document.getElementById(\'toolbarSegment\').innerHTML = response.data.productTitle;\r\n        let preProcess = \'\';\r\n        preProcess += `\r\n          <div class=\"q-pa-md\">\r\n            <label for=\"selectTester\">Tester:</label>\r\n            <select name=\"selectTester\" id=\"selectTester\" onchange=\"changeTester(this.value)\">\r\n              <option value=\"0\">Select Your Name</option>\r\n        `;\r\n\r\n        const testersResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"testers\",\r\n              action: \"getTesters\",\r\n              params: {}\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (testersResponse.data.success) {\r\n          testersResponse.data.testers.forEach(tester => {\r\n            preProcess += \'<option value=\"\' + tester.employeeId + \'\">\' + tester.firstName + \' \' + tester.lastName + \'</option>\';\r\n          });\r\n        }\r\n\r\n        preProcess += `\r\n            </select>\r\n          </div>\r\n          <div id=\"subStages\"></div>\r\n        `;\r\n        \r\n        document.getElementById(\"templateWrapper\").innerHTML = preProcess;\r\n\r\n        // Select drop down element for user\r\n        if (window.global.testerId) {\r\n          document.getElementById(\'selectTester\').value = window.global.testerId;\r\n          changeTester(document.getElementById(\'selectTester\').value);\r\n        }\r\n      }\r\n    }\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(26, '2022-09-28 15:01:17', 2, 'Generic Multi-Select Test Sets', '<div style=\"float:left; background:rgba(128,128,128,0.4); width: 200px; height:100%;\">\r\n  <div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Select a Test</div>\r\n  <div id=\"testList\">list</div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 220px); height:100%;\">\r\n  <div style=\"border:3px solid rgba(128,128,128,0.4); border-radius:15px; margin:20px 20px 0 0;\">\r\n    <div style=\"margin: 15px;\" id=\"testDescription\">\r\n      <div class=\"text-h5\">Instructions:</div>\r\n      <div id=\"instructions\"></div>\r\n      <div id=\"testDescriptionWrapper\" style=\"opacity: 0;\">\r\n        <div class=\"text-h5\">Test Description:</div>\r\n        <div id=\"testDetails\"></div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>', 'window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\nconsole.log(window.selectedProduct);\r\ndocument.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\ndocument.getElementById(\'instructions\').innerHTML = window.selectedProduct.subStageInstructions;\r\n\r\n// Get the list of tests\r\nconst testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n  {\r\n    query: {\r\n      dataset: \"testSets\",\r\n      action: \"getTestSetsForSubStage\",\r\n      params: {\r\n        subStageId: window.selectedProduct.subStageId\r\n      }\r\n    }\r\n  },\r\n  { headers: { \"Content-Type\": \"application/json\" }}\r\n);\r\n\r\nif (testSetResponse.data.success) {\r\n  console.log(testSetResponse.data);\r\n}\r\n\r\nwindow.gsap.to(\"#testDescriptionWrapper\", { opacity: 1, duration: 0.3, delay: 2 });', 1),
