tSetResponse.data.testSets.forEach(testSet => {\r\n        preProcess += \'<div style=\"border-top:1px solid rgba(255,255,255,0.5); border-bottom: 1px solid rgba(0,0,0,0.5); padding:10px; cursor:pointer;\" onclick=\"selectTestSet(\' + testSet.testSetId + \')\">\' + testSet.title + \'</div>\';\r\n      });\r\n      document.getElementById(\'testList\').innerHTML = preProcess;\r\n      window.gsap.to(\"#testList\", { opacity: 1, duration: 0.3 });\r\n    }\r\n\r\n    window.gsap.to(\"#testDescriptionWrapper\", { opacity: 1, duration: 0.3, delay: 2 });\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
