(62, '2022-09-28 16:56:24', 2, 'Generic Multi-Select Test Sets', '<style>\r\n  #testList {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 77px);\r\n  }\r\n  .testSetBtn {\r\n    background-color: rgba(0,0,0,0.1);\r\n    border-top:1px solid rgba(255,255,255,0.5); \r\n    border-bottom: 1px solid rgba(0,0,0,0.5); \r\n    padding:5px; \r\n    cursor:pointer;\r\n    font-size: 90%;\r\n  }\r\n    .testSetBtn:hover {\r\n      background-color: #96c997;\r\n    }\r\n  #testActions{\r\n    text-align: right;\r\n    position: fixed;\r\n    bottom: 10px;\r\n    right: 20px;\r\n    width: calc(100vw - 300px);\r\n  }\r\n  .actionBtn {\r\n    display: inline-block;\r\n    border: 1px solid rgba(0,0,0,0.1);\r\n    border-radius: 10px;\r\n    padding: 10px 15px;\r\n    font-weight: bold;\r\n    background-color:#1976d2;\r\n    color: #fff;\r\n    cursor: pointer;\r\n  }\r\n    .actionBtn:hover {\r\n      background-color: #96c997;\r\n      color:#000;\r\n    }\r\n</style>\r\n<div style=\"float:left; background:rgba(128,128,128,0.4); border-right:1px solid rgba(0,0,0,0.1); width: 260px; height:100%;\">\r\n  <div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Select a Test</div>\r\n  <div id=\"testList\"></div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 280px); height:100%;\">\r\n  <div style=\"border:3px solid rgba(128,128,128,0.4); border-radius:15px; margin:20px 20px 0 0;\">\r\n    <div style=\"margin: 15px;\" id=\"testDescription\">\r\n      <div class=\"text-h5\">Instructions:</div>\r\n      <div id=\"instructions\"></div>\r\n      <div id=\"testDescriptionWrapper\" style=\"opacity: 0;\">\r\n        <div class=\"text-h5\" id=\"testDescriptionHeading\">Test Description:</div>\r\n        <div id=\"testDetails\"></div>\r\n      </div>\r\n      <div id=\"testActions\">\r\n        <div class=\"actionBtn\" onclick=\"loadTestSet()\">Start Test</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>', 'async function selectTestSet (testSetId) {\r\n  window.selectedProduct.selectedTestSet = window.selectedProduct.testSets[testSetId];\r\n  window.gsap.to(\"#testDescriptionWrapper\", { opacity: 0, duration: 0.3, onComplete: () => {\r\n    document.getElementById(\"testDescriptionHeading\").innerHTML = window.selectedProduct.testSets[testSetId].title;\r\n    document.getElementById(\'testDetails\').innerHTML = window.selectedProduct.testSets[testSetId].description;\r\n    window.gsap.to(\"#testDescriptionWrapper\", { opacity: 1, duration: 0.3 });\r\n    window.gsap.to(\"#testActions\", { opacity: 1, duration: 0.3 });\r\n  }});\r\n}\r\n\r\nasync function loadTestSet () {\r\n  console.log(window.selectedProduct);\r\n\r\n  // Clear Screen\r\n  window.gsap.to(\"#templateWrapper\", { opacity: 0, duration: 0.2, onComplete: async () => {\r\n    document.getElementById(\'templateWrapper\').innerHTML = \'\';\r\n\r\n    // Load template\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"templates\",\r\n          action: \"getTemplate\",\r\n          params: {\r\n            templateId: window.selectedProduct.selectedTestSet.extTemplateId\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      document.getElementById(\"templateWrapper\").innerHTML = response.data.template;\r\n\r\n      // Get API script if it exists for this test set\r\n      if (window.selectedProduct.selectedTestSet.extApiId && window.selectedProduct.selectedTestSet.extApiId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n          {\r\n            query: {\r\n              dataset: \"apis\",\r\n              action: \"getApi\",\r\n              params: {\r\n                apiId: window.selectedProduct.selectedTestSet.extApiId\r\n              }\r\n            }\r\n          }, \r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if(response.data.success) {\r\n          // Destroy old API if exists\r\n          const oldApiScript = document.getElementById(\'apiScript\');\r\n          if (oldApiScript) {\r\n            oldApiScript.remove();\r\n          }\r\n\r\n          // Create new API script\r\n          const apiScript = document.createElement(\'script\');\r\n          apiScript.id = \'apiScript\';\r\n          apiScript.text = response.data.script;\r\n          apiScript.type = \'text/javascript\';\r\n          document.body.appendChild(apiScript);\r\n        }\r\n      }\r\n\r\n      // Destroy self\r\n      const oldScript = document.getElementById(\'templateScript\');\r\n      if (oldScript) {\r\n          oldScript.remove();\r\n      }\r\n\r\n      // Load script\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = response.data.script;\r\n      script.id = \'testScript\';\r\n      document.body.appendChild(script);\r\n\r\n    }\r\n  }});\r\n}\r\n\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#testList\", {opacity: 0});\r\n    window.gsap.set(\"#testActions\", {opacity: 0});\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n    document.getElementById(\'instructions\').innerHTML = window.selectedProduct.subStageInstructions;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if (testSetResponse.data.success) {\r\n      window.selectedProduct.testSets = {};\r\n      let preProcess = \'\';\r\n      testSetResponse.data.testSets.forEach(testSet => {\r\n        window.selectedProduct.testSets[testSet.testSetId] = testSet;\r\n        preProcess += \'<div class=\"testSetBtn\" style=\"border-top:1px solid rgba(255,255,255,0.5); border-bottom: 1px solid rgba(0,0,0,0.5); padding:10px; cursor:pointer;\" onclick=\"selectTestSet(\' + testSet.testSetId + \' )\">\' + testSet.title + \'</div>\';\r\n      });\r\n      document.getElementById(\'testList\').innerHTML = preProcess;\r\n      window.gsap.to(\"#testList\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(63, '2022-09-28 17:00:34', 1, 'Generic Show Sub Stages', '', 'async function loadSubStage (subStageId, subStageTitle) {\r\n  window.selectedProduct.subStageId = subStageId;\r\n  window.selectedProduct.subStageTitle = subStageTitle;\r\n  let userSelect = document.querySelector(\'#selectTester\');\r\n  window.selectedProduct.testerId = parseInt(userSelect.value);\r\n  window.global.testerId = parseInt(userSelect.value);\r\n\r\n  // Clear screen\r\n  window.gsap.to(\"#templateWrapper\", { opacity: 0, duration: 0.2, onComplete: async () => {\r\n    document.getElementById(\'templateWrapper\').innerHTML = \'\';\r\n\r\n    // Load template\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"products\",\r\n          action: \"getSubStageTemplate\",\r\n          params: {\r\n            subStageId: subStageId\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      document.getElementById(\"templateWrapper\").innerHTML = response.data.template;\r\n\r\n      window.selectedProduct.subStageInstructions = response.data.instructions;\r\n\r\n      // Destroy self\r\n      const oldScript = document.getElementById(\'templateScript\');\r\n      if (oldScript) {\r\n          oldScript.remove();\r\n      }\r\n\r\n      // Load script\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = response.data.script;\r\n      script.id = \'templateScript\';\r\n      document.body.appendChild(script);\r\n    }\r\n  }});\r\n}\r\n\r\nasync function changeTester (testerId) {\r\n  // Save tester name for display\r\n  const testerList = document.getElementById(\'selectTester\');\r\n  const testerName = testerList.options[testerList.selectedIndex].innerHTML;\r\n  window.selectedProduct.testerName = testerName;\r\n  \r\n  const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n    {\r\n      query: {\r\n        dataset: \"products\",\r\n        action: \"getSubStages\",\r\n        params: {\r\n          productId: window.selectedProduct.productId,\r\n          testerId: testerId\r\n        }\r\n      }\r\n    }, \r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  let preProcess = \'\';\r\n\r\n  if (response.data.success) {\r\n    for (let i = 0; i < response.data.subStages.length; i++) {\r\n      if (response.data.subStages[i].authorized) {\r\n        preProcess += `\r\n          <div class=\"productBtn q-mt-md\" onclick=\"loadSubStage(` + response.data.subStages[i].subStageId + `, \'` + response.data.subStages[i].title + `\')\">\r\n          <img src=\"` + response.data.subStages[i].imgFilename + `\" style=\"width: 90px; height: 90px; object-fit: contain;\" />` + response.data.subStages[i].title + `</div>\r\n        `;\r\n      } else {\r\n        preProcess += `\r\n          <div class=\"productBtn q-mt-md\" style=\"background-color:#700; color:#fff; cursor: not-allowed; \">\r\n          <img src=\"` + response.data.subStages[i].imgFilename + `\" style=\"width: 90px; height: 90px; object-fit: contain; opacity:0.2;\" /><div style=\"float:left; margin-top:-60px; width:110px;\">Requires Training</div>` + response.data.subStages[i].title + `</div>\r\n        `;\r\n      }\r\n      \r\n    }\r\n  }\r\n\r\n  document.getElementById(\'subStages\').innerHTML = preProcess;\r\n}\r\n\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#templateWrapper\", { opacity: 0 });\r\n\r\n    if(!window.global) {\r\n      window.global = {};\r\n    }\r\n\r\n    // Load generic Platform API\r\n    const apiResponse = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 1\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(apiResponse.data.success) {\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = apiResponse.data.script;\r\n      script.id = \'globalApiScript\';\r\n      document.body.appendChild(script);\r\n    \r\n      // Get the product data\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"products\",\r\n            action: \"getProduct\",\r\n            params: {\r\n              productId: window.selectedProduct.productId\r\n            }\r\n          }\r\n        }, \r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      if (response.data.success) {\r\n        document.getElementById(\'toolbarSegment\').innerHTML = response.data.productTitle;\r\n        let preProcess = \'\';\r\n        preProcess += `\r\n          <div class=\"q-pa-md\">\r\n            <label for=\"selectTester\">Tester:</label>\r\n            <select name=\"selectTester\" id=\"selectTester\" onchange=\"changeTester(this.value)\">\r\n              <option value=\"0\">Select Your Name</option>\r\n        `;\r\n\r\n        const testersResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"testers\",\r\n              action: \"getTesters\",\r\n              params: {}\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (testersResponse.data.success) {\r\n          testersResponse.data.testers.forEach(tester => {\r\n            preProcess += \'<option value=\"\' + tester.employeeId + \'\">\' + tester.firstName + \' \' + tester.lastName + \'</option>\';\r\n          });\r\n        }\r\n\r\n        preProcess += `\r\n            </select>\r\n          </div>\r\n          <div id=\"subStages\"></div>\r\n        `;\r\n        \r\n        document.getElementById(\"templateWrapper\").innerHTML = preProcess;\r\n\r\n        // Select drop down element for user\r\n        if (window.global.testerId) {\r\n          document.getElementById(\'selectTester\').value = window.global.testerId;\r\n          changeTester(document.getElementById(\'selectTester\').value);\r\n        }\r\n      }\r\n    }\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(64, '2022-09-28 17:01:09', 2, 'Generic Multi-Select Test Sets', '<style>\r\n  #testList {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 77px);\r\n  }\r\n  .testSetBtn {\r\n    background-color: rgba(0,0,0,0.1);\r\n    border-top:1px solid rgba(255,255,255,0.5); \r\n    border-bottom: 1px solid rgba(0,0,0,0.5); \r\n    padding:5px; \r\n    cursor:pointer;\r\n    font-size: 90%;\r\n  }\r\n    .testSetBtn:hover {\r\n      background-color: #96c997;\r\n    }\r\n  #testActions{\r\n    text-align: right;\r\n    position: fixed;\r\n    bottom: 10px;\r\n    right: 20px;\r\n    width: calc(100vw - 300px);\r\n  }\r\n  .actionBtn {\r\n    display: inline-block;\r\n    border: 1px solid rgba(0,0,0,0.1);\r\n    border-radius: 10px;\r\n    padding: 10px 15px;\r\n    font-weight: bold;\r\n    background-color:#1976d2;\r\n    color: #fff;\r\n    cursor: pointer;\r\n  }\r\n    .actionBtn:hover {\r\n      background-color: #96c997;\r\n      color:#000;\r\n    }\r\n</style>\r\n<div style=\"float:left; background:rgba(128,128,128,0.4); border-right:1px solid rgba(0,0,0,0.1); width: 260px; height:100%;\">\r\n  <div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Select a Test</div>\r\n  <div id=\"testList\"></div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 280px); height:100%;\">\r\n  <div style=\"border:3px solid rgba(128,128,128,0.4); border-radius:15px; margin:20px 20px 0 0;\">\r\n    <div style=\"margin: 15px;\" id=\"testDescription\">\r\n      <div class=\"text-h5\">Instructions:</div>\r\n      <div id=\"instructions\"></div>\r\n      <div id=\"testDescriptionWrapper\" style=\"opacity: 0;\">\r\n        <div class=\"text-h5\" id=\"testDescriptionHeading\">Test Description:</div>\r\n        <div id=\"testDetails\"></div>\r\n      </div>\r\n      <div id=\"testActions\">\r\n        <div class=\"actionBtn\" onclick=\"loadTestSet()\">Start Test</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>', 'async function selectTestSet (testSetId) {\r\n  window.selectedProduct.selectedTestSet = window.selectedProduct.testSets[testSetId];\r\n  window.gsap.to(\"#testDescriptionWrapper\", { opacity: 0, duration: 0.3, onComplete: () => {\r\n    document.getElementById(\"testDescriptionHeading\").innerHTML = window.selectedProduct.testSets[testSetId].title;\r\n    document.getElementById(\'testDetails\').innerHTML = window.selectedProduct.testSets[testSetId].description;\r\n    window.gsap.to(\"#testDescriptionWrapper\", { opacity: 1, duration: 0.3 });\r\n    window.gsap.to(\"#testActions\", { opacity: 1, duration: 0.3 });\r\n  }});\r\n}\r\n\r\nasync function loadTestSet () {\r\n  console.log(window.selectedProduct);\r\n\r\n  // Clear Screen\r\n  window.gsap.to(\"#templateWrapper\", { opacity: 0, duration: 0.2, onComplete: async () => {\r\n    document.getElementById(\'templateWrapper\').innerHTML = \'\';\r\n\r\n    // Load template\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"templates\",\r\n          action: \"getTemplate\",\r\n          params: {\r\n            templateId: window.selectedProduct.selectedTestSet.extTemplateId\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      document.getElementById(\"templateWrapper\").innerHTML = response.data.template;\r\n\r\n      // Get API script if it exists for this test set\r\n      if (window.selectedProduct.selectedTestSet.extApiId && window.selectedProduct.selectedTestSet.extApiId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n          {\r\n            query: {\r\n              dataset: \"apis\",\r\n              action: \"getApi\",\r\n              params: {\r\n                apiId: window.selectedProduct.selectedTestSet.extApiId\r\n              }\r\n            }\r\n          }, \r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if(response.data.success) {\r\n          // Destroy old API if exists\r\n          const oldApiScript = document.getElementById(\'apiScript\');\r\n          if (oldApiScript) {\r\n            oldApiScript.remove();\r\n          }\r\n\r\n          // Create new API script\r\n          const apiScript = document.createElement(\'script\');\r\n          apiScript.id = \'apiScript\';\r\n          apiScript.text = response.data.script;\r\n          apiScript.type = \'text/javascript\';\r\n          document.body.appendChild(apiScript);\r\n        }\r\n      }\r\n\r\n      // Destroy self\r\n      const oldScript = document.getElementById(\'templateScript\');\r\n      if (oldScript) {\r\n          oldScript.remove();\r\n      }\r\n\r\n      // Load script\r\n      const script = document.createElement(\'script\');\r\n      script.type = \'text/javascript\';\r\n      script.text = response.data.script;\r\n      script.id = \'templateScript\';\r\n      document.body.appendChild(script);\r\n\r\n    }\r\n  }});\r\n}\r\n\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#testList\", {opacity: 0});\r\n    window.gsap.set(\"#testActions\", {opacity: 0});\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n    document.getElementById(\'instructions\').innerHTML = window.selectedProduct.subStageInstructions;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if (testSetResponse.data.success) {\r\n      window.selectedProduct.testSets = {};\r\n      let preProcess = \'\';\r\n      testSetResponse.data.testSets.forEach(testSet => {\r\n        window.selectedProduct.testSets[testSet.testSetId] = testSet;\r\n        preProcess += \'<div class=\"testSetBtn\" style=\"border-top:1px solid rgba(255,255,255,0.5); border-bottom: 1px solid rgba(0,0,0,0.5); padding:10px; cursor:pointer;\" onclick=\"selectTestSet(\' + testSet.testSetId + \' )\">\' + testSet.title + \'</div>\';\r\n      });\r\n      document.getElementById(\'testList\').innerHTML = preProcess;\r\n      window.gsap.to(\"#testList\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
