(112, '2022-09-29 14:11:26', 4, 'Generic Tests in Test Set', '<style>\r\n  #testList {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 77px);\r\n  }\r\n    .testStep{\r\n      border-top:1px solid rgba(255,255,255,0.2);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n      cursor: not-allowed;\r\n    }\r\n  #testActions{\r\n    text-align: right;\r\n    position: fixed;\r\n    bottom: 10px;\r\n    right: 20px;\r\n    width: calc(100vw - 300px);\r\n  }\r\n  #testSetTitle {\r\n    text-align: right;\r\n    font-size: 120%;\r\n    font-weight: bold;\r\n    color:rgba(0,0,0,0.5);\r\n    padding-right: 20px;\r\n  }\r\n  #testWrapper {\r\n    padding-right: 20px;\r\n  }\r\n  .actionBtn {\r\n    display: inline-block;\r\n    border: 1px solid rgba(0,0,0,0.1);\r\n    border-radius: 10px;\r\n    padding: 10px 15px;\r\n    font-weight: bold;\r\n    background-color:#1976d2;\r\n    color: #fff;\r\n    cursor: pointer;\r\n  }\r\n    .actionBtn:hover {\r\n      background-color: #96c997;\r\n      color:#000;\r\n    }\r\n</style>\r\n<div style=\"float:left; background:rgba(128,128,128,0.4); border-right:1px solid rgba(0,0,0,0.1); width: 260px; height:100%;\">\r\n  <div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Test Steps</div>\r\n  <div id=\"testList\"></div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 280px); height:100%;\">\r\n  <div id=\"testSetTitle\"></div>\r\n  <div id=\"testWrapper\"></div>\r\n  <div id=\"testActions\">\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"individualTestMode()\" id=\"individualTestMode\">Switch to Individual Tests</div>\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"sequentialTestMode()\" id=\"sequentialTestMode\">Switch to Sequential Tests</div>\r\n    <div class=\"actionBtn\" onclick=\"reRunTests()\" id=\"reRunTests\">Test Another Device</div>\r\n    <div class=\"actionBtn\" onclick=\"retryTest()\" id=\"retryTest\">Retry Test</div>\r\n    <div class=\"actionBtn\" onclick=\"startTest()\" id=\"startTest\">Start Test</div>\r\n  </div>\r\n</div>', 'async function startTest () {\r\n  window.gsap.set(\"#startTest\", {display: \"none\"});\r\n\r\n  // Mark test progress\r\n  await markTestProgress ();\r\n\r\n  // Destroy old test script\r\n  const oldScript = document.getElementById(\'testScript\');\r\n  if (oldScript) {\r\n    oldScript.remove();\r\n  }\r\n\r\n  // Load script\r\n  if (window.selectedProduct.tests[window.selectedProduct.currentTestIndex]) {\r\n    const script = document.createElement(\'script\');\r\n    script.type = \'text/javascript\';\r\n    script.text = window.selectedProduct.tests[window.selectedProduct.currentTestIndex].script;\r\n    script.id = \'testScript\';\r\n    document.body.appendChild(script);\r\n  }\r\n}\r\n\r\nasync function markTestProgress () {\r\n  window.selectedProduct.tests.forEach((test, index) => {\r\n    if (index < window.selectedProduct.currentTestIndex) {\r\n      window.gsap.set(`#testStep${index}`, {backgroundColor: \"#b5f5b9\"});\r\n    } else if (index === window.selectedProduct.currentTestIndex) {\r\n      window.gsap.set(`#testStep${index}`, {backgroundColor: \"#f1f5b5\"});\r\n    } else {\r\n      window.gsap.set(`#testStep${index}`, {backgroundColor: \"rgba(128,128,128,0)\"});\r\n    }\r\n  });\r\n}\r\n\r\nfunction loadTemplate () {\r\n  return new Promise(resolve => {\r\n    window.gsap.to(\"#testWrapper\", {opacity: 0, duration: 0.2, onComplete: () => {\r\n      document.getElementById(\'testWrapper\').innerHTML = window.selectedProduct.tests[window.selectedProduct.currentTestIndex].codeset;\r\n      window.gsap.to(\"#testWrapper\", {opacity: 1, duration: 0.2, onComplete: () => {\r\n        resolve();\r\n      }});\r\n    }});\r\n  });\r\n}\r\n\r\nasync function individualTestMode() {\r\n  console.log(\"individualTestMode\");\r\n  window.gsap.set(\"#individualTestMode\", {display: \"none\"});\r\n  window.gsap.set(\"#startTest\", {display: \"none\"});\r\n  window.gsap.set(\"#sequentialTestMode\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#sequentialTestMode\", {opacity: 1, duration: 0.2});\r\n}\r\n\r\nasync function sequentialTestMode() {\r\n  console.log(\"sequentialTestMode\");\r\n  window.gsap.set(\"#sequentialTestMode\", {display: \"none\"});\r\n  window.gsap.set(\"#individualTestMode\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#individualTestMode\", {opacity: 1, duration: 0.2});\r\n  window.gsap.set(\"#startTest\", {display: \"inline-block\"});\r\n}\r\n\r\nasync function passTest () {\r\n  if (window.selectedProduct.currentTestIndex < window.selectedProduct.tests.length - 1) {\r\n    window.selectedProduct.currentTestIndex++;\r\n    await markTestProgress ();\r\n    await loadTemplate();\r\n    startTest();\r\n  } else {\r\n    window.selectedProduct.currentTestIndex++;\r\n    await markTestProgress ();\r\n    window.gsap.set(\"#reRunTests\", {display: \"inline-block\"});\r\n    console.log(\'all passed\');\r\n  }\r\n}\r\n\r\nasync function failTest () {\r\n  console.log(\"failTest\");\r\n  window.gsap.set(\"#retryTest\", {display: \"inline-block\"});\r\n}\r\n\r\nasync function retryTest() {\r\n  window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n  await loadTemplate();\r\n  startTest();\r\n}\r\n\r\nasync function reRunTests () {\r\n  window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n  window.selectedProduct.currentTestIndex = 0;\r\n  await markTestProgress ();\r\n  await loadTemplate();\r\n  window.gsap.set(\"#startTest\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#startTest\", {opacity: 1, duration: 0.2});\r\n}\r\n\r\n(async () => {\r\n  try {\r\n    // Set test set title\r\n    document.getElementById(\'testSetTitle\').innerHTML = window.selectedProduct.selectedTestSet.title;\r\n\r\n    // Hide buttons\r\n    window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n    window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n    window.gsap.set(\"#sequentialTestMode\", {display: \"none\"});\r\n\r\n    // Get the list of tests\r\n    const testResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: window.selectedProduct.selectedTestSet.testSetId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if (testResponse.data.success) {\r\n      window.selectedProduct.tests = testResponse.data.tests;\r\n      window.selectedProduct.currentTestIndex = 0;\r\n\r\n      let preprocess = \'\';\r\n      testResponse.data.tests.forEach((test, index) => {\r\n        preprocess += \'<div class=\"testStep\" id=\"testStep\' + index + \'\">\' + test.title + \'</div>\';\r\n      });\r\n      document.getElementById(\'testList\').innerHTML = preprocess;\r\n\r\n      // Load first test template but don\'t run script until start is clicked\r\n      document.getElementById(\'testWrapper\').innerHTML = window.selectedProduct.tests[0].codeset;\r\n\r\n      window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
