(165, '2022-10-05 21:06:18', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n</div>', '(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      console.log(testSetResponse.data);\r\n    }\r\n\r\n    console.log(window.selectedProduct);\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(166, '2022-10-05 21:14:25', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n</div>', '(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      console.log(testSetResponse.data);\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\">\';\r\n      foreach(testSetResponse.data.testSets as testSet) {\r\n        preProcess += \'<option value=\"\' + testSet.testSetId + \'\">\' + testSet.title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n\r\n    console.log(window.selectedProduct);\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(167, '2022-10-05 21:16:45', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n</div>', '(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      console.log(testSetResponse.data);\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\">\';\r\n      testSetResponse.data.testSets.foreach(testSet => {\r\n        preProcess += \'<option value=\"\' + testSet.testSetId + \'\">\' + testSet.title + \'</option>\';\r\n      });\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n\r\n    console.log(window.selectedProduct);\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
