oduct.calibrationClients[index].connection);\r\n            await window.selectedProduct.calibrationClients[index].connection.request(\'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n              console.log(response);\r\n              window.selectedProduct.calibrationClients[index].readyForCommand = true;\r\n            })\r\n          }\r\n        } else {\r\n          // Attempt connection\r\n          console.log(\"client not connected\", client);\r\n          window.selectedProduct.calibrationClients[index].connection = await window.messenger.createSpeaker(client.ipAddress + \':2600\');\r\n          window.selectedProduct.calibrationClients[index].connected = true;\r\n          window.selectedProduct.calibrationClients[index].readyForCommand = true;\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += \'<div class=\"clientItem\" onclick=\"clientSelected(\' + i + \')\">\' + clientResponse.data.clients[i].title + \'</div>\';\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      console.log(window.selectedProduct.calibrationClients);\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
