(227, '2022-10-06 22:50:10', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n    window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n    console.log(window.selectedProduct.calibrationClients[index]);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (client.readyForCommand) {\r\n          if (!client.responsePending) {\r\n            client.responsePending = true;\r\n            window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n              client.responsePending = false;\r\n              console.log(response);\r\n              if (response.error === \'-1\') {\r\n                console.log(\'hit\');\r\n                client.connected = false;\r\n                client.scannerIsCortex = false;\r\n                client.scannerOnline = false;\r\n                client.sensorStatus = 0;\r\n              } else {\r\n                client.connected = true;\r\n                client.scannerOnline = response.online;\r\n                if (response.online) {\r\n                  client.isCortex = response.scannerIsCortex;\r\n                  client.sensorStatus = response.status.ub_sens;\r\n                } else {\r\n                  client.isCortex = false;\r\n                  client.sensorStatus = 0;\r\n                }\r\n              }\r\n            })\r\n          }\r\n        } else {\r\n          // Attempt connection\r\n          window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n          client.readyForCommand = true;\r\n          client.responsePending = false;\r\n        }\r\n\r\n        //Update UI\r\n        console.log(client.connected, client.scannerOnline, client.sensorStatus);\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 200);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `<div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\"><div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div></div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(228, '2022-10-06 22:52:08', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n    window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n    console.log(window.selectedProduct.calibrationClients[index]);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (client.readyForCommand) {\r\n          if (!client.responsePending) {\r\n            client.responsePending = true;\r\n            window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n              client.responsePending = false;\r\n              console.log(response);\r\n              if (response.error === \'-1\') {\r\n                console.log(\'hit\');\r\n                client.connected = false;\r\n                client.scannerIsCortex = false;\r\n                client.scannerOnline = false;\r\n                client.sensorStatus = 0;\r\n              } else {\r\n                client.connected = true;\r\n                client.scannerOnline = response.online;\r\n                if (response.online) {\r\n                  client.isCortex = response.scannerIsCortex;\r\n                  client.sensorStatus = response.status.ub_sens;\r\n                } else {\r\n                  client.isCortex = false;\r\n                  client.sensorStatus = 0;\r\n                }\r\n              }\r\n\r\n              //Update UI\r\n              console.log(client.connected, client.scannerOnline, client.sensorStatus);\r\n            })\r\n          }\r\n        } else {\r\n          // Attempt connection\r\n          window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n          client.readyForCommand = true;\r\n          client.responsePending = false;\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 200);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `<div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\"><div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div></div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(229, '2022-10-06 22:55:34', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n    window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n    console.log(window.selectedProduct.calibrationClients[index]);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (client.readyForCommand) {\r\n          client.readyForCommand = false;\r\n          if (!client.responsePending) {\r\n            client.responsePending = true;\r\n            window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n              client.responsePending = false;\r\n              console.log(response);\r\n              if (response.error === \'-1\') {\r\n                console.log(\'hit\');\r\n                client.connected = false;\r\n                client.scannerIsCortex = false;\r\n                client.scannerOnline = false;\r\n                client.sensorStatus = 0;\r\n              } else {\r\n                client.connected = true;\r\n                client.scannerOnline = response.online;\r\n                if (response.online) {\r\n                  client.isCortex = response.scannerIsCortex;\r\n                  client.sensorStatus = response.status.ub_sens;\r\n                } else {\r\n                  client.isCortex = false;\r\n                  client.sensorStatus = 0;\r\n                }\r\n              }\r\n\r\n              //Update UI\r\n              console.log(client.connected, client.scannerOnline, client.sensorStatus);\r\n            })\r\n          }\r\n        } else {\r\n          // Attempt connection\r\n          window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n          client.readyForCommand = true;\r\n          client.responsePending = false;\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 200);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `<div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\"><div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div></div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
