ess) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                console.log(\'productConfig\', window.selectedProduct.productConfig);\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// --------------------------------------------------------