n            if (!client.responsePending) {\r\n              client.responsePending = true;\r\n\r\n              window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                client.responsePending = false;\r\n                if (response.error === -1) {\r\n                  client.connected = false;\r\n                  client.scannerIsCortex = false;\r\n                  client.scannerOnline = false;\r\n                  client.sensorStatus = 0;\r\n                  client.reconnectCountdown = 5;\r\n                } else {\r\n                  client.connected = true;\r\n                  client.scannerOnline = response.online;\r\n                  if (response.online) {\r\n                    client.isCortex = response.scannerIsCortex;\r\n                    client.sensorStatus = response.status.ub_sens;\r\n                  } else {\r\n                    client.isCortex = false;\r\n                    client.sensorStatus = 0;\r\n                  }\r\n                }\r\n\r\n                //Update UI\r\n                //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                let container = document.getElementById(`client${index}`);\r\n                container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                redrawSensorStatus(index);\r\n              })\r\n            }\r\n          }\r\n        } else {\r\n          \r\n            // Attempt connection\r\n            window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n            client.readyForCommand = true;\r\n            client.responsePending = false;\r\n          \r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(276, '2022-10-07 02:31:28', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n    window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n                  console.log(window.selectedProduct.calibrationClients);\r\n                  \r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (client.readyForCommand && !client.inCalibration) {\r\n          if (client.reconnectCountdown) {\r\n            client.reconnectCountdown--;\r\n          } else {\r\n            client.readyForCommand = false;\r\n            if (!client.responsePending) {\r\n              client.responsePending = true;\r\n\r\n              window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                client.responsePending = false;\r\n                if (response.error === -1) {\r\n                  client.connected = false;\r\n                  client.scannerIsCortex = false;\r\n                  client.scannerOnline = false;\r\n                  client.sensorStatus = 0;\r\n                  client.reconnectCountdown = 5;\r\n                } else {\r\n                  client.connected = true;\r\n                  client.scannerOnline = response.online;\r\n                  if (response.online) {\r\n                    client.isCortex = response.scannerIsCortex;\r\n                    client.sensorStatus = response.status.ub_sens;\r\n                  } else {\r\n                    client.isCortex = false;\r\n                    client.sensorStatus = 0;\r\n                  }\r\n                }\r\n\r\n                //Update UI\r\n                //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                let container = document.getElementById(`client${index}`);\r\n                container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                redrawSensorStatus(index);\r\n              })\r\n            }\r\n          }\r\n        } else {\r\n          \r\n            // Attempt connection\r\n            window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n            client.readyForCommand = true;\r\n            client.responsePending = false;\r\n          \r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
