                  {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  loadTests(index);\r\n\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (client.readyForCommand && !client.inCalibration) {\r\n          if (client.reconnectCountdown) {\r\n            client.reconnectCountdown--;\r\n          } else {\r\n            client.readyForCommand = false;\r\n            if (!client.responsePending) {\r\n              client.responsePending = true;\r\n\r\n              window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                client.responsePending = false;\r\n                if (response.error === -1) {\r\n                  client.connected = false;\r\n                  client.scannerIsCortex = false;\r\n                  client.scannerOnline = false;\r\n                  client.sensorStatus = 0;\r\n                  client.reconnectCountdown = 5;\r\n                } else {\r\n                  client.connected = true;\r\n                  client.scannerOnline = response.online;\r\n                  if (response.online) {\r\n                    client.isCortex = response.scannerIsCortex;\r\n                    client.sensorStatus = response.status.ub_sens;\r\n                  } else {\r\n                    client.isCortex = false;\r\n                    client.sensorStatus = 0;\r\n                  }\r\n                }\r\n\r\n                //Update UI\r\n                //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                let container = document.getElementById(`client${index}`);\r\n                container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                redrawSensorStatus(index);\r\n              })\r\n            }\r\n          }\r\n        } else {\r\n          \r\n            // Attempt connection\r\n            window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n            client.readyForCommand = true;\r\n            client.responsePending = false;\r\n          \r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(292, '2022-10-10 15:49:11', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n  } catch (err) {\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  loadTests(index);\r\n\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(293, '2022-10-10 19:13:38', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n  } catch (err) {\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  loadTests(index);\r\n\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(294, '2022-10-10 19:18:49', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.3);\r\n    height: 180px;\r\n    position: relative;\r\n    top: -180px;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n  } catch (err) {\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  loadTests(index);\r\n\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(295, '2022-10-10 19:20:50', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.3);\r\n    height: 170px;\r\n    position: relative;\r\n    top: 0px;\r\n    display: none;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n  } catch (err) {\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  loadTests(index);\r\n\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(296, '2022-10-10 19:26:08', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n    position:relative;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.7);\r\n    height: 170px;\r\n    position: absolute;\r\n    top: 30px;\r\n    padding-top:50px;\r\n    font-weight: bold;\r\n    color:#fff;\r\n    display: none;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n  } catch (err) {\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  loadTests(index);\r\n\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(297, '2022-10-11 01:02:40', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n    position:relative;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.7);\r\n    height: 170px;\r\n    position: absolute;\r\n    top: 30px;\r\n    padding-top:50px;\r\n    font-weight: bold;\r\n    color:#fff;\r\n    display: none;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n    await configureHardware(index);\r\n  } catch (err) {\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  loadTests(index);\r\n\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(298, '2022-10-11 01:41:39', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n    position:relative;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.7);\r\n    height: 170px;\r\n    position: absolute;\r\n    top: 30px;\r\n    padding-top:50px;\r\n    font-weight: bold;\r\n    color:#fff;\r\n    display: none;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n    await configureHardware(index);\r\n  } catch (err) {\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          const barcode = value;\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress,\r\n                        secondarySerialNum: barcode\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId,\r\n                          secondarySerialNum: barcode\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  loadTests(index);\r\n\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(299, '2022-10-11 02:00:16', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n    position:relative;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.7);\r\n    height: 170px;\r\n    position: absolute;\r\n    top: 30px;\r\n    padding-top:50px;\r\n    font-weight: bold;\r\n    color:#fff;\r\n    display: none;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n    await configureHardware(index);\r\n    await startCalibration(index);\r\n  } catch (err) {\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          const barcode = value;\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress,\r\n                        secondarySerialNum: barcode\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId,\r\n                          secondarySerialNum: barcode\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  loadTests(index);\r\n\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(300, '2022-10-11 02:10:00', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n    position:relative;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.7);\r\n    height: 170px;\r\n    position: absolute;\r\n    top: 30px;\r\n    padding-top:50px;\r\n    font-weight: bold;\r\n    color:#fff;\r\n    display: none;\r\n    width: 198px;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n    await configureHardware(index);\r\n    await startCalibration(index);\r\n  } catch (err) {\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          const barcode = value;\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress,\r\n                        secondarySerialNum: barcode\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId,\r\n                          secondarySerialNum: barcode\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  loadTests(index);\r\n\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(301, '2022-10-11 16:32:22', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n    position:relative;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.7);\r\n    height: 170px;\r\n    position: absolute;\r\n    top: 30px;\r\n    padding-top:50px;\r\n    font-weight: bold;\r\n    color:#fff;\r\n    display: none;\r\n    width: 198px;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function indicateFailure (index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].failedCalibration = true;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function cleanUpPassing(index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].passedCalibration = true;\r\n\r\n  // Inform tests server that all tests passed\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  // Inform analytics server that all tests passed\r\n  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n    await configureHardware(index);\r\n    await startCalibration(index);\r\n    await cleanUpPassing(index);\r\n  } catch (err) {\r\n    indicateFailure(index);\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].passedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].failedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          const barcode = value;\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress,\r\n                        secondarySerialNum: barcode\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId,\r\n                          secondarySerialNum: barcode\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  await loadTests(index);\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  //console.log(\'Pi\', client.connected, \'Scanner\', client.scannerOnline, \'Sensors\', client.sensorStatus);\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + (client.connected ? (client.scannerOnline ? (client.isCortex ? \'uploads/calibration-controller/online.png\' : \'uploads/calibration-controller/zoran.png\' ) : \'uploads/calibration-controller/offline.png\') : \'uploads/calibration-controller/no-connection.png\') + \')\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].passedCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].failedCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(302, '2022-10-11 19:08:00', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n    position:relative;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.7);\r\n    height: 170px;\r\n    position: absolute;\r\n    top: 30px;\r\n    padding-top:50px;\r\n    font-weight: bold;\r\n    color:#fff;\r\n    display: none;\r\n    width: 198px;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function indicateFailure (index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].failedCalibration = true;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function cleanUpPassing(index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].passedCalibration = true;\r\n\r\n  // Inform tests server that all tests passed\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  // Inform analytics server that all tests passed\r\n  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  try {\r\n    await updateFirmware(index);\r\n    await configureHardware(index);\r\n    await startCalibration(index);\r\n    await cleanUpPassing(index);\r\n  } catch (err) {\r\n    indicateFailure(index);\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].passedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].failedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          const barcode = value;\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress,\r\n                        secondarySerialNum: barcode\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId,\r\n                          secondarySerialNum: barcode\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  await loadTests(index);\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  let bgImg = \'no-connection\';\r\n                  if (client.connected) {\r\n                    if (client.scannerOnline) {\r\n                      if (client.isCortex) {\r\n                        if(client.passedCalibration) {\r\n                          bgImg = \'passed\';\r\n                        } else if (client.failedCalibration) {\r\n                          bgImg = \'failed\';\r\n                        } else {\r\n                          bgImg = \'online\';\r\n                        }\r\n                      } else {\r\n                        bgImg = \'zoran\';\r\n                      }\r\n                    } else {\r\n                      bgImg = \'offline\';\r\n                    }\r\n                  }\r\n\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + bgImg + \'.png)\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].passedCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].failedCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(303, '2022-10-11 19:09:19', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n    position:relative;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.7);\r\n    height: 170px;\r\n    position: absolute;\r\n    top: 30px;\r\n    padding-top:50px;\r\n    font-weight: bold;\r\n    color:#fff;\r\n    display: none;\r\n    width: 198px;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function indicateFailure (index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].failedCalibration = true;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function cleanUpPassing(index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].passedCalibration = true;\r\n\r\n  // Inform tests server that all tests passed\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  // Inform analytics server that all tests passed\r\n  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  try {\r\n    await updateFirmware(index);\r\n    await configureHardware(index);\r\n    await startCalibration(index);\r\n    await cleanUpPassing(index);\r\n  } catch (err) {\r\n    indicateFailure(index);\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].passedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].failedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          const barcode = value;\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress,\r\n                        secondarySerialNum: barcode\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId,\r\n                          secondarySerialNum: barcode\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  await loadTests(index);\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  let bgImg = \'no-connection\';\r\n                  if (client.connected) {\r\n                    if (client.scannerOnline) {\r\n                      if (client.isCortex) {\r\n                        if(client.passedCalibration) {\r\n                          bgImg = \'passed\';\r\n                        } else if (client.failedCalibration) {\r\n                          bgImg = \'failed\';\r\n                        } else {\r\n                          bgImg = \'online\';\r\n                        }\r\n                      } else {\r\n                        bgImg = \'zoran\';\r\n                      }\r\n                    } else {\r\n                      bgImg = \'offline\';\r\n                    }\r\n                  }\r\n\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + \'uploads/calibration-controller/\' + bgImg + \'.png)\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].passedCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].failedCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(304, '2022-10-11 19:13:43', 3, 'Calibration Controller', '<style>\r\n  #calWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n  .clientItem {\r\n    display:inline-block;\r\n    width: 200px;\r\n    height: 200px;\r\n    border: 1px solid rgba(0,0,0,0.2);\r\n    border-radius: 15px 15px 0 0;\r\n    cursor: pointer;\r\n    text-align: center;\r\n    margin: 20px;\r\n    background-repeat: no-repeat;\r\n    background-position: center center;\r\n    position:relative;\r\n  }\r\n    .clientItem:hover {\r\n      background-color: rgba(0,0,0,0.1);\r\n    }\r\n    .clientTitle {\r\n      line-height: 2em;\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      font-weight: bold;\r\n      border-radius: 15px 15px 0 0;\r\n    }\r\n    .sensorCell {\r\n      display:block;\r\n      float: left;\r\n      position: relative;\r\n      width:66px;\r\n      height: 57px;\r\n      margin:0;\r\n    }\r\n    .sensorCellMarked {\r\n      background-color:rgba(61,109,192,0.8);\r\n    }\r\n      \r\n      .sensorCellActive {\r\n        opacity: 0;\r\n        position: absolute;\r\n        top: 50%; left: 50%;\r\n        transform: translate(-50%,-50%);\r\n        color:#fff;\r\n      }\r\n      .visible {\r\n        opacity:1;\r\n      }\r\n\r\n  .clientStatus {\r\n    background-color: rgba(0,0,0,0.7);\r\n    height: 170px;\r\n    position: absolute;\r\n    top: 30px;\r\n    padding-top:50px;\r\n    font-weight: bold;\r\n    color:#fff;\r\n    display: none;\r\n    width: 198px;\r\n  }\r\n</style>\r\n<div id=\"calWrapper\">\r\n  <div id=\"selectMenu\"><label for=\"selectTestSet\">Select TLA:</label><div id=\"testSetSegment\"></div></div>\r\n  <div id=\"instructions\">Select a TLA first then select a scanner to configure.</div>\r\n  <div id=\"clientSegment\"></div>\r\n</div>', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function indicateFailure (index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].failedCalibration = true;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function cleanUpPassing(index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].passedCalibration = true;\r\n\r\n  // Inform tests server that all tests passed\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  // Inform analytics server that all tests passed\r\n  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  try {\r\n    await updateFirmware(index);\r\n    await configureHardware(index);\r\n    await startCalibration(index);\r\n    await cleanUpPassing(index);\r\n  } catch (err) {\r\n    indicateFailure(index);\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].passedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].failedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n\r\n    let container = document.getElementById(`client${index}`);\r\n    container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + \'uploads/calibration-controller/online.png)\';\r\n\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          const barcode = value;\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress,\r\n                        secondarySerialNum: barcode\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId,\r\n                          secondarySerialNum: barcode\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  await loadTests(index);\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  let bgImg = \'no-connection\';\r\n                  if (client.connected) {\r\n                    if (client.scannerOnline) {\r\n                      if (client.isCortex) {\r\n                        if(client.passedCalibration) {\r\n                          bgImg = \'passed\';\r\n                        } else if (client.failedCalibration) {\r\n                          bgImg = \'failed\';\r\n                        } else {\r\n                          bgImg = \'online\';\r\n                        }\r\n                      } else {\r\n                        bgImg = \'zoran\';\r\n                      }\r\n                    } else {\r\n                      bgImg = \'offline\';\r\n                    }\r\n                  }\r\n\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + \'uploads/calibration-controller/\' + bgImg + \'.png)\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].passedCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].failedCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(305, '2022-10-11 20:03:40', 4, 'Generic Tests in Test Set', '<style>\r\n  #testList {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 77px);\r\n  }\r\n    .testStep{\r\n      border-top:1px solid rgba(255,255,255,0.2);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n      cursor: pointer;\r\n    }\r\n  #testActions{\r\n    text-align: right;\r\n    position: fixed;\r\n    bottom: 10px;\r\n    right: 20px;\r\n    width: calc(100vw - 300px);\r\n  }\r\n  #testSetTitle {\r\n    text-align: right;\r\n    font-size: 120%;\r\n    font-weight: bold;\r\n    color:rgba(0,0,0,0.5);\r\n    padding-right: 20px;\r\n  }\r\n  #testWrapper {\r\n    padding-right: 20px;\r\n  }\r\n  .actionBtn {\r\n    display: inline-block;\r\n    border: 1px solid rgba(0,0,0,0.1);\r\n    border-radius: 10px;\r\n    padding: 10px 15px;\r\n    font-weight: bold;\r\n    background-color:#1976d2;\r\n    color: #fff;\r\n    cursor: pointer;\r\n  }\r\n    .actionBtn:hover {\r\n      background-color: #96c997;\r\n      color:#000;\r\n    }\r\n</style>\r\n<div style=\"float:left; background:rgba(128,128,128,0.4); border-right:1px solid rgba(0,0,0,0.1); width: 260px; height:100%;\">\r\n  <div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Test Steps</div>\r\n  <div id=\"testList\"></div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 280px); height:100%;\">\r\n  <div id=\"testSetTitle\"></div>\r\n  <div id=\"testWrapper\"></div>\r\n  <div id=\"testActions\">\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"individualTestMode()\" id=\"individualTestMode\">Switch to Individual Tests</div>\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"sequentialTestMode()\" id=\"sequentialTestMode\">Switch to Sequential Tests</div>\r\n    <div class=\"actionBtn\" onclick=\"reRunTests()\" id=\"reRunTests\">Test Another Device</div>\r\n    <div class=\"actionBtn\" onclick=\"retryTest()\" id=\"retryTest\">Retry Test</div>\r\n    <div class=\"actionBtn\" onclick=\"startTest()\" id=\"startTest\">Start Test</div>\r\n  </div>\r\n</div>', 'async function startTest () {\r\n  let continueProcessing = true;\r\n\r\n  window.gsap.set(\"#startTest\", {display: \"none\"});\r\n\r\n  // Mark test progress\r\n  await markTestProgress ();\r\n\r\n  // Destroy old test script\r\n  const oldScript = document.getElementById(\'testScript\');\r\n  if (oldScript) {\r\n    oldScript.remove();\r\n  }\r\n\r\n  // Determine if it is the start of a production test and if so, start tracking full test set\r\n  if (window.selectedProduct.currentTestIndex === 0 && !window.selectedProduct.individualTestMode) {\r\n    continueProcessing = false;\r\n    const macAdress = await getMacAddress();\r\n\r\n    // Reset local tracking of production test\r\n    window.selectedProduct.productionId = null;\r\n    window.selectedProduct.analyticsProductionId = null;\r\n    window.selectedProduct.analyticsResults = {};\r\n    window.selectedProduct.productionResults = {};\r\n\r\n    // Set up start entry in tests database\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"createInitialTrackingEntry\",\r\n          params: {\r\n            productId: window.selectedProduct.productId,\r\n            testSetId: window.selectedProduct.selectedTestSet.testSetId,\r\n            testerName: window.selectedProduct.testerName,\r\n            macAddress: macAdress\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.productionId = response.data.productionId;\r\n\r\n      // Set up start entry in analytics database\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"createInitialTrackingEntry\",\r\n            params: {\r\n              serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n              productId: window.selectedProduct.productId,\r\n              productTitle: window.selectedProduct.productTitle,\r\n              testSetId: window.selectedProduct.selectedTestSet.testSetId,\r\n              testSetTitle: window.selectedProduct.selectedTestSet.title,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAdress,\r\n              productionId: window.selectedProduct.productionId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n      if (analyticsResponse.data.success) {\r\n        window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n      }\r\n    } else {\r\n      promptUser(\'Failed to create production tracking entry\');\r\n    }\r\n  }\r\n\r\n  // Load script\r\n  if (continueProcessing && window.selectedProduct.tests[window.selectedProduct.currentTestIndex]) {\r\n    const script = document.createElement(\'script\');\r\n    script.type = \'text/javascript\';\r\n    script.text = window.selectedProduct.tests[window.selectedProduct.currentTestIndex].script;\r\n    script.id = \'testScript\';\r\n    document.body.appendChild(script);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function markTestProgress () {\r\n  if (!window.selectedProduct.individualTestMode) {\r\n    window.selectedProduct.tests.forEach((test, index) => {\r\n      if (index < window.selectedProduct.currentTestIndex) {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"#b5f5b9\"});\r\n      } else if (index === window.selectedProduct.currentTestIndex) {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"#f1f5b5\"});\r\n      } else {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"rgba(128,128,128,0)\"});\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clearTestProgress () {\r\n  window.selectedProduct.tests.forEach((test, index) => {\r\n    window.gsap.set(`#testStep${index}`, {backgroundColor: \"rgba(128,128,128,0)\"});\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction loadTemplate () {\r\n  return new Promise(resolve => {\r\n    window.gsap.to(\"#testWrapper\", {opacity: 0, duration: 0.2, onComplete: () => {\r\n      document.getElementById(\'testWrapper\').innerHTML = window.selectedProduct.tests[window.selectedProduct.currentTestIndex].codeset;\r\n      window.gsap.to(\"#testWrapper\", {opacity: 1, duration: 0.2, onComplete: () => {\r\n        resolve();\r\n      }});\r\n    }});\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function individualTestMode() {\r\n  window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n  window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n  window.gsap.set(\"#individualTestMode\", {display: \"none\"});\r\n  window.gsap.set(\"#startTest\", {display: \"none\"});\r\n  window.gsap.set(\"#sequentialTestMode\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#sequentialTestMode\", {opacity: 1, duration: 0.2});\r\n  clearTestProgress();\r\n  window.selectedProduct.individualTestMode = true;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function sequentialTestMode() {\r\n  reRunTests();\r\n  window.gsap.set(\"#sequentialTestMode\", {display: \"none\"});\r\n  window.gsap.set(\"#individualTestMode\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#individualTestMode\", {opacity: 1, duration: 0.2});\r\n  window.gsap.set(\"#startTest\", {display: \"inline-block\"});\r\n  window.selectedProduct.individualTestMode = false;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function runSingleTest (testIndex) {\r\n  if (window.selectedProduct.individualTestMode) {\r\n    window.selectedProduct.currentTestIndex = testIndex;\r\n    await loadTemplate();\r\n    window.gsap.set(\"#startTest\", {display: \"inline-block\", opacity: 0});\r\n    window.gsap.to(\"#startTest\", {opacity: 1, duration: 0.2});\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function saveTestAnalytics (testPassed, failMsg) {\r\n  const macAdress = await getMacAddress();\r\n  const extAnalyticsProductionId = window.selectedProduct.individualTestMode ? 0 : window.selectedProduct.analyticsProductionId;\r\n\r\n  if (window.selectedProduct.customError) {\r\n    customError = window.selectedProduct.customError;\r\n  } else {\r\n    customError = \'\';\r\n  }\r\n\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: getElapsedTime(),\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSet.title,\r\n          testTitle: window.selectedProduct.tests[window.selectedProduct.currentTestIndex].title,\r\n          testId: window.selectedProduct.tests[window.selectedProduct.currentTestIndex].testId,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: failMsg,\r\n          customError: customError\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  // Save analytics\r\n  await saveTestAnalytics(true,\'\');\r\n\r\n  window.Notify.create({\r\n    message: \'Passed \' + window.selectedProduct.tests[window.selectedProduct.currentTestIndex].title + \' test\',\r\n    position: \'top\',\r\n    color: \'positive\'\r\n  });\r\n\r\n  // Advance Forward if in sequential mode\r\n  if (!window.selectedProduct.individualTestMode) {\r\n    if (window.selectedProduct.currentTestIndex < window.selectedProduct.tests.length - 1) {\r\n      window.selectedProduct.currentTestIndex++;\r\n      await markTestProgress ();\r\n      await loadTemplate();\r\n      startTest();\r\n    } else {\r\n      window.selectedProduct.currentTestIndex++;\r\n      await markTestProgress ();\r\n\r\n      // Inform tests server that all tests passed\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"passProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      // Inform analytics server that all tests passed\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"passProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      // Inform user that all tests passed\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div style=\"text-align: center; margin-top: 50px; border:2px solid #008001; padding: 15px; border-radius:15px; font-weight:bold; font-size:140%; color:#008001; background-color:#dbfadb;\">All Tests Passed!</div>\r\n      `;\r\n\r\n      window.gsap.set(\"#reRunTests\", {display: \"inline-block\"});\r\n    }\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  // Prompt user to select fail reason\r\n  // Get product fail reasons\r\n  const failReasonsResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"products\",\r\n        action: \"getProductFailReasons\",\r\n        params: {\r\n          productId: window.selectedProduct.productId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (failReasonsResponse.data.success) {\r\n    window.Dialog.create({\r\n      title: \'Select Fail Reason\',\r\n      html: true,\r\n      message: `\r\n        <div style=\"color:red; font-weight:bold;\">${err}</div>\r\n        Select a fail reason from the list below:\r\n        <select id=\"failReasonSelect\">\r\n          <option value=\"0\">---Select a fail reason---</option>\r\n          ${failReasonsResponse.data.failReasons.map(failReason => {\r\n            return `<option value=\"${failReason.title}\">${failReason.title}</option>`;\r\n          })}\r\n          <option value=\"other\">Other</option>\r\n        </select>\r\n      `\r\n    }).onOk(async () => {\r\n      window.selectedProduct.customError = document.getElementById(\'failReasonSelect\').value;\r\n\r\n      // Save analytics\r\n      await saveTestAnalytics(false, err);\r\n\r\n      window.gsap.set(\"#retryTest\", {display: \"inline-block\"});\r\n    });\r\n  } else {\r\n    window.selectedProduct.customError = \'Other\';\r\n    await promptUser(err);\r\n\r\n    // Save analytics\r\n    await saveTestAnalytics(false, err);\r\n\r\n    window.gsap.set(\"#retryTest\", {display: \"inline-block\"});\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function retryTest() {\r\n  window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n  await loadTemplate();\r\n  startTest();\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function reRunTests () {\r\n  window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n  window.selectedProduct.currentTestIndex = 0;\r\n  window.selectedProduct.productionResults = {};\r\n  await markTestProgress ();\r\n  await loadTemplate();\r\n  window.gsap.set(\"#startTest\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#startTest\", {opacity: 1, duration: 0.2});\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    // Set test set title\r\n    document.getElementById(\'testSetTitle\').innerHTML = window.selectedProduct.selectedTestSet.title;\r\n\r\n    // Hide buttons\r\n    window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n    window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n    window.gsap.set(\"#sequentialTestMode\", {display: \"none\"});\r\n\r\n    // Get product config\r\n    const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getProductConfigForTestSet\",\r\n          params: {\r\n            testSetId: window.selectedProduct.selectedTestSet.testSetId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    // Set product config\r\n    if (productCfgResponse.data.success) {\r\n      window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n      // Get the list of tests\r\n      const testResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"testSets\",\r\n            action: \"getTestsForTestSet\",\r\n            params: {\r\n              testSetId: window.selectedProduct.selectedTestSet.testSetId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      if (testResponse.data.success) {\r\n        window.selectedProduct.tests = testResponse.data.tests;\r\n        window.selectedProduct.currentTestIndex = 0;\r\n        window.selectedProduct.productionResults = {};\r\n\r\n        let preprocess = \'\';\r\n        testResponse.data.tests.forEach((test, index) => {\r\n          preprocess += \'<div class=\"testStep\" id=\"testStep\' + index + \'\" onclick=\"runSingleTest(\' + index + \')\">\' + test.title + \'</div>\';\r\n        });\r\n        document.getElementById(\'testList\').innerHTML = preprocess;\r\n\r\n        // Load first test template but don\'t run script until start is clicked\r\n        document.getElementById(\'testWrapper\').innerHTML = window.selectedProduct.tests[0].codeset;\r\n\r\n        window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n      } else {\r\n        promptUser(\'Failed to get any tests\');\r\n      }\r\n    } else {\r\n      promptUser(\'Failed to get the config for this product\');\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(306, '2022-10-11 21:02:41', 4, 'Generic Tests in Test Set', '<style>\r\n  #testList {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 77px);\r\n  }\r\n    .testStep{\r\n      border-top:1px solid rgba(255,255,255,0.2);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n      cursor: pointer;\r\n    }\r\n  #testActions{\r\n    text-align: right;\r\n    position: fixed;\r\n    bottom: 10px;\r\n    right: 20px;\r\n    width: calc(100vw - 300px);\r\n  }\r\n  #testSetTitle {\r\n    text-align: right;\r\n    font-size: 120%;\r\n    font-weight: bold;\r\n    color:rgba(0,0,0,0.5);\r\n    padding-right: 20px;\r\n  }\r\n  #testWrapper {\r\n    padding-right: 20px;\r\n  }\r\n  .actionBtn {\r\n    display: inline-block;\r\n    border: 1px solid rgba(0,0,0,0.1);\r\n    border-radius: 10px;\r\n    padding: 10px 15px;\r\n    font-weight: bold;\r\n    background-color:#1976d2;\r\n    color: #fff;\r\n    cursor: pointer;\r\n  }\r\n    .actionBtn:hover {\r\n      background-color: #96c997;\r\n      color:#000;\r\n    }\r\n</style>\r\n<div style=\"float:left; background:rgba(128,128,128,0.4); border-right:1px solid rgba(0,0,0,0.1); width: 260px; height:100%;\">\r\n  <div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Test Steps</div>\r\n  <div id=\"testList\"></div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 280px); height:100%;\">\r\n  <div id=\"testSetTitle\"></div>\r\n  <div id=\"testWrapper\"></div>\r\n  <div id=\"testActions\">\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"individualTestMode()\" id=\"individualTestMode\">Switch to Individual Tests</div>\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"sequentialTestMode()\" id=\"sequentialTestMode\">Switch to Sequential Tests</div>\r\n    <div class=\"actionBtn\" onclick=\"reRunTests()\" id=\"reRunTests\">Test Another Device</div>\r\n    <div class=\"actionBtn\" onclick=\"retryTest()\" id=\"retryTest\">Retry Test</div>\r\n    <div class=\"actionBtn\" onclick=\"startTest()\" id=\"startTest\">Start Test</div>\r\n  </div>\r\n</div>', 'async function startTest () {\r\n  let continueProcessing = true;\r\n\r\n  window.gsap.set(\"#startTest\", {display: \"none\"});\r\n\r\n  // Mark test progress\r\n  await markTestProgress ();\r\n\r\n  // Destroy old test script\r\n  const oldScript = document.getElementById(\'testScript\');\r\n  if (oldScript) {\r\n    oldScript.remove();\r\n  }\r\n\r\n  // Determine if it is the start of a production test and if so, start tracking full test set\r\n  if (window.selectedProduct.currentTestIndex === 0 && !window.selectedProduct.individualTestMode) {\r\n    continueProcessing = false;\r\n    const macAdress = await getMacAddress();\r\n\r\n    // Reset local tracking of production test\r\n    window.selectedProduct.productionId = null;\r\n    window.selectedProduct.analyticsProductionId = null;\r\n    window.selectedProduct.analyticsResults = {};\r\n    window.selectedProduct.productionResults = {};\r\n\r\n    // Set up start entry in tests database\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"createInitialTrackingEntry\",\r\n          params: {\r\n            productId: window.selectedProduct.productId,\r\n            testSetId: window.selectedProduct.selectedTestSet.testSetId,\r\n            testerName: window.selectedProduct.testerName,\r\n            macAddress: macAdress\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.productionId = response.data.productionId;\r\n\r\n      // Set up start entry in analytics database\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"createInitialTrackingEntry\",\r\n            params: {\r\n              serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n              productId: window.selectedProduct.productId,\r\n              productTitle: window.selectedProduct.productTitle,\r\n              testSetId: window.selectedProduct.selectedTestSet.testSetId,\r\n              testSetTitle: window.selectedProduct.selectedTestSet.title,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAdress,\r\n              productionId: window.selectedProduct.productionId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n      if (analyticsResponse.data.success) {\r\n        window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n      }\r\n    } else {\r\n      promptUser(\'Failed to create production tracking entry\');\r\n    }\r\n  }\r\n\r\n  // Load script\r\n  if (continueProcessing && window.selectedProduct.tests[window.selectedProduct.currentTestIndex]) {\r\n    const script = document.createElement(\'script\');\r\n    script.type = \'text/javascript\';\r\n    script.text = window.selectedProduct.tests[window.selectedProduct.currentTestIndex].script;\r\n    script.id = \'testScript\';\r\n    document.body.appendChild(script);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function markTestProgress () {\r\n  if (!window.selectedProduct.individualTestMode) {\r\n    window.selectedProduct.tests.forEach((test, index) => {\r\n      if (index < window.selectedProduct.currentTestIndex) {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"#b5f5b9\"});\r\n      } else if (index === window.selectedProduct.currentTestIndex) {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"#f1f5b5\"});\r\n      } else {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"rgba(128,128,128,0)\"});\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clearTestProgress () {\r\n  window.selectedProduct.tests.forEach((test, index) => {\r\n    window.gsap.set(`#testStep${index}`, {backgroundColor: \"rgba(128,128,128,0)\"});\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction loadTemplate () {\r\n  return new Promise(resolve => {\r\n    window.gsap.to(\"#testWrapper\", {opacity: 0, duration: 0.2, onComplete: () => {\r\n      document.getElementById(\'testWrapper\').innerHTML = window.selectedProduct.tests[window.selectedProduct.currentTestIndex].codeset;\r\n      window.gsap.to(\"#testWrapper\", {opacity: 1, duration: 0.2, onComplete: () => {\r\n        resolve();\r\n      }});\r\n    }});\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function individualTestMode() {\r\n  window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n  window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n  window.gsap.set(\"#individualTestMode\", {display: \"none\"});\r\n  window.gsap.set(\"#startTest\", {display: \"none\"});\r\n  window.gsap.set(\"#sequentialTestMode\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#sequentialTestMode\", {opacity: 1, duration: 0.2});\r\n  clearTestProgress();\r\n  window.selectedProduct.individualTestMode = true;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function sequentialTestMode() {\r\n  reRunTests();\r\n  window.gsap.set(\"#sequentialTestMode\", {display: \"none\"});\r\n  window.gsap.set(\"#individualTestMode\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#individualTestMode\", {opacity: 1, duration: 0.2});\r\n  window.gsap.set(\"#startTest\", {display: \"inline-block\"});\r\n  window.selectedProduct.individualTestMode = false;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function runSingleTest (testIndex) {\r\n  if (window.selectedProduct.individualTestMode) {\r\n    window.selectedProduct.currentTestIndex = testIndex;\r\n    await loadTemplate();\r\n    window.gsap.set(\"#startTest\", {display: \"inline-block\", opacity: 0});\r\n    window.gsap.to(\"#startTest\", {opacity: 1, duration: 0.2});\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function saveTestAnalytics (testPassed, failMsg) {\r\n  const macAdress = await getMacAddress();\r\n  const extAnalyticsProductionId = window.selectedProduct.individualTestMode ? 0 : window.selectedProduct.analyticsProductionId;\r\n\r\n  if (window.selectedProduct.customError) {\r\n    customError = window.selectedProduct.customError;\r\n  } else {\r\n    customError = \'\';\r\n  }\r\n\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: getElapsedTime(),\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSet.title,\r\n          testTitle: window.selectedProduct.tests[window.selectedProduct.currentTestIndex].title,\r\n          testId: window.selectedProduct.tests[window.selectedProduct.currentTestIndex].testId,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: failMsg,\r\n          customError: customError\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  // Save analytics\r\n  await saveTestAnalytics(true,\'\');\r\n\r\n  window.Notify.create({\r\n    message: \'Passed \' + window.selectedProduct.tests[window.selectedProduct.currentTestIndex].title + \' test\',\r\n    position: \'top\',\r\n    color: \'positive\'\r\n  });\r\n\r\n  // Advance Forward if in sequential mode\r\n  if (!window.selectedProduct.individualTestMode) {\r\n    if (window.selectedProduct.currentTestIndex < window.selectedProduct.tests.length - 1) {\r\n      window.selectedProduct.currentTestIndex++;\r\n      await markTestProgress ();\r\n      await loadTemplate();\r\n      startTest();\r\n    } else {\r\n      window.selectedProduct.currentTestIndex++;\r\n      await markTestProgress ();\r\n\r\n      // Inform tests server that all tests passed\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"passProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      // Inform analytics server that all tests passed\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"passProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      // Inform user that all tests passed\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div style=\"text-align: center; margin-top: 50px; border:2px solid #008001; padding: 15px; border-radius:15px; font-weight:bold; font-size:140%; color:#008001; background-color:#dbfadb;\">All Tests Passed!</div>\r\n      `;\r\n\r\n      window.gsap.set(\"#reRunTests\", {display: \"inline-block\"});\r\n    }\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  // Prompt user to select fail reason\r\n  // Get product fail reasons\r\n  const failReasonsResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"products\",\r\n        action: \"getProductFailReasons\",\r\n        params: {\r\n          productId: window.selectedProduct.productId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (failReasonsResponse.data.success) {\r\n    window.Dialog.create({\r\n      title: \'Select Fail Reason\',\r\n      html: true,\r\n      message: `\r\n        <div style=\"color:red; font-weight:bold;\">${err}</div>\r\n        Select a fail reason from the list below:\r\n        <select id=\"failReasonSelect\">\r\n        \r\n          ${failReasonsResponse.data.failReasons.map(failReason => {\r\n            return `<option value=\"${failReason.title}\">${failReason.title}</option>`;\r\n          })}\r\n          <option value=\"other\">Other</option>\r\n        </select>\r\n      `\r\n    }).onOk(async () => {\r\n      window.selectedProduct.customError = document.getElementById(\'failReasonSelect\').value;\r\n\r\n      // Save analytics\r\n      await saveTestAnalytics(false, err);\r\n\r\n      window.gsap.set(\"#retryTest\", {display: \"inline-block\"});\r\n    });\r\n  } else {\r\n    window.selectedProduct.customError = \'Other\';\r\n    await promptUser(err);\r\n\r\n    // Save analytics\r\n    await saveTestAnalytics(false, err);\r\n\r\n    window.gsap.set(\"#retryTest\", {display: \"inline-block\"});\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function retryTest() {\r\n  window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n  await loadTemplate();\r\n  startTest();\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function reRunTests () {\r\n  window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n  window.selectedProduct.currentTestIndex = 0;\r\n  window.selectedProduct.productionResults = {};\r\n  await markTestProgress ();\r\n  await loadTemplate();\r\n  window.gsap.set(\"#startTest\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#startTest\", {opacity: 1, duration: 0.2});\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    // Set test set title\r\n    document.getElementById(\'testSetTitle\').innerHTML = window.selectedProduct.selectedTestSet.title;\r\n\r\n    // Hide buttons\r\n    window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n    window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n    window.gsap.set(\"#sequentialTestMode\", {display: \"none\"});\r\n\r\n    // Get product config\r\n    const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getProductConfigForTestSet\",\r\n          params: {\r\n            testSetId: window.selectedProduct.selectedTestSet.testSetId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    // Set product config\r\n    if (productCfgResponse.data.success) {\r\n      window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n      // Get the list of tests\r\n      const testResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"testSets\",\r\n            action: \"getTestsForTestSet\",\r\n            params: {\r\n              testSetId: window.selectedProduct.selectedTestSet.testSetId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      if (testResponse.data.success) {\r\n        window.selectedProduct.tests = testResponse.data.tests;\r\n        window.selectedProduct.currentTestIndex = 0;\r\n        window.selectedProduct.productionResults = {};\r\n\r\n        let preprocess = \'\';\r\n        testResponse.data.tests.forEach((test, index) => {\r\n          preprocess += \'<div class=\"testStep\" id=\"testStep\' + index + \'\" onclick=\"runSingleTest(\' + index + \')\">\' + test.title + \'</div>\';\r\n        });\r\n        document.getElementById(\'testList\').innerHTML = preprocess;\r\n\r\n        // Load first test template but don\'t run script until start is clicked\r\n        document.getElementById(\'testWrapper\').innerHTML = window.selectedProduct.tests[0].codeset;\r\n\r\n        window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n      } else {\r\n        promptUser(\'Failed to get any tests\');\r\n      }\r\n    } else {\r\n      promptUser(\'Failed to get the config for this product\');\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(307, '2022-10-11 21:21:20', 4, 'Generic Tests in Test Set', '<style>\r\n  #testList {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 77px);\r\n  }\r\n    .testStep{\r\n      border-top:1px solid rgba(255,255,255,0.2);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n      cursor: pointer;\r\n    }\r\n  #testActions{\r\n    text-align: right;\r\n    position: fixed;\r\n    bottom: 10px;\r\n    right: 20px;\r\n    width: calc(100vw - 300px);\r\n  }\r\n  #testSetTitle {\r\n    text-align: right;\r\n    font-size: 120%;\r\n    font-weight: bold;\r\n    color:rgba(0,0,0,0.5);\r\n    padding-right: 20px;\r\n  }\r\n  #testWrapper {\r\n    padding-right: 20px;\r\n  }\r\n  .actionBtn {\r\n    display: inline-block;\r\n    border: 1px solid rgba(0,0,0,0.1);\r\n    border-radius: 10px;\r\n    padding: 10px 15px;\r\n    font-weight: bold;\r\n    background-color:#1976d2;\r\n    color: #fff;\r\n    cursor: pointer;\r\n  }\r\n    .actionBtn:hover {\r\n      background-color: #96c997;\r\n      color:#000;\r\n    }\r\n</style>\r\n<div style=\"float:left; background:rgba(128,128,128,0.4); border-right:1px solid rgba(0,0,0,0.1); width: 260px; height:100%;\">\r\n  <div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Test Steps</div>\r\n  <div id=\"testList\"></div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 280px); height:100%;\">\r\n  <div id=\"testSetTitle\"></div>\r\n  <div id=\"testWrapper\"></div>\r\n  <div id=\"testActions\">\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"individualTestMode()\" id=\"individualTestMode\">Switch to Individual Tests</div>\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"sequentialTestMode()\" id=\"sequentialTestMode\">Switch to Sequential Tests</div>\r\n    <div class=\"actionBtn\" onclick=\"reRunTests()\" id=\"reRunTests\">Test Another Device</div>\r\n    <div class=\"actionBtn\" onclick=\"retryTest()\" id=