(314, '2022-10-12 19:27:12', 5, 'Generic: Print Labels', '<style>\r\n  #labelWrapper {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n</style>\r\n<div id=\"labelWrapper\">\r\n<div id=\"toolbarSegment\"></div>\r\n  test\r\n</div>', '// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
