(342, '2022-10-20 15:09:11', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignment(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignment()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentVal) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(343, '2022-10-20 15:12:21', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignment(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignment()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentVal) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
