window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(345, '2022-10-20 15:28:43', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignment(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignment()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      \r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(346, '2022-10-20 15:40:55', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignment()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(347, '2022-10-20 15:51:01', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignment()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          const d = new Date();\r\n          let dateString = d.toString();\r\n          dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n          dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n          let timeString = d.toTimeString();\r\n          timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n          timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          let lotsOfH = new Array(64).fill(0x48);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(348, '2022-10-20 16:06:33', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignment()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionSerialUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(349, '2022-10-20 16:07:40', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignment()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(350, '2022-10-20 16:11:00', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(351, '2022-10-20 16:15:10', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          let usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          let usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          let usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          let usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(352, '2022-10-20 16:19:54', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(353, '2022-10-20 16:22:14', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(354, '2022-10-24 07:48:42', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      console.log(\'startTestLog\');\r\n      console.log(window.selectedProduct);\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      console.log(\'endTestLog\');\r\n      console.log(window.selectedProduct);\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(355, '2022-10-24 07:58:51', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(356, '2022-10-24 08:19:50', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'instructions\').innerHTML = \'Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.\';\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\">img</td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, and device is turned on.\';\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(357, '2022-10-24 08:25:27', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n    }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:200px;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      document.getElementById(\'instructions\').innerHTML = \'Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.\';\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\">img</td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, and device is turned on.\';\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(358, '2022-10-24 08:26:27', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n    }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:200px;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      document.getElementById(\'instructions\').innerHTML = \'Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.\';\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\">img</td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, and device is turned on.\';\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(359, '2022-10-24 08:28:49', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n    }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      document.getElementById(\'instructions\').innerHTML = \'\';\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\"><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, and device is turned on.\';\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(360, '2022-10-24 08:30:22', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n    }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\"><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(361, '2022-10-24 08:49:47', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n    }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: center center;\r\n      background-size: contain;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(362, '2022-10-24 08:53:09', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n    }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(363, '2022-10-24 08:56:58', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      \r\n    }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(364, '2022-10-24 08:58:07', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      \r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(365, '2022-10-24 08:59:27', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      \r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      padding: 10px;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(366, '2022-10-24 09:00:57', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      \r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.95);\r\n      padding:10px;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(367, '2022-10-24 09:01:48', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      \r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.95);\r\n      padding:10px;\r\n      max-width: 500px;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(368, '2022-10-24 09:02:36', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.95);\r\n      padding:10px;\r\n      max-width: 500px;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(369, '2022-10-24 09:03:21', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.95);\r\n      padding:10px;\r\n      max-width: 500px;\r\n      margin: 10px auto;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(370, '2022-10-24 09:04:10', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.95);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(371, '2022-10-24 09:05:22', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.9);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n      border-radius: 10px;\r\n      box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(372, '2022-10-24 09:32:22', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.9);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n      border-radius: 10px;\r\n      box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setBurstAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.burstAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Burst Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.horizontalAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Horizontal Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(373, '2022-10-24 09:40:24', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.9);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n      border-radius: 10px;\r\n      box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n    }\r\n    .selected {\r\n      background-color: #ccc;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setBurstAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.burstAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Burst Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.horizontalAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Horizontal Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkBurstSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.burstAlignment && window.selectedProduct.productionResults.burstAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkHorizontalSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.horizontalAlignment && window.selectedProduct.productionResults.horizontalAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\" class=\"` + checkBurstSelection(62) + `\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\" class=\"` + checkBurstSelection(63) + `\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\" class=\"` + checkBurstSelection(64) + `\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\" class=\"` + checkBurstSelection(65) + `\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\" class=\"` + checkBurstSelection(66) + `\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\" class=\"` + checkBurstSelection(67) + `\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\" class=\"` + checkBurstSelection(68) + `\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\" class=\"` + checkBurstSelection(69) + `\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\" class=\"` + checkBurstSelection(70) + `\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\" class=\"` + checkBurstSelection(71) + `\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\" class=\"` + checkBurstSelection(72) + `\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\" class=\"` + checkBurstSelection(73) + `\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\" class=\"` + checkBurstSelection(74) + `\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\" class=\"` + checkBurstSelection(75) + `\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\" class=\"` + checkBurstSelection(76) + `\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\" class=\"` + checkBurstSelection(77) + `\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\" class=\"` + checkHorizontalSelection(0) + `\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\" class=\"` + checkHorizontalSelection(1) + `\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\" class=\"` + checkHorizontalSelection(2) + `\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\" class=\"` + checkHorizontalSelection(3) + `\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\" class=\"` + checkHorizontalSelection(4) + `\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\" class=\"` + checkHorizontalSelection(5) + `\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(374, '2022-10-24 09:40:56', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.9);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n      border-radius: 10px;\r\n      box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n    }\r\n    .selected {\r\n      background-color: #aaa;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setBurstAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.burstAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Burst Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.horizontalAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Horizontal Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkBurstSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.burstAlignment && window.selectedProduct.productionResults.burstAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkHorizontalSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.horizontalAlignment && window.selectedProduct.productionResults.horizontalAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\" class=\"` + checkBurstSelection(62) + `\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\" class=\"` + checkBurstSelection(63) + `\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\" class=\"` + checkBurstSelection(64) + `\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\" class=\"` + checkBurstSelection(65) + `\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\" class=\"` + checkBurstSelection(66) + `\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\" class=\"` + checkBurstSelection(67) + `\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\" class=\"` + checkBurstSelection(68) + `\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\" class=\"` + checkBurstSelection(69) + `\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\" class=\"` + checkBurstSelection(70) + `\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\" class=\"` + checkBurstSelection(71) + `\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\" class=\"` + checkBurstSelection(72) + `\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\" class=\"` + checkBurstSelection(73) + `\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\" class=\"` + checkBurstSelection(74) + `\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\" class=\"` + checkBurstSelection(75) + `\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\" class=\"` + checkBurstSelection(76) + `\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\" class=\"` + checkBurstSelection(77) + `\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\" class=\"` + checkHorizontalSelection(0) + `\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\" class=\"` + checkHorizontalSelection(1) + `\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\" class=\"` + checkHorizontalSelection(2) + `\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\" class=\"` + checkHorizontalSelection(3) + `\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\" class=\"` + checkHorizontalSelection(4) + `\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\" class=\"` + checkHorizontalSelection(5) + `\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(375, '2022-10-24 09:41:44', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.9);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n      border-radius: 10px;\r\n      box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n    }\r\n    .selected {\r\n      background-color: #aaa;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setBurstAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.burstAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Burst Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.horizontalAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Horizontal Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkBurstSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.burstAlignment && window.selectedProduct.productionResults.burstAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkHorizontalSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.horizontalAlignment && window.selectedProduct.productionResults.horizontalAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\" class=\"` + checkBurstSelection(62) + `\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\" class=\"` + checkBurstSelection(63) + `\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\" class=\"` + checkBurstSelection(64) + `\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\" class=\"` + checkBurstSelection(65) + `\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\" class=\"` + checkBurstSelection(66) + `\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\" class=\"` + checkBurstSelection(67) + `\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\" class=\"` + checkBurstSelection(68) + `\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\" class=\"` + checkBurstSelection(69) + `\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\" class=\"` + checkBurstSelection(70) + `\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\" class=\"` + checkBurstSelection(71) + `\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\" class=\"` + checkBurstSelection(72) + `\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\" class=\"` + checkBurstSelection(73) + `\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\" class=\"` + checkBurstSelection(74) + `\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\" class=\"` + checkBurstSelection(75) + `\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\" class=\"` + checkBurstSelection(76) + `\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\" class=\"` + checkBurstSelection(77) + `\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\" class=\"` + checkHorizontalSelection(0) + `\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\" class=\"` + checkHorizontalSelection(1) + `\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\" class=\"` + checkHorizontalSelection(2) + `\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\" class=\"` + checkHorizontalSelection(3) + `\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\" class=\"` + checkHorizontalSelection(4) + `\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\" class=\"` + checkHorizontalSelection(5) + `\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(376, '2022-10-24 09:43:30', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.9);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n      border-radius: 10px;\r\n      box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n    }\r\n    .selected {\r\n      background-color: #aaa;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setBurstAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.burstAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Burst Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.horizontalAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Horizontal Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkBurstSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.burstAlignment && window.selectedProduct.productionResults.burstAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkHorizontalSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.horizontalAlignment !== null && window.selectedProduct.productionResults.horizontalAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\" class=\"` + checkBurstSelection(62) + `\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\" class=\"` + checkBurstSelection(63) + `\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\" class=\"` + checkBurstSelection(64) + `\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\" class=\"` + checkBurstSelection(65) + `\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\" class=\"` + checkBurstSelection(66) + `\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\" class=\"` + checkBurstSelection(67) + `\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\" class=\"` + checkBurstSelection(68) + `\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\" class=\"` + checkBurstSelection(69) + `\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\" class=\"` + checkBurstSelection(70) + `\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\" class=\"` + checkBurstSelection(71) + `\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\" class=\"` + checkBurstSelection(72) + `\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\" class=\"` + checkBurstSelection(73) + `\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\" class=\"` + checkBurstSelection(74) + `\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\" class=\"` + checkBurstSelection(75) + `\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\" class=\"` + checkBurstSelection(76) + `\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\" class=\"` + checkBurstSelection(77) + `\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\" class=\"` + checkHorizontalSelection(0) + `\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\" class=\"` + checkHorizontalSelection(1) + `\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\" class=\"` + checkHorizontalSelection(2) + `\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\" class=\"` + checkHorizontalSelection(3) + `\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\" class=\"` + checkHorizontalSelection(4) + `\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\" class=\"` + checkHorizontalSelection(5) + `\">5</button></td>\r\n          </tr>\r\n        </table>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(377, '2022-10-24 09:52:11', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.9);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n      border-radius: 10px;\r\n      box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n    }\r\n    .selected {\r\n      background-color: #aaa;\r\n    }\r\n    .alignBtns {\r\n      text-align: right;\r\n    }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setBurstAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.burstAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Burst Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = false;\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.horizontalAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Horizontal Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = false;\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkBurstSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.burstAlignment && window.selectedProduct.productionResults.burstAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkHorizontalSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.horizontalAlignment !== null && window.selectedProduct.productionResults.horizontalAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\" class=\"` + checkBurstSelection(62) + `\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\" class=\"` + checkBurstSelection(63) + `\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\" class=\"` + checkBurstSelection(64) + `\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\" class=\"` + checkBurstSelection(65) + `\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\" class=\"` + checkBurstSelection(66) + `\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\" class=\"` + checkBurstSelection(67) + `\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\" class=\"` + checkBurstSelection(68) + `\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\" class=\"` + checkBurstSelection(69) + `\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\" class=\"` + checkBurstSelection(70) + `\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\" class=\"` + checkBurstSelection(71) + `\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\" class=\"` + checkBurstSelection(72) + `\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\" class=\"` + checkBurstSelection(73) + `\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\" class=\"` + checkBurstSelection(74) + `\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\" class=\"` + checkBurstSelection(75) + `\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\" class=\"` + checkBurstSelection(76) + `\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\" class=\"` + checkBurstSelection(77) + `\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\" class=\"` + checkHorizontalSelection(0) + `\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\" class=\"` + checkHorizontalSelection(1) + `\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\" class=\"` + checkHorizontalSelection(2) + `\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\" class=\"` + checkHorizontalSelection(3) + `\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\" class=\"` + checkHorizontalSelection(4) + `\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\" class=\"` + checkHorizontalSelection(5) + `\">5</button></td>\r\n          </tr>\r\n        </table>\r\n        <div class=\"alignBtns\">\r\n          ` + (window.selectedProduct.alignmentNotAdjusted ? \'<button onclick=\"exitAlignment()\">Alignment Good</button>\' : \'<button onclick=\"testAlignment()\">Print Again</button>\' ) + `\r\n        </div>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#userPrompt\', { display: \'none\' });\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction exitAlignment () {\r\n  window.gsap.set(\'#actionsBar\', { display: \'block\' });\r\n  window.gsap.set(\'#instructions\', { display: \'block\' });\r\n  window.gsap.set(\'#userPrompt\', { display: \'none\' });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = true;\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(378, '2022-10-24 09:54:50', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.9);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n      border-radius: 10px;\r\n      box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n    }\r\n    .selected {\r\n      background-color: #aaa;\r\n    }\r\n    .alignBtns {\r\n      text-align: right;\r\n    }\r\n      .alignBtns button{\r\n        margin: 10px;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setBurstAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.burstAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Burst Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = false;\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.horizontalAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Horizontal Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = false;\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkBurstSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.burstAlignment && window.selectedProduct.productionResults.burstAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkHorizontalSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.horizontalAlignment !== null && window.selectedProduct.productionResults.horizontalAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\" class=\"` + checkBurstSelection(62) + `\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\" class=\"` + checkBurstSelection(63) + `\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\" class=\"` + checkBurstSelection(64) + `\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\" class=\"` + checkBurstSelection(65) + `\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\" class=\"` + checkBurstSelection(66) + `\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\" class=\"` + checkBurstSelection(67) + `\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\" class=\"` + checkBurstSelection(68) + `\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\" class=\"` + checkBurstSelection(69) + `\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\" class=\"` + checkBurstSelection(70) + `\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\" class=\"` + checkBurstSelection(71) + `\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\" class=\"` + checkBurstSelection(72) + `\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\" class=\"` + checkBurstSelection(73) + `\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\" class=\"` + checkBurstSelection(74) + `\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\" class=\"` + checkBurstSelection(75) + `\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\" class=\"` + checkBurstSelection(76) + `\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\" class=\"` + checkBurstSelection(77) + `\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\" class=\"` + checkHorizontalSelection(0) + `\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\" class=\"` + checkHorizontalSelection(1) + `\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\" class=\"` + checkHorizontalSelection(2) + `\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\" class=\"` + checkHorizontalSelection(3) + `\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\" class=\"` + checkHorizontalSelection(4) + `\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\" class=\"` + checkHorizontalSelection(5) + `\">5</button></td>\r\n          </tr>\r\n        </table>\r\n        <div class=\"alignBtns\">\r\n          ` + (window.selectedProduct.alignmentNotAdjusted ? \'<button onclick=\"exitAlignment()\">Cannot Align</button><button onclick=\"exitAlignment()\">Alignment Good</button>\' : \'<button onclick=\"testAlignment()\">Print Again</button>\' ) + `\r\n        </div>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#userPrompt\', { display: \'none\' });\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction exitAlignment () {\r\n  window.gsap.set(\'#actionsBar\', { display: \'block\' });\r\n  window.gsap.set(\'#instructions\', { display: \'block\' });\r\n  window.gsap.set(\'#userPrompt\', { display: \'none\' });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      /*const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }*/\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = true;\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(379, '2022-10-24 09:55:49', 6, '7680 Burn-in', '<style>\r\n  #burnInWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #selectMenu {\r\n      background-color:rgba(0,0,0,0.1);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 10px;\r\n    }\r\n      #selectMenu label {\r\n        font-weight: bold;\r\n      }\r\n      #selectMenu select{\r\n        padding:5px;\r\n      }\r\n    #instructions {\r\n      border: 1px solid rgba(0,0,0,0.1);\r\n      border-radius: 15px;\r\n      padding: 20px;\r\n      margin:20px;\r\n      font-size: 120%;\r\n    }\r\n    #actionsBar {\r\n      width: 100%;\r\n      height: 80px;\r\n      position:fixed;\r\n      bottom:0;\r\n      left:0;\r\n      background-color: rgb(18, 52, 117);\r\n      color: white;\r\n      font-size: 200%;\r\n      text-align: center;\r\n      padding: 10px 0;\r\n    }\r\n      #actionsBar .center{\r\n        width:100%;\r\n        margin:0 auto;\r\n      }\r\n      #actionsBar button {\r\n        display:inline-block;\r\n        width: 21%;\r\n        margin:0 2%;\r\n        font-size: 19px;\r\n        line-height: 24px;\r\n        height: 60px;\r\n        float: left;\r\n      }\r\n    .alignmentTbl {\r\n      font-size: 90%;\r\n      width: 100%;\r\n    }\r\n      .alignmentTbl td{\r\n        text-align: center;\r\n      }\r\n      .alignmentTbl button {\r\n        display: inline-block;\r\n        width:100px;\r\n      }\r\n\r\n    .alignBg {\r\n      background-repeat: no-repeat;\r\n      background-position: left bottom;\r\n      background-size: contain;\r\n      vertical-align: top;\r\n      font-weight: bold;\r\n      font-size: 120%;\r\n    }\r\n\r\n    .burstOpt {\r\n      background-color: #275676;\r\n    }\r\n    .horizontalOpt {\r\n      background-color: #277627;\r\n    }\r\n    .alignInstructions {\r\n      background-color: rgba(255,255,255,0.9);\r\n      padding:10px;\r\n      max-width: 768px;\r\n      margin: 10px auto;\r\n      border-radius: 10px;\r\n      box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n    }\r\n    .selected {\r\n      background-color: #aaa;\r\n    }\r\n    .alignBtns {\r\n      text-align: right;\r\n    }\r\n      .alignBtns button{\r\n        margin: 10px;\r\n      }\r\n</style>\r\n<div id=\"burnInWrapper\">\r\n  <div id=\"selectMenu\">\r\n    <label for=\"selectCommunications\">Select Communications:</label>\r\n    <select name=\"selectCommunications\" id=\"selectCommunications\" onchange=\"updateCommunications()\">\r\n      <option value=\"serial\" selected=\"selected\">Serial</option>\r\n      <option value=\"usb\">USB</option>\r\n    </select>\r\n  </div>\r\n  <div id=\"instructions\">Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.</div>\r\n  <div id=\"userPrompt\"></div>\r\n  <div id=\"actionsBar\">\r\n    <div class=\"center\">\r\n      <button onclick=\"setHorizontalAlignmentAndPrint(2)\">Set Horizontal Alignment = 2</button>\r\n      <button onclick=\"testAlignmentBtn()\">Test Alignment</button>\r\n      <button onclick=\"startBurnIn()\">Start Burn-In</button>\r\n      <button onclick=\"unlockVault()\">Unlock Vault</button>\r\n      <div style=\"clear: both;\"></div>\r\n    </div>\r\n  </div>\r\n</div>', 'function updateCommunications () {\r\n  window.selectedProduct.currentCommunications = document.getElementById(\'selectCommunications\').value;\r\n  switch(window.selectedProduct.currentCommunications) {\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'serial\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, Serial connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n    case \'usb\':\r\n      document.getElementById(\'instructions\').innerHTML = \'Ensure device vault has 20 forms loaded, vault is connected, ribbon loaded, USB connected, and device is turned on.\';\r\n    break;\r\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (!window.selectedProduct.productionId) {\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        const macAdress = await getMacAddress();\r\n\r\n        // Set up start entry in tests database\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"createInitialTrackingEntry\",\r\n              params: {\r\n                productId: window.selectedProduct.productId,\r\n                testSetId: 0,\r\n                testerName: window.selectedProduct.testerName,\r\n                macAddress: macAdress\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (response.data.success) {\r\n          window.selectedProduct.productionId = response.data.productionId;\r\n\r\n          // Set up start entry in analytics database\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"createInitialTrackingEntry\",\r\n                params: {\r\n                  serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                  productId: window.selectedProduct.productId,\r\n                  productTitle: window.selectedProduct.productTitle,\r\n                  testSetId: 7680,\r\n                  testSetTitle: \'Burn-In\',\r\n                  testerName: window.selectedProduct.testerName,\r\n                  macAddress: macAdress,\r\n                  productionId: window.selectedProduct.productionId\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n          if (analyticsResponse.data.success) {\r\n            window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n          }\r\n        }\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction endTestLog () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.productionId) {\r\n        // Inform tests server that all tests passed\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        // Inform analytics server that all tests passed\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"passProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        window.selectedProduct.productionId = null;\r\n      }\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject (err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setBurstAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.burstAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Burst Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = false;\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignment (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.productionResults.horizontalAlignment = alignmentValue;\r\n\r\n      window.Notify.create({\r\n        message: \'Set Horizontal Alignment to: \' + alignmentValue,\r\n        position: \'top\',\r\n        color: \'positive\'\r\n      });\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = false;\r\n\r\n      showAlignmentForm();\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction setHorizontalAlignmentAndPrint (alignmentValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setHorizontalAlignment(alignmentValue);\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignmentBtn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkBurstSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.burstAlignment && window.selectedProduct.productionResults.burstAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkHorizontalSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.horizontalAlignment !== null && window.selectedProduct.productionResults.horizontalAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction showAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#actionsBar\', { display: \'none\' });\r\n      window.gsap.set(\'#instructions\', { display: \'none\' });\r\n      document.getElementById(\'userPrompt\').innerHTML = `\r\n        <table class=\"alignmentTbl\">\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\" class=\"` + checkBurstSelection(62) + `\">62</button></td>\r\n            <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\" class=\"` + checkBurstSelection(63) + `\">63</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\" class=\"` + checkBurstSelection(64) + `\">64</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\" class=\"` + checkBurstSelection(65) + `\">65</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\" class=\"` + checkBurstSelection(66) + `\">66</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\" class=\"` + checkBurstSelection(67) + `\">67</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\" class=\"` + checkBurstSelection(68) + `\">68 (default)</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\" class=\"` + checkBurstSelection(69) + `\">69</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\" class=\"` + checkBurstSelection(70) + `\">70</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\" class=\"` + checkBurstSelection(71) + `\">71</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\" class=\"` + checkBurstSelection(72) + `\">72</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\" class=\"` + checkBurstSelection(73) + `\">73</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\" class=\"` + checkBurstSelection(74) + `\">74</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\" class=\"` + checkBurstSelection(75) + `\">75</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\" class=\"` + checkBurstSelection(76) + `\">76</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\" class=\"` + checkBurstSelection(77) + `\">77</button></td>\r\n          </tr>\r\n          <tr>\r\n            <td></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\" class=\"` + checkHorizontalSelection(0) + `\">0</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\" class=\"` + checkHorizontalSelection(1) + `\">1</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\" class=\"` + checkHorizontalSelection(2) + `\">2</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\" class=\"` + checkHorizontalSelection(3) + `\">3</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\" class=\"` + checkHorizontalSelection(4) + `\">4</button></td>\r\n            <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\" class=\"` + checkHorizontalSelection(5) + `\">5</button></td>\r\n          </tr>\r\n        </table>\r\n        <div class=\"alignBtns\">\r\n          ` + (window.selectedProduct.alignmentNotAdjusted ? \'<button onclick=\"exitAlignment()\">Cannot Align</button><button onclick=\"exitAlignment()\">Alignment Good</button>\' : \'<button onclick=\"testAlignment()\">Print Again</button>\' ) + `\r\n        </div>\r\n      `;\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#userPrompt\', { display: \'none\' });\r\n      await testAlignment();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction exitAlignment () {\r\n  window.gsap.set(\'#actionsBar\', { display: \'block\' });\r\n  window.gsap.set(\'#instructions\', { display: \'block\' });\r\n  window.gsap.set(\'#userPrompt\', { display: \'none\' });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction testAlignment () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await startTestLog();\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n          let barcode = await window.genericRS232.getBytes(14);\r\n          let lineFeed = new Array(16).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await printStringViaSerial(\'Barcode is: \');\r\n          barcode.pop();\r\n          barcode.pop();\r\n          barcode.push(0x0A);\r\n          await window.genericRS232.sendBytes(barcode);\r\n\r\n          await printStringViaSerial(\'B/F VER: \');\r\n          const fwVersion = await getFirmwareVersionSerial();\r\n          await printStringViaSerial(fwVersion);\r\n          await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeed = new Array(6).fill(0x0A);\r\n          await window.genericRS232.sendBytes(lineFeed);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await window.genericRS232.sendBytes(lotsOfH);\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaSerial(\'11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaSerial(\' ****\');\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaSerial(\'         11\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericRS232.sendBytes([0x0A]);\r\n          await printStringViaSerial(dateString);\r\n          await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUsb = await getSecurityBytesUsb(\'loadFormKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4A, securityResultUsb[0], securityResultUsb[1], 0x0C]);\r\n          let barcodeUsb = await window.genericUSB.getBytes(14);\r\n          let lineFeedUsb = new Array(16).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await printStringViaUsb(\'Barcode is: \');\r\n          barcodeUsb.pop();\r\n          barcodeUsb.pop();\r\n          barcodeUsb.push(0x0A);\r\n          await window.genericUSB.sendBytes(barcodeUsb);\r\n\r\n          await printStringViaUsb(\'B/F VER: \');\r\n          const fwVersionUsb = await getFirmwareVersionUsb();\r\n          await printStringViaUsb(fwVersionUsb);\r\n          await printStringViaUsb(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH \' + dateString + \' $11.11\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n          lineFeedUsb = new Array(6).fill(0x0A);\r\n          await window.genericUSB.sendBytes(lineFeedUsb);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          \r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await window.genericUSB.sendBytes(lotsOfH);\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n          await window.genericUSB.sendBytes([0x0A, 0x0A]);\r\n\r\n          await printStringViaUsb(\'HHHHH LOCATION 82501                         \');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n          await printStringViaUsb(\'11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await printStringViaUsb(\' ****\');\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(\'HHHHH Time \' + timeString);\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n          await printStringViaUsb(\'         11\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n          await window.genericUSB.sendBytes([0x0A]);\r\n          await printStringViaUsb(dateString);\r\n          await window.genericUSB.sendBytes([0x0A, 0x1B, 0x45]); // Bold\r\n\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      window.selectedProduct.alignmentNotAdjusted = true;\r\n      await showAlignmentForm();\r\n\r\n      window.Loading.hide();\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction startBurnIn () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFE]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          await window.genericUSB.sendBytes([0x1B, 0x4E, 0xFE]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n\r\n      await endTestLog();\r\n      window.gsap.set(\'#instructions\', { display: \'block\' });\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction unlockVault () {\r\n  return new Promise(async (resolve, reject) => {\r\n    let usbConnected = false;\r\n    try {\r\n      switch (window.selectedProduct.currentCommunications) {\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'serial\':\r\n          if (!window.selectedProduct.comPort) {\r\n            // Find the com port\r\n            await findComPort();\r\n          }\r\n\r\n          await connectToSerial(window.selectedProduct.comPort);\r\n          const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n          await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n        case \'usb\':\r\n          await connectToUsb();\r\n          usbConnected = true;\r\n          const securityResultUSB = await getSecurityBytesUsb(\'feederKey\');\r\n          await window.genericUSB.sendBytes([0x1B, 0x55, 0x33, securityResultUSB[0], securityResultUSB[1]]);\r\n          await disconnectFromUsb();\r\n          usbConnected = false;\r\n        break;\r\n        // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ //\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      if(usbConnected) {\r\n        await disconnectFromUsb();\r\n        usbConnected = false;\r\n      }\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findComPort () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const foundDevice = await isPrinterOnSerial();\r\n      if (foundDevice.foundPrinter) {\r\n        window.selectedProduct.comPort = foundDevice.printerCom;\r\n        resolve();\r\n      } else {\r\n        reject(\'Could not find the printer connected via serial.\');\r\n      }\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    updateCommunications();\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get API script (specifically 4 = 7680 API)\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n      {\r\n        query: {\r\n          dataset: \"apis\",\r\n          action: \"getApi\",\r\n          params: {\r\n            apiId: 4\r\n          }\r\n        }\r\n      }, \r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if(response.data.success) {\r\n      // Destroy old API if exists\r\n      const oldApiScript = document.getElementById(\'apiScript\');\r\n      if (oldApiScript) {\r\n        oldApiScript.remove();\r\n      }\r\n\r\n      // Create new API script\r\n      const apiScript = document.createElement(\'script\');\r\n      apiScript.id = \'apiScript\';\r\n      apiScript.text = response.data.script;\r\n      apiScript.type = \'text/javascript\';\r\n      document.body.appendChild(apiScript);\r\n    }\r\n    \r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(380, '2022-10-26 11:34:49', 4, 'Generic Tests in Test Set', '<style>\r\n  #testList {\r\n    overflow-y: scroll;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 77px);\r\n  }\r\n    .testStep{\r\n      border-top:1px solid rgba(255,255,255,0.2);\r\n      border-bottom: 1px solid rgba(0,0,0,0.2);\r\n      padding: 8px 10px;\r\n      cursor: pointer;\r\n    }\r\n  #testActions{\r\n    text-align: right;\r\n    position: fixed;\r\n    bottom: 10px;\r\n    right: 20px;\r\n    width: calc(100vw - 300px);\r\n  }\r\n  #testSetTitle {\r\n    text-align: right;\r\n    font-size: 120%;\r\n    font-weight: bold;\r\n    color:rgba(0,0,0,0.5);\r\n    padding-right: 20px;\r\n  }\r\n  #testWrapper {\r\n    padding-right: 20px;\r\n  }\r\n  .actionBtn {\r\n    display: inline-block;\r\n    border: 1px solid rgba(0,0,0,0.1);\r\n    border-radius: 10px;\r\n    padding: 10px 15px;\r\n    font-weight: bold;\r\n    background-color:#1976d2;\r\n    color: #fff;\r\n    cursor: pointer;\r\n  }\r\n    .actionBtn:hover {\r\n      background-color: #96c997;\r\n      color:#000;\r\n    }\r\n</style>\r\n<div style=\"float:left; background:rgba(128,128,128,0.4); border-right:1px solid rgba(0,0,0,0.1); width: 260px; height:100%;\">\r\n  <div style=\"text-align:center; font-weight:bold; font-size:120%; opacity:0.7;\">Test Steps</div>\r\n  <div id=\"testList\"></div>\r\n</div>\r\n<div style=\"float:right; width: calc(100vw - 280px); height:100%;\">\r\n  <div id=\"testSetTitle\"></div>\r\n  <div id=\"testWrapper\"></div>\r\n  <div id=\"testActions\">\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"individualTestMode()\" id=\"individualTestMode\">Switch to Individual Tests</div>\r\n    <div class=\"actionBtn\" style=\"float: left;\" onclick=\"sequentialTestMode()\" id=\"sequentialTestMode\">Switch to Sequential Tests</div>\r\n    <div class=\"actionBtn\" onclick=\"reRunTests()\" id=\"reRunTests\">Test Another Device</div>\r\n    <div class=\"actionBtn\" onclick=\"retryTest()\" id=\"retryTest\">Retry Test</div>\r\n    <div class=\"actionBtn\" onclick=\"startTest()\" id=\"startTest\">Start Test</div>\r\n  </div>\r\n</div>', 'async function startTest () {\r\n  let continueProcessing = true;\r\n\r\n  window.gsap.set(\"#startTest\", {display: \"none\"});\r\n\r\n  // Mark test progress\r\n  await markTestProgress ();\r\n\r\n  // Destroy old test script\r\n  const oldScript = document.getElementById(\'testScript\');\r\n  if (oldScript) {\r\n    oldScript.remove();\r\n  }\r\n\r\n  // Determine if it is the start of a production test and if so, start tracking full test set\r\n  if (window.selectedProduct.currentTestIndex === 0 && !window.selectedProduct.individualTestMode) {\r\n    continueProcessing = false;\r\n    const macAdress = await getMacAddress();\r\n\r\n    // Reset local tracking of production test\r\n    window.selectedProduct.productionId = null;\r\n    window.selectedProduct.analyticsProductionId = null;\r\n    window.selectedProduct.analyticsResults = {};\r\n    window.selectedProduct.productionResults = {};\r\n    window.selectedProduct.productionResults.files = {};\r\n\r\n    // Set up start entry in tests database\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"createInitialTrackingEntry\",\r\n          params: {\r\n            productId: window.selectedProduct.productId,\r\n            testSetId: window.selectedProduct.selectedTestSet.testSetId,\r\n            testerName: window.selectedProduct.testerName,\r\n            macAddress: macAdress\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.productionId = response.data.productionId;\r\n\r\n      // Set up start entry in analytics database\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"createInitialTrackingEntry\",\r\n            params: {\r\n              serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n              productId: window.selectedProduct.productId,\r\n              productTitle: window.selectedProduct.productTitle,\r\n              testSetId: window.selectedProduct.selectedTestSet.testSetId,\r\n              testSetTitle: window.selectedProduct.selectedTestSet.title,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAdress,\r\n              productionId: window.selectedProduct.productionId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      continueProcessing = true; // Do NOT depend on analytics to continue\r\n\r\n      if (analyticsResponse.data.success) {\r\n        window.selectedProduct.analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n      }\r\n    } else {\r\n      promptUser(\'Failed to create production tracking entry\');\r\n    }\r\n  }\r\n\r\n  // Load script\r\n  if (continueProcessing && window.selectedProduct.tests[window.selectedProduct.currentTestIndex]) {\r\n    const script = document.createElement(\'script\');\r\n    script.type = \'text/javascript\';\r\n    script.text = window.selectedProduct.tests[window.selectedProduct.currentTestIndex].script;\r\n    script.id = \'testScript\';\r\n    document.body.appendChild(script);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function markTestProgress () {\r\n  if (!window.selectedProduct.individualTestMode) {\r\n    window.selectedProduct.tests.forEach((test, index) => {\r\n      if (index < window.selectedProduct.currentTestIndex) {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"#b5f5b9\"});\r\n      } else if (index === window.selectedProduct.currentTestIndex) {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"#f1f5b5\"});\r\n      } else {\r\n        window.gsap.set(`#testStep${index}`, {backgroundColor: \"rgba(128,128,128,0)\"});\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clearTestProgress () {\r\n  window.selectedProduct.tests.forEach((test, index) => {\r\n    window.gsap.set(`#testStep${index}`, {backgroundColor: \"rgba(128,128,128,0)\"});\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction loadTemplate () {\r\n  return new Promise(resolve => {\r\n    window.gsap.to(\"#testWrapper\", {opacity: 0, duration: 0.2, onComplete: () => {\r\n      document.getElementById(\'testWrapper\').innerHTML = window.selectedProduct.tests[window.selectedProduct.currentTestIndex].codeset;\r\n      window.gsap.to(\"#testWrapper\", {opacity: 1, duration: 0.2, onComplete: () => {\r\n        resolve();\r\n      }});\r\n    }});\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function individualTestMode() {\r\n  window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n  window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n  window.gsap.set(\"#individualTestMode\", {display: \"none\"});\r\n  window.gsap.set(\"#startTest\", {display: \"none\"});\r\n  window.gsap.set(\"#sequentialTestMode\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#sequentialTestMode\", {opacity: 1, duration: 0.2});\r\n  clearTestProgress();\r\n  window.selectedProduct.individualTestMode = true;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function sequentialTestMode() {\r\n  reRunTests();\r\n  window.gsap.set(\"#sequentialTestMode\", {display: \"none\"});\r\n  window.gsap.set(\"#individualTestMode\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#individualTestMode\", {opacity: 1, duration: 0.2});\r\n  window.gsap.set(\"#startTest\", {display: \"inline-block\"});\r\n  window.selectedProduct.individualTestMode = false;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function runSingleTest (testIndex) {\r\n  if (window.selectedProduct.individualTestMode) {\r\n    window.selectedProduct.currentTestIndex = testIndex;\r\n    await loadTemplate();\r\n    window.gsap.set(\"#startTest\", {display: \"inline-block\", opacity: 0});\r\n    window.gsap.to(\"#startTest\", {opacity: 1, duration: 0.2});\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function saveTestAnalytics (testPassed, failMsg) {\r\n  const macAdress = await getMacAddress();\r\n  const extAnalyticsProductionId = window.selectedProduct.individualTestMode ? 0 : window.selectedProduct.analyticsProductionId;\r\n\r\n  if (window.selectedProduct.customError) {\r\n    customError = window.selectedProduct.customError;\r\n  } else {\r\n    customError = \'\';\r\n  }\r\n\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: getElapsedTime(),\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSet.title,\r\n          testTitle: window.selectedProduct.tests[window.selectedProduct.currentTestIndex].title,\r\n          testId: window.selectedProduct.tests[window.selectedProduct.currentTestIndex].testId,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: failMsg,\r\n          customError: (testPassed ? \'\' : customError)\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  // Save analytics\r\n  await saveTestAnalytics(true,\'\');\r\n\r\n  window.Notify.create({\r\n    message: \'Passed \' + window.selectedProduct.tests[window.selectedProduct.currentTestIndex].title + \' test\',\r\n    position: \'top\',\r\n    color: \'positive\'\r\n  });\r\n\r\n  // Advance Forward if in sequential mode\r\n  if (!window.selectedProduct.individualTestMode) {\r\n    if (window.selectedProduct.currentTestIndex < window.selectedProduct.tests.length - 1) {\r\n      window.selectedProduct.currentTestIndex++;\r\n      await markTestProgress ();\r\n      await loadTemplate();\r\n      startTest();\r\n    } else {\r\n      window.selectedProduct.currentTestIndex++;\r\n      await markTestProgress ();\r\n\r\n      // Inform tests server that all tests passed\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"passProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      // Inform analytics server that all tests passed\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"passProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      // Inform user that all tests passed\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div style=\"text-align: center; margin-top: 50px; border:2px solid #008001; padding: 15px; border-radius:15px; font-weight:bold; font-size:140%; color:#008001; background-color:#dbfadb;\">All Tests Passed!</div>\r\n      `;\r\n\r\n      window.gsap.set(\"#reRunTests\", {display: \"inline-block\"});\r\n    }\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  // Prompt user to select fail reason\r\n  // Get product fail reasons\r\n  const failReasonsResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"products\",\r\n        action: \"getProductFailReasons\",\r\n        params: {\r\n          productId: window.selectedProduct.productId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (failReasonsResponse.data.success) {\r\n    window.Dialog.create({\r\n      title: \'Select Fail Reason\',\r\n      html: true,\r\n      message: `\r\n        <div style=\"color:red; font-weight:bold;\">${err}</div>\r\n        Select a fail reason from the list below:\r\n        <select id=\"failReasonSelect\">\r\n        \r\n          ${failReasonsResponse.data.failReasons.map(failReason => {\r\n            return `<option value=\"${failReason.title}\">${failReason.title}</option>`;\r\n          })}\r\n          <option value=\"other\">Other</option>\r\n        </select>\r\n      `\r\n    }).onOk(async () => {\r\n      window.selectedProduct.customError = document.getElementById(\'failReasonSelect\').value;\r\n\r\n      // Save analytics\r\n      await saveTestAnalytics(false, err);\r\n\r\n      window.gsap.set(\"#retryTest\", {display: \"inline-block\"});\r\n    });\r\n  } else {\r\n    window.selectedProduct.customError = \'Other\';\r\n    await promptUser(err);\r\n\r\n    // Save analytics\r\n    await saveTestAnalytics(false, err);\r\n\r\n    window.gsap.set(\"#retryTest\", {display: \"inline-block\"});\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function retryTest() {\r\n  window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n  await loadTemplate();\r\n  startTest();\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function reRunTests () {\r\n  window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n  window.selectedProduct.currentTestIndex = 0;\r\n  window.selectedProduct.productionResults = {};\r\n  window.selectedProduct.productionResults.files = {};\r\n  await markTestProgress ();\r\n  await loadTemplate();\r\n  window.gsap.set(\"#startTest\", {display: \"inline-block\", opacity: 0});\r\n  window.gsap.to(\"#startTest\", {opacity: 1, duration: 0.2});\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    // Set test set title\r\n    document.getElementById(\'testSetTitle\').innerHTML = window.selectedProduct.selectedTestSet.title;\r\n\r\n    // Hide buttons\r\n    window.gsap.set(\"#retryTest\", {display: \"none\"});\r\n    window.gsap.set(\"#reRunTests\", {display: \"none\"});\r\n    window.gsap.set(\"#sequentialTestMode\", {display: \"none\"});\r\n\r\n    // Get product config\r\n    const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getProductConfigForTestSet\",\r\n          params: {\r\n            testSetId: window.selectedProduct.selectedTestSet.testSetId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    // Set product config\r\n    if (productCfgResponse.data.success) {\r\n      window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n      // Get the list of tests\r\n      const testResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"testSets\",\r\n            action: \"getTestsForTestSet\",\r\n            params: {\r\n              testSetId: window.selectedProduct.selectedTestSet.testSetId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n      if (testResponse.data.success) {\r\n        window.selectedProduct.tests = testResponse.data.tests;\r\n        window.selectedProduct.currentTestIndex = 0;\r\n        window.selectedProduct.productionResults = {};\r\n        window.selectedProduct.productionResults.files = {};\r\n\r\n        let preprocess = \'\';\r\n        testResponse.data.tests.forEach((test, index) => {\r\n          preprocess += \'<div class=\"testStep\" id=\"testStep\' + index + \'\" onclick=\"runSingleTest(\' + index + \')\">\' + test.title + \'</div>\';\r\n        });\r\n        document.getElementById(\'testList\').innerHTML = preprocess;\r\n\r\n        // Load first test template but don\'t run script until start is clicked\r\n        document.getElementById(\'testWrapper\').innerHTML = window.selectedProduct.tests[0].codeset;\r\n\r\n        window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n      } else {\r\n        promptUser(\'Failed to get any tests\');\r\n      }\r\n    } else {\r\n      promptUser(\'Failed to get the config for this product\');\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(381, '2022-10-26 16:04:34', 7, '7680 Palletize', '', '', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(382, '2022-10-31 08:15:03', 7, '7680 Palletize', '<style>\r\n  #palletizeWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n</style>', '', 1),
(383, '2022-10-31 08:18:49', 7, '7680 Palletize', '<style>\r\n  #palletizeWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n</style>\r\n<div id=\"palletizeWrapper\">\r\n  <div id=\"instructions\">Instructions:</div>\r\n  <div id=\"inputFrm\">Frm</div>\r\n  <div id=\"results\">Results</div>\r\n</div>', '// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(384, '2022-10-31 08:24:39', 7, '7680 Palletize', '<style>\r\n  #palletizeWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n</style>\r\n<div id=\"palletizeWrapper\">\r\n  <div id=\"instructions\">Instructions:</div>\r\n  <div id=\"inputFrm\">Frm</div>\r\n  <div id=\"results\">Results</div>\r\n</div>', '// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Find where at in the palletizing process we are\r\n    const currentStep = await window.axios.post(window.selectedProduct.apiUrl,\r\n      {\r\n        query: {\r\n          dataset: \'7680palletize\',\r\n          action: \'getStep\',\r\n          params: {}\r\n        }\r\n      },\r\n      { headers: { \'Content-Type\': \'application/json\' } }\r\n    );\r\n\r\n    echo(\'currentStep\', currentStep.data);\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
