ex = /^5785/;\r\n      if (vaultBarcode.length !== 14 || !regex.test(vaultBarcode)) {\r\n        document.getElementById(\'vaultBarcode\').value = \'\';\r\n        throw new Error(\'Invalid vault barcode\');\r\n      }\r\n\r\n      // Add item to pallet\r\n      const macAddress = await getMacAddress();\r\n      const item = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'addItem\',\r\n            params: {\r\n              palletId: palletId,\r\n              primarySerialNum: mainBarcode,\r\n              secondarySerialNum: vaultBarcode,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (item.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(item.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}  \r\n// ---------------------------------------------------------- //\r\nfunction focusOnVault() {\r\n  document.getElementById(\'vaultBarcode\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction buildProgressReport (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Get pallet data\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'progressReport\',\r\n            params: {\r\n              palletId: palletId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        // Build progress report\r\n        let itemsList = \'\';\r\n        pallet.data.items.forEach(item => {\r\n          itemsList += `<li>${item.primarySerialNum}<br/> ${item.secondarySerialNum}</li>`;\r\n        });\r\n\r\n\r\n        document.getElementById(\'results\').innerHTML = `\r\n          <div class=\"progressHeading\">Order Progress</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.orderCurrentQty * 100 / pallet.data.orderTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.orderCurrentQty} / ${pallet.data.orderTargetQty}</div>\r\n\r\n          <div class=\"progressHeading\">Current Pallet</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.palletCurrentQty * 100 / pallet.data.palletTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.palletCurrentQty} / ${pallet.data.palletTargetQty}</div>\r\n\r\n          <div class=\"palletItems\">\r\n            <ul>\r\n              ${itemsList}\r\n            </ul>\r\n          </div>\r\n        `;\r\n      } else {\r\n        throw new Error(\'Could not build progress report\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan main barcode followed by matching vault barcode.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"focusOnVault(); return false;\">\r\n        <input type=\"text\" id=\"mainBarcode\" class=\"form-control\" placeholder=\"Scan Main Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\" style=\"opacity:0;\">Submit</button>\r\n      </form>\r\n      <form id=\"barcode2Frm\" onsubmit=\"addItem(${palletId}); return false;\">\r\n        <input type=\"text\" id=\"vaultBarcode\" class=\"form-control\" placeholder=\"Scan Vault Barcode\">\r\n        <button type=\"button\" id=\"submit2\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'mainBarcode\').focus();\r\n\r\n      // Build progress report\r\n      await buildProgressReport(palletId);\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new pallet format\r\n      const regex = /^806576/; // (remaining digits are the quantity of items)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new pallet\r\n      const macAddress = await getMacAddress();\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createPallet\',\r\n            params: {\r\n              orderId: orderId,\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(pallet.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items to be place on this pallet.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createPallet(${orderId}); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new order format\r\n      const regex = /^798268/; // (remaining digits are the quantity of items in the order)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new order\r\n      const macAddress = await getMacAddress();\r\n      const newOrder = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createOrder\',\r\n            params: {\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (newOrder.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(\'Could not create new order\');\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items in the order.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createOrder(); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findCurrentStep () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Find where at in the palletizing process we are\r\n      const currentStep = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'getStep\',\r\n            params: {}\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (currentStep.data.success) {\r\n        switch (currentStep.data.currentStep) {\r\n          case \'newOrder\':\r\n            await newOrder();\r\n          break;\r\n          case \'newPallet\':\r\n            await newPallet(currentStep.data.currentId);\r\n          break;\r\n          case \'newItem\':\r\n            await newItem(currentStep.data.currentId);\r\n          break;\r\n        }\r\n      } else {\r\n        throw new Error(\'Could not determine current step\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    await findCurrentStep();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(412, '2022-10-31 13:27:59', 7, '7680 Palletize', '<style>\r\n  #palletizeWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #palletizeWrapper #instructions {\r\n      margin: 20px 20px 10px 20px;\r\n      font-weight: bold;\r\n      font-size: 115%;\r\n    }\r\n    #palletizeWrapper #inputFrm {\r\n      margin: 0px 20px 20px 20px;\r\n    }\r\n    #palletizeWrapper #results {\r\n      margin: 0px 20px 0 20px;\r\n    }\r\n  .progressHeading {\r\n    font-weight: bold;\r\n    font-size: 115%;\r\n    text-align: center;\r\n  }\r\n  .progressBar {\r\n    width: 100%;\r\n    height: 20px;\r\n    background-color: #ddd;\r\n  }\r\n  .progressBar div {\r\n    height: 100%;\r\n    background-color: #4CAF50;\r\n    width: 0%;\r\n  }\r\n  .progressDescription {\r\n    text-align: center;\r\n    margin-bottom: 10px;\r\n  }\r\n  .palletItems {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    justify-content: center;\r\n  }\r\n  .palletItems ul{\r\n    list-style-type: none;\r\n    margin: 0;\r\n    padding: 0;\r\n  }\r\n  .palletItems li {\r\n    margin: 5px;\r\n    padding: 5px;\r\n    border: 1px solid #ddd;\r\n    border-radius: 5px;\r\n    background-color: #f1f1f1;\r\n    text-align: center;\r\n  }\r\n</style>\r\n<div id=\"palletizeWrapper\">\r\n  <div id=\"instructions\"></div>\r\n  <div id=\"inputFrm\"></div>\r\n  <div id=\"results\"></div>\r\n</div>', 'function addItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const mainBarcode = document.getElementById(\'mainBarcode\').value;\r\n      const vaultBarcode = document.getElementById(\'vaultBarcode\').value;\r\n\r\n      // Validate barcode matches format\r\n      let regex = /^7680/;\r\n      if (mainBarcode.length !== 14 || !regex.test(mainBarcode)) {\r\n        document.getElementById(\'mainBarcode\').value = \'\';\r\n        throw new Error(\'Invalid main barcode\');\r\n      }\r\n      regex = /^5785/;\r\n      if (vaultBarcode.length !== 14 || !regex.test(vaultBarcode)) {\r\n        document.getElementById(\'vaultBarcode\').value = \'\';\r\n        throw new Error(\'Invalid vault barcode\');\r\n      }\r\n\r\n      // Add item to pallet\r\n      const macAddress = await getMacAddress();\r\n      const item = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'addItem\',\r\n            params: {\r\n              palletId: palletId,\r\n              primarySerialNum: mainBarcode,\r\n              secondarySerialNum: vaultBarcode,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (item.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(item.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}  \r\n// ---------------------------------------------------------- //\r\nfunction focusOnVault() {\r\n  document.getElementById(\'vaultBarcode\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction buildProgressReport (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Get pallet data\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'progressReport\',\r\n            params: {\r\n              palletId: palletId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        // Build progress report\r\n        let itemsList = \'\';\r\n        pallet.data.items.forEach(item => {\r\n          itemsList += `<li>${item.primarySerialNum}<br/> ${item.secondarySerialNum}</li>`;\r\n        });\r\n\r\n\r\n        document.getElementById(\'results\').innerHTML = `\r\n          <div class=\"progressHeading\">Order Progress</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.orderCurrentQty * 100 / pallet.data.orderTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.orderCurrentQty} / ${pallet.data.orderTargetQty}</div>\r\n\r\n          <div class=\"progressHeading\">Current Pallet</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.palletCurrentQty * 100 / pallet.data.palletTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.palletCurrentQty} / ${pallet.data.palletTargetQty}</div>\r\n\r\n          <div class=\"palletItems\">\r\n            <ul>\r\n              ${itemsList}\r\n            </ul>\r\n          </div>\r\n        `;\r\n      } else {\r\n        throw new Error(\'Could not build progress report\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan main barcode followed by matching vault barcode.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"focusOnVault(); return false;\">\r\n        <input type=\"text\" id=\"mainBarcode\" class=\"form-control\" placeholder=\"Scan Main Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\" style=\"opacity:0;\">Submit</button>\r\n      </form>\r\n      <form id=\"barcode2Frm\" onsubmit=\"addItem(${palletId}); return false;\">\r\n        <input type=\"text\" id=\"vaultBarcode\" class=\"form-control\" placeholder=\"Scan Vault Barcode\">\r\n        <button type=\"button\" id=\"submit2\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'mainBarcode\').focus();\r\n\r\n      // Build progress report\r\n      await buildProgressReport(palletId);\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new pallet format\r\n      const regex = /^806576/; // (remaining digits are the quantity of items)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new pallet\r\n      const macAddress = await getMacAddress();\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createPallet\',\r\n            params: {\r\n              orderId: orderId,\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(pallet.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items to be place on this pallet.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createPallet(${orderId}); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new order format\r\n      const regex = /^798268/; // (remaining digits are the quantity of items in the order)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new order\r\n      const macAddress = await getMacAddress();\r\n      const newOrder = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createOrder\',\r\n            params: {\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (newOrder.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(\'Could not create new order\');\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items in the order.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createOrder(); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findCurrentStep () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Find where at in the palletizing process we are\r\n      const currentStep = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'getStep\',\r\n            params: {}\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (currentStep.data.success) {\r\n        switch (currentStep.data.currentStep) {\r\n          case \'newOrder\':\r\n            await newOrder();\r\n          break;\r\n          case \'newPallet\':\r\n            await newPallet(currentStep.data.currentId);\r\n          break;\r\n          case \'newItem\':\r\n            await newItem(currentStep.data.currentId);\r\n          break;\r\n        }\r\n      } else {\r\n        throw new Error(\'Could not determine current step\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    await findCurrentStep();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
