      regex = /^5785/;\r\n      if (vaultBarcode.length !== 14 || !regex.test(vaultBarcode)) {\r\n        document.getElementById(\'vaultBarcode\').value = \'\';\r\n        throw new Error(\'Invalid vault barcode\');\r\n      }\r\n\r\n      // Add item to pallet\r\n      const macAddress = await getMacAddress();\r\n      const item = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'addItem\',\r\n            params: {\r\n              palletId: palletId,\r\n              primarySerialNum: mainBarcode,\r\n              secondarySerialNum: vaultBarcode,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (item.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(item.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}  \r\n// ---------------------------------------------------------- //\r\nfunction focusOnVault() {\r\n  document.getElementById(\'vaultBarcode\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction buildProgressReport (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Get pallet data\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'progressReport\',\r\n            params: {\r\n              palletId: palletId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        // Build progress report\r\n        let itemsList = \'\';\r\n        pallet.data.items.forEach(item => {\r\n          itemsList += `<li>${item.primarySerialNum}<br/> ${item.secondarySerialNum}</li>`;\r\n        });\r\n\r\n\r\n        document.getElementById(\'results\').innerHTML = `\r\n          <div class=\"progressHeading\">Order Progress</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.orderCurrentQty * 100 / pallet.data.orderTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.orderCurrentQty} / ${pallet.data.orderTargetQty}</div>\r\n\r\n          <div class=\"progressHeading\">Current Pallet</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.palletCurrentQty * 100 / pallet.data.palletTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.palletCurrentQty} / ${pallet.data.palletTargetQty}</div>\r\n\r\n          <div class=\"palletItems\">\r\n            <ul>\r\n              ${itemsList}\r\n            </ul>\r\n          </div>\r\n        `;\r\n      } else {\r\n        throw new Error(\'Could not build progress report\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan main barcode followed by matching vault barcode.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"focusOnVault(); return false;\">\r\n        <input type=\"text\" id=\"mainBarcode\" class=\"form-control\" placeholder=\"Scan Main Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\" style=\"opacity:0;\">Submit</button>\r\n      </form>\r\n      <form id=\"barcode2Frm\" onsubmit=\"addItem(${palletId}); return false;\">\r\n        <input type=\"text\" id=\"vaultBarcode\" class=\"form-control\" placeholder=\"Scan Vault Barcode\">\r\n        <button type=\"button\" id=\"submit2\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'mainBarcode\').focus();\r\n\r\n      // Build progress report\r\n      await buildProgressReport(palletId);\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new pallet format\r\n      const regex = /^806576/; // (remaining digits are the quantity of items)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new pallet\r\n      const macAddress = await getMacAddress();\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createPallet\',\r\n            params: {\r\n              orderId: orderId,\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(pallet.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items to be place on this pallet.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createPallet(${orderId}); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new order format\r\n      const regex = /^798268/; // (remaining digits are the quantity of items in the order)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new order\r\n      const macAddress = await getMacAddress();\r\n      const newOrder = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createOrder\',\r\n            params: {\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (newOrder.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(\'Could not create new order\');\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items in the order.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createOrder(); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findCurrentStep () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Find where at in the palletizing process we are\r\n      const currentStep = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'getStep\',\r\n            params: {}\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (currentStep.data.success) {\r\n        switch (currentStep.data.currentStep) {\r\n          case \'newOrder\':\r\n            await newOrder();\r\n          break;\r\n          case \'newPallet\':\r\n            await newPallet(currentStep.data.currentId);\r\n          break;\r\n          case \'newItem\':\r\n            await newItem(currentStep.data.currentId);\r\n          break;\r\n        }\r\n      } else {\r\n        throw new Error(\'Could not determine current step\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    await findCurrentStep();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(414, '2022-10-31 13:32:30', 7, '7680 Palletize', '<style>\r\n  #palletizeWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #palletizeWrapper #instructions {\r\n      margin: 20px 20px 10px 20px;\r\n      font-weight: bold;\r\n      font-size: 115%;\r\n    }\r\n    #palletizeWrapper #inputFrm {\r\n      margin: 0px 20px 20px 20px;\r\n    }\r\n    #palletizeWrapper #results {\r\n      margin: 0px 20px 0 20px;\r\n    }\r\n  .progressHeading {\r\n    font-weight: bold;\r\n    font-size: 115%;\r\n    text-align: center;\r\n  }\r\n  .progressBar {\r\n    width: 100%;\r\n    height: 20px;\r\n    background-color: #ddd;\r\n  }\r\n  .progressBar div {\r\n    height: 100%;\r\n    background-color: #4CAF50;\r\n    width: 0%;\r\n  }\r\n  .progressDescription {\r\n    text-align: center;\r\n    margin-bottom: 10px;\r\n  }\r\n  .palletItems {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    justify-content: center;\r\n  }\r\n  .palletItems ul{\r\n    list-style-type: none;\r\n    margin: 0;\r\n    padding: 0;\r\n  }\r\n  .palletItems li {\r\n    margin: 5px;\r\n    padding: 5px;\r\n    border: 1px solid #ddd;\r\n    border-radius: 5px;\r\n    background-color: #f1f1f1;\r\n    text-align: center;\r\n    display: inline-block;\r\n  }\r\n</style>\r\n<div id=\"palletizeWrapper\">\r\n  <div id=\"instructions\"></div>\r\n  <div id=\"inputFrm\"></div>\r\n  <div id=\"results\"></div>\r\n</div>', '\r\nfunction addItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const mainBarcode = document.getElementById(\'mainBarcode\').value;\r\n      const vaultBarcode = document.getElementById(\'vaultBarcode\').value;\r\n\r\n      // Validate barcode matches format\r\n      let regex = /^7680/;\r\n      if (mainBarcode.length !== 14 || !regex.test(mainBarcode)) {\r\n        document.getElementById(\'mainBarcode\').value = \'\';\r\n        throw new Error(\'Invalid main barcode\');\r\n      }\r\n      regex = /^5785/;\r\n      if (vaultBarcode.length !== 14 || !regex.test(vaultBarcode)) {\r\n        document.getElementById(\'vaultBarcode\').value = \'\';\r\n        throw new Error(\'Invalid vault barcode\');\r\n      }\r\n\r\n      // Add item to pallet\r\n      const macAddress = await getMacAddress();\r\n      const item = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'addItem\',\r\n            params: {\r\n              palletId: palletId,\r\n              primarySerialNum: mainBarcode,\r\n              secondarySerialNum: vaultBarcode,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (item.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(item.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}  \r\n// ---------------------------------------------------------- //\r\nfunction focusOnVault() {\r\n  document.getElementById(\'vaultBarcode\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction buildProgressReport (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Get pallet data\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'progressReport\',\r\n            params: {\r\n              palletId: palletId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        // Build progress report\r\n        let itemsList = \'\';\r\n        pallet.data.items.forEach(item => {\r\n          itemsList += `<li>${item.primarySerialNum}<br/> ${item.secondarySerialNum}</li>`;\r\n        });\r\n\r\n\r\n        document.getElementById(\'results\').innerHTML = `\r\n          <div class=\"progressHeading\">Order Progress</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.orderCurrentQty * 100 / pallet.data.orderTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.orderCurrentQty} / ${pallet.data.orderTargetQty}</div>\r\n\r\n          <div class=\"progressHeading\">Current Pallet</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.palletCurrentQty * 100 / pallet.data.palletTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.palletCurrentQty} / ${pallet.data.palletTargetQty}</div>\r\n\r\n          <div class=\"palletItems\">\r\n            <ul>\r\n              ${itemsList}\r\n            </ul>\r\n          </div>\r\n        `;\r\n      } else {\r\n        throw new Error(\'Could not build progress report\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan main barcode followed by matching vault barcode.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"focusOnVault(); return false;\">\r\n        <input type=\"text\" id=\"mainBarcode\" class=\"form-control\" placeholder=\"Scan Main Barcode\">\r\n        <button type=\"submit\" id=\"submit\" class=\"btn btn-primary\" style=\"opacity:0;\">Submit</button>\r\n      </form>\r\n      <form id=\"barcode2Frm\" onsubmit=\"addItem(${palletId}); return false;\">\r\n        <input type=\"text\" id=\"vaultBarcode\" class=\"form-control\" placeholder=\"Scan Vault Barcode\">\r\n        <button type=\"submit\" id=\"submit2\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'mainBarcode\').focus();\r\n\r\n      // Build progress report\r\n      await buildProgressReport(palletId);\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new pallet format\r\n      const regex = /^806576/; // (remaining digits are the quantity of items)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new pallet\r\n      const macAddress = await getMacAddress();\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createPallet\',\r\n            params: {\r\n              orderId: orderId,\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(pallet.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items to be place on this pallet.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createPallet(${orderId}); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new order format\r\n      const regex = /^798268/; // (remaining digits are the quantity of items in the order)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new order\r\n      const macAddress = await getMacAddress();\r\n      const newOrder = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createOrder\',\r\n            params: {\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (newOrder.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(\'Could not create new order\');\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items in the order.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createOrder(); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findCurrentStep () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Find where at in the palletizing process we are\r\n      const currentStep = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'getStep\',\r\n            params: {}\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (currentStep.data.success) {\r\n        switch (currentStep.data.currentStep) {\r\n          case \'newOrder\':\r\n            await newOrder();\r\n          break;\r\n          case \'newPallet\':\r\n            await newPallet(currentStep.data.currentId);\r\n          break;\r\n          case \'newItem\':\r\n            await newItem(currentStep.data.currentId);\r\n          break;\r\n        }\r\n      } else {\r\n        throw new Error(\'Could not determine current step\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    await findCurrentStep();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_templates_archive` (`archiveId`, `generatedDateTime`, `templateId`, `title`, `codeset`, `script`, `active`) VALUES
(415, '2022-10-31 13:35:18', 7, '7680 Palletize', '<style>\r\n  #palletizeWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #palletizeWrapper #instructions {\r\n      margin: 20px 20px 10px 20px;\r\n      font-weight: bold;\r\n      font-size: 115%;\r\n    }\r\n    #palletizeWrapper #inputFrm {\r\n      margin: 0px 20px 20px 20px;\r\n    }\r\n    #palletizeWrapper #results {\r\n      margin: 0px 20px 0 20px;\r\n    }\r\n  .progressHeading {\r\n    font-weight: bold;\r\n    font-size: 115%;\r\n    text-align: center;\r\n  }\r\n  .progressBar {\r\n    width: 100%;\r\n    height: 20px;\r\n    background-color: #ddd;\r\n  }\r\n  .progressBar div {\r\n    height: 100%;\r\n    background-color: #4CAF50;\r\n    width: 0%;\r\n  }\r\n  .progressDescription {\r\n    text-align: center;\r\n    margin-bottom: 10px;\r\n  }\r\n  .palletItems {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    justify-content: center;\r\n  }\r\n  .palletItems ul{\r\n    list-style-type: none;\r\n    margin: 0;\r\n    padding: 0;\r\n  }\r\n  .palletItems li {\r\n    margin: 5px;\r\n    padding: 5px;\r\n    border: 1px solid #ddd;\r\n    border-radius: 5px;\r\n    background-color: #f1f1f1;\r\n    text-align: center;\r\n    display: inline-block;\r\n    font-size: 80%;\r\n  }\r\n</style>\r\n<div id=\"palletizeWrapper\">\r\n  <div id=\"instructions\"></div>\r\n  <div id=\"inputFrm\"></div>\r\n  <div id=\"results\"></div>\r\n</div>', 'function addItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const mainBarcode = document.getElementById(\'mainBarcode\').value;\r\n      const vaultBarcode = document.getElementById(\'vaultBarcode\').value;\r\n\r\n      // Validate barcode matches format\r\n      let regex = /^7680/;\r\n      if (mainBarcode.length !== 14 || !regex.test(mainBarcode)) {\r\n        document.getElementById(\'mainBarcode\').value = \'\';\r\n        throw new Error(\'Invalid main barcode\');\r\n      }\r\n      regex = /^5785/;\r\n      if (vaultBarcode.length !== 14 || !regex.test(vaultBarcode)) {\r\n        document.getElementById(\'vaultBarcode\').value = \'\';\r\n        throw new Error(\'Invalid vault barcode\');\r\n      }\r\n\r\n      // Add item to pallet\r\n      const macAddress = await getMacAddress();\r\n      const item = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'addItem\',\r\n            params: {\r\n              palletId: palletId,\r\n              primarySerialNum: mainBarcode,\r\n              secondarySerialNum: vaultBarcode,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (item.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(item.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}  \r\n// ---------------------------------------------------------- //\r\nfunction focusOnVault() {\r\n  document.getElementById(\'vaultBarcode\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction buildProgressReport (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Get pallet data\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'progressReport\',\r\n            params: {\r\n              palletId: palletId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        // Build progress report\r\n        let itemsList = \'\';\r\n        pallet.data.items.forEach(item => {\r\n          itemsList += `<li>${item.primarySerialNum}<br/> ${item.secondarySerialNum}</li>`;\r\n        });\r\n\r\n\r\n        document.getElementById(\'results\').innerHTML = `\r\n          <div class=\"progressHeading\">Order Progress</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.orderCurrentQty * 100 / pallet.data.orderTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.orderCurrentQty} / ${pallet.data.orderTargetQty}</div>\r\n\r\n          <div class=\"progressHeading\">Current Pallet</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.palletCurrentQty * 100 / pallet.data.palletTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.palletCurrentQty} / ${pallet.data.palletTargetQty}</div>\r\n\r\n          <div class=\"palletItems\">\r\n            <ul>\r\n              ${itemsList}\r\n            </ul>\r\n          </div>\r\n        `;\r\n      } else {\r\n        throw new Error(\'Could not build progress report\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan main barcode followed by matching vault barcode.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"focusOnVault(); return false;\">\r\n        <input type=\"text\" id=\"mainBarcode\" class=\"form-control\" placeholder=\"Scan Main Barcode\">\r\n        <button type=\"submit\" id=\"submit\" class=\"btn btn-primary\" style=\"opacity:0;\">Submit</button>\r\n      </form>\r\n      <form id=\"barcode2Frm\" onsubmit=\"addItem(${palletId}); return false;\">\r\n        <input type=\"text\" id=\"vaultBarcode\" class=\"form-control\" placeholder=\"Scan Vault Barcode\">\r\n        <button type=\"submit\" id=\"submit2\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'mainBarcode\').focus();\r\n\r\n      // Build progress report\r\n      await buildProgressReport(palletId);\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new pallet format\r\n      const regex = /^806576/; // (remaining digits are the quantity of items)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new pallet\r\n      const macAddress = await getMacAddress();\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createPallet\',\r\n            params: {\r\n              orderId: orderId,\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(pallet.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items to be place on this pallet.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createPallet(${orderId}); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new order format\r\n      const regex = /^798268/; // (remaining digits are the quantity of items in the order)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new order\r\n      const macAddress = await getMacAddress();\r\n      const newOrder = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createOrder\',\r\n            params: {\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (newOrder.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(\'Could not create new order\');\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items in the order.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createOrder(); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findCurrentStep () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Find where at in the palletizing process we are\r\n      const currentStep = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'getStep\',\r\n            params: {}\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (currentStep.data.success) {\r\n        switch (currentStep.data.currentStep) {\r\n          case \'newOrder\':\r\n            await newOrder();\r\n          break;\r\n          case \'newPallet\':\r\n            await newPallet(currentStep.data.currentId);\r\n          break;\r\n          case \'newItem\':\r\n            await newItem(currentStep.data.currentId);\r\n          break;\r\n        }\r\n      } else {\r\n        throw new Error(\'Could not determine current step\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    await findCurrentStep();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(416, '2022-10-31 13:41:13', 7, '7680 Palletize', '<style>\r\n  #palletizeWrapper {\r\n    overflow-y: hidden;\r\n    overflow-x: hidden;\r\n    height: calc(100vh - 52px);\r\n  }\r\n    #palletizeWrapper #instructions {\r\n      margin: 20px 20px 10px 20px;\r\n      font-weight: bold;\r\n      font-size: 115%;\r\n    }\r\n    #palletizeWrapper #inputFrm {\r\n      margin: 0px 20px 20px 20px;\r\n    }\r\n    #palletizeWrapper #results {\r\n      margin: 0px 20px 0 20px;\r\n    }\r\n  .progressHeading {\r\n    font-weight: bold;\r\n    font-size: 115%;\r\n    text-align: center;\r\n  }\r\n  .progressBar {\r\n    width: 100%;\r\n    height: 20px;\r\n    background-color: #ddd;\r\n  }\r\n  .progressBar div {\r\n    height: 100%;\r\n    background-color: #4CAF50;\r\n    width: 0%;\r\n  }\r\n  .progressDescription {\r\n    text-align: center;\r\n    margin-bottom: 10px;\r\n  }\r\n  .palletItems {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    justify-content: center;\r\n  }\r\n  .palletItems ul{\r\n    list-style-type: none;\r\n    margin: 0;\r\n    padding: 0;\r\n  }\r\n  .palletItems li {\r\n    margin: 5px;\r\n    padding: 5px;\r\n    border: 1px solid #ddd;\r\n    border-radius: 5px;\r\n    background-color: #f1f1f1;\r\n    text-align: center;\r\n    display: inline-block;\r\n    font-size: 80%;\r\n  }\r\n</style>\r\n<div id=\"palletizeWrapper\">\r\n  <div id=\"instructions\"></div>\r\n  <div id=\"inputFrm\"></div>\r\n  <div id=\"results\"></div>\r\n</div>', '\r\nfunction addItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const mainBarcode = document.getElementById(\'mainBarcode\').value;\r\n      const vaultBarcode = document.getElementById(\'vaultBarcode\').value;\r\n\r\n      // Validate barcode matches format\r\n      let regex = /^7680/;\r\n      if (mainBarcode.length !== 14 || !regex.test(mainBarcode)) {\r\n        document.getElementById(\'mainBarcode\').value = \'\';\r\n        throw new Error(\'Invalid main barcode\');\r\n      }\r\n      regex = /^5785/;\r\n      if (vaultBarcode.length !== 14 || !regex.test(vaultBarcode)) {\r\n        document.getElementById(\'vaultBarcode\').value = \'\';\r\n        throw new Error(\'Invalid vault barcode\');\r\n      }\r\n\r\n      // Add item to pallet\r\n      const macAddress = await getMacAddress();\r\n      const item = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'addItem\',\r\n            params: {\r\n              palletId: palletId,\r\n              primarySerialNum: mainBarcode,\r\n              secondarySerialNum: vaultBarcode,\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (item.data.success) {\r\n        // Success\r\n        const audio = new Audio(window.selectedProduct.serverUrl + \'/uploads/audio/chirp.mp3\');\r\n        audio.play();\r\n\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(item.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      // Failed\r\n      const audio = new Audio(window.selectedProduct.serverUrl + \'/uploads/audio/alarm.mp3\');\r\n      audio.play();\r\n\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}  \r\n// ---------------------------------------------------------- //\r\nfunction focusOnVault() {\r\n  document.getElementById(\'vaultBarcode\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction buildProgressReport (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Get pallet data\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'progressReport\',\r\n            params: {\r\n              palletId: palletId\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        // Build progress report\r\n        let itemsList = \'\';\r\n        pallet.data.items.forEach(item => {\r\n          itemsList += `<li>${item.primarySerialNum}<br/> ${item.secondarySerialNum}</li>`;\r\n        });\r\n\r\n\r\n        document.getElementById(\'results\').innerHTML = `\r\n          <div class=\"progressHeading\">Order Progress</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.orderCurrentQty * 100 / pallet.data.orderTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.orderCurrentQty} / ${pallet.data.orderTargetQty}</div>\r\n\r\n          <div class=\"progressHeading\">Current Pallet</div>\r\n          <div class=\"progressBar\">\r\n            <div class=\"progressBarFill\" style=\"width:${pallet.data.palletCurrentQty * 100 / pallet.data.palletTargetQty }%\"></div>\r\n          </div>\r\n\r\n          <div class=\"progressDescription\">${pallet.data.palletCurrentQty} / ${pallet.data.palletTargetQty}</div>\r\n\r\n          <div class=\"palletItems\">\r\n            <ul>\r\n              ${itemsList}\r\n            </ul>\r\n          </div>\r\n        `;\r\n      } else {\r\n        throw new Error(\'Could not build progress report\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newItem (palletId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan main barcode followed by matching vault barcode.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"focusOnVault(); return false;\">\r\n        <input type=\"text\" id=\"mainBarcode\" class=\"form-control\" placeholder=\"Scan Main Barcode\">\r\n        <button type=\"submit\" id=\"submit\" class=\"btn btn-primary\" style=\"opacity:0;\">Submit</button>\r\n      </form>\r\n      <form id=\"barcode2Frm\" onsubmit=\"addItem(${palletId}); return false;\">\r\n        <input type=\"text\" id=\"vaultBarcode\" class=\"form-control\" placeholder=\"Scan Vault Barcode\">\r\n        <button type=\"submit\" id=\"submit2\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'mainBarcode\').focus();\r\n\r\n      // Build progress report\r\n      await buildProgressReport(palletId);\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new pallet format\r\n      const regex = /^806576/; // (remaining digits are the quantity of items)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new pallet\r\n      const macAddress = await getMacAddress();\r\n      const pallet = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createPallet\',\r\n            params: {\r\n              orderId: orderId,\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (pallet.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(pallet.data.errorMsg);\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newPallet (orderId) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items to be place on this pallet.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createPallet(${orderId}); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction createOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const barcode = document.getElementById(\'barcode\').value;\r\n\r\n      // Validate barcode matches new order format\r\n      const regex = /^798268/; // (remaining digits are the quantity of items in the order)\r\n      if (barcode.length !== 10 || !regex.test(barcode)) {\r\n        document.getElementById(\'barcode\').value = \'\';\r\n        throw new Error(\'Invalid barcode\');\r\n      }\r\n\r\n      // Create new order\r\n      const macAddress = await getMacAddress();\r\n      const newOrder = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'createOrder\',\r\n            params: {\r\n              targetQty: barcode.slice(6, 10),\r\n              testerName: window.selectedProduct.testerName,\r\n              macAddress: macAddress\r\n            }\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (newOrder.data.success) {\r\n        document.getElementById(\'results\').innerHTML = \'\';\r\n        document.getElementById(\'instructions\').innerHTML = \'\';\r\n        document.getElementById(\'inputFrm\').innerHTML = \'\';\r\n        await findCurrentStep();\r\n      } else {\r\n        throw new Error(\'Could not create new order\');\r\n      }\r\n    } catch (error) {\r\n      promptUser(error.message);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction newOrder () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      document.getElementById(\'results\').innerHTML = \'\';\r\n      document.getElementById(\'instructions\').innerHTML = \'Please scan barcode that represents the quantity of items in the order.\';\r\n      document.getElementById(\'inputFrm\').innerHTML = `\r\n      <form id=\"barcodeFrm\" onsubmit=\"createOrder(); return false;\">\r\n        <input type=\"text\" id=\"barcode\" class=\"form-control\" placeholder=\"Scan Barcode\">\r\n        <button type=\"button\" id=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n      </form>\r\n      `;\r\n      document.getElementById(\'barcode\').focus();\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction findCurrentStep () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Find where at in the palletizing process we are\r\n      const currentStep = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \'palletize7680\',\r\n            action: \'getStep\',\r\n            params: {}\r\n          }\r\n        },\r\n        { headers: { \'Content-Type\': \'application/json\' } }\r\n      );\r\n\r\n      if (currentStep.data.success) {\r\n        switch (currentStep.data.currentStep) {\r\n          case \'newOrder\':\r\n            await newOrder();\r\n          break;\r\n          case \'newPallet\':\r\n            await newPallet(currentStep.data.currentId);\r\n          break;\r\n          case \'newItem\':\r\n            await newItem(currentStep.data.currentId);\r\n          break;\r\n        }\r\n      } else {\r\n        throw new Error(\'Could not determine current step\');\r\n      }\r\n    } catch (error) {\r\n      reject(error)\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    await findCurrentStep();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests` (`testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(1, 3, 'Verify Cortex Device Found', 'Find Device', NULL, '<div class=\"text-h5\">Instructions:</div>\r\n<p>Please connect power and USB to scanner and turn the device on. Then click \"Start Test\" in the lower right corner.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await window.api6100.isCortex();\r\n    await window.api6100.closeDevice();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(2, 3, 'Configure For Board Test (Holtek Shading)', 'Configure For Board Test', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will set the hardware and software configuration in the device. At this stage the population specific config for the PCBA is set. A generic calibration table will be sent to the device in preparation of scanning documents.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Prepare configs\r\n    const hardwareConfig = [\r\n      1,\r\n      parseInt(window.selectedProduct.productConfig.topCis),\r\n      parseInt(window.selectedProduct.productConfig.bottomCis),\r\n      parseInt(window.selectedProduct.productConfig.hasMicr),\r\n      parseInt(window.selectedProduct.productConfig.hasStamp),\r\n      parseInt(window.selectedProduct.productConfig.hasWatermark),\r\n      0,\r\n      parseInt(window.selectedProduct.productConfig.entrySensorType),\r\n      parseInt(window.selectedProduct.productConfig.midfieldType) | parseInt(window.selectedProduct.productConfig.holtekType) | parseInt(window.selectedProduct.productConfig.stepperType),\r\n      0\r\n    ];\r\n\r\n    const softwareConfig = [\r\n      0,\r\n      parseInt(window.selectedProduct.productConfig.hasEncryption),\r\n      0,\r\n      0,\r\n      0,\r\n      0,\r\n      0,\r\n      0\r\n    ];\r\n\r\n    window.Loading.show({\r\n      message: \'Configuring hardware...\'\r\n    });\r\n\r\n    await window.api6100.openDevice();\r\n    await window.api6100.cortexSetScannerHardware(hardwareConfig);\r\n    await window.api6100.cortexSetScannerSoftware(softwareConfig);\r\n    await window.api6100.cortexSetUSBDescriptorMode(parseInt(window.selectedProduct.productConfig.usbDescriptor));\r\n    await window.api6100.cortexSetSkew(parseInt(window.selectedProduct.productConfig.skewTolerance), parseInt(window.selectedProduct.productConfig.skewReject));\r\n\r\n    // Pull generic shading tables\r\n    await setCalibrationTable(window.selectedProduct.serverUrl + \'uploads/calibrations/pcba.dat\');\r\n\r\n    await window.api6100.closeDevice();\r\n    window.Loading.hide();\r\n    document.getElementById(\'testWrapper\').innerHTML = \'<p>Configured scanner.</p>\';\r\n    passTestActions();\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    failTestActions(err);\r\n  }\r\n})();', 1),
(3, 3, 'Update Firmware', 'Update Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will compare the firmware version on the device with the version specified in this test set. If the versions don\'t match, the correct firmware will be downloaded to the device.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    let validVersion = false;\r\n    await window.api6100.openDevice();\r\n    \r\n    // Get device\'s current firmware version\r\n    let version = await getFirmwareVersion();\r\n    if(version === window.selectedProduct.productConfig.firmwareVersion) {\r\n      validVersion = true;\r\n    }\r\n\r\n    if (!validVersion) {\r\n      // Need to change firmware version\r\n      window.Loading.show({\r\n        message: \'Updating firmware from \' + version + \' to \' + window.selectedProduct.productConfig.firmwareVersion\r\n      });\r\n\r\n      await updateFirmware(window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware, window.selectedProduct.productConfig.firmwareMd5);\r\n      window.Loading.hide();\r\n      await window.api6100.openDevice();\r\n      \r\n      // Verify update went through\r\n      version = await getFirmwareVersion();\r\n      if(version === window.selectedProduct.productConfig.firmwareVersion) {\r\n        validVersion = true;\r\n      }\r\n    }\r\n  \r\n    await window.api6100.closeDevice();\r\n\r\n    if(validVersion) {\r\n      // Firmware version is correct\r\n      document.getElementById(\'testWrapper\').innerHTML = \'<p>Firmware version is correct (\' + version + \')</p>\';\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Failed to update firmware\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(4, 3, 'PCBA Check (300dpi Grayscale)', 'Scan Check (300dpi Grayscale)', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test scans a check to verify both CIS capture an image and that both MICR circuits can decode a magnetic code line.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true);\r\n    await window.api6100.performScan(0, 300, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(7, 3, 1);\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 300px);\" /></div>\r\n      <div id=\"micrData\" style=\"text-align: center; font-size: 20px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' }));\r\n\r\n    await window.api6100.ejectDocument(1);\r\n    const micrResponse = await window.api6100.getFullE13bMICR();\r\n\r\n    document.getElementById(\'micrData\').innerHTML = `\r\n      <div>MICR: ${micrResponse.mag1}</div>\r\n    `;\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Perform initial test of MICR data (testing magnetic decode only)\r\n    if (micrResponse.mag1 !== micrResponse.mag2) {\r\n      await failTestActions(\'Mag1 and Mag2 do not match\');\r\n    } else if (micrResponse.mag1.includes(\'*\')) {\r\n      await failTestActions(\'MICR data contains invalid characters\');\r\n    } else {\r\n      // Have user determine if image and MICR data is correct\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Can you see both front and back of the check and does the MICR match the check?\', \'User failed test\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(5, 3, 'PCBA ID Card (600dpi Color)', 'Scan ID Card (600dpi Color)', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test verifies the motor circuit is able to properly pull in a card. It verifies that the 600dpi switch is possible and that all 3 colors can be illuminated.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(false);\r\n    await window.api6100.performScan(1, 600, 1, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(8, 3, 1);\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 200px);\" /></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' }));\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Have user determine if image is correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Can you see both front and back of the ID card and can you see Red, Green, and Blue on both sides?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(6, 3, 'PCBA ID Card (300dpi Grayscale)', 'Scan ID Card (300dpi Grayscale)', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test verifies the motor circuit is able to properly pull in a card.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(false);\r\n    await window.api6100.performScan(0, 300, 1, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(7, 3, 1);\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 200px);\" /></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' }));\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Have user determine if image is correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Can you see both front and back of the ID card?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(7, 3, 'Update Firmware Via Calibration Controller', 'Update Firmware', NULL, '', 'async function getCurrentFirmwareVersion(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'firmwareVersion\' }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to get current firmware version. Error Code: \' + response.success);\r\n        } else {\r\n          if (response.firmware !== window.selectedProduct.productConfig.firmwareVersion) {\r\n            // Firmware version is not up to date\r\n            const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n            clientStatus.innerHTML = \'Firmware Updating To: \' + window.selectedProduct.productConfig.firmwareVersion;\r\n            clientStatus.style.display = \'block\';\r\n\r\n            // Update firmware\r\n            window.messenger.request(index, \'scannerRequest\', { mode: \'firmwareUpdateV2\', url: window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware, md5: window.selectedProduct.productConfig.firmwareMd5 }, async response => {\r\n              clientStatus.style.display = \'none\';\r\n              if (response.success) {\r\n                reject(\'Failed to update firmware. Error Code: \' + response.success);\r\n              } else {\r\n                setTimeout(async () => {\r\n                  resolve();\r\n                }, 6000);\r\n              }\r\n            });\r\n          } else {\r\n            resolve();\r\n          }\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function updateFirmware(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n    const macAdress = await getMacAddress();\r\n\r\n    try {\r\n      // Get device\'s current version\r\n      let currentVersion = await getCurrentFirmwareVersion(index);\r\n\r\n      // Create analytics entry\r\n      const response = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"timings\",\r\n            action: \"setTestTiming\",\r\n            params: {\r\n              timelapsed: Date.now() - startTime,\r\n              productTitle: window.selectedProduct.productTitle,\r\n              selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n              testTitle: \'Update Firmware\',\r\n              testId: 7,\r\n              testerName: window.selectedProduct.testerName,\r\n              testPassed: 1,\r\n              serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n              macAddress: macAdress,\r\n              extAnalyticsProductionId: window.selectedProduct.calibrationClients[index].analyticsProductionId,\r\n              failMsg: \'\',\r\n              customError: \'\'\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    \r\n      if (response.data.message) {\r\n        promptUser(response.data.message);\r\n      }\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      const response = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"timings\",\r\n            action: \"setTestTiming\",\r\n            params: {\r\n              timelapsed: Date.now() - startTime,\r\n              productTitle: window.selectedProduct.productTitle,\r\n              selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n              testTitle: \'Update Firmware\',\r\n              testId: 7,\r\n              testerName: window.selectedProduct.testerName,\r\n              testPassed: 0,\r\n              serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n              macAddress: macAdress,\r\n              extAnalyticsProductionId: window.selectedProduct.calibrationClients[index].analyticsProductionId,\r\n              failMsg: error,\r\n              customError: \'\'\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    \r\n      if (response.data.message) {\r\n        promptUser(response.data.message);\r\n      }\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(8, 3, 'Configure Hardware Via Calibration Controller', 'Configure Hardware', NULL, '', 'async function setHardware (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const hwCfg = [\r\n        1,\r\n        parseInt(window.selectedProduct.productConfig.topCis),\r\n        parseInt(window.selectedProduct.productConfig.bottomCis),\r\n        parseInt(window.selectedProduct.productConfig.hasMicr),\r\n        parseInt(window.selectedProduct.productConfig.hasStamp),\r\n        parseInt(window.selectedProduct.productConfig.hasWatermark),\r\n        0,\r\n        parseInt(window.selectedProduct.productConfig.entrySensorType),\r\n        0, /* NOTE THIS BYTE IS MAINTAINED FROM THE CURRENT CONFIG BY THE Raspberry PI */\r\n        0\r\n      ];\r\n\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'setHardware\', cfg: hwCfg }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to set hardware. Error Code: \' + response.success);\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function setSoftware (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const swCfg = [\r\n        0,\r\n        parseInt(window.selectedProduct.productConfig.hasEncryption),\r\n        0,\r\n        0,\r\n        0,\r\n        0,\r\n        0,\r\n        0\r\n      ];\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'setSoftware\', cfg: swCfg }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to set software. Error Code: \' + response.success);\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function setTla (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'setTLA\', tla: window.selectedProduct.productConfig.tlaNumber }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to set TLA. Error Code: \' + response.success);\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function analyticsEntryHardware (timelapsed, testPassed, extAnalyticsProductionId, error) {\r\n  const macAdress = await getMacAddress();\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: timelapsed,\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n          testTitle: \'Configure Hardware\',\r\n          testId: 8,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: error,\r\n          customError: \'\'\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function configureHardware(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n\r\n    try {\r\n      await setHardware(index);\r\n      await setSoftware(index);\r\n      await setTla(index);\r\n\r\n      // Create analytics entry\r\n      analyticsEntryHardware (Date.now() - startTime, 1, window.selectedProduct.calibrationClients[index].analyticsProductionId, \'\');\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      analyticsEntryHardware (Date.now() - startTime, 0, window.selectedProduct.calibrationClients[index].analyticsProductionId, error);\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(9, 3, 'Calibrate Via Calibration Controller', 'Calibrate', NULL, '', 'async function calibrate (index) {\r\n  const advancedErrorCodes = {\r\n    0: \'No Detailed Error\',\r\n    1: \'Bad CIS Signal (verify connectivity to both CIS)\',\r\n    2: \'Upper Deck CIS Failed (calibrating red)\',\r\n    3: \'Lower Deck CIS Failed (calibrating red)\',\r\n    4: \'Upper Deck CIS Failed (calibrating green)\',\r\n    5: \'Lower Deck CIS Failed (calibrating green)\',\r\n    6: \'Upper Deck CIS Failed (calibrating blue)\',\r\n    7: \'Lower Deck CIS Failed (calibrating blue)\',\r\n    8: \'Upper Deck CIS Failed (calibrating uv)\',\r\n    9: \'Lower Deck CIS Failed (calibrating uv)\',\r\n    10: \'Upper Deck CIS Failed (calibrating ir)\',\r\n    11: \'Lower Deck CIS Failed (calibrating ir)\',\r\n    12: \'Upper Deck CIS Failed (calibrating watermark)\',\r\n    13: \'Lower Deck CIS Failed (calibrating watermark)\',\r\n    14: \'Upper Deck CIS Failed (calibrating grayscale)\',\r\n    15: \'Lower Deck CIS Failed (calibrating grayscale)\',\r\n    16: \'Corrupted Image During Calibration\',\r\n    17: \'Failed UV Calibration\',\r\n  }\r\n\r\n  return new Promise(async (resolve, reject) => {\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n    try {\r\n      clientStatus.innerHTML = \'Calibrating: Load Sheet <div style=\"background-color:#090;\" id=\"progress\' + index + \'\" class=\"progress\"></div><div id=\"progressText\' + index + \'\" class=\"progressText\"></div>\';\r\n      clientStatus.style.display = \'block\';\r\n      window.selectedProduct.calibrationClients[index].progressStart = Date.now();\r\n      window.selectedProduct.calibrationClients[index].progressMax = 120000;\r\n      showProgress(index);\r\n\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'calibrate\' }, async response => {\r\n        clientStatus.style.display = \'none\';\r\n        if (response.success) {\r\n          if (response.success === 19) {\r\n            reject(\'Failed to calibrate: Never saw paper loaded\');\r\n          }\r\n\r\n          // Get advanced error\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'getAdvancedError\' }, async response => {\r\n            reject(\'Failed to calibrate. Error Code: \' + advancedErrorCodes[response.success]);\r\n          });\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      clientStatus.style.display = \'none\';\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showProgress (index) {\r\n  const progressTimer = setInterval(() => {\r\n    const progress = document.getElementById(\'progress\' + index);\r\n    const progressText = document.getElementById(\'progressText\' + index);\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n\r\n    const progressPercent = Math.round((Date.now() - window.selectedProduct.calibrationClients[index].progressStart) / window.selectedProduct.calibrationClients[index].progressMax * 100);\r\n    progress.style.width = progressPercent + \'%\';\r\n    progressText.innerHTML = progressPercent + \'%\';\r\n\r\n    if (progressPercent >= 100 || window.selectedProduct.calibrationClients[index].inCalibration === false) {\r\n      clearInterval(progressTimer);\r\n      clientStatus.style.display = \'none\';\r\n    }\r\n  }, 100);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function collectCalibrationData (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'collectCalibrationData\', productionId: window.selectedProduct.calibrationClients[index].productionId, serverUrl: window.selectedProduct.serverUrl }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to collect calibration data\');\r\n        } else {\r\n          // Inform test of calibration data\r\n          window.selectedProduct.calibrationClients[index].productionResults = {\r\n            files: {\r\n              calibrationTables: \'6100-test-results/\' + window.selectedProduct.calibrationClients[index].productionId + \'.dat\'\r\n            }\r\n          }\r\n          // Inform server of calibration dat file\r\n          const response = await window.axios.post(window.selectedProduct.serverUrl, \r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"updateProduction\",\r\n                params: {\r\n                  productionId: window.selectedProduct.calibrationClients[index].productionId,\r\n                  productionResults: window.selectedProduct.calibrationClients[index].productionResults\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n\r\n          if (response.data.success) {\r\n            resolve();\r\n          } else {\r\n            reject(\'Failed to update prduction results\');\r\n          }\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function analyticsEntry (timelapsed, testPassed, extAnalyticsProductionId, error) {\r\n  const macAdress = await getMacAddress();\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: timelapsed,\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n          testTitle: \'Calibrate\',\r\n          testId: 9,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: error,\r\n          customError: \'\'\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startCalibration(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n\r\n    try {\r\n      await calibrate(index);\r\n      await collectCalibrationData(index);\r\n\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 1, window.selectedProduct.calibrationClients[index].analyticsProductionId, \'\');\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n       resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 0, window.selectedProduct.calibrationClients[index].analyticsProductionId, error);\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(10, 3, 'Verify Config', 'Verify Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify the hardware and software configuration in the device matches the TLA.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n\r\n    // Check hardware\r\n    const deviceHardware = await window.api6100.cortexGetScannerHardware();\r\n    if (\r\n      deviceHardware.hardwareConfig[0] !== 1 ||\r\n      deviceHardware.hardwareConfig[1] !== parseInt(window.selectedProduct.productConfig.topCis) ||\r\n      deviceHardware.hardwareConfig[2] !== parseInt(window.selectedProduct.productConfig.bottomCis) ||\r\n      deviceHardware.hardwareConfig[3] !== parseInt(window.selectedProduct.productConfig.hasMicr) ||\r\n      deviceHardware.hardwareConfig[4] !== parseInt(window.selectedProduct.productConfig.hasStamp) ||\r\n      deviceHardware.hardwareConfig[5] !== parseInt(window.selectedProduct.productConfig.hasWatermark) ||\r\n      deviceHardware.hardwareConfig[7] !== parseInt(window.selectedProduct.productConfig.entrySensorType)\r\n    ) {\r\n      throw new Error(\r\n        `The scanner hardware config does not match the selected TLA.`\r\n      );\r\n    }\r\n    \r\n    // Check software\r\n    const deviceSoftware = await window.api6100.cortexGetScannerSoftware();\r\n    if (\r\n      deviceSoftware.softwareConfig[1] !== parseInt(window.selectedProduct.productConfig.hasEncryption)\r\n    ) {\r\n      throw new Error(\r\n        `The scanner software config does not match the selected TLA.`\r\n      );\r\n    }\r\n\r\n    // Check firmware\r\n    const firmwareVersion = await getFirmwareVersion();\r\n    if (firmwareVersion !== window.selectedProduct.productConfig.firmwareVersion) {\r\n      throw new Error(\r\n        `The scanner firmware version does not match the selected TLA.`\r\n      );\r\n    }\r\n\r\n    // Set TLA\r\n    await window.api6100.cortexSetTLA(window.selectedProduct.productConfig.tlaNumber);\r\n\r\n    // Set USB Descriptor\r\n    await window.api6100.cortexSetUSBDescriptorMode(parseInt(window.selectedProduct.productConfig.usbDescriptor));\r\n\r\n    // Set Skew Tolerance/Reject\r\n    await window.api6100.cortexSetSkew(parseInt(window.selectedProduct.productConfig.skewTolerance), parseInt(window.selectedProduct.productConfig.skewReject));\r\n\r\n    \r\n\r\n    // Update results\r\n    window.selectedProduct.productionResults.deviceHardware = deviceHardware.hardwareConfig;\r\n    window.selectedProduct.productionResults.deviceSoftware = deviceSoftware.softwareConfig;\r\n    window.selectedProduct.productionResults.firmwareVersion = firmwareVersion;\r\n    \r\n\r\n    await window.api6100.closeDevice();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(11, 3, 'Scan Inner Barcode', 'Scan Inner Barcode', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will collect the inner barcode and save it on the device and database.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please scan the inner barcode on the scanner.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              return value.length === 6;\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n\r\n    // Get barcode\r\n    let barcode = await getBarcode();\r\n\r\n    // Transform barcode\r\n    const twoDigitsYear = parseInt(new Date().getFullYear().toString().substr(2,2), 10);\r\n    let twoDigitsMonth = (new Date().getMonth() + 1).toString();\r\n    if(twoDigitsMonth.length===1){\r\n        twoDigitsMonth = \'0\' + twoDigitsMonth;\r\n    }\r\n    const barcodeStr = twoDigitsYear.toString() + twoDigitsMonth + barcode;\r\n\r\n    await window.api6100.cortexSetSerialNum(barcodeStr);\r\n    await window.api6100.cortexSetProductionSerialNum(barcodeStr);\r\n\r\n    const deviceProductionSerialNum = await window.api6100.cortexGetProductionSerialNum();\r\n    if (deviceProductionSerialNum.serialNum !== barcodeStr) {\r\n      throw new Error(\'Device production serial number is not set correctly\');\r\n    }\r\n    window.selectedProduct.productionResults.deviceProductionSerialNum = deviceProductionSerialNum.serialNum;\r\n    \r\n    // Get scanner config\r\n    const scannerConfig = await window.api6100.xfn(0x49);\r\n    window.selectedProduct.productionResults.scannerConfig = scannerConfig.xfn;\r\n\r\n    // Update results\r\n    const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"updateProduction\",\r\n          params: {\r\n            productionId: window.selectedProduct.productionId,\r\n            secondarySerialNum: barcode,\r\n            tla: window.selectedProduct.productConfig.tlaNumber,\r\n            productionResults: window.selectedProduct.productionResults\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"updateProduction\",\r\n          params: {\r\n            analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n            secondarySerialNum: barcode,\r\n            tla: window.selectedProduct.productConfig.tlaNumber,\r\n            analyticsResults: window.selectedProduct.productionResults\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    await window.api6100.closeDevice();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(12, 3, 'Image Quality: Uniformity', 'Image Quality: Uniformity', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify calibration has caused shading uniformity across both CIS.</p>', 'async function hideLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the pastel blue sheet aligned to the right of the scan deck.\');\r\n    await window.api6100.performScan(1, 300, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(8, 3, 1);\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 200px);\" onclick=\"showLargeImage()\" /></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"viewLarger\" onclick=\"hideLargeImage()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n    `;\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(imgBlob);\r\n    document.getElementById(\'scanImg2\').src = URL.createObjectURL(imgBlob);\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Save image to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-uniformity.jpg\');\r\n      window.selectedProduct.productionResults.files.uniformityImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-uniformity.jpg\';\r\n      await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    // Have user determine if image is correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is the front and back image uniformly shaded with no distinguishable horizontal lines?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(13, 3, 'Image Quality: Color', 'Image Quality: Color', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify calibration has caused proper blending across colors.</p>', 'async function hideLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the fish printed check face down with the codeline aligned to the right of the scan deck.\');\r\n    await window.api6100.performScan(1, 300, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(8, 3, 1);\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 300px);\" onclick=\"showLargeImage()\" /></div>\r\n      <div id=\"micrData\" style=\"text-align: center; font-size: 20px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"viewLarger\" onclick=\"hideLargeImage()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n    `;\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(imgBlob);\r\n    document.getElementById(\'scanImg2\').src = URL.createObjectURL(imgBlob);\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    // Get MICR data\r\n    const micrResponse = await window.api6100.getFullE13bMICR();\r\n\r\n    document.getElementById(\'micrData\').innerHTML = `\r\n      <div>MICR OCR: ${micrResponse.ocr}</div>\r\n      <div>MICR MAG: ${micrResponse.combined}</div>\r\n    `;\r\n\r\n    // Save image and micr info to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Get MICR raw\r\n      const micrRawResponse = await window.api6100.xmitRawMICR();\r\n      const micrBlob = new Blob([micrRawResponse.micrRawBuffer], { type: \'application/octet-stream\' });\r\n      await uploadFile(micrBlob, window.selectedProduct.productionId + \'-fish.micr\');\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-fish.jpg\');\r\n\r\n      window.selectedProduct.productionResults.fishMicr = micrResponse;\r\n      window.selectedProduct.productionResults.files.fishMicrRaw = \'6100-test-results/\' + window.selectedProduct.productionId + \'-fish.micr\';\r\n      window.selectedProduct.productionResults.files.fishImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-fish.jpg\';\r\n\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Perform initial test of MICR data\r\n    if (micrResponse.mag1 !== micrResponse.mag2 || micrResponse.mag1 !== micrResponse.ocr) {\r\n      await failTestActions(\'Mag1, Mag2, OCR do not match\');\r\n    } else if (micrResponse.mag1.includes(\'*\')) {\r\n      await failTestActions(\'MICR data contains invalid characters\');\r\n    } else if (!matchMICR(\'+00****+ @123456780@ 123-456-7+\', micrResponse.mag1)) {\r\n      await failTestActions(\'MICR data doess not match expected values\');\r\n    }else {\r\n      // Have user determine if image is correct\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is MICR correct and is the image properly cropped with the colors matching the check with white appearing white?\', \'User failed test\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(14, 3, 'Image Quality: RGB Ink', 'Image Quality: RGB Ink', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify that grayscale imaging is capturing red, green, and blue ink.</p>', 'async function hideLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the check with red, green, and blue ink face down with the codeline aligned to the right of the scan deck.\');\r\n    await window.api6100.performScan(0, 600, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(7, 3, 1);\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 300px);\" onclick=\"showLargeImage()\" /></div>\r\n      <div id=\"micrData\" style=\"text-align: center; font-size: 20px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"viewLarger\" onclick=\"hideLargeImage()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n    `;\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(imgBlob);\r\n    document.getElementById(\'scanImg2\').src = URL.createObjectURL(imgBlob);\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    // Get MICR data\r\n    const micrResponse = await window.api6100.getFullE13bMICR();\r\n\r\n    document.getElementById(\'micrData\').innerHTML = `\r\n      <div>MICR OCR: ${micrResponse.ocr}</div>\r\n      <div>MICR MAG: ${micrResponse.combined}</div>\r\n    `;\r\n\r\n    // Save image and micr info to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Get MICR raw\r\n      const micrRawResponse = await window.api6100.xmitRawMICR();\r\n      const micrBlob = new Blob([micrRawResponse.micrRawBuffer], { type: \'application/octet-stream\' });\r\n      await uploadFile(micrBlob, window.selectedProduct.productionId + \'-ink.micr\');\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-ink.jpg\');\r\n\r\n      window.selectedProduct.productionResults.inkMicr = micrResponse;\r\n      window.selectedProduct.productionResults.files.inkMicrRaw = \'6100-test-results/\' + window.selectedProduct.productionId + \'-ink.micr\';\r\n      window.selectedProduct.productionResults.files.inkImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-ink.jpg\';\r\n\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Perform initial test of MICR data\r\n    if (micrResponse.mag1 !== micrResponse.mag2 || micrResponse.mag1 !== micrResponse.ocr) {\r\n      await failTestActions(\'Mag1, Mag2, OCR do not match\');\r\n    } else if (micrResponse.mag1.includes(\'*\')) {\r\n      await failTestActions(\'MICR data contains invalid characters\');\r\n    } else if (!matchMICR(\'@123456780@ 1234567890+ ****\', micrResponse.mag1)) {\r\n      await failTestActions(\'MICR data doess not match expected values\');\r\n    }else {\r\n      // Have user determine if image is correct\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is MICR correct and is the image properly cropped with all written text visible?\', \'User failed test\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(15, 3, 'Image Quality: ID Card', 'Image Quality: ID Card', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to check card scan path and 600dpi color.</p>', 'async function hideLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(false, \'Please load the yellow, blue, red ID card aligned to the left of the scan deck.\');\r\n    await window.api6100.performScan(1, 600, 1, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(8, 3, 1);\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 200px);\" onclick=\"showLargeImage()\" /></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"viewLarger\" onclick=\"hideLargeImage()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n    `;\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(imgBlob);\r\n    document.getElementById(\'scanImg2\').src = URL.createObjectURL(imgBlob);\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Save image to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-card.jpg\');\r\n      window.selectedProduct.productionResults.files.cardImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-card.jpg\';\r\n      await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    // Have user determine if image is correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is the front and back image colored properly with no image stretching?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests` (`testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(16, 3, 'MICR: E13B Low', 'MICR: E13B Low', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify MICR decode on low signal is working.</p>', 'async function hideLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the pink low signal check face down with the codeline aligned to the right of the scan deck.\');\r\n    await window.api6100.performScan(0, 300, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(7, 3, 1);\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 300px);\" onclick=\"showLargeImage()\" /></div>\r\n      <div id=\"micrData\" style=\"text-align: center; font-size: 20px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"viewLarger\" onclick=\"hideLargeImage()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n    `;\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(imgBlob);\r\n    document.getElementById(\'scanImg2\').src = URL.createObjectURL(imgBlob);\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    // Get MICR data\r\n    const micrResponse = await window.api6100.getFullE13bMICR();\r\n\r\n    document.getElementById(\'micrData\').innerHTML = `\r\n      <div>MICR OCR: ${micrResponse.ocr}</div>\r\n      <div>MICR MAG: ${micrResponse.combined}</div>\r\n    `;\r\n\r\n    // Save image and micr info to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Get MICR raw\r\n      const micrRawResponse = await window.api6100.xmitRawMICR();\r\n      const micrBlob = new Blob([micrRawResponse.micrRawBuffer], { type: \'application/octet-stream\' });\r\n      await uploadFile(micrBlob, window.selectedProduct.productionId + \'-e13b-low.micr\');\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-e13b-low.jpg\');\r\n\r\n      window.selectedProduct.productionResults.e13bLowMicr = micrResponse;\r\n      window.selectedProduct.productionResults.files.e13bLowMicrRaw = \'6100-test-results/\' + window.selectedProduct.productionId + \'-e13b-low.micr\';\r\n      window.selectedProduct.productionResults.files.e13bLowImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-e13b-low.jpg\';\r\n\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Perform initial test of MICR data\r\n    if (micrResponse.mag1 !== micrResponse.ocr && micrResponse.mag2 !== micrResponse.ocr) {\r\n      await failTestActions(\'Magnetic and OCR MICR data do not match.\');\r\n    } else if (!matchMICR(\'+******+ @075911616@   8100-014+\', micrResponse.ocr)) {\r\n      await failTestActions(\'MICR data doess not match expected values\');\r\n    }else {\r\n      // Have user determine if image is correct\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is MICR correct?\', \'User failed test\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(17, 3, 'MICR: E13B High', 'MICR: E13B High', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify MICR decode on high signal is working.</p>', 'async function hideLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the seafoam green high signal check face down with the codeline aligned to the right of the scan deck.\');\r\n    await window.api6100.performScan(0, 300, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(7, 3, 1);\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 300px);\" onclick=\"showLargeImage()\" /></div>\r\n      <div id=\"micrData\" style=\"text-align: center; font-size: 20px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"viewLarger\" onclick=\"hideLargeImage()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n    `;\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(imgBlob);\r\n    document.getElementById(\'scanImg2\').src = URL.createObjectURL(imgBlob);\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    // Get MICR data\r\n    const micrResponse = await window.api6100.getFullE13bMICR();\r\n\r\n    document.getElementById(\'micrData\').innerHTML = `\r\n      <div>MICR OCR: ${micrResponse.ocr}</div>\r\n      <div>MICR MAG: ${micrResponse.combined}</div>\r\n    `;\r\n\r\n    // Save image and micr info to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Get MICR raw\r\n      const micrRawResponse = await window.api6100.xmitRawMICR();\r\n      const micrBlob = new Blob([micrRawResponse.micrRawBuffer], { type: \'application/octet-stream\' });\r\n      await uploadFile(micrBlob, window.selectedProduct.productionId + \'-e13b-high.micr\');\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-e13b-high.jpg\');\r\n\r\n      window.selectedProduct.productionResults.e13bHighMicr = micrResponse;\r\n      window.selectedProduct.productionResults.files.e13bHighMicrRaw = \'6100-test-results/\' + window.selectedProduct.productionId + \'-e13b-high.micr\';\r\n      window.selectedProduct.productionResults.files.e13bHighImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-e13b-high.jpg\';\r\n\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Perform initial test of MICR data\r\n    if (micrResponse.mag1 !== micrResponse.ocr && micrResponse.mag2 !== micrResponse.ocr) {\r\n      await failTestActions(\'Magnetic and OCR MICR data do not match.\');\r\n    } else if (!matchMICR(\'+******+ @075911616@   8100-014+\', micrResponse.ocr)) {\r\n      await failTestActions(\'MICR data doess not match expected values\');\r\n    }else {\r\n      // Have user determine if image is correct\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is MICR correct?\', \'User failed test\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(18, 3, 'MICR: CMC7', 'MICR: CMC7', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify CMC7 decode is working.</p>', 'async function hideLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the CMC-7 Test Document check face down with the codeline aligned to the right of the scan deck.\');\r\n    await window.api6100.performScan(0, 300, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(7, 3, 1);\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 300px);\" onclick=\"showLargeImage()\" /></div>\r\n      <div id=\"micrData\" style=\"text-align: center; font-size: 20px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"viewLarger\" onclick=\"hideLargeImage()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n    `;\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(imgBlob);\r\n    document.getElementById(\'scanImg2\').src = URL.createObjectURL(imgBlob);\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    // Get MICR data\r\n    const micrResponse = await window.api6100.getLastMICR(0x01, 0x02);\r\n\r\n    document.getElementById(\'micrData\').innerHTML = `\r\n      <div>MICR: ${micrResponse.micrStr}</div>\r\n    `;\r\n\r\n    // Save image and micr info to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Get MICR raw\r\n      const micrRawResponse = await window.api6100.xmitRawMICR();\r\n      const micrBlob = new Blob([micrRawResponse.micrRawBuffer], { type: \'application/octet-stream\' });\r\n      await uploadFile(micrBlob, window.selectedProduct.productionId + \'-cmc7.micr\');\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-cmc7.jpg\');\r\n\r\n      window.selectedProduct.productionResults.cmc7Micr = micrResponse.micrStr;\r\n      window.selectedProduct.productionResults.files.cmc7MicrRaw = \'6100-test-results/\' + window.selectedProduct.productionId + \'-cmc7.micr\';\r\n      window.selectedProduct.productionResults.files.cmc7Image = \'6100-test-results/\' + window.selectedProduct.productionId + \'-cmc7.jpg\';\r\n\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Perform initial test of MICR data\r\n   if (!matchMICR(\'12-345678>1234+5678>123456789012@123456789***$\', micrResponse.micrStr) && !matchMICR(\'12-345678>1234+5678>123456789012@12***$\', micrResponse.micrStr)) {\r\n      await failTestActions(\'MICR data doess not match expected values\');\r\n    }else {\r\n      // Have user determine if image is correct\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is MICR correct?\', \'User failed test\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(19, 3, 'Stamp', 'Stamp', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify the stamp works.</p>', 'async function hideLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImage() {\r\n  document.getElementById(\'viewLarger\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the check sheet along check side with snipped corner away from the right side.\');\r\n    await window.api6100.performScan(0, 300, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    await window.api6100.rewind();\r\n    await window.api6100.fwdFeedAndStamp(720);\r\n    await window.api6100.rewind();\r\n    await window.api6100.performScan(0, 300, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    \r\n    const documentResponse = await window.api6100.getLastDocument(7, 3, 1);\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\"><img id=\"scanImg\" style=\"max-width:100%; max-height:calc(100vh - 200px);\" onclick=\"showLargeImage()\" /></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"viewLarger\" onclick=\"hideLargeImage()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n    `;\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImg\').src = URL.createObjectURL(imgBlob);\r\n    document.getElementById(\'scanImg2\').src = URL.createObjectURL(imgBlob);\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Save image to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-stamp.jpg\');\r\n      window.selectedProduct.productionResults.files.stampImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-stamp.jpg\';\r\n      await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n\r\n    }\r\n\r\n    // Have user determine if image is correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is image clean, properly cropped, and with stamp impression?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(20, 3, 'Skew', 'Skew', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify skew response as expected based upon TLA config.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the check sheet along check side with snipped corner near the right side entry sensor.\');\r\n    await window.api6100.performScan(0, 300, 0, 300);\r\n    \r\n    try {\r\n      await window.api6100.waitForScanComplete();\r\n      await window.api6100.ejectDocument(1);\r\n      await window.api6100.closeDevice();\r\n      if (parseInt(window.selectedProduct.productConfig.skewTolerance) < 2) {\r\n        await failTestActions(\'Skew tolerance setting should have prevented this document from scanning.\');\r\n      } else {\r\n        await passTestActions();\r\n      }\r\n    } catch (e) {\r\n      let promptMsg = \'Did document not fully scan and is stuck in scanner?\';\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n\r\n      await window.api6100.closeDevice();\r\n\r\n      if (e === \'Wait For Scan Complete: Skew\') {\r\n        if (parseInt(window.selectedProduct.productConfig.skewReject) === 1) {\r\n          promptMsg = \'Did document not fully scan and is ejected out the front of the scanner?\';\r\n        }\r\n        // Have user determine if image is correct\r\n        document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(promptMsg, \'User failed test\');\r\n      } else {\r\n        await failTestActions(e);\r\n      }\r\n    }\r\n\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(21, 3, 'Close Up', 'Close Up', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will reset tallies, collect the bottom barcode, and collect any tester notes.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please attach the barcode label to the bottom of the unit and then scan the serial number.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              return value.length === 10;\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function getTesterNotes() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Tester Notes\',\r\n        message: \'Please enter any notes about the unit being tested.\',\r\n        prompt: {\r\n          type: \'textarea\'\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled tester notes prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n\r\n    window.Loading.show({\r\n      message: \'Resetting tallies\'\r\n    });\r\n\r\n    await resetScanner();\r\n    await window.api6100.openDevice();\r\n    await window.api6100.cortexResetTallies();\r\n    const tallies = await window.api6100.xfn(75);\r\n    if (tallies.xfn !== \'HoursOn,0,ChkScans,0,IDScans,0,SkewCount,0,CoverOpen,0,FwdPaperSteps,0,Stamps,0\') {\r\n      throw new Error(\'Tallies not reset\');\r\n    }\r\n\r\n    window.Loading.hide();\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Get bottom serial number\r\n      const serialNumber = await getBarcode();\r\n\r\n      // Get tester notes\r\n      window.selectedProduct.productionResults.testerNotes = await getTesterNotes();\r\n\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              primarySerialNum: serialNumber,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              primarySerialNum: serialNumber,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await window.api6100.closeDevice();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(22, 3, 'Image Quality: UV WM Gray', 'Image Quality: UV WM Gray', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify calibration of UV/Watermark.</p>', 'async function hideLargeImageUV() {\r\n  document.getElementById(\'viewLargerUV\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImageUV() {\r\n  document.getElementById(\'viewLargerUV\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function hideLargeImageWM() {\r\n  document.getElementById(\'viewLargerWM\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImageWM() {\r\n  document.getElementById(\'viewLargerWM\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function hideLargeImageGray() {\r\n  document.getElementById(\'viewLargerGray\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImageGray() {\r\n  document.getElementById(\'viewLargerGray\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the UV WM sheet aligned to the right of the scan deck.\');\r\n    await window.api6100.performScan(6, 300, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(0x0C, 3, 1); // UV\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\">\r\n        <img id=\"scanImgUV\" style=\"max-width:30%; max-height:calc(100vh - 200px);\" onclick=\"showLargeImageUV()\" />\r\n        <img id=\"scanImgWM\" style=\"max-width:30%; max-height:calc(100vh - 200px);\" onclick=\"showLargeImageWM()\" />\r\n        <img id=\"scanImgGray\" style=\"max-width:30%; max-height:calc(100vh - 200px);\" onclick=\"showLargeImageGray()\" />\r\n      </div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"viewLargerUV\" onclick=\"hideLargeImageUV()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2UV\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n      <div id=\"viewLargerWM\" onclick=\"hideLargeImageWM()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2WM\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n      <div id=\"viewLargerGray\" onclick=\"hideLargeImageGray()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2Gray\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n    `;\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImgUV\').src = URL.createObjectURL(imgBlob);\r\n    document.getElementById(\'scanImg2UV\').src = URL.createObjectURL(imgBlob);\r\n\r\n    const documentResponseWM = await window.api6100.getLastDocument(0x0E, 3, 1); // WM\r\n    const imgBlobWM = new Blob([documentResponseWM.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImgWM\').src = URL.createObjectURL(imgBlobWM);\r\n    document.getElementById(\'scanImg2WM\').src = URL.createObjectURL(imgBlobWM);\r\n\r\n    const documentResponseGray = await window.api6100.getLastDocument(0x07, 3, 1); // Gray\r\n    const imgBlobGray = new Blob([documentResponseGray.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImgGray\').src = URL.createObjectURL(imgBlobGray);\r\n    document.getElementById(\'scanImg2Gray\').src = URL.createObjectURL(imgBlobGray);\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Save image to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // UV\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-uv-wm-gray-uv.jpg\');\r\n      window.selectedProduct.productionResults.files.uvWmGrayUvImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-uv-wm-gray-uv.jpg\';\r\n\r\n      // WM\r\n      await uploadFile(imgBlobWM, window.selectedProduct.productionId + \'-uv-wm-gray-wm.jpg\');\r\n      window.selectedProduct.productionResults.files.uvWmGrayWmImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-uv-wm-gray-wm.jpg\';\r\n\r\n      // Gray\r\n      await uploadFile(imgBlobGray, window.selectedProduct.productionId + \'-uv-wm-gray-gray.jpg\');\r\n      window.selectedProduct.productionResults.files.uvWmGrayGrayImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-uv-wm-gray-gray.jpg\';\r\n      await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    // Have user determine if image is correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Do all three images appear uniform and properly cropped?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(23, 3, 'Image Quality: UV', 'Image Quality: UV', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify calibration of UV.</p>', 'async function hideLargeImageUV() {\r\n  document.getElementById(\'viewLargerUV\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImageUV() {\r\n  document.getElementById(\'viewLargerUV\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function hideLargeImageGray() {\r\n  document.getElementById(\'viewLargerGray\').style.display = \'none\';\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showLargeImageGray() {\r\n  document.getElementById(\'viewLargerGray\').style.display = \'block\';\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the UV Test Sheet aligned to the right of the scan deck.\');\r\n    await window.api6100.performScan(2, 300, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(0x0C, 3, 1); // UV\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"text-align: center;\">\r\n        <img id=\"scanImgUV\" style=\"max-width:45%; max-height:calc(100vh - 200px);\" onclick=\"showLargeImageUV()\" />\r\n        <img id=\"scanImgGray\" style=\"max-width:45%; max-height:calc(100vh - 200px);\" onclick=\"showLargeImageGray()\" />\r\n      </div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      <div id=\"viewLargerUV\" onclick=\"hideLargeImageUV()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2UV\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n      <div id=\"viewLargerGray\" onclick=\"hideLargeImageGray()\" style=\"display: none; text-align:center; position: fixed; bottom: 0; top:0; left:0; right:0; background-color:rgba(0,0,0,0.9); z-index:120;\"><img id=\"scanImg2Gray\" style=\"max-width:100%; max-height:100vh;\" /></div>\r\n    `;\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImgUV\').src = URL.createObjectURL(imgBlob);\r\n    document.getElementById(\'scanImg2UV\').src = URL.createObjectURL(imgBlob);\r\n\r\n    const documentResponseGray = await window.api6100.getLastDocument(0x07, 3, 1); // Gray\r\n    const imgBlobGray = new Blob([documentResponseGray.imgBuffer], { type: \'image/jpeg\' });\r\n    document.getElementById(\'scanImgGray\').src = URL.createObjectURL(imgBlobGray);\r\n    document.getElementById(\'scanImg2Gray\').src = URL.createObjectURL(imgBlobGray);\r\n\r\n    await window.api6100.ejectDocument(1);\r\n\r\n    await window.api6100.closeDevice();\r\n\r\n    // Save image to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // UV\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-uv-gray-uv.jpg\');\r\n      window.selectedProduct.productionResults.files.uvGrayUvImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-uv-gray-uv.jpg\';\r\n\r\n      // Gray\r\n      await uploadFile(imgBlobGray, window.selectedProduct.productionId + \'-uv-gray-gray.jpg\');\r\n      window.selectedProduct.productionResults.files.uvGrayGrayImage = \'6100-test-results/\' + window.selectedProduct.productionId + \'-uv-gray-gray.jpg\';\r\n      await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    // Have user determine if image is correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Do both images appear uniform and properly cropped?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(24, 3, 'Calibrate Double Feed', 'Calibrate Double Feed', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will calibrate the double feed sensor based upon customer target checks.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await window.api6100.cortexSetDoubleFeedDetection(1);\r\n\r\n    // Find without paper loaded first\r\n    window.Loading.show({\r\n      message: \'Finding double feed sensor threshold...\'\r\n    });\r\n\r\n    const TARGET_NO_PAPER_MIN = 1\r\n    const TARGET_NO_PAPER_MAX = 0x28 // Default for single paper presence\r\n\r\n    let noPaperCutoff = TARGET_NO_PAPER_MAX; \r\n    let foundNoPaperCutoff = false;\r\n\r\n    while(!foundNoPaperCutoff && noPaperCutoff > TARGET_NO_PAPER_MIN) {\r\n      await window.api6100.cortexSetDoubleFeedTolerances(noPaperCutoff, 0x190, 0x12C, 0x00, 0x00); // 0x12C\r\n      let response = await window.api6100.getStatus();\r\n      if (response.ub_sens & 0b00100000) {\r\n        noPaperCutoff+=10 // Shift up to be trigger for single paper edge case\r\n        foundNoPaperCutoff = true; \r\n        break;\r\n      }\r\n      noPaperCutoff--;\r\n    }\r\n    window.Loading.hide();\r\n\r\n    if(foundNoPaperCutoff) {\r\n      // Good to find actual avg\r\n      // Set very wide window of acceptability to scan a single doc and a double doc\r\n      await window.api6100.cortexSetDoubleFeedTolerances(noPaperCutoff, 0x3FF, 0x12C, 0x00, 0x00);\r\n\r\n      // Single doc\r\n      await waitForDocumentLoad(true, \'Please load single check on right of the scan deck.\');\r\n      await window.api6100.performScan(0, 300, 0, 300);\r\n      await window.api6100.waitForScanComplete();\r\n      const response = await window.api6100.cortexGetDoubleFeedSensorScanAvg();\r\n      let midPoint = response.avgSensorValue\r\n      //let singlePaperValue = midPoint - ((midPoint - noPaperCutoff) >> 1)\r\nlet singlePaperValue = (noPaperCutoff - 10) + ((midPoint + (noPaperCutoff - 10)) >> 3)\r\n\r\n      // Double doc\r\n      await waitForDocumentLoad(true, \'Please load double stacked check on right of the scan deck.\');\r\n      await window.api6100.performScan(0, 300, 0, 300);\r\n      await window.api6100.waitForScanComplete();\r\n      const responseDouble = await window.api6100.cortexGetDoubleFeedSensorScanAvg();\r\n      let doublePaperValue = responseDouble.avgSensorValue - ((responseDouble.avgSensorValue - midPoint) >> 2)\r\n\r\n      // Set config\r\n      await window.api6100.cortexSetDoubleFeedTolerances(singlePaperValue, doublePaperValue, 0x12C, 0x00, 0x00);\r\n\r\n      await window.api6100.ejectDocument(0);\r\n\r\n      await window.api6100.closeDevice();\r\n\r\n      // Save cfg to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.doubleFeed = {\r\n          noPaperCutoff: (noPaperCutoff - 10),\r\n          singleAvg: midPoint,\r\n          doubleAvg: responseDouble.avgSensorValue,\r\n          singlePaperValue: singlePaperValue,\r\n          doublePaperValue: doublePaperValue\r\n        }\r\n        await window.axios.post(window.selectedProduct.serverUrl, \r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\nconst analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      }\r\n\r\n      //Pass test\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Unable to find double feed sensor threshold.\');\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(25, 4, 'Connect Via USB', 'Connect Via USB', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify ability to connect to the device via USB. Please ensure device is connected via USB and is turned on.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n    await disconnectFromUsb();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(26, 4, 'Install Main Firmware', 'Install Main Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will install the main firmware onto the device.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n    });\r\n\r\n    const fwVersion = await updateFirmware (window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n    const targetFw = window.selectedProduct.productConfig.firmwareVersion.split(\'\');\r\n    const returnFw = fwVersion.split(\'\');\r\n\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n\r\n    if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Firmware version does NOT match targetted version.\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(27, 4, 'Connect Via Serial', 'Connect Via Serial', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify ability to connect to the device via Serial. Please ensure device is connected via Serial (with USB disconnected) and is turned on.</p>', 'function findDeviceOnSerial (attemptTimeInSec) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let timeLeft = attemptTimeInSec;\r\n      const attemptInterval = setInterval(async () => {\r\n        timeLeft--;\r\n        window.Loading.show({\r\n          message: \'Searching for device on Serial. Please make sure device is turned on and connected only by serial. (\' + timeLeft + \' seconds remaining)\'\r\n        });\r\n\r\n        try {\r\n          let foundDevice = await isPrinterOnSerial();\r\n          if (foundDevice.foundPrinter) {\r\n            clearInterval(attemptInterval);\r\n            window.selectedProduct.comPort = foundDevice.printerCom;\r\n            window.Loading.hide();\r\n            resolve();\r\n          }\r\n        } catch (e) {\r\n          window.Loading.hide();\r\n          clearInterval(attemptInterval);\r\n          reject(e);\r\n        }\r\n\r\n        if (timeLeft <= 0) {\r\n          clearInterval(attemptInterval);\r\n          window.Loading.hide();\r\n          reject(\'Never saw device on serial\')\r\n        }\r\n      }, 1000)\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    let timeLeft = 30;\r\n\r\n    window.Loading.show({\r\n      message: \'Searching for device on Serial. Please make sure device is turned on and connected only by serial. (\' + timeLeft + \' seconds remaining)\'\r\n    });\r\n\r\n    await findDeviceOnSerial(timeLeft);\r\n\r\n    window.Loading.hide();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(28, 4, 'PCBA Serial Print Test', 'Serial Print Form', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify ability to print a form over serial. This test is dependent on \"Connect Via Serial\" already being performed.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort) {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n      const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n      let barcode = await window.genericRS232.getBytes(14);\r\n\r\n      let lineFeed = new Array(16).fill(0x0A);\r\n      await window.genericRS232.sendBytes(lineFeed);\r\n\r\n      await printStringViaSerial(\'Barcode is: \');\r\n      barcode.pop();\r\n      barcode.pop();\r\n\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const barcodeByteArray = new Uint8Array(barcode);\r\n        const barcodeDecoder = new TextDecoder(\'UTF-8\');\r\n        window.selectedProduct.productionResults.barcodeOnForm = barcodeDecoder.decode(barcodeByteArray);\r\n\r\n        // Update results\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      barcode.push(0x0A);\r\n      await window.genericRS232.sendBytes(barcode);\r\n\r\n      await printStringViaSerial(\'B/F VER: \');\r\n      const fwVersion = await getFirmwareVersionSerial();\r\n      await printStringViaSerial(fwVersion);\r\n      await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n\r\n      await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n\r\n      await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n      lineFeed = new Array(6).fill(0x0A);\r\n      await window.genericRS232.sendBytes(lineFeed);\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n      await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n      await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n      await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n      await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n      await window.genericRS232.sendBytes(lotsOfH);\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n      await window.genericRS232.sendBytes(lotsOfH);\r\n      await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n      await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n      await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n      await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n      await printStringViaSerial(\'11\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n      await printStringViaSerial(\' ****\');\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n      await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n      await printStringViaSerial(\'         11\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n      await printStringViaSerial(dateString);\r\n      await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]);\r\n\r\n      window.Loading.hide();\r\n\r\n      // Have user determine if correct\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Verify correct barcode, aligned print, and clean tear. Is form good?\', \'User failed test\');\r\n    } else {\r\n      await failTestActions(\'Device has yet to be found on serial.\');\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests` (`testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(29, 4, 'Unlock Vault Via Serial', 'Unlock Vault', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will unlock the vault over serial. This test is dependent on \"Connect Via Serial\" already being performed.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort) {\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n      const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n\r\n      // Have user determine if correct\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did the vault unlock?\', \'User failed test\');\r\n    } else {\r\n      await failTestActions(\'Device has yet to be found on serial.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(30, 4, 'Scan Board Barcode', 'Scan Board Barcode', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will associate the barcode scanned with the test results.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please scan the board barcode.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              const regex = /^[0-9]{6}$/;\r\n              return value.length === 6 && regex.test(value);\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get barcode\r\n    const barcode = await getBarcode();\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      window.selectedProduct.productionResults.boardSerialNum = barcode;\r\n\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              tertiarySerialNum: barcode,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              tertiarySerialNum: barcode,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(31, 4, 'Find Burster Sensor Test Fixture', 'Find Fixture', NULL, '<p>Please ensure fixture is connected to PC prior to starting.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    const response = await isFixtureOnSerial();\r\n    if (response.foundFixture) {\r\n      window.selectedProduct.comPort = response.fixtureCom;\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n\r\n      if (!window.selectedProduct.fixtureSerialNumber) {\r\n        window.selectedProduct.fixtureSerialNumber = await getFixtureSerialNumber();\r\n        await configureFixture();\r\n      }\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Could not find the fixture attached to the computer.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', 'function lookForSensorConnected(secondsToLook, lookingForSensorToBeConnected) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for sensor to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n        if(!lookingForSensorToBeConnected) {\r\n          message = \'Waiting for sensor to be disconnected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorConnectedResponse = await isSensorConnected();\r\n        if(sensorConnectedResponse.sensorConnected === lookingForSensorToBeConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorConnectedResponse.ledValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForSensorNotBlocked(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to NOT be blocked. (\' + Math.round(countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorBlockedResponse = await isSensorBlocked();\r\n        if(sensorBlockedResponse.sensorNotBlocked) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorBlockedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForSensorBlocked(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to be blocked. (\' + Math.round(countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorBlockedResponse = await isSensorBlocked();\r\n        if(sensorBlockedResponse.sensorBlocked) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorBlockedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      await checkForVoltageIssues();\r\n\r\n      window.selectedProduct.productionResults.ledVoltage = await lookForSensorConnected(30, true);\r\n      window.selectedProduct.productionResults.sensorNotBlocked = await lookForSensorNotBlocked(30);\r\n      window.selectedProduct.productionResults.sensorBlocked = await lookForSensorBlocked(30);\r\n      window.selectedProduct.productionResults.ledVoltage = await lookForSensorConnected(30, false);\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n      \r\n      await passTestActions();\r\n\r\n      // Rerun the test\r\n      await reRunTests();\r\n      startTest();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(33, 4, 'Find VCSEL Test Fixture', 'Find Fixture', NULL, '<p>Please ensure fixture is connected to PC prior to starting.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    const response = await isFixtureOnSerial();\r\n    if (response.foundFixture) {\r\n      window.selectedProduct.comPort = response.fixtureCom;\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n\r\n      if (!window.selectedProduct.fixtureSerialNumber) {\r\n        window.selectedProduct.fixtureSerialNumber = await getFixtureSerialNumber();\r\n        await configureFixture();\r\n      }\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Could not find the fixture attached to the computer.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(34, 4, 'Read VCSEL Config', 'Read Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will read the current configuration of the VCSEL.</p>', 'function lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.serialNumber = await getSerialNumber();\r\n      window.selectedProduct.productionResults.currentCollectorValue = await getCurrentCollectorValue();\r\n      window.selectedProduct.productionResults.currentTransmitterValue = await getCurrentTransmitterValue();\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n\r\n      // Show results\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div class=\"testResults\">\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Serial Number:</strong> ${window.selectedProduct.productionResults.serialNumber}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Collector Value:</strong> ${window.selectedProduct.productionResults.currentCollectorValue}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Transmitter Value:</strong> ${window.selectedProduct.productionResults.currentTransmitterValue}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Collector Voltage Reading:</strong> ${window.selectedProduct.productionResults.currentCollectorVoltageReading}</div>\r\n          </div>\r\n        </div>\r\n\r\n        ${drawGauge (window.selectedProduct.productionResults.currentTransmitterValue, window.selectedProduct.productionResults.currentCollectorValue, window.selectedProduct.productionResults.currentCollectorVoltageReading)}\r\n      `;\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(35, 4, 'VCSEL Manual Set', 'Manual Set', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will read the current configuration of the VCSEL and allow for manually setting values.</p>', 'function lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction updateVolatilePots() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#cfgFrm\', {display: \'none\'});\r\n      await setCollectorPot(parseInt(document.getElementById(\'collectorValue\').value));\r\n      await setTransmitterPot(parseInt(document.getElementById(\'emitterValue\').value));\r\n      await waitForReadingToStabilize(3);\r\n\r\n      window.selectedProduct.productionResults.currentCollectorValue = await getCurrentCollectorValue();\r\n      window.selectedProduct.productionResults.currentTransmitterValue = await getCurrentTransmitterValue();\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: window.selectedProduct.productionResults.currentCollectorValue,\r\n        transmitter: window.selectedProduct.productionResults.currentTransmitterValue,\r\n        voltage: window.selectedProduct.productionResults.currentCollectorVoltageReading\r\n      });\r\n\r\n      await drawResults();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction saveNV () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#userDecisionCfg\', {display: \'none\'});\r\n      window.gsap.set(\'#cfgFrm\', {display: \'none\'});\r\n      await setCollectorPot(parseInt(document.getElementById(\'collectorValue\').value));\r\n      await setTransmitterPot(parseInt(document.getElementById(\'emitterValue\').value));\r\n      await waitForReadingToStabilize(3);\r\n      await setCollectorPotNV(parseInt(document.getElementById(\'collectorValue\').value));\r\n      await setTransmitterPotNV(parseInt(document.getElementById(\'emitterValue\').value));\r\n\r\n      window.selectedProduct.productionResults.currentCollectorValue = await getCurrentCollectorValue();\r\n      window.selectedProduct.productionResults.currentTransmitterValue = await getCurrentTransmitterValue();\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: window.selectedProduct.productionResults.currentCollectorValue,\r\n        transmitter: window.selectedProduct.productionResults.currentTransmitterValue,\r\n        voltage: window.selectedProduct.productionResults.currentCollectorVoltageReading\r\n      });\r\n\r\n      await passTestActions();\r\n      await drawResults();\r\n      window.gsap.set(\'#userDecisionCfg\', {display: \'none\'});\r\n      window.gsap.set(\'#cfgFrm\', {display: \'none\'});\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawResults() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Show results\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div class=\"testResults\">\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Serial Number:</strong> ${window.selectedProduct.productionResults.serialNumber}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Collector Value:</strong> ${window.selectedProduct.productionResults.currentCollectorValue}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Transmitter Value:</strong> ${window.selectedProduct.productionResults.currentTransmitterValue}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Collector Voltage Reading:</strong> ${window.selectedProduct.productionResults.currentCollectorVoltageReading}</div>\r\n          </div>\r\n        </div>\r\n\r\n        ${drawGauge (window.selectedProduct.productionResults.currentTransmitterValue, window.selectedProduct.productionResults.currentCollectorValue, window.selectedProduct.productionResults.currentCollectorVoltageReading)}\r\n      \r\n        <form onsubmit=\"return false;\" style=\"margin-top: 50px;\" id=\"cfgFrm\">\r\n          Emitter: <input type=\"text\" id=\"emitterValue\" style=\"width:100px;\" value=\"${window.selectedProduct.productionResults.currentTransmitterValue}\" />\r\n          Collector: <input type=\"text\" id=\"collectorValue\" style=\"width:100px;\" value=\"${window.selectedProduct.productionResults.currentCollectorValue}\" />\r\n          <input type=\"submit\" value=\"Submit\" onclick=\"updateVolatilePots()\" />\r\n        </form>\r\n\r\n        <div id=\"userDecisionCfg\" style=\"position:fixed; right:20px; left:280px; bottom:80px;\">\r\n          <div class=\"actionBtn\" onclick=\"reRunTests()\">Cancel</div>\r\n          <div class=\"actionBtn\" style=\"float:right;\" onclick=\"saveNV()\">Pass/Save Non-Volatile</div>\r\n        </div>\r\n      `;\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.serialNumber = await getSerialNumber();\r\n      window.selectedProduct.productionResults.currentCollectorValue = await getCurrentCollectorValue();\r\n      window.selectedProduct.productionResults.currentTransmitterValue = await getCurrentTransmitterValue();\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      window.selectedProduct.productionResults.testsRan = [];\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: window.selectedProduct.productionResults.currentCollectorValue,\r\n        transmitter: window.selectedProduct.productionResults.currentTransmitterValue,\r\n        voltage: window.selectedProduct.productionResults.currentCollectorVoltageReading\r\n      });\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      // Show results\r\n      drawResults();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', 'IDEAL_VOLTAGE = 1.65;\r\nMIN_COLLECTOR_VAL = 100;\r\nMAX_COLLECTOR_VAL = 127;\r\nMIN_TRANSMITTER_VAL = 110;\r\nMAX_TRANSMITTER_VAL = 127;\r\n\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findCollectorValue (collectorValue, lastVoltage) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (collectorValue < MIN_COLLECTOR_VAL || collectorValue > MAX_COLLECTOR_VAL) {\r\n        reject(\'Could not find good collector value\');\r\n      }\r\n\r\n      await setCollectorPot(collectorValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        let newValue = collectorValue + 1;\r\n        if (voltage < 1.2) {\r\n          newValue+=2; // Extra increment to speed up when far off ideal\r\n        } else if (voltage < 1.4) {\r\n          newValue++; // Extra increment to speed up when far off ideal\r\n        }\r\n        resolve(await findCollectorValue(newValue, voltage));\r\n      } else {\r\n        // Determine if last reading was closer to ideal voltage\r\n        if (Math.abs(IDEAL_VOLTAGE - lastVoltage) < Math.abs(voltage - IDEAL_VOLTAGE)) {\r\n          // Last reading was closer to ideal voltage\r\n          const oldValue = collectorValue - 1;\r\n          await setCollectorPot(oldValue);\r\n          await waitForReadingToStabilize(3);\r\n          await drawProcessing();\r\n          resolve(oldValue);\r\n        } else {\r\n          resolve(collectorValue);\r\n        }\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: collector,\r\n        transmitter: emitter,\r\n        voltage: voltage\r\n      });\r\n\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.testsRan = [];\r\n\r\n      await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n      let collectorValue = await findCollectorValue(MIN_COLLECTOR_VAL, voltage);\r\n\r\n      // Found good value, save to NV RAM\r\n      await setTransmitterPotNV(transmitterValue);\r\n      await setCollectorPotNV(collectorValue);\r\n\r\n      // Perform serialization\r\n      let serialNumber = await getSerialNumber();\r\n      if (serialNumber == 0) {\r\n        // Request new serial number from server\r\n        const serialResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"printer7680\",\r\n              action: \"getNextVcselSerialNumber\",\r\n              params: {}\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (serialResponse.data.success) {\r\n          // Set Serial Number\r\n          await setSerialNumber(parseInt(serialResponse.data.serialNumber));\r\n\r\n          // Get Serial Number\r\n          serialNumber = await getSerialNumber();\r\nif (serialNumber !== parseInt(serialResponse.data.serialNumber)) {\r\nthrow new Error(\'Could not program serial number\');\r\n}\r\n        } else {\r\n          throw new Error(\'Could not get serial number from server\');\r\n        }\r\n      }\r\n\r\n      window.selectedProduct.productionResults.serialNumber = serialNumber;\r\n      window.selectedProduct.productionResults.collectorNV = await getCollectorPotNV();\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.currentCollectorValue = collectorValue;\r\n      window.selectedProduct.productionResults.currentTransmitterValue = transmitterValue;\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n\r\n      // Rerun the test\r\n      await reRunTests();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(37, 4, 'Calibrate VCSEL (Rheostat)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', 'IDEAL_VOLTAGE = 1.65;\r\nMIN_COLLECTOR_VAL = 27;\r\nMAX_COLLECTOR_VAL = 0;\r\nMIN_TRANSMITTER_VAL = 110;\r\nMAX_TRANSMITTER_VAL = 127;\r\n\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findCollectorValue (collectorValue, lastVoltage) { // Note: Reverse direction of values for Rheostat\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (collectorValue < MIN_COLLECTOR_VAL || collectorValue > MAX_COLLECTOR_VAL) {\r\n        reject(\'Could not find good collector value\');\r\n      }\r\n\r\n      await setCollectorPot(collectorValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        let newValue = collectorValue - 1;\r\n        if (voltage < 1.2) {\r\n          newValue-=2; // Extra increment to speed up when far off ideal\r\n        } else if (voltage < 1.4) {\r\n          newValue--; // Extra increment to speed up when far off ideal\r\n        }\r\n        resolve(await findCollectorValue(newValue, voltage));\r\n      } else {\r\n        // Determine if last reading was closer to ideal voltage\r\n        if (Math.abs(IDEAL_VOLTAGE - lastVoltage) < Math.abs(voltage - IDEAL_VOLTAGE)) {\r\n          // Last reading was closer to ideal voltage\r\n          const oldValue = collectorValue - 1;\r\n          await setCollectorPot(oldValue);\r\n          await waitForReadingToStabilize(3);\r\n          await drawProcessing();\r\n          resolve(oldValue);\r\n        } else {\r\n          resolve(collectorValue);\r\n        }\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: collector,\r\n        transmitter: emitter,\r\n        voltage: voltage\r\n      });\r\n\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.testsRan = [];\r\n\r\n      await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n\r\n\r\n      // Found good value, save to NV RAM\r\n      await setTransmitterPotNV(transmitterValue);\r\n      await setCollectorPotNV(collectorValue);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n      let collectorValue = await findCollectorValue(MIN_COLLECTOR_VAL, voltage);\r\n\r\n      // Perform serialization\r\n      let serialNumber = await getSerialNumber();\r\n      if (serialNumber == 0) {\r\n        // Request new serial number from server\r\n        const serialResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"printer7680\",\r\n              action: \"getNextVcselSerialNumber\",\r\n              params: {}\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (serialResponse.data.success) {\r\n          // Set Serial Number\r\n          await setSerialNumber(parseInt(serialResponse.data.serialNumber));\r\n\r\n          // Get Serial Number\r\n          serialNumber = await getSerialNumber();\r\nif (serialNumber !== parseInt(serialResponse.data.serialNumber)) {\r\nthrow new Error(\'Could not program serial number\');\r\n}\r\n        } else {\r\n          throw new Error(\'Could not get serial number from server\');\r\n        }\r\n      }\r\n\r\n      window.selectedProduct.productionResults.serialNumber = serialNumber;\r\n      window.selectedProduct.productionResults.collectorNV = await getCollectorPotNV();\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.currentCollectorValue = collectorValue;\r\n      window.selectedProduct.productionResults.currentTransmitterValue = transmitterValue;\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n\r\n      // Rerun the test\r\n      await reRunTests();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(38, 4, 'OGR (Serial)', 'OGR', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will send the OGR test command over serial. This test is dependent on \"Connect Via Serial\" already being performed.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort) {\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n      await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFA]);\r\n\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Device has yet to be found on serial.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(39, 4, 'Connect USB w/Extended Status', 'Connect Via USB', NULL, '<p>Make sure printer has ribbon, forms, and vault installed. Connect USB, Serial, and HyperComm Test Box.</p>', '\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n    const status = await getExtendedStatusUsb();\r\n    await disconnectFromUsb();\r\n\r\n    let errorString = \'\';\r\n\r\n    if(status.carriageHomeSensorInError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Carriage Home Sensor\'\r\n    }\r\n    if(status.bursterHomeSensorInError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Burster Home Sensor\'\r\n    }\r\n    if(status.paperOut) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Paper Out\'\r\n    }\r\n    if(status.paperLoadingError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Paper Loading\'\r\n    }\r\n    if(status.failedTopOfFormMark) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Failed Top Of Form\'\r\n    }\r\n    if(status.burstError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Burst\'\r\n    }\r\n    if(status.checksumError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Checksum\'\r\n    }\r\n    if(status.feederNotPresent) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Feeder Missing\'\r\n    }\r\n    if(status.burstSensorDefective) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Burst Sensor\'\r\n    }\r\n    if(status.ejectFailed) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Eject\'\r\n    }\r\n\r\n    if (errorString === \'\') {\r\n      await passTestActions();\r\n    } else {\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.onConnectExtendedStatus = status;\r\n\r\n        await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await failTestActions(\'The following issues were found: \' + errorString);\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests` (`testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(40, 4, 'Firmware Update', 'Firmware Update', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will check the current firmware version and update if necessary.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Check current version against desired version\r\n    const currentVersion = await getFirmwareVersionUsb();\r\n    let returnFw = currentVersion.split(\'\');\r\n    const targetFw = window.selectedProduct.productConfig.firmwareVersion.split(\'\');\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      window.selectedProduct.productionResults.reportedFirmware = currentVersion;\r\n    }\r\n\r\n    // Check boot first (fail out if boot wrong) (v3.03A)\r\n    if(returnFw[0]!==\'3\' || returnFw[2]!==\'0\' || returnFw[3]!==\'3\' || returnFw[4]!==\'A\') {\r\n      await disconnectFromUsb();\r\n      await failTestActions(\'Boot Firmware Invalid\');\r\n    } else if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n      // Update not needed\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } else {\r\n      // Update needed\r\n      window.Loading.show({\r\n        message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n      });\r\n      const fwVersion = await updateFirmware (window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n      returnFw = fwVersion.split(\'\');\r\n      await disconnectFromUsb();\r\n      window.Loading.hide();\r\n\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.reportedFirmware = fwVersion;\r\n      }\r\n\r\n      if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n        await passTestActions();\r\n      } else {\r\n        await failTestActions(\'Firmware update failed.\');\r\n      }\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(41, 4, 'Configure For TLA', 'Configure For TLA', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will configure the printer to the TLA settings.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Set configuration\r\n    const isWideVault = parseInt(window.selectedProduct.productConfig.wideVault) === 0 ? false : true;\r\n    if (isWideVault) {\r\n      await window.genericUSB.sendBytes([0x1B, 0x2D, 0x00, 0xA6, 0x00, 0x44, 0x1B, 0x2C, 0x01]); // Wide Vault\r\n    } else {\r\n      await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, 0x44, 0x1B, 0x2C, 0x00]); // Normal Vault\r\n    }\r\n\r\n    // Verify configuration\r\n    await window.genericUSB.sendBytes([0x1B, 0x59]);\r\n    const response = await window.genericUSB.getBytes(128);\r\n    await disconnectFromUsb();\r\n\r\n    if ((isWideVault && response[12]) || (!isWideVault && !response[12])) {\r\n      // Properly configured\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.isWideVault = isWideVault ? \'True\' : \'False\';\r\n      }\r\n\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Failed to configure for TLA\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(42, 4, 'FCT Test', 'FCT Test', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will check the FCT bit that verifies that the board was tested in PCBA.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    const returnResponse = {\r\n      success: false,\r\n      message: \'\'\r\n    }\r\n\r\n    // Verify configuration\r\n    await window.genericUSB.sendBytes([0x1B, 0x59]);\r\n    const response = await window.genericUSB.getBytes(128);\r\n\r\n    switch (response[0]) {\r\n      case 0x03:\r\n        // Clear bit\r\n        const securityResult = await getSecurityBytesUsb(\'fctKey\');\r\n        await window.genericUSB.sendBytes([0x1B, 0x79, 0x00, securityResult[0], securityResult[1]]);\r\n        returnResponse.success = true;\r\n      break;\r\n      case 0x02:\r\n        returnResponse.message = \'Self test was attempted but failed.\';\r\n      break;\r\n      default:\r\n        returnResponse.message = \'Self test was NOT attempted.\';\r\n      break;\r\n    }\r\n\r\n    await disconnectFromUsb();\r\n\r\n    if (returnResponse.success) {\r\n      await passTestActions();\r\n    } else {\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.fctReportedIssue = returnResponse.message;\r\n        await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 40vh;\"></div>\r\n      `;\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(returnResponse.message + \' Continue?\', \'User failed test\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(43, 4, 'HyperComm Power Test', 'HyperComm Power Test', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test is to verify that a HyperComm will receive power.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    \r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 40vh;\"></div>\r\n    `;\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is LED lit on HyperComm Test Box?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(44, 4, 'Switch To Serial (Hex Dump)', 'Switch To Serial (Hex Dump)', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will look for device on serial and perform hex dump.</p>', 'function findDeviceOnSerial (attemptTimeInSec) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let timeLeft = attemptTimeInSec;\r\n      const attemptInterval = setInterval(async () => {\r\n        timeLeft--;\r\n        window.Loading.show({\r\n          message: \'Please load checklist and then disconnect USB so serial connection can occur. (\' + timeLeft + \' seconds remaining)\'\r\n        });\r\n\r\n        try {\r\n          let foundDevice = await isPrinterOnSerial();\r\n          if (foundDevice.foundPrinter) {\r\n            clearInterval(attemptInterval);\r\n            window.selectedProduct.comPort = foundDevice.printerCom;\r\n            window.Loading.hide();\r\n            resolve();\r\n          }\r\n        } catch (e) {\r\n          window.Loading.hide();\r\n          clearInterval(attemptInterval);\r\n          reject(e);\r\n        }\r\n\r\n        if (timeLeft <= 0) {\r\n          clearInterval(attemptInterval);\r\n          window.Loading.hide();\r\n          reject(\'Never saw device on serial\')\r\n        }\r\n      }, 1000)\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction convertHexToPrintableHex (hexByte) {\r\n  let response = [0x00, 0x00, 0x20];\r\n\r\n  response[0] = (hexByte >> 4);\r\n  if(response[0] <= 9) {\r\n    response[0] += 48;\r\n  } else {\r\n    response[0] += (65 - 9);\r\n  }\r\n\r\n  response[1] = (hexByte & 0xF);\r\n  if(response[1] <= 9) {\r\n    response[1] += 48;\r\n  } else {\r\n    response[1] += (65 - 9);\r\n  }\r\n\r\n  return response;\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await findDeviceOnSerial(30);\r\n\r\n    // Get config\r\n    await window.genericRS232.sendBytes([0x1B, 0x59]);\r\n    let configArray = await window.genericRS232.getBytes(128);\r\n\r\n    const margin = new Array(30).fill(0x20);\r\n    const doubleMargin = new Array(15).fill(0x20);\r\n\r\n    //Load form\r\n    await window.genericRS232.sendBytes([0x1B, 0x46]);\r\n\r\n    // Delay 4 seconds for form to load\r\n    await new Promise((resolve) => {\r\n      setTimeout(() => {\r\n        resolve();\r\n      }, 4000);\r\n    });\r\n\r\n    // Check for load\r\n    await window.genericRS232.sendBytes([0x1B, 0x50]);\r\n    const loadResponse = await window.genericRS232.getBytes(1);\r\n    if(loadResponse[0] === 0x01) {\r\n      const extendedStatus = await getExtendedStatusSerial();\r\n      if(extendedStatus.paperOut || extendedStatus.paperLoadingError) {\r\n       throw new Error(\'Paper loading error\');\r\n      }\r\n\r\n      let printJob = [];\r\n\r\n      //Advance form some\r\n      printJob = printJob.concat([0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A]);\r\n\r\n      for(let i=128; i>=8; i-=8) {\r\n        printJob = printJob.concat(margin);\r\n        printJob = printJob.concat(convertHexToPrintableHex(configArray[(i - 8)]));\r\n        printJob = printJob.concat(convertHexToPrintableHex(configArray[(i - 7)]));\r\n        printJob = printJob.concat(convertHexToPrintableHex(configArray[(i - 6)]));\r\n        printJob = printJob.concat(convertHexToPrintableHex(configArray[(i - 5)]));\r\n        printJob = printJob.concat(convertHexToPrintableHex(configArray[(i - 4)]));\r\n        printJob = printJob.concat(convertHexToPrintableHex(configArray[(i - 3)]));\r\n        printJob = printJob.concat(convertHexToPrintableHex(configArray[(i - 2)]));\r\n        printJob = printJob.concat(convertHexToPrintableHex(configArray[(i - 1)]));\r\n        printJob = printJob.concat([0x0A]);\r\n      }\r\n\r\n      //Advance form some\r\n      printJob = printJob.concat([0x0A]);\r\n      await window.genericRS232.sendBytes(printJob);\r\n\r\n      //Font expansion to double wide, double high\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]);\r\n\r\n      await window.genericRS232.sendBytes(doubleMargin);\r\n      await window.genericRS232.sendBytes([0x48, 0x45, 0x58, 0x20, 0x44, 0x55, 0x4D, 0x50, 0x0A]); //HEX DUMP\r\n\r\n      //Font expansion to normal\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]);\r\n      \r\n      //Eject\r\n      await window.genericRS232.sendBytes([0x1B, 0x45]);\r\n\r\n      // Delay 10 seconds for form to print\r\n      await new Promise((resolve) => {\r\n        setTimeout(() => {\r\n          resolve();\r\n        }, 11000);\r\n      });\r\n\r\n      window.Loading.hide();\r\n      passTestActions();\r\n    } else {\r\n      window.Loading.hide();\r\n      await failTestActions(\'Never saw form loaded.\');\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(45, 4, 'Serial Print Test', 'Serial Print Test', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify ability to print a form over serial. This test is dependent on \"Connect Via Serial\" already being performed.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort) {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n      const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n      let barcode = await window.genericRS232.getBytes(14);\r\n\r\n      let lineFeed = new Array(16).fill(0x0A);\r\n      await window.genericRS232.sendBytes(lineFeed);\r\n\r\n      await printStringViaSerial(\'Barcode is: \');\r\n      barcode.pop();\r\n      barcode.pop();\r\n\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const barcodeByteArray = new Uint8Array(barcode);\r\n        const barcodeDecoder = new TextDecoder(\'UTF-8\');\r\n        window.selectedProduct.productionResults.barcodeOnForm = barcodeDecoder.decode(barcodeByteArray);\r\n\r\n        // Update results\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      barcode.push(0x0A);\r\n      await window.genericRS232.sendBytes(barcode);\r\n\r\n      await printStringViaSerial(\'B/F VER: \');\r\n      const fwVersion = await getFirmwareVersionSerial();\r\n      await printStringViaSerial(fwVersion);\r\n      await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n\r\n      await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n\r\n      await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n      lineFeed = new Array(6).fill(0x0A);\r\n      await window.genericRS232.sendBytes(lineFeed);\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n      await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n      await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n      await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n      await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n      let lotsOfH = new Array(64).fill(0x48);\r\n      await window.genericRS232.sendBytes(lotsOfH);\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n      await window.genericRS232.sendBytes(lotsOfH);\r\n      await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n      await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n      await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n      await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n      await printStringViaSerial(\'11\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n      await printStringViaSerial(\' ****\');\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n      await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n      await printStringViaSerial(\'         11\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n      await printStringViaSerial(dateString);\r\n      await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]);\r\n\r\n      window.Loading.hide();\r\n\r\n      // Have user determine if correct\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Verify correct barcode, aligned print, and clean tear. Is form good?\', \'User failed test\');\r\n    } else {\r\n      await failTestActions(\'Device has yet to be found on serial.\');\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(46, 4, 'Program Unit S/N', 'Program Unit S/N', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will collect the main unit\'s serial number and program it into the firmware.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please scan the main unit barcode.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              const regex = /^7680/;\r\n              return value.length === 14 && regex.test(value);\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get barcode\r\n    const barcode = await getBarcode();\r\n\r\n    // Check to see if packed before\r\n    const packedResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"printer7680\",\r\n          action: \"checkIfPackedBefore\",\r\n          params: {\r\n            primarySerialNum: barcode\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if (packedResponse.data.success && !packedResponse.data.packedBefore) {\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        // Update results\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                primarySerialNum: barcode,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                primarySerialNum: barcode,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      // Calc key\r\n      let payload = [];\r\n      for (let i = 0; i < 14; i++) {\r\n        payload.push(barcode.charCodeAt(i));\r\n      }\r\n      const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n        query: {\r\n          dataset: \'printer7680\',\r\n          action: \'getSecuritySeed\',\r\n          params: {\r\n            requestType: \'serialKey\',\r\n            token: payload\r\n          }\r\n        }\r\n      })\r\n      if (serverResponse.data.success) {\r\n        // Write barcode to firmware\r\n        await connectToSerial(window.selectedProduct.comPort);\r\n        await window.genericRS232.sendBytes([0x1B, 0x7D, 0x00, serverResponse.data.securitySeed[0]]);\r\n        await printStringViaSerial(barcode);\r\n\r\n        // Read back and verify match\r\n        await window.genericRS232.sendBytes([0x1B, 0x74, 0x14]);\r\n        const serialResponse = await window.genericRS232.getBytes(15);\r\n\r\n        let validCode = true;\r\n        for (let i = 0; i < 14; i++) {\r\n          if(serialResponse[i] != payload[i]) {\r\n            validCode = false;\r\n          }\r\n        }\r\n\r\n        if(!validCode) {\r\n          throw new Error(\'Unable to write serial number.\');\r\n        }\r\n\r\n        await passTestActions();\r\n      } else {\r\n        throw new Error(\'Unable to generate security seed.\');\r\n      }\r\n    } else {\r\n      throw new Error(\'This unit has already been packed.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(47, 4, 'Program Vault S/N', 'Program Vault S/N', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will collect the vault unit\'s serial number.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please scan the vault unit barcode.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              const regex = /^5785/;\r\n              return value.length === 14 && regex.test(value);\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get barcode\r\n    const barcode = await getBarcode();\r\n\r\n    // Check to see if packed before\r\n    const packedResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"printer7680\",\r\n          action: \"checkIfPackedBefore\",\r\n          params: {\r\n            secondarySerialNum: barcode\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    if (packedResponse.data.success && !packedResponse.data.packedBefore) {\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        // Update results\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                secondarySerialNum: barcode,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                secondarySerialNum: barcode,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n    } else {\r\n      throw new Error(\'This unit has already been packed.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(48, 4, 'Serial Print Test w/Device SN', 'Serial Print Test With S/N', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will print a test form that includes the serial number.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort) {\r\n      window.Loading.show({\r\n        message: \'Printing test form\'\r\n      });\r\n\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n      const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n      let barcode = await window.genericRS232.getBytes(14);\r\n\r\n      let lineFeed = new Array(16).fill(0x0A);\r\n      await window.genericRS232.sendBytes(lineFeed);\r\n\r\n      await printStringViaSerial(\'Barcode is: \');\r\n      barcode.pop();\r\n      barcode.pop();\r\n\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const barcodeByteArray = new Uint8Array(barcode);\r\n        const barcodeDecoder = new TextDecoder(\'UTF-8\');\r\n        window.selectedProduct.productionResults.barcodeOnSerialNumberForm = barcodeDecoder.decode(barcodeByteArray);\r\n\r\n        // Update results\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await window.genericRS232.sendBytes(barcode);\r\n\r\n      await printStringViaSerial(\' Serial Number: \');\r\n\r\n      //Get serial number from device\r\n      await window.genericRS232.sendBytes([0x1B, 0x74, 0x14]);\r\n      let responseSN = await window.genericRS232.getBytes(15);\r\n      responseSN.pop();\r\n      await window.genericRS232.sendBytes(responseSN);\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n\r\n      await printStringViaSerial(\'B/F VER: \');\r\n      const fwVersion = await getFirmwareVersionSerial();\r\n      await printStringViaSerial(fwVersion);\r\n      await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n\r\n      await printStringViaSerial(\'Money Order **22 DOLLAR AND 22 CENTS\');\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n\r\n      const d = new Date();\r\n      let dateString = d.toString();\r\n      dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n      let timeString = d.toTimeString();\r\n      timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n      timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n\r\n\r\n      await printStringViaSerial(dateString + \' $22.22\');\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n\r\n      lineFeed = new Array(14).fill(0x0A);\r\n      await window.genericRS232.sendBytes(lineFeed);\r\n\r\n      await printStringViaSerial(\'TWENTY TWO DOLLARS AND TWENTY TWO CENTS ********\');\r\n      await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n\r\n      await printStringViaSerial(\'SERIAL NUMBER: \');\r\n      await window.genericRS232.sendBytes(responseSN);\r\n      await printStringViaSerial(\'                \');\r\n\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n      await printStringViaSerial(\'22\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n      await printStringViaSerial(\' ****\');\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n      await printStringViaSerial(\'Time \' + timeString + \'      \');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n      await printStringViaSerial(\'         22\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n      await window.genericRS232.sendBytes([0x0A]);\r\n      await printStringViaSerial(dateString);\r\n      await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]);\r\n\r\n      window.Loading.hide();\r\n\r\n      // Have user determine if correct\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Verify correct barcode, aligned print, and clean tear. Is form good?\', \'User failed test\');\r\n    } else {\r\n      await failTestActions(\'Device has yet to be found on serial.\');\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(49, 4, 'Get Tallies And Config', 'Get Tallies And Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will read the tallies and config of the device.</p>', '\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get Firmware Version\r\n    window.selectedProduct.productionResults.finalFirmwareVersion = await getFirmwareVersionSerial();\r\n\r\n    // Get Formatted Config\r\n    window.selectedProduct.productionResults.finalConfig = await getFormattedConfigSerial();\r\n\r\n    if (window.selectedProduct.productionResults.finalConfig.flashWriteProtect == 0) {\r\n      throw new Error(\"Flash Write Protect is not enabled\");\r\n    }\r\n\r\n    // Get Tallies\r\n    window.selectedProduct.productionResults.finalTallies = await getTalliesSerial();\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"width:47%; float:left; border:1px solid #aeaeae; border-radius:5px; margin-top:10px; margin-left:20px;\">\r\n        <div class=\"text-h4\" style=\"text-align:center;\">Tallies</div>\r\n        <ul>\r\n          <li><strong>Dot Count:</strong> ${window.selectedProduct.productionResults.finalTallies.dotCount}</li>\r\n          <li><strong>Form Count:</strong> ${window.selectedProduct.productionResults.finalTallies.formCount}</li>\r\n          <li><strong>Void Count:</strong> ${window.selectedProduct.productionResults.finalTallies.voidCount}</li>\r\n          <li><strong>Burst Count:</strong> ${window.selectedProduct.productionResults.finalTallies.burstCount}</li>\r\n          <li><strong>Vault Install Count:</strong> ${window.selectedProduct.productionResults.finalTallies.vaultInstalledCount}</li>\r\n          <li><strong>Time On:</strong> ${window.selectedProduct.productionResults.finalTallies.timeOn}</li>\r\n          <li><strong>Resets:</strong> ${window.selectedProduct.productionResults.finalTallies.resetsCount}</li>\r\n          <li><strong>Firmware Updates:</strong> ${window.selectedProduct.productionResults.finalTallies.firmwareUpdatesCount}</li>\r\n          <li><strong>External Sheets Loaded:</strong> ${window.selectedProduct.productionResults.finalTallies.extSheetsLoadedCount}</li>\r\n          <li><strong>Ribbon Count:</strong> ${window.selectedProduct.productionResults.finalTallies.ribbonsCount}</li>\r\n          <li><strong>Ribbon Dot Count:</strong> ${window.selectedProduct.productionResults.finalTallies.ribbonDotCount}</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div style=\"width:47%; float:right; border:1px solid #aeaeae; border-radius:5px; margin-top:10px;\">\r\n        <div class=\"text-h4\" style=\"text-align:center;\">Config</div>\r\n        <ul>\r\n          <li><strong>FCT:</strong> ${window.selectedProduct.productionResults.finalConfig.fct}</li>\r\n          <li><strong>AC-Coupled Barcode Enabled:</strong> ${window.selectedProduct.productionResults.finalConfig.acCoupledBarcodeEnabled}</li>\r\n          <li><strong>Burster Sensor Config:</strong> ${window.selectedProduct.productionResults.finalConfig.bursterSensorCfg}</li>\r\n          <li><strong>Print Line Offset:</strong> ${window.selectedProduct.productionResults.finalConfig.printLineOffset}</li>\r\n          <li><strong>Burst Search Max Distance:</strong> ${window.selectedProduct.productionResults.finalConfig.burstSearchMaxDistance}</li>\r\n          <li><strong>Burst Mark to Perforation:</strong> ${window.selectedProduct.productionResults.finalConfig.burstMarkToPerforation}</li>\r\n          <li><strong>Wide Vault Enabled:</strong> ${window.selectedProduct.productionResults.finalConfig.wideVaultEnabled}</li>\r\n          <li><strong>Design Level:</strong> ${window.selectedProduct.productionResults.finalConfig.designLevel}</li>\r\n          <li><strong>Flash Write Protect:</strong> ${window.selectedProduct.productionResults.finalConfig.flashWriteProtect}</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div style=\"clear:both;\"></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 20px;\"></div>\r\n    `;\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Verify configuration and tallies. Is it correct?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(50, 4, 'Scan Printer Checklist', 'Scan Printer Checklist', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will scan and store the printer checklist.</p>', '\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the printer checklist aligned to the right of the scan deck.\');\r\n    await window.api6100.performScan(0, 200, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(7, 3, 1);\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    await window.api6100.ejectDocument(0);\r\n    await window.api6100.closeDevice();\r\n\r\n    // Save image to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-printer-checklist.jpg\');\r\n      window.selectedProduct.productionResults.files.printerChecklist = \'7680-test-results/\' + window.selectedProduct.productionId + \'-printer-checklist.jpg\';\r\n      await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(51, 4, 'Scan Vault Checklist', 'Scan Vault Checklist', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will scan and store the vault checklist.</p>', '\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await waitForDocumentLoad(true, \'Please load the vault checklist aligned to the right of the scan deck.\');\r\n    await window.api6100.performScan(0, 200, 0, 300);\r\n    await window.api6100.waitForScanComplete();\r\n    const documentResponse = await window.api6100.getLastDocument(7, 3, 1);\r\n    const imgBlob = new Blob([documentResponse.imgBuffer], { type: \'image/jpeg\' });\r\n    await window.api6100.ejectDocument(0);\r\n    await window.api6100.closeDevice();\r\n\r\n    // Save image to server\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      await uploadFile(imgBlob, window.selectedProduct.productionId + \'-vault-checklist.jpg\');\r\n      window.selectedProduct.productionResults.files.vaultChecklist = \'7680-test-results/\' + window.selectedProduct.productionId + \'-vault-checklist.jpg\';\r\n      await window.axios.post(window.selectedProduct.serverUrl, \r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests` (`testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(52, 4, 'Alignment (For Final Test)', 'Alignment', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will print a test form and allow for alignment adjustment.</p>', '\r\nfunction printAlignmentForm () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (window.selectedProduct.comPort) {\r\n        window.Loading.show({\r\n          message: \'Printing test form\'\r\n        });\r\n  \r\n        await connectToSerial(window.selectedProduct.comPort);\r\n        const securityResult = await getSecurityBytesSerial(\'loadFormKey\');\r\n        await window.genericRS232.sendBytes([0x1B, 0x4A, securityResult[0], securityResult[1], 0x0C]);\r\n        let barcode = await window.genericRS232.getBytes(14);\r\n  \r\n        let lineFeed = new Array(16).fill(0x0A);\r\n        await window.genericRS232.sendBytes(lineFeed);\r\n  \r\n        await printStringViaSerial(\'Barcode is: \');\r\n        barcode.pop();\r\n        barcode.pop();\r\n  \r\n        if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n          const barcodeByteArray = new Uint8Array(barcode);\r\n          const barcodeDecoder = new TextDecoder(\'UTF-8\');\r\n          window.selectedProduct.productionResults.barcodeOnForm = barcodeDecoder.decode(barcodeByteArray);\r\n  \r\n          // Update results\r\n          const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"updateProduction\",\r\n                params: {\r\n                  productionId: window.selectedProduct.productionId,\r\n                  productionResults: window.selectedProduct.productionResults\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n          const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n            {\r\n              query: {\r\n                dataset: \"productionTracking\",\r\n                action: \"updateProduction\",\r\n                params: {\r\n                  analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                  analyticsResults: window.selectedProduct.productionResults\r\n                }\r\n              }\r\n            },\r\n            { headers: { \"Content-Type\": \"application/json\" }}\r\n          );\r\n        }\r\n  \r\n        barcode.push(0x0A);\r\n        await window.genericRS232.sendBytes(barcode);\r\n  \r\n        await printStringViaSerial(\'B/F VER: \');\r\n        const fwVersion = await getFirmwareVersionSerial();\r\n        await printStringViaSerial(fwVersion);\r\n        await printStringViaSerial(\' Serial Test By: \' + window.selectedProduct.testerName);\r\n        await window.genericRS232.sendBytes([0x0A]);\r\n  \r\n        await printStringViaSerial(\'HHHHH Money Order **11 DOLLAR AND 11 CENTS\');\r\n        await window.genericRS232.sendBytes([0x0A]);\r\n  \r\n        const d = new Date();\r\n        let dateString = d.toString();\r\n        dateString = dateString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n        dateString = dateString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n        let timeString = d.toTimeString();\r\n        timeString = timeString.replace(\'(Mountain Daylight Time)\', \'(MDT)\');\r\n        timeString = timeString.replace(\'(Mountain Standard Time)\', \'(MST)\');\r\n  \r\n  \r\n        await printStringViaSerial(\'HHHHH \' + dateString + \' $11.11\');\r\n        await window.genericRS232.sendBytes([0x0A]);\r\n  \r\n        await window.genericRS232.sendBytes([0x1B, 0x51]); // Burst\r\n  \r\n        lineFeed = new Array(6).fill(0x0A);\r\n        await window.genericRS232.sendBytes(lineFeed);\r\n  \r\n        await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n        await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHH\');\r\n        await window.genericRS232.sendBytes([0x0A, 0x0A, 0x0A]);\r\n  \r\n        await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n        await printStringViaSerial(\'HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH\');\r\n        await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n  \r\n        await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n        let lotsOfH = new Array(64).fill(0x48);\r\n        await window.genericRS232.sendBytes(lotsOfH);\r\n        await window.genericRS232.sendBytes([0x0A]);\r\n        await window.genericRS232.sendBytes(lotsOfH);\r\n        await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n  \r\n        await printStringViaSerial(\'HHHHHHHH DOLLARS AND ELEVEN CENTS ********\');\r\n        await window.genericRS232.sendBytes([0x0A, 0x0A]);\r\n  \r\n        await printStringViaSerial(\'HHHHH LOCATION 82501                         \');\r\n        await window.genericRS232.sendBytes([0x1B, 0x4B, 0x33]); // Triple wide/high\r\n        await printStringViaSerial(\'11\');\r\n        await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n        await printStringViaSerial(\' ****\');\r\n        await window.genericRS232.sendBytes([0x0A]);\r\n        await printStringViaSerial(\'HHHHH Time \' + timeString);\r\n        await window.genericRS232.sendBytes([0x1B, 0x4B, 0x32]); // Double wide/high\r\n        await printStringViaSerial(\'         11\');\r\n        await window.genericRS232.sendBytes([0x1B, 0x4B, 0x30]); // Normal\r\n        await window.genericRS232.sendBytes([0x0A]);\r\n        await printStringViaSerial(dateString);\r\n        await window.genericRS232.sendBytes([0x0A, 0x1B, 0x45]);\r\n  \r\n        window.Loading.hide();\r\n  \r\n        resolve();\r\n      } else {\r\n        reject(\'Device has yet to be found on serial.\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nasync function setBurstAlignment (alignmentValue) {\r\n  try {\r\n    await connectToSerial(window.selectedProduct.comPort);\r\n    await window.genericRS232.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, alignmentValue, 0x1B, 0x2C, 0x00]);\r\n      \r\n    window.selectedProduct.productionResults.burstAlignment = alignmentValue;\r\n\r\n    window.Notify.create({\r\n      message: \'Set Burst Alignment to: \' + alignmentValue,\r\n      position: \'top\',\r\n      color: \'positive\'\r\n    });\r\n\r\n    showAlignmentAdjForm();\r\n  } catch (err) {\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function setHorizontalAlignment (alignmentValue) {\r\n  try {\r\n    await connectToSerial(window.selectedProduct.comPort);\r\n    await window.genericRS232.sendBytes([0x1B, 0x5D, alignmentValue, 0x00]);\r\n      \r\n    window.selectedProduct.productionResults.horizontalAlignment = alignmentValue;\r\n\r\n    window.Notify.create({\r\n      message: \'Set Horizontal Alignment to: \' + alignmentValue,\r\n      position: \'top\',\r\n      color: \'positive\'\r\n    });\r\n\r\n    showAlignmentAdjForm();\r\n  } catch (err) {\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkBurstSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.burstAlignment && window.selectedProduct.productionResults.burstAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction checkHorizontalSelection (selectedValue) {\r\n  let classValue = \'notSelected\';\r\n\r\n  if (window.selectedProduct.productionResults.horizontalAlignment !== null && window.selectedProduct.productionResults.horizontalAlignment == selectedValue) {\r\n    classValue = \'selected\';\r\n  }\r\n\r\n  return classValue;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showAlignmentAdjForm () {\r\n  try {\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <table class=\"alignmentTbl\">\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(62)\" class=\"` + checkBurstSelection(62) + `\">62</button></td>\r\n          <td colspan=\"6\" rowspan=\"16\" class=\"alignBg\" style=\"background-image:url(\'${window.selectedProduct.serverUrl}uploads/7680_instructions/align-sample.webp\');\")><div class=\"alignInstructions\">Please adjust alignment if needed. Burst alignment is adjusted using the left vertical adjustment values. Character horizontal band alignment is adjusted using the horizontal adjustment values across the bottom.</div></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(63)\" class=\"` + checkBurstSelection(63) + `\">63</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(64)\" class=\"` + checkBurstSelection(64) + `\">64</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(65)\" class=\"` + checkBurstSelection(65) + `\">65</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(66)\" class=\"` + checkBurstSelection(66) + `\">66</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(67)\" class=\"` + checkBurstSelection(67) + `\">67</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(68)\" class=\"` + checkBurstSelection(68) + `\">68 (default)</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(69)\" class=\"` + checkBurstSelection(69) + `\">69</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(70)\" class=\"` + checkBurstSelection(70) + `\">70</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(71)\" class=\"` + checkBurstSelection(71) + `\">71</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(72)\" class=\"` + checkBurstSelection(72) + `\">72</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(73)\" class=\"` + checkBurstSelection(73) + `\">73</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(74)\" class=\"` + checkBurstSelection(74) + `\">74</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(75)\" class=\"` + checkBurstSelection(75) + `\">75</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(76)\" class=\"` + checkBurstSelection(76) + `\">76</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td class=\"burstOpt\"><button onclick=\"setBurstAlignment(77)\" class=\"` + checkBurstSelection(77) + `\">77</button></td>\r\n        </tr>\r\n        <tr>\r\n          <td></td>\r\n          <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(0)\" class=\"` + checkHorizontalSelection(0) + `\">0</button></td>\r\n          <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(1)\" class=\"` + checkHorizontalSelection(1) + `\">1</button></td>\r\n          <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(2)\" class=\"` + checkHorizontalSelection(2) + `\">2</button></td>\r\n          <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(3)\" class=\"` + checkHorizontalSelection(3) + `\">3</button></td>\r\n          <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(4)\" class=\"` + checkHorizontalSelection(4) + `\">4</button></td>\r\n          <td class=\"horizontalOpt\"><button onclick=\"setHorizontalAlignment(5)\" class=\"` + checkHorizontalSelection(5) + `\">5</button></td>\r\n        </tr>\r\n      </table>\r\n      <div class=\"alignBtns\">\r\n        <button onclick=\"failTestActions(\'Cannot Align\')\">Cannot Align</button>\r\n        <button onclick=\"printAndAlignLoop()\">Print Again</button>\r\n      </div>\r\n\r\n      <style>\r\n        .alignmentTbl {\r\n          font-size: 90%;\r\n          width: 100%;\r\n        }\r\n          .alignmentTbl td{\r\n            text-align: center;\r\n          }\r\n          .alignmentTbl button {\r\n            display: inline-block;\r\n            width:100px;\r\n          }\r\n\r\n        .alignBg {\r\n          background-repeat: no-repeat;\r\n          background-position: left bottom;\r\n          background-size: contain;\r\n          vertical-align: top;\r\n          font-weight: bold;\r\n          font-size: 120%;\r\n        }\r\n\r\n        .burstOpt {\r\n          background-color: #275676;\r\n        }\r\n        .horizontalOpt {\r\n          background-color: #277627;\r\n        }\r\n        .alignInstructions {\r\n          background-color: rgba(255,255,255,0.9);\r\n          padding:10px;\r\n          max-width: 768px;\r\n          margin: 10px auto;\r\n          border-radius: 10px;\r\n          box-shadow: 2px 2px 10px rgba(0,0,0,0.5);\r\n        }\r\n        .selected {\r\n          background-color: #aaa;\r\n        }\r\n        .alignBtns {\r\n          text-align: right;\r\n        }\r\n          .alignBtns button{\r\n            margin: 10px;\r\n          }\r\n      </style>\r\n    `;\r\n  } catch (e) {\r\n    console.log(e);\r\n  }\r\n}\r\n// -------------------------------------------------------- //\r\nfunction promptForIfAlignmentGood () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Have user determine if correct\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\">\r\n          <div id=\"userDecisionPromptWrapper\">\r\n            <div class=\"dialog\">Is both the burst and horizontal alignment good?</div>\r\n            <div class=\"dialog-buttons\" style=\"padding-top:10px;\">\r\n              <button class=\"dialog-button\" style=\"padding:0 40px; margin-right: 40px;\" onclick=\"(async () => { \r\n                showAlignmentAdjForm();\r\n              })();\">No</button>\r\n              <button class=\"dialog-button\" style=\"padding:0 40px; \" onclick=\"(async () => { \r\n                passTestActions();\r\n              })();\">Yes</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      `;\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction printAndAlignLoop () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await printAlignmentForm();\r\n      await promptForIfAlignmentGood();\r\n\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await printAndAlignLoop();\r\n\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(53, 4, 'Program Unit S/N (RMA Only)', 'Program Unit S/N', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will collect the main unit\'s serial number and program it into the firmware.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please scan the main unit barcode.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              const regex = /^7680/;\r\n              return value.length === 14 && regex.test(value);\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get barcode\r\n    const barcode = await getBarcode();\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              primarySerialNum: barcode,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              primarySerialNum: barcode,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    // Calc key\r\n    let payload = [];\r\n    for (let i = 0; i < 14; i++) {\r\n      payload.push(barcode.charCodeAt(i));\r\n    }\r\n    const serverResponse = await window.axios.post(window.selectedProduct.serverUrl, {\r\n      query: {\r\n        dataset: \'printer7680\',\r\n        action: \'getSecuritySeed\',\r\n        params: {\r\n          requestType: \'serialKey\',\r\n          token: payload\r\n        }\r\n      }\r\n    })\r\n    if (serverResponse.data.success) {\r\n      // Write barcode to firmware\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n      await window.genericRS232.sendBytes([0x1B, 0x7D, 0x00, serverResponse.data.securitySeed[0]]);\r\n      await printStringViaSerial(barcode);\r\n\r\n      // Read back and verify match\r\n      await window.genericRS232.sendBytes([0x1B, 0x74, 0x14]);\r\n      const serialResponse = await window.genericRS232.getBytes(15);\r\n\r\n      let validCode = true;\r\n      for (let i = 0; i < 14; i++) {\r\n        if(serialResponse[i] != payload[i]) {\r\n          validCode = false;\r\n        }\r\n      }\r\n\r\n      if(!validCode) {\r\n        throw new Error(\'Unable to write serial number.\');\r\n      }\r\n\r\n      await passTestActions();\r\n    } else {\r\n      throw new Error(\'Unable to generate security seed.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(54, 4, 'Program Vault S/N (RMA Only)', 'Program Vault S/N', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will collect the vault unit\'s serial number.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please scan the vault unit barcode.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              const regex = /^5785/;\r\n              return value.length === 14 && regex.test(value);\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get barcode\r\n    const barcode = await getBarcode();\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              secondarySerialNum: barcode,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              secondarySerialNum: barcode,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(55, 4, 'Get Tallies And Config (Start/USB)', 'Get Tallies And Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will read the tallies and config of the device.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Get Firmware Version\r\n    window.selectedProduct.productionResults.initialFirmwareVersion = await getFirmwareVersionUsb();\r\n\r\n    // Get Formatted Config\r\n    window.selectedProduct.productionResults.initialConfig = await getFormattedConfigUsb();\r\n\r\n    if (window.selectedProduct.productionResults.initialConfig.flashWriteProtect == 0) {\r\n      throw new Error(\"Flash Write Protect is not enabled\");\r\n    }\r\n\r\n    // Get Tallies\r\n    window.selectedProduct.productionResults.initialTallies = await getTalliesUsb();\r\n    await disconnectFromUsb();\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div style=\"width:47%; float:left; border:1px solid #aeaeae; border-radius:5px; margin-top:10px; margin-left:20px;\">\r\n        <div class=\"text-h4\" style=\"text-align:center;\">Tallies</div>\r\n        <ul>\r\n          <li><strong>Dot Count:</strong> ${window.selectedProduct.productionResults.initialTallies.dotCount}</li>\r\n          <li><strong>Form Count:</strong> ${window.selectedProduct.productionResults.initialTallies.formCount}</li>\r\n          <li><strong>Void Count:</strong> ${window.selectedProduct.productionResults.initialTallies.voidCount}</li>\r\n          <li><strong>Burst Count:</strong> ${window.selectedProduct.productionResults.initialTallies.burstCount}</li>\r\n          <li><strong>Vault Install Count:</strong> ${window.selectedProduct.productionResults.initialTallies.vaultInstalledCount}</li>\r\n          <li><strong>Time On:</strong> ${window.selectedProduct.productionResults.initialTallies.timeOn}</li>\r\n          <li><strong>Resets:</strong> ${window.selectedProduct.productionResults.initialTallies.resetsCount}</li>\r\n          <li><strong>Firmware Updates:</strong> ${window.selectedProduct.productionResults.initialTallies.firmwareUpdatesCount}</li>\r\n          <li><strong>External Sheets Loaded:</strong> ${window.selectedProduct.productionResults.initialTallies.extSheetsLoadedCount}</li>\r\n          <li><strong>Ribbon Count:</strong> ${window.selectedProduct.productionResults.initialTallies.ribbonsCount}</li>\r\n          <li><strong>Ribbon Dot Count:</strong> ${window.selectedProduct.productionResults.initialTallies.ribbonDotCount}</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div style=\"width:47%; float:right; border:1px solid #aeaeae; border-radius:5px; margin-top:10px;\">\r\n        <div class=\"text-h4\" style=\"text-align:center;\">Config</div>\r\n        <ul>\r\n          <li><strong>FCT:</strong> ${window.selectedProduct.productionResults.initialConfig.fct}</li>\r\n          <li><strong>AC-Coupled Barcode Enabled:</strong> ${window.selectedProduct.productionResults.initialConfig.acCoupledBarcodeEnabled}</li>\r\n          <li><strong>Burster Sensor Config:</strong> ${window.selectedProduct.productionResults.initialConfig.bursterSensorCfg}</li>\r\n          <li><strong>Print Line Offset:</strong> ${window.selectedProduct.productionResults.initialConfig.printLineOffset}</li>\r\n          <li><strong>Burst Search Max Distance:</strong> ${window.selectedProduct.productionResults.initialConfig.burstSearchMaxDistance}</li>\r\n          <li><strong>Burst Mark to Perforation:</strong> ${window.selectedProduct.productionResults.initialConfig.burstMarkToPerforation}</li>\r\n          <li><strong>Wide Vault Enabled:</strong> ${window.selectedProduct.productionResults.initialConfig.wideVaultEnabled}</li>\r\n          <li><strong>Design Level:</strong> ${window.selectedProduct.productionResults.initialConfig.designLevel}</li>\r\n          <li><strong>Flash Write Protect:</strong> ${window.selectedProduct.productionResults.initialConfig.flashWriteProtect}</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div style=\"clear:both;\"></div>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 20px;\"></div>\r\n    `;\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Verify configuration and tallies. Is it correct?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(56, 1, 'Find on USB and Print Config (RMA)', 'Find on USB and Print Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will connect via USB either in Printer or VirtualCom mode. Once found, will print config information and then change USB to print device mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    const usbResponse = await determineUsbMode();\r\n    window.selectedProduct.productionResults.initialUsbMode = usbResponse.mode;\r\n    switch (usbResponse.mode) {\r\n      case \'boot\':\r\n        throw new Error(\'Device is in boot mode.\');\r\n      case \'usb\':\r\n        await connectToUsb();\r\n        const usbLanguageResponse = await determineUsbLanguage();\r\n        window.selectedProduct.productionResults.initialLanguage = usbLanguageResponse;\r\n        switch (usbLanguageResponse) {\r\n          case \'acl\':\r\n            await window.genericUSB.sendBytes([0x1F, 0x74, 0x00, 0x01]);\r\n          break;\r\n          case \'a470\':\r\n            await window.genericUSB.sendBytes([0x1B, 0x13]);\r\n          break;\r\n        }\r\n        await disconnectFromUsb();\r\n      break;\r\n      case \'virtualCom\':\r\n        await connectToSerial(usbResponse.printerCom);\r\n        const virtualComLanguageResponse = await determineVirtualComLanguage();\r\n        window.selectedProduct.productionResults.initialLanguage = virtualComLanguageResponse;\r\n\r\n        window.Loading.show({\r\n          message: \'Printing configuration page...\'\r\n        });\r\n\r\n        switch (virtualComLanguageResponse) {\r\n          case \'acl\':\r\n            await window.genericRS232.sendBytes([0x1F, 0x74, 0x00, 0x01]);\r\n            // Wait 18 seconds for print then reconfigure usb\r\n            await new Promise(resolve => setTimeout(resolve, 18000));\r\n            window.Loading.show({\r\n              message: \'Changing config...\'\r\n            });\r\n\r\n            await window.genericRS232.sendBytes([0x10, 0x40]); // Reboot\r\n            await disconnectFromSerial();\r\n            await new Promise(resolve => setTimeout(resolve, 2000));\r\n            await connectToSerial(usbResponse.printerCom);\r\n\r\n            await window.genericRS232.sendBytes([0x1F, 0x02, 0x00, 0x06, 0x02, 0x00, 0x01, 0x00]); // Exit virtual com mode\r\n            // Wait 2 seconds for reconfigure usb\r\n            await new Promise(resolve => setTimeout(resolve, 2000));\r\n            await window.genericRS232.sendBytes([0x10, 0x40]); // Reboot\r\n            await disconnectFromSerial();\r\n          break;\r\n          case \'a470\':\r\n            await window.genericRS232.sendBytes([0x1B, 0x13]);\r\n            // Wait 18 seconds for print then reconfigure usb\r\n            await new Promise(resolve => setTimeout(resolve, 18000));\r\n            window.Loading.show({\r\n              message: \'Changing config...\'\r\n            });\r\n\r\n            await window.genericRS232.sendBytes([0x10, 0x40]); // Reboot\r\n            await disconnectFromSerial();\r\n            await new Promise(resolve => setTimeout(resolve, 2000));\r\n            await connectToSerial(usbResponse.printerCom);\r\n\r\n            await window.genericRS232.sendBytes([0x08, 0x02, 0x00, 0x06, 0x02, 0x00, 0x01, 0x00]); // Exit virtual com mode\r\n            // Wait 2 seconds for reconfigure usb\r\n            await new Promise(resolve => setTimeout(resolve, 2000));\r\n            await window.genericRS232.sendBytes([0x1B, 0x00]); // Reboot\r\n            await disconnectFromSerial();\r\n          break;\r\n        }\r\n        window.Loading.hide();\r\n      break;\r\n    }\r\n    await passTestActions();\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(57, 1, 'Connect To Boot Firmware', 'Connect To Boot Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Please connect USB, serial, cash box, and power. Turn on device and start the test.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    try {\r\n      await connectToUsbInBoot();\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } catch (e) {\r\n      // Change over to boot if possible\r\n      await connectToUsb();\r\n\r\n      // Change to boot mode\r\n      window.Loading.show({\r\n        message: \'Switching to boot mode...\'\r\n      });\r\n      await window.genericUSB.sendBytes([0x1B, 0x5B, 0x7A]);\r\n\r\n      await disconnectFromUsb();\r\n\r\n      // wait for 4 seconds and attempt to reconnect to boot\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsbInBoot();\r\n      await disconnectFromUsb();\r\n\r\n      window.Loading.hide();\r\n      await passTestActions();\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(58, 1, 'Install Main Firmware', 'Install Main Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will install the main firmware onto the device.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsbInBoot();\r\n\r\n    window.Loading.show({\r\n      message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n    });\r\n\r\n    await updateFirmwareFromBootUsb(window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n\r\n    await switchToAclUsb();\r\n\r\n    const readFirmware = await getFirmwareVersionAclUsb();\r\n\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n\r\n    if(window.selectedProduct.productConfig.firmwareVersion == readFirmware) {\r\n      window.selectedProduct.productionResults.firmwareVersion = readFirmware;\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Firmware version does NOT match targetted version.\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Updating configuration and performing reboot\'\r\n    });\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await window.genericUSB.sendBytes([0x10, 0x40]); // Reboot\r\n    await disconnectFromUsb();\r\n    await new Promise(resolve => setTimeout(resolve, 9000));\r\n    window.Loading.hide();\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(60, 1, 'Print On Receipt (USB)', 'Print On Receipt', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print on the receipt paper.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await printLineViaUsb(\"PC Load Letter\", \'center\');\r\n    await window.genericUSB.sendBytes([0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A]);\r\n\r\n    await disconnectFromUsb();\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    // Have user determine if correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did \"PC Load Letter\" print on the receipt paper?\', \'User failed test\');\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(61, 1, 'Switch To Serial', 'Switch To Serial', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will look for device on serial.</p>', 'function findDeviceOnSerial (attemptTimeInSec) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let timeLeft = attemptTimeInSec;\r\n      const attemptInterval = setInterval(async () => {\r\n        timeLeft--;\r\n        window.Loading.show({\r\n          message: \'Please disconnect USB and ensure serial is connected. Looking for device on serial. (\' + timeLeft + \' seconds remaining)\'\r\n        });\r\n\r\n        try {\r\n          let foundDevice = await isPrinterOnSerialAcl();\r\n          if (foundDevice.foundPrinter) {\r\n            clearInterval(attemptInterval);\r\n            window.selectedProduct.comPort = foundDevice.printerCom;\r\n            window.Loading.hide();\r\n            resolve();\r\n          }\r\n        } catch (e) {\r\n          window.Loading.hide();\r\n          clearInterval(attemptInterval);\r\n          reject(e);\r\n        }\r\n\r\n        if (timeLeft <= 0) {\r\n          clearInterval(attemptInterval);\r\n          window.Loading.hide();\r\n          reject(\'Never saw device on serial\')\r\n        }\r\n      }, 1000)\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await findDeviceOnSerial(30);\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(62, 1, 'Print Validation (Serial)', 'Print Validation', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print via validation.</p>', 'function lookForFormTakenSensorChanges (failAfterTimestamp) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPaperInSensor = false;\r\n      let foundPaperRemovedFromSensor = false;\r\n\r\n      let checkInterval = setInterval(async () => {\r\n        let currentTimestamp = new Date().getTime();\r\n        if (currentTimestamp > failAfterTimestamp) {\r\n          clearInterval(checkInterval);\r\n          reject(\'Never found the form taken sensor changes\');\r\n        } else {\r\n          await window.genericRS232.sendBytes([0x10, 0x04, 0x0B]) // Request form taken status\r\n          const response = await window.genericRS232.getBytes(1);\r\n          if (!foundPaperInSensor && (response[0] & 0x20)) {\r\n            foundPaperInSensor = true;\r\n            window.Loading.show({\r\n              message: \'Looking for form to be taken...\'\r\n            });\r\n          } else if (foundPaperInSensor && !(response[0] & 0x20)) {\r\n            foundPaperRemovedFromSensor = true;\r\n          }\r\n\r\n          if (foundPaperInSensor && foundPaperRemovedFromSensor) {\r\n            clearInterval(checkInterval);\r\n            resolve();\r\n          }\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (parseInt(window.selectedProduct.productConfig.hasFormTakenSensor)) {\r\n      // This read should happen before form load, if it thinks a form is already loaded, sensor not working\r\n      await window.genericRS232.sendBytes([0x10, 0x04, 0x0B]) // Request form taken status\r\n      const response = await window.genericRS232.getBytes(1);\r\n      if (response[0] & 0x20) {\r\n        throw new Error(\'Form taken sensor already thinks a form is in its path. Is sensor present?\');\r\n      }\r\n    }\r\n\r\n    await window.genericRS232.sendBytes([0x1B, 0x63, 0x30, 0x08]); // Validation form\r\n    await printLineViaSerial(\'All work and no play\');\r\n    await printLineViaSerial(\'makes Jack a dull boy\');\r\n    await printLineViaSerial(\'All work and no play\');\r\n    await printLineViaSerial(\'makes Jack a dull boy\');\r\n\r\n    await window.genericRS232.sendBytes([0x0C]) // Eject form\r\n\r\n    if (parseInt(window.selectedProduct.productConfig.hasFormTakenSensor)) {\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div style=\"margin-top:30vh\">\r\n          <div class=\"text-h5\">Instructions:</div>\r\n          1. Load Form (will print text and eject)<br/>\r\n          2. Verify clamp opens only after form is removed.<br/>\r\n          3. Verify print quality\r\n        </div>\r\n\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n\r\n      // Get current timestamp and add 15 seconds to it\r\n      const failAfterTimestamp = Date.now() + 15000;\r\n      await lookForFormTakenSensorChanges(failAfterTimestamp);\r\n      window.Loading.hide();\r\n\r\n    } else {\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div style=\"margin-top:30vh\">\r\n          <div class=\"text-h5\">Instructions:</div>\r\n          1. Load Form (will print text and eject)<br/>\r\n          2. Verify print quality\r\n        </div>\r\n\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n    }\r\n    \r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did text properly print on the loaded slip?\', \'User failed test\');\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n      await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(63, 1, 'Cash Drawer (Serial)', 'Cash Drawer', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure the cash drawer port is operating as expected.</p>', 'function lookForCashDrawerSwitchPosition(desiredPosition, failAfterTimestamp, ledMessage) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.Loading.show({\r\n        message: `While looking for the ${ledMessage} LED, please flip the cash drawer switch`\r\n      });\r\n\r\n      let checkInterval = setInterval(async () => {\r\n        let currentTimestamp = new Date().getTime();\r\n        if (currentTimestamp > failAfterTimestamp) {\r\n          clearInterval(checkInterval);\r\n          reject(\'Never saw the cash drawer switch to the desired position\');\r\n        } else {\r\n          // get the current position of the cash drawer switch\r\n          await window.genericRS232.sendBytes([0x10, 0x04, 0x01]);\r\n          const response = await window.genericRS232.getBytes(1);\r\n          if (desiredPosition && (response[0] & 0x04)) {\r\n            clearInterval(checkInterval);\r\n            resolve();\r\n          } else if (!desiredPosition && !(response[0] & 0x04)) {\r\n            clearInterval(checkInterval);\r\n            resolve();\r\n          }\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Determine switch position\r\n    await window.genericRS232.sendBytes([0x10, 0x04, 0x01]);\r\n    const response = await window.genericRS232.getBytes(1);\r\n    let targetPosition = response[0] & 0x04 ? 0 : 1;\r\n\r\n    // Get current timestamp and add 15 seconds to it\r\n    let failAfterTimestamp = Date.now() + 15000;\r\n    await lookForCashDrawerSwitchPosition(targetPosition, failAfterTimestamp, \'RED\');\r\n\r\n    // Blink the red LED\r\n    await window.genericRS232.sendBytes([0x10, 0x14, 0x00, 0x0A, 0x0A]);\r\n\r\n    // Look for switch to change position\r\n    failAfterTimestamp = Date.now() + 15000;\r\n    await lookForCashDrawerSwitchPosition(targetPosition ? 0 : 1, failAfterTimestamp, \'GREEN\');\r\n\r\n    // Blink the green LED\r\n    await window.genericRS232.sendBytes([0x10, 0x14, 0x01, 0x0A, 0x0A]);\r\n    window.Loading.hide();\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did both LEDs blink?\', \'User failed test\');\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n      await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(64, 1, 'Scan Board Barcode', 'Scan Board Barcode', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will associate the barcode scanned with the test results.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please scan the board barcode.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              const regex = /^[0-9]{6}$/;\r\n              return value.length === 6 && regex.test(value);\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get barcode\r\n    const barcode = await getBarcode();\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      window.selectedProduct.productionResults.boardSerialNum = barcode;\r\n\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              tertiarySerialNum: barcode,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              tertiarySerialNum: barcode,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests` (`testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(65, 1, 'Connect and Switch to ACL w/Cash Drawer', 'Connect and Switch to ACL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Please connect the serial, USB, and cash drawer tester to the printer. Ensure button on USB hub to corresponding printer is in the depressed state. Turn on printer. Click \"Start Test\" in the lower right corner of the screen.</p>', 'function switchUsb () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await connectToUsb();\r\n      const usbLanguageResponse = await determineUsbLanguage();\r\n      window.selectedProduct.productionResults.initialLanguage = usbLanguageResponse;\r\n      if (usbLanguageResponse == \'a470\') {\r\n        await switchToAclUsb();\r\n      }\r\n      await disconnectFromUsb();\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// ------------------------------------------------ //\r\nfunction attemptSwitch () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const usbResponse = await determineUsbMode();\r\n      window.selectedProduct.productionResults.initialUsbMode = usbResponse.mode;\r\n      switch (usbResponse.mode) {\r\n        case \'boot\':\r\n          window.Loading.show({\r\n            message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n          });\r\n      \r\n          await updateFirmwareFromBootUsb(window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n          window.Loading.hide();\r\n          await attemptSwitch();\r\n          break;\r\n        case \'usb\':\r\n          await switchUsb();\r\n        break;\r\n        case \'virtualCom\':\r\n          await connectToSerial(usbResponse.printerCom);\r\n          const virtualComLanguageResponse = await determineVirtualComLanguage();\r\n          window.selectedProduct.productionResults.initialLanguage = virtualComLanguageResponse;\r\n\r\n          window.Loading.show({\r\n            message: \'Exiting VirtualCom mode...\'\r\n          });\r\n\r\n          switch (virtualComLanguageResponse) {\r\n            case \'acl\':\r\n              await window.genericRS232.sendBytes([0x1F, 0x02, 0x00, 0x06, 0x02, 0x00, 0x01, 0x00]); // Exit virtual com mode\r\n              // Wait 2 seconds for reconfigure usb\r\n              await new Promise(resolve => setTimeout(resolve, 2000));\r\n              await window.genericRS232.sendBytes([0x10, 0x40]); // Reboot\r\n              await disconnectFromSerial();\r\n              await new Promise(resolve => setTimeout(resolve, 9000));\r\n            break;\r\n            case \'a470\':\r\n              await window.genericRS232.sendBytes([0x08, 0x02, 0x00, 0x06, 0x02, 0x00, 0x01, 0x00]); // Exit virtual com mode\r\n              // Wait 2 seconds for reconfigure usb\r\n              await new Promise(resolve => setTimeout(resolve, 2000));\r\n              await window.genericRS232.sendBytes([0x1B, 0x00]); // Reboot\r\n              await disconnectFromSerial();\r\n              await new Promise(resolve => setTimeout(resolve, 9000));\r\n              await switchUsb();\r\n            break;\r\n          }\r\n          window.Loading.hide();\r\n        break;\r\n      }\r\n      resolve();\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// ------------------------------------------------ //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await attemptSwitch();\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(66, 1, 'Update Firmware', 'Update Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will check if firmware version matches TLA. If it does NOT match, will perform a firmware update.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Check current version against desired version\r\n    const currentVersion = await getFirmwareVersionAclUsb();\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      window.selectedProduct.productionResults.reportedFirmware = currentVersion;\r\n    }\r\n\r\n    if(currentVersion == window.selectedProduct.productConfig.firmwareVersion) {\r\n      // Update not needed\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.finalFirmware = currentVersion;\r\n      }\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } else {\r\n      // Update needed\r\n      window.Loading.show({\r\n        message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n      });\r\n\r\n      // Enter boot mode\r\n      await window.genericUSB.sendBytes([0x1B, 0x5B, 0x7A]);\r\n      await disconnectFromUsb();\r\n      // wait for 4 seconds and attempt to reconnect to boot\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsbInBoot();\r\n\r\n      await updateFirmwareFromBootUsb (window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n      await disconnectFromUsb();\r\n\r\n      // wait for 9 seconds and attempt to reconnect to main\r\n      await new Promise(resolve => setTimeout(resolve, 9000));\r\n      await connectToUsb();\r\n\r\n      // Check new version against desired version\r\n      const newVersion = await getFirmwareVersionAclUsb();\r\n      await disconnectFromUsb();\r\n\r\n      window.Loading.hide();\r\n\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.finalFirmware = newVersion;\r\n      }\r\n\r\n      if(currentVersion == window.selectedProduct.productConfig.firmwareVersion) {\r\n        await passTestActions();\r\n      } else {\r\n        await failTestActions(\'Firmware update failed.\');\r\n      }\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(67, 1, 'Load Cart and Paper', 'Load Cart and Paper', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Monitors sensors while user loads paper and ink cart.</p>', 'function checkDoorAndPaperSensors (timeoutValue) {\r\n  return new Promise (async (resolve, reject) => {\r\n    try {\r\n      let coverOpenFound = false;\r\n      let coverClosedFound = false;\r\n      let paperOutFound = false;\r\n      let paperInFound = false;\r\n\r\n      while (new Date().getTime() < timeoutValue && (!coverOpenFound || !coverClosedFound || !paperOutFound || !paperInFound)) {\r\n        // read sensors\r\n        const coverResponse = await window.genericUSB.sendAndReceiveBytes([0x10, 0x04, 0x02], 1);\r\n        if (coverResponse[0] & 0x04) {\r\n          coverOpenFound = true;\r\n        } else if (coverOpenFound) {\r\n          coverClosedFound = true;\r\n        }\r\n\r\n        const paperResponse = await window.genericUSB.sendAndReceiveBytes([0x10, 0x04, 0x04], 1);\r\n        if (paperResponse[0] & 0x20) {\r\n          paperOutFound = true;\r\n        } else if (paperOutFound) {\r\n          paperInFound = true;\r\n        }\r\n\r\n        // Wait 300 ms\r\n        await new Promise(resolve => setTimeout(resolve, 300));\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Please load ink cart and paper roll; if loading ribbon, verify that the ribbon moves.\'\r\n    });\r\n\r\n    await checkDoorAndPaperSensors(new Date().getTime() + 15000);\r\n    \r\n    await disconnectFromUsb();\r\n\r\n    // Wait for door close operations\r\n    await new Promise(resolve => setTimeout(resolve, 2000));\r\n\r\n    window.Loading.hide();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(68, 1, 'Perform Alignment', 'Perform Alignment', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Performs character alignment test.</p>', 'function printAlignmentSamples (startAlignment, endAlignment) {\r\n  return new Promise (async (resolve, reject) => {\r\n    try {\r\n      let curAlignment = startAlignment;\r\n\r\n      while (curAlignment <= endAlignment) {\r\n        // Configure carriage column alignment\r\n        await configureCarriageColumnAlignmentUsb(curAlignment);\r\n\r\n        // Print a sample of each alignment\r\n        await printLineViaUsb(curAlignment.toString(), \'center\');\r\n        await printLineViaUsb(\'| | | | | | | | | | | | | | | | | | | |\', \'center\');\r\n        await printLineViaUsb(\'| | | | | | | | | | | | | | | | | | | |\', \'center\');\r\n        await printLineViaUsb(\'| | | | | | | | | | | | | | | | | | | |\', \'center\');\r\n        \r\n        curAlignment++;\r\n\r\n        // Wait 2.5sec\r\n        await new Promise(resolve => setTimeout(resolve, 2500));\r\n      }\r\n\r\n      // Feed the paper out some\r\n      await window.genericUSB.sendBytes([0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A, 0x0A]);\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction setAlignment (alignment) {\r\n  return new Promise (async (resolve, reject) => {\r\n    try {\r\n      // Hide form\r\n      document.getElementById(\'testWrapper\').innerHTML =\'\';\r\n\r\n      // Configure carriage column alignment\r\n      await configureCarriageColumnAlignmentUsb(alignment);\r\n\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.carriageColumnAlignment = alignment;\r\n      }\r\n\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Printing Alignment Samples...\'\r\n    });\r\n\r\n    await printAlignmentSamples(5, 8);\r\n    \r\n    window.Loading.hide();\r\n\r\n    // Show form for user to select appropriate alignment\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div class=\"text-h5\">Please Select Best Alignment</div>\r\n      <div style=\"text-align: center; margin-top: 20px;\">\r\n        <button style=\"padding:5px 20px; margin:0 5px;\" onclick=\"setAlignment(5)\">5</button>\r\n        <button style=\"padding:5px 20px; margin:0 5px;\" onclick=\"setAlignment(6)\">6</button>\r\n        <button style=\"padding:5px 20px; margin:0 5px;\" onclick=\"setAlignment(7)\">7</button>\r\n        <button style=\"padding:5px 20px; margin:0 5px;\" onclick=\"setAlignment(8)\">8</button>\r\n      </div>\r\n    `;\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(69, 1, 'Switch To USB', 'Switch To USB', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will look for device on USB.</p>', 'function findDeviceOnUsb (attemptTimeInSec) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let timeLeft = attemptTimeInSec;\r\n      const attemptInterval = setInterval(async () => {\r\n        timeLeft--;\r\n        window.Loading.show({\r\n          message: \'Please reconnect USB. Looking for device on USB. (\' + timeLeft + \' seconds remaining)\'\r\n        });\r\n\r\n        try {\r\n          await connectToUsb();\r\n          await disconnectFromUsb();\r\n          clearInterval(attemptInterval);\r\n          window.Loading.hide();\r\n          resolve();\r\n        } catch (e) {\r\n          // Do nothing to try again\r\n        }\r\n\r\n        if (timeLeft <= 0) {\r\n          clearInterval(attemptInterval);\r\n          window.Loading.hide();\r\n          reject(\'Never saw device on USB\')\r\n        }\r\n      }, 1000)\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await findDeviceOnUsb(30);\r\n    await passTestActions();\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(70, 1, 'Configure Printer For TLA', 'Configure Printer For TLA', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will configure the printer to match the TLA config.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Rebooting Device...\'\r\n    });\r\n\r\n    await rebootAclUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Resetting EEPROM...\'\r\n    });\r\n\r\n    await window.genericUSB.sendBytes([0x1F, 0x7D, 0x01, 0xED, 0x00]); // Reset EEPROM\r\n\r\n    // Wait 12 seconds for device to reset EEPROM\r\n    await new Promise(resolve => setTimeout(resolve, 12000));\r\n\r\n    window.Loading.show({\r\n      message: \'Rebooting Device...\'\r\n    });\r\n\r\n    await rebootAclUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Configuring Device...\'\r\n    });\r\n\r\n    await configCarriageReturnUsage(parseInt(window.selectedProduct.productConfig.carriageReturnUsage));\r\n    await configSoftFaultRecovery(parseInt(window.selectedProduct.productConfig.softFaultRecovery));\r\n    await configDefaultFont(parseInt(window.selectedProduct.productConfig.font));\r\n    await configDefaultFontQuality(parseInt(window.selectedProduct.productConfig.fontQuality));\r\n    await configDefaultInternationalCharacterSubstitution(parseInt(window.selectedProduct.productConfig.internationalCharacterSet));\r\n    await configDefaultFontLarge(parseInt(window.selectedProduct.productConfig.defaultToFontLarge));\r\n    await configDefaultCodePage(parseInt(window.selectedProduct.productConfig.codePage));\r\n    await configDefaultLpi(parseInt(window.selectedProduct.productConfig.journalLinesPerInch) | parseInt(window.selectedProduct.productConfig.validationLinesPerInch));\r\n    await configCommunications(\r\n      parseInt(window.selectedProduct.productConfig.serialBaud), \r\n      parseInt(window.selectedProduct.productConfig.serialStopBits), \r\n      parseInt(window.selectedProduct.productConfig.serialParityType), \r\n      parseInt(window.selectedProduct.productConfig.serialParity), \r\n      parseInt(window.selectedProduct.productConfig.serialFlowControl), \r\n      parseInt(window.selectedProduct.productConfig.usbDriverClass), \r\n      parseInt(window.selectedProduct.productConfig.usbDescriptor), \r\n      parseInt(window.selectedProduct.productConfig.usbDeviceIdEnabled)\r\n    );\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(parseInt(window.selectedProduct.productConfig.formInsertWaitTime));\r\n    await configDefaultClampDelay(parseInt(window.selectedProduct.productConfig.clampDelay));\r\n    await configWidePrintField(parseInt(window.selectedProduct.productConfig.widePrintFieldEnabled));\r\n    await configInkjetDotCountReset(parseInt(window.selectedProduct.productConfig.inkjetDotResetMode));\r\n    await configVirtualDocumentStop(parseInt(window.selectedProduct.productConfig.virtualDocumentStop));\r\n\r\n    if (parseInt(window.selectedProduct.productConfig.printerControlLanguage) == 1) {\r\n      // A470 Mode, switch and program\r\n      window.Loading.show({\r\n        message: \'Switching to A470...\'\r\n      });\r\n      await switchToA470Usb();\r\n\r\n      window.Loading.show({\r\n        message: \'Configuring A470...\'\r\n      });\r\n\r\n      // Configure A470\r\n      // Determine if standard USB or VitualCom\r\n      if (parseInt(window.selectedProduct.productConfig.usbDriverClass) == 2) {\r\n        // VirtualCom\r\n        await connectToVirtualCom();\r\n        await configA470ClampDefaultSerial(parseInt(window.selectedProduct.productConfig.a470ClampDefault));\r\n        await configA470PitchDefaultSerial(parseInt(window.selectedProduct.productConfig.a470DefaultPitch));\r\n      } else {\r\n        // Standard USB\r\n        await connectToUsb();\r\n        await configA470ClampDefault(parseInt(window.selectedProduct.productConfig.a470ClampDefault));\r\n        await configA470PitchDefault(parseInt(window.selectedProduct.productConfig.a470DefaultPitch));\r\n        await disconnectFromUsb();\r\n      }\r\n\r\n    } else if (parseInt(window.selectedProduct.productConfig.printerControlLanguage) == 4) {\r\n      // Sub Mode 3, switch to it\r\n      window.Loading.show({\r\n        message: \'Switching to Sub Mode 3...\'\r\n      });\r\n      await switchToSubMode3Usb();\r\n    } else {\r\n      await disconnectFromUsb();\r\n    }\r\n    \r\n    window.Loading.hide();\r\n    \r\n    // Save config used\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      window.selectedProduct.productionResults.configUsed = window.selectedProduct.productConfig;\r\n    }\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(71, 1, 'Verify Printer Config', 'Verify Printer Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will have the tester verify that the configuration is correct.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div class=\"text-h5\">Instructions:</div>\r\n      <p>Please disconnect printer from computer and print out the configuration using the One-Button method and verify it matches the TLA and the Tallies are reset.</p>\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is the configuration correct with tallies reset?\', \'User failed test\');\r\n  } catch (err) {\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(72, 1, 'Close Up', 'Close Up', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will collect the bottom barcode, program serial number, and collect any tester notes.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please attach the barcode label to the bottom of the unit and then scan the serial number.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              const regex = /^[0-9]{8}$/;\r\n              return value.length === 8 && regex.test(value);\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function getTesterNotes() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Tester Notes\',\r\n        message: \'Please enter any notes about the unit being tested.\',\r\n        prompt: {\r\n          type: \'textarea\'\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled tester notes prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction programSerialNumber(serialNumber) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Determine USB driver class\r\n      if (parseInt(window.selectedProduct.productConfig.usbDriverClass) === 0) {\r\n        // Print driver\r\n        await connectToUsb();\r\n\r\n        // Determine PCL\r\n        if (parseInt(window.selectedProduct.productConfig.printerControlLanguage) === 1) {\r\n          // A470 Print Driver\r\n          await window.genericUSB.sendBytes([0x08, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericUSB.sendAndReceiveBytes([0x08, 0x49, 0x44], 10); // Get serial number back\r\n          if (rawBytes[0] === 0x20 && rawBytes[1] === 0x20 && rawBytes[2] === serialNumber.charCodeAt(0) && rawBytes[3] === serialNumber.charCodeAt(1) && rawBytes[4] === serialNumber.charCodeAt(2) && rawBytes[5] === serialNumber.charCodeAt(3) && rawBytes[6] === serialNumber.charCodeAt(4) && rawBytes[7] === serialNumber.charCodeAt(5) && rawBytes[8] === serialNumber.charCodeAt(6) && rawBytes[9] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        } else {\r\n          // ACL Print Driver\r\n          await window.genericUSB.sendBytes([0x1D, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericUSB.sendAndReceiveBytes([0x1D, 0x49, 0x23], 12); // Get serial number back\r\n          if (rawBytes[1] === 0x20 && rawBytes[2] === 0x20 && rawBytes[3] === serialNumber.charCodeAt(0) && rawBytes[4] === serialNumber.charCodeAt(1) && rawBytes[5] === serialNumber.charCodeAt(2) && rawBytes[6] === serialNumber.charCodeAt(3) && rawBytes[7] === serialNumber.charCodeAt(4) && rawBytes[8] === serialNumber.charCodeAt(5) && rawBytes[9] === serialNumber.charCodeAt(6) && rawBytes[10] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        }\r\n\r\n        await disconnectFromUsb();\r\n      } else {\r\n        // VirtualCom driver\r\n        await connectToVirtualCom();\r\n\r\n        // Determine PCL\r\n        if (parseInt(window.selectedProduct.productConfig.printerControlLanguage) === 1) {\r\n          // A470 VirtualCom\r\n          await window.genericRS232.sendBytes([0x08, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericRS232.sendAndReceiveBytes([0x08, 0x49, 0x44], 10); // Get serial number back\r\n          if (rawBytes[0] === 0x20 && rawBytes[1] === 0x20 && rawBytes[2] === serialNumber.charCodeAt(0) && rawBytes[3] === serialNumber.charCodeAt(1) && rawBytes[4] === serialNumber.charCodeAt(2) && rawBytes[5] === serialNumber.charCodeAt(3) && rawBytes[6] === serialNumber.charCodeAt(4) && rawBytes[7] === serialNumber.charCodeAt(5) && rawBytes[8] === serialNumber.charCodeAt(6) && rawBytes[9] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        } else {\r\n          // ACL VirtualCom\r\n          await window.genericRS232.sendBytes([0x1D, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericRS232.sendAndReceiveBytes([0x1D, 0x49, 0x23], 12); // Get serial number back\r\n          if (rawBytes[1] === 0x20 && rawBytes[2] === 0x20 && rawBytes[3] === serialNumber.charCodeAt(0) && rawBytes[4] === serialNumber.charCodeAt(1) && rawBytes[5] === serialNumber.charCodeAt(2) && rawBytes[6] === serialNumber.charCodeAt(3) && rawBytes[7] === serialNumber.charCodeAt(4) && rawBytes[8] === serialNumber.charCodeAt(5) && rawBytes[9] === serialNumber.charCodeAt(6) && rawBytes[10] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        }\r\n      }\r\n\r\n      // Get tester notes\r\n      window.selectedProduct.productionResults.testerNotes = await getTesterNotes();\r\n\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        // Update results\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                primarySerialNum: serialNumber,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tla: window.selectedProduct.productConfig.tla\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                primarySerialNum: serialNumber,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tla: window.selectedProduct.productConfig.tla\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n    } catch (e) {\r\n      if (parseInt(window.selectedProduct.productConfig.usbDriverClass) === 0) {\r\n        // Disconnect USB\r\n        await disconnectFromUsb();\r\n      }\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get bottom serial number\r\n    const serialNumber = await getBarcode();\r\n\r\n    // Prompt user to turn unit back on w/USB to program serial number\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div class=\"text-h5\">Instructions:</div>\r\n      <p>Please connect printer to computer via USB and ensure printer is turned on; then click \"Program Serial Number on Unit\" below.</p>\r\n      <div style=\"text-align: center; margin-top: 20px;\">\r\n        <button style=\"padding:5px 20px; margin:0 5px;\" onclick=\"programSerialNumber(\'${serialNumber}\')\">Program Serial Number on Unit</button>\r\n      </div>\r\n    `;\r\n  } catch (err) {\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(73, 3, 'Configure For Board Test (AD Shading)', 'Configure For Board Test', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will set the hardware and software configuration in the device. At this stage the population specific config for the PCBA is set. A generic calibration table will be sent to the device in preparation of scanning documents.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Prepare configs\r\n    const hardwareConfig = [\r\n      1,\r\n      parseInt(window.selectedProduct.productConfig.topCis),\r\n      parseInt(window.selectedProduct.productConfig.bottomCis),\r\n      parseInt(window.selectedProduct.productConfig.hasMicr),\r\n      parseInt(window.selectedProduct.productConfig.hasStamp),\r\n      parseInt(window.selectedProduct.productConfig.hasWatermark),\r\n      0,\r\n      parseInt(window.selectedProduct.productConfig.entrySensorType),\r\n      parseInt(window.selectedProduct.productConfig.midfieldType) | parseInt(window.selectedProduct.productConfig.holtekType) | parseInt(window.selectedProduct.productConfig.stepperType),\r\n      0\r\n    ];\r\n\r\n    const softwareConfig = [\r\n      0,\r\n      parseInt(window.selectedProduct.productConfig.hasEncryption),\r\n      0,\r\n      0,\r\n      0,\r\n      0,\r\n      0,\r\n      0\r\n    ];\r\n\r\n    window.Loading.show({\r\n      message: \'Configuring hardware...\'\r\n    });\r\n\r\n    await window.api6100.openDevice();\r\n    await window.api6100.cortexSetScannerHardware(hardwareConfig);\r\n    await window.api6100.cortexSetScannerSoftware(softwareConfig);\r\n    await window.api6100.cortexSetUSBDescriptorMode(parseInt(window.selectedProduct.productConfig.usbDescriptor));\r\n    await window.api6100.cortexSetSkew(parseInt(window.selectedProduct.productConfig.skewTolerance), parseInt(window.selectedProduct.productConfig.skewReject));\r\n\r\n    // Pull generic shading tables\r\n    await setCalibrationTable(window.selectedProduct.serverUrl + \'uploads/calibrations/pcba-pop1.dat\');\r\n\r\n    await window.api6100.closeDevice();\r\n    window.Loading.hide();\r\n    document.getElementById(\'testWrapper\').innerHTML = \'<p>Configured scanner.</p>\';\r\n    passTestActions();\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    failTestActions(err);\r\n  }\r\n})();', 1),
(74, 1, 'Load Cart (Validation Only)', 'Load Cart', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Monitors sensors while user loads ink cart.</p>', 'function checkDoorSensor (timeoutValue) {\r\n  return new Promise (async (resolve, reject) => {\r\n    try {\r\n      let coverOpenFound = false;\r\n      let coverClosedFound = false;\r\n\r\n      while (new Date().getTime() < timeoutValue && (!coverOpenFound || !coverClosedFound)) {\r\n        // read sensors\r\n        const coverResponse = await window.genericUSB.sendAndReceiveBytes([0x10, 0x04, 0x02], 1);\r\n        if (coverResponse[0] & 0x04) {\r\n          coverOpenFound = true;\r\n        } else if (coverOpenFound) {\r\n          coverClosedFound = true;\r\n        }\r\n\r\n        // Wait 300 ms\r\n        await new Promise(resolve => setTimeout(resolve, 300));\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Please load ink cart; if loading ribbon, verify that the ribbon moves.\'\r\n    });\r\n\r\n    await checkDoorSensor(new Date().getTime() + 15000);\r\n    \r\n    await disconnectFromUsb();\r\n\r\n    // Wait for door close operations\r\n    await new Promise(resolve => setTimeout(resolve, 2000));\r\n\r\n    window.Loading.hide();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(75, 4, 'Tester Notes', 'Tester Notes', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will any notes from the tester.</p>', '// ---------------------------------------------------------- //\r\nasync function getTesterNotes() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Tester Notes\',\r\n        message: \'Please enter any notes about the unit being tested.\',\r\n        prompt: {\r\n          type: \'textarea\'\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled tester notes prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get tester notes\r\n    window.selectedProduct.productionResults.testerNotes = await getTesterNotes();\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              primarySerialNum: serialNumber,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              primarySerialNum: serialNumber,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1);
