(7, '2022-09-28 21:50:06', 1, 3, 'Verify Cortex Device Found', NULL, NULL, '<div class=\"text-h5\">Instructions:</div>\r\n<p>Please connect power and USB to scanner and turn the device on. Then click \"Start Test\" in the lower right corner.</p>', '(async () => {\r\n  try {\r\n    await window.api6100.openDevice();\r\n    const isCortex = await window.api6100.isCortex();\r\n    if (isCortex) {\r\n      console.log(\'good\');\r\n    } else {\r\n      console.log(\'bad\');\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
