(12, '2022-09-28 22:13:15', 2, 3, 'Configure For Board Test', NULL, NULL, 'Config', '(async () => {\r\n  try {\r\n    setStartTime();\r\n    await window.api6100.openDevice();\r\n    await window.api6100.eject(1);\r\n    await window.api6100.closeDevice();\r\n    console.log(getElapsedTime());\r\n    passTestActions();\r\n  } catch (err) {\r\n    failTestActions(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(13, '2022-09-28 22:14:07', 2, 3, 'Configure For Board Test', NULL, NULL, 'Config', '(async () => {\r\n  try {\r\n    setStartTime();\r\n    await window.api6100.openDevice();\r\n    await window.api6100.ejectDocument(1);\r\n    await window.api6100.closeDevice();\r\n    console.log(getElapsedTime());\r\n    passTestActions();\r\n  } catch (err) {\r\n    failTestActions(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
