(86, '2022-10-10 15:39:46', 7, 3, 'Update Firmware Via Calibration Controller', 'Update Firmware', NULL, '', 'async function updateFirmware(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      console.log(\'update\', index);\r\n      const startTime = Date.now();\r\n      const macAdress = await getMacAddress();\r\n\r\n      // Create analytics entry\r\n      const response = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"timings\",\r\n            action: \"setTestTiming\",\r\n            params: {\r\n              timelapsed: Date.now() - startTime,\r\n              productTitle: window.selectedProduct.productTitle,\r\n              selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n              testTitle: \'Update Firmware\',\r\n              testId: 7,\r\n              testerName: window.selectedProduct.testerName,\r\n              testPassed: 1,\r\n              serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n              macAddress: macAdress,\r\n              extAnalyticsProductionId: window.selectedProduct.calibrationClients[index].analyticsProductionId,\r\n              failMsg: \'\'\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    \r\n      if (response.data.message) {\r\n        promptUser(response.data.message);\r\n      }\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
