\n              extAnalyticsProductionId: window.selectedProduct.calibrationClients[index].analyticsProductionId,\r\n              failMsg: error,\r\n              customError: \'\'\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    \r\n      if (response.data.message) {\r\n        promptUser(response.data.message);\r\n      }\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(95, '2022-10-11 01:01:40', 7, 3, 'Update Firmware Via Calibration Controller', 'Update Firmware', NULL, '', 'async function getCurrentFirmwareVersion(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'firmwareVersion\' }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to get current firmware version. Error Code: \' + response.success);\r\n        } else {\r\n          if (response.firmware !== window.selectedProduct.productConfig.firmwareVersion) {\r\n            // Firmware version is not up to date\r\n            const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n            clientStatus.innerHTML = \'Firmware Updating To: \' + window.selectedProduct.productConfig.firmwareVersion;\r\n            clientStatus.style.display = \'block\';\r\n\r\n            // Update firmware\r\n            window.messenger.request(index, \'scannerRequest\', { mode: \'firmwareUpdate\', url: window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware, md5: window.selectedProduct.productConfig.firmwareMd5 }, async response => {\r\n              clientStatus.style.display = \'none\';\r\n              if (response.success) {\r\n                reject(\'Failed to update firmware. Error Code: \' + response.success);\r\n              } else {\r\n                setTimeout(async () => {\r\n                  resolve();\r\n                }, 6000);\r\n              }\r\n            });\r\n          } else {\r\n            resolve();\r\n          }\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function updateFirmware(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n    const macAdress = await getMacAddress();\r\n\r\n    try {\r\n      // Get device\'s current version\r\n      let currentVersion = await getCurrentFirmwareVersion(index);\r\n\r\n      // Create analytics entry\r\n      const response = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"timings\",\r\n            action: \"setTestTiming\",\r\n            params: {\r\n              timelapsed: Date.now() - startTime,\r\n              productTitle: window.selectedProduct.productTitle,\r\n              selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n              testTitle: \'Update Firmware\',\r\n              testId: 7,\r\n              testerName: window.selectedProduct.testerName,\r\n              testPassed: 1,\r\n              serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n              macAddress: macAdress,\r\n              extAnalyticsProductionId: window.selectedProduct.calibrationClients[index].analyticsProductionId,\r\n              failMsg: \'\',\r\n              customError: \'\'\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    \r\n      if (response.data.message) {\r\n        promptUser(response.data.message);\r\n      }\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      const response = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"timings\",\r\n            action: \"setTestTiming\",\r\n            params: {\r\n              timelapsed: Date.now() - startTime,\r\n              productTitle: window.selectedProduct.productTitle,\r\n              selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n              testTitle: \'Update Firmware\',\r\n              testId: 7,\r\n              testerName: window.selectedProduct.testerName,\r\n              testPassed: 0,\r\n              serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n              macAddress: macAdress,\r\n              extAnalyticsProductionId: window.selectedProduct.calibrationClients[index].analyticsProductionId,\r\n              failMsg: error,\r\n              customError: \'\'\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    \r\n      if (response.data.message) {\r\n        promptUser(response.data.message);\r\n      }\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
