(102, '2022-10-11 02:21:27', 9, 3, 'Calibrate Via Calibration Controller', 'Calibrate', NULL, '', 'async function calibrate (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n    try {\r\n      clientStatus.innerHTML = \'Calibrating: Load Sheet\';\r\n      clientStatus.style.display = \'block\';\r\n\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'calibrate\' }, async response => {\r\n        clientStatus.style.display = \'none\';\r\n        if (response.success) {\r\n          // Get advanced error\r\n\r\n\r\n\r\n          reject(\'Failed to calibrate. Error Code: \' + response.success);\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      clientStatus.style.display = \'none\';\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function analyticsEntry (timelapsed, testPassed, extAnalyticsProductionId, error) {\r\n  const macAdress = await getMacAddress();\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: timelapsed,\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n          testTitle: \'Calibrate\',\r\n          testId: 9,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: error,\r\n          customError: \'\'\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startCalibration(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n\r\n    try {\r\n      await calibrate(index);\r\n\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 1, window.selectedProduct.calibrationClients[index].analyticsProductionId, \'\');\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 0, window.selectedProduct.calibrationClients[index].analyticsProductionId, error);\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(103, '2022-10-11 14:48:48', 9, 3, 'Calibrate Via Calibration Controller', 'Calibrate', NULL, '', 'async function calibrate (index) {\r\n  const advancedErrorCodes = {\r\n    0: \'No Detailed Error\',\r\n    1: \'Bad CIS Signal (verify connectivity to both CIS)\',\r\n    2: \'Upper Deck CIS Failed (calibrating red)\',\r\n    3: \'Lower Deck CIS Failed (calibrating red)\',\r\n    4: \'Upper Deck CIS Failed (calibrating green)\',\r\n    5: \'Lower Deck CIS Failed (calibrating green)\',\r\n    6: \'Upper Deck CIS Failed (calibrating blue)\',\r\n    7: \'Lower Deck CIS Failed (calibrating blue)\',\r\n    8: \'Upper Deck CIS Failed (calibrating uv)\',\r\n    9: \'Lower Deck CIS Failed (calibrating uv)\',\r\n    10: \'Upper Deck CIS Failed (calibrating ir)\',\r\n    11: \'Lower Deck CIS Failed (calibrating ir)\',\r\n    12: \'Upper Deck CIS Failed (calibrating watermark)\',\r\n    13: \'Lower Deck CIS Failed (calibrating watermark)\',\r\n    14: \'Upper Deck CIS Failed (calibrating grayscale)\',\r\n    15: \'Lower Deck CIS Failed (calibrating grayscale)\',\r\n    16: \'Corrupted Image During Calibration\',\r\n    17: \'Failed UV Calibration\',\r\n  }\r\n\r\n  return new Promise(async (resolve, reject) => {\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n    try {\r\n      clientStatus.innerHTML = \'Calibrating: Load Sheet\';\r\n      clientStatus.style.display = \'block\';\r\n\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'calibrate\' }, async response => {\r\n        clientStatus.style.display = \'none\';\r\n        if (response.success) {\r\n          if (response.success === 19) {\r\n            reject(\'Failed to calibrate: Never saw paper loaded\');\r\n          }\r\n\r\n          // Get advanced error\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'getAdvancedError\' }, async response => {\r\n            reject(\'Failed to calibrate. Error Code: \' + advancedErrorCodes[response.success]);\r\n          });\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      clientStatus.style.display = \'none\';\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function collectCalibrationData (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'collectCalibrationData\', productionId: window.selectedProduct.calibrationClients[index].productionId, serverUrl: window.selectedProduct.serverUrl }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to collect calibration data\');\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function analyticsEntry (timelapsed, testPassed, extAnalyticsProductionId, error) {\r\n  const macAdress = await getMacAddress();\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: timelapsed,\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n          testTitle: \'Calibrate\',\r\n          testId: 9,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: error,\r\n          customError: \'\'\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startCalibration(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n\r\n    try {\r\n      await calibrate(index);\r\n      await collectCalibrationData(index);\r\n\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 1, window.selectedProduct.calibrationClients[index].analyticsProductionId, \'\');\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 0, window.selectedProduct.calibrationClients[index].analyticsProductionId, error);\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1);
INSERT INTO `prod_v2_tests_archive` (`archiveId`, `generatedDateTime`, `testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(104, '2022-10-11 15:11:06', 9, 3, 'Calibrate Via Calibration Controller', 'Calibrate', NULL, '', 'async function calibrate (index) {\r\n  const advancedErrorCodes = {\r\n    0: \'No Detailed Error\',\r\n    1: \'Bad CIS Signal (verify connectivity to both CIS)\',\r\n    2: \'Upper Deck CIS Failed (calibrating red)\',\r\n    3: \'Lower Deck CIS Failed (calibrating red)\',\r\n    4: \'Upper Deck CIS Failed (calibrating green)\',\r\n    5: \'Lower Deck CIS Failed (calibrating green)\',\r\n    6: \'Upper Deck CIS Failed (calibrating blue)\',\r\n    7: \'Lower Deck CIS Failed (calibrating blue)\',\r\n    8: \'Upper Deck CIS Failed (calibrating uv)\',\r\n    9: \'Lower Deck CIS Failed (calibrating uv)\',\r\n    10: \'Upper Deck CIS Failed (calibrating ir)\',\r\n    11: \'Lower Deck CIS Failed (calibrating ir)\',\r\n    12: \'Upper Deck CIS Failed (calibrating watermark)\',\r\n    13: \'Lower Deck CIS Failed (calibrating watermark)\',\r\n    14: \'Upper Deck CIS Failed (calibrating grayscale)\',\r\n    15: \'Lower Deck CIS Failed (calibrating grayscale)\',\r\n    16: \'Corrupted Image During Calibration\',\r\n    17: \'Failed UV Calibration\',\r\n  }\r\n\r\n  return new Promise(async (resolve, reject) => {\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n    try {\r\n      clientStatus.innerHTML = \'Calibrating: Load Sheet\';\r\n      clientStatus.style.display = \'block\';\r\n\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'calibrate\' }, async response => {\r\n        clientStatus.style.display = \'none\';\r\n        if (response.success) {\r\n          if (response.success === 19) {\r\n            reject(\'Failed to calibrate: Never saw paper loaded\');\r\n          }\r\n\r\n          // Get advanced error\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'getAdvancedError\' }, async response => {\r\n            reject(\'Failed to calibrate. Error Code: \' + advancedErrorCodes[response.success]);\r\n          });\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      clientStatus.style.display = \'none\';\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function collectCalibrationData (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'collectCalibrationData\', productionId: window.selectedProduct.calibrationClients[index].productionId, serverUrl: window.selectedProduct.serverUrl }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to collect calibration data\');\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function analyticsEntry (timelapsed, testPassed, extAnalyticsProductionId, error) {\r\n  const macAdress = await getMacAddress();\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: timelapsed,\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n          testTitle: \'Calibrate\',\r\n          testId: 9,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: error,\r\n          customError: \'\'\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startCalibration(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n\r\n    try {\r\n      await calibrate(index);\r\n      await collectCalibrationData(index);\r\n\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 1, window.selectedProduct.calibrationClients[index].analyticsProductionId, \'\');\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 0, window.selectedProduct.calibrationClients[index].analyticsProductionId, error);\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(105, '2022-10-11 16:38:54', 8, 3, 'Configure Hardware Via Calibration Controller', 'Configure Hardware', NULL, '', 'async function setHardware (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const hwCfg = [\r\n        1,\r\n        parseInt(window.selectedProduct.productConfig.topCis),\r\n        parseInt(window.selectedProduct.productConfig.bottomCis),\r\n        parseInt(window.selectedProduct.productConfig.hasMicr),\r\n        parseInt(window.selectedProduct.productConfig.hasStamp),\r\n        parseInt(window.selectedProduct.productConfig.hasWatermark),\r\n        0,\r\n        parseInt(window.selectedProduct.productConfig.entrySensorType),\r\n        0, /* NOTE THIS BYTE IS MAINTAINED FROM THE CURRENT CONFIG BY THE Raspberry PI */\r\n        0\r\n      ];\r\n\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'setHardware\', cfg: hwCfg }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to set hardware. Error Code: \' + response.success);\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function setSoftware (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const swCfg = [\r\n        0,\r\n        parseInt(window.selectedProduct.productConfig.hasEncryption),\r\n        0,\r\n        0,\r\n        0,\r\n        0,\r\n        0,\r\n        0\r\n      ];\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'setSoftware\', cfg: swCfg }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to set software. Error Code: \' + response.success);\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function setTla (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'setTLA\', tla: window.selectedProduct.productConfig.tlaNumber }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to set TLA. Error Code: \' + response.success);\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function analyticsEntryHardware (timelapsed, testPassed, extAnalyticsProductionId, error) {\r\n  const macAdress = await getMacAddress();\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: timelapsed,\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n          testTitle: \'Configure Hardware\',\r\n          testId: 8,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: error,\r\n          customError: \'\'\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function configureHardware(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n\r\n    try {\r\n      await setHardware(index);\r\n      await setSoftware(index);\r\n      await setTla(index);\r\n\r\n      // Create analytics entry\r\n      analyticsEntryHardware (Date.now() - startTime, 1, window.selectedProduct.calibrationClients[index].analyticsProductionId, \'\');\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      analyticsEntryHardware (Date.now() - startTime, 0, window.selectedProduct.calibrationClients[index].analyticsProductionId, error);\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(106, '2022-10-11 16:50:48', 9, 3, 'Calibrate Via Calibration Controller', 'Calibrate', NULL, '', 'async function calibrate (index) {\r\n  const advancedErrorCodes = {\r\n    0: \'No Detailed Error\',\r\n    1: \'Bad CIS Signal (verify connectivity to both CIS)\',\r\n    2: \'Upper Deck CIS Failed (calibrating red)\',\r\n    3: \'Lower Deck CIS Failed (calibrating red)\',\r\n    4: \'Upper Deck CIS Failed (calibrating green)\',\r\n    5: \'Lower Deck CIS Failed (calibrating green)\',\r\n    6: \'Upper Deck CIS Failed (calibrating blue)\',\r\n    7: \'Lower Deck CIS Failed (calibrating blue)\',\r\n    8: \'Upper Deck CIS Failed (calibrating uv)\',\r\n    9: \'Lower Deck CIS Failed (calibrating uv)\',\r\n    10: \'Upper Deck CIS Failed (calibrating ir)\',\r\n    11: \'Lower Deck CIS Failed (calibrating ir)\',\r\n    12: \'Upper Deck CIS Failed (calibrating watermark)\',\r\n    13: \'Lower Deck CIS Failed (calibrating watermark)\',\r\n    14: \'Upper Deck CIS Failed (calibrating grayscale)\',\r\n    15: \'Lower Deck CIS Failed (calibrating grayscale)\',\r\n    16: \'Corrupted Image During Calibration\',\r\n    17: \'Failed UV Calibration\',\r\n  }\r\n\r\n  return new Promise(async (resolve, reject) => {\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n    try {\r\n      clientStatus.innerHTML = \'Calibrating: Load Sheet <div style=\"background-color:#090;\" id=\"progress\' + index + \'\" class=\"progress\"></div><div id=\"progressText\' + index + \'\" class=\"progressText\"></div>\';\r\n      clientStatus.style.display = \'block\';\r\n      window.selectedProduct.calibrationClients[index].progressStart = Date.now();\r\n      window.selectedProduct.calibrationClients[index].progressMax = 120000;\r\n      showProgress(index);\r\n\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'calibrate\' }, async response => {\r\n        clientStatus.style.display = \'none\';\r\n        if (response.success) {\r\n          if (response.success === 19) {\r\n            reject(\'Failed to calibrate: Never saw paper loaded\');\r\n          }\r\n\r\n          // Get advanced error\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'getAdvancedError\' }, async response => {\r\n            reject(\'Failed to calibrate. Error Code: \' + advancedErrorCodes[response.success]);\r\n          });\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      clientStatus.style.display = \'none\';\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showProgress (index) {\r\n  const progressTimer = setInterval(() => {\r\n    const progress = document.getElementById(\'progress\' + index);\r\n    const progressText = document.getElementById(\'progressText\' + index);\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n\r\n    const progressPercent = Math.round((Date.now() - window.selectedProduct.calibrationClients[index].progressStart) / window.selectedProduct.calibrationClients[index].progressMax * 100);\r\n    progress.style.width = progressPercent + \'%\';\r\n    progressText.innerHTML = progressPercent + \'%\';\r\n\r\n    if (progressPercent >= 100) {\r\n      clearInterval(progressTimer);\r\n      clientStatus.innerHTML = \'Calibrating: Complete\';\r\n      clientStatus.style.display = \'block\';\r\n    }\r\n  }, 100);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function collectCalibrationData (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'collectCalibrationData\', productionId: window.selectedProduct.calibrationClients[index].productionId, serverUrl: window.selectedProduct.serverUrl }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to collect calibration data\');\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function analyticsEntry (timelapsed, testPassed, extAnalyticsProductionId, error) {\r\n  const macAdress = await getMacAddress();\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: timelapsed,\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n          testTitle: \'Calibrate\',\r\n          testId: 9,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: error,\r\n          customError: \'\'\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startCalibration(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n\r\n    try {\r\n      await calibrate(index);\r\n      await collectCalibrationData(index);\r\n\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 1, window.selectedProduct.calibrationClients[index].analyticsProductionId, \'\');\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 0, window.selectedProduct.calibrationClients[index].analyticsProductionId, error);\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(107, '2022-10-11 16:54:27', 9, 3, 'Calibrate Via Calibration Controller', 'Calibrate', NULL, '', 'async function calibrate (index) {\r\n  const advancedErrorCodes = {\r\n    0: \'No Detailed Error\',\r\n    1: \'Bad CIS Signal (verify connectivity to both CIS)\',\r\n    2: \'Upper Deck CIS Failed (calibrating red)\',\r\n    3: \'Lower Deck CIS Failed (calibrating red)\',\r\n    4: \'Upper Deck CIS Failed (calibrating green)\',\r\n    5: \'Lower Deck CIS Failed (calibrating green)\',\r\n    6: \'Upper Deck CIS Failed (calibrating blue)\',\r\n    7: \'Lower Deck CIS Failed (calibrating blue)\',\r\n    8: \'Upper Deck CIS Failed (calibrating uv)\',\r\n    9: \'Lower Deck CIS Failed (calibrating uv)\',\r\n    10: \'Upper Deck CIS Failed (calibrating ir)\',\r\n    11: \'Lower Deck CIS Failed (calibrating ir)\',\r\n    12: \'Upper Deck CIS Failed (calibrating watermark)\',\r\n    13: \'Lower Deck CIS Failed (calibrating watermark)\',\r\n    14: \'Upper Deck CIS Failed (calibrating grayscale)\',\r\n    15: \'Lower Deck CIS Failed (calibrating grayscale)\',\r\n    16: \'Corrupted Image During Calibration\',\r\n    17: \'Failed UV Calibration\',\r\n  }\r\n\r\n  return new Promise(async (resolve, reject) => {\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n    try {\r\n      clientStatus.innerHTML = \'Calibrating: Load Sheet <div style=\"background-color:#090;\" id=\"progress\' + index + \'\" class=\"progress\"></div><div id=\"progressText\' + index + \'\" class=\"progressText\"></div>\';\r\n      clientStatus.style.display = \'block\';\r\n      window.selectedProduct.calibrationClients[index].progressStart = Date.now();\r\n      window.selectedProduct.calibrationClients[index].progressMax = 120000;\r\n      showProgress(index);\r\n\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'calibrate\' }, async response => {\r\n        clientStatus.style.display = \'none\';\r\n        if (response.success) {\r\n          if (response.success === 19) {\r\n            reject(\'Failed to calibrate: Never saw paper loaded\');\r\n          }\r\n\r\n          // Get advanced error\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'getAdvancedError\' }, async response => {\r\n            reject(\'Failed to calibrate. Error Code: \' + advancedErrorCodes[response.success]);\r\n          });\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      clientStatus.style.display = \'none\';\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showProgress (index) {\r\n  const progressTimer = setInterval(() => {\r\n    const progress = document.getElementById(\'progress\' + index);\r\n    const progressText = document.getElementById(\'progressText\' + index);\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n\r\n    const progressPercent = Math.round((Date.now() - window.selectedProduct.calibrationClients[index].progressStart) / window.selectedProduct.calibrationClients[index].progressMax * 100);\r\n    progress.style.width = progressPercent + \'%\';\r\n    progressText.innerHTML = progressPercent + \'%\';\r\n\r\n    if (progressPercent >= 100 || window.selectedProduct.calibrationClients[index].inCalibration === false) {\r\n      clearInterval(progressTimer);\r\n      clientStatus.innerHTML = \'Calibrating: Complete\';\r\n      clientStatus.style.display = \'block\';\r\n    }\r\n  }, 100);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function collectCalibrationData (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'collectCalibrationData\', productionId: window.selectedProduct.calibrationClients[index].productionId, serverUrl: window.selectedProduct.serverUrl }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to collect calibration data\');\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function analyticsEntry (timelapsed, testPassed, extAnalyticsProductionId, error) {\r\n  const macAdress = await getMacAddress();\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: timelapsed,\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n          testTitle: \'Calibrate\',\r\n          testId: 9,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: error,\r\n          customError: \'\'\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startCalibration(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n\r\n    try {\r\n      await calibrate(index);\r\n      await collectCalibrationData(index);\r\n\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 1, window.selectedProduct.calibrationClients[index].analyticsProductionId, \'\');\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 0, window.selectedProduct.calibrationClients[index].analyticsProductionId, error);\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(108, '2022-10-11 19:01:23', 9, 3, 'Calibrate Via Calibration Controller', 'Calibrate', NULL, '', 'async function calibrate (index) {\r\n  const advancedErrorCodes = {\r\n    0: \'No Detailed Error\',\r\n    1: \'Bad CIS Signal (verify connectivity to both CIS)\',\r\n    2: \'Upper Deck CIS Failed (calibrating red)\',\r\n    3: \'Lower Deck CIS Failed (calibrating red)\',\r\n    4: \'Upper Deck CIS Failed (calibrating green)\',\r\n    5: \'Lower Deck CIS Failed (calibrating green)\',\r\n    6: \'Upper Deck CIS Failed (calibrating blue)\',\r\n    7: \'Lower Deck CIS Failed (calibrating blue)\',\r\n    8: \'Upper Deck CIS Failed (calibrating uv)\',\r\n    9: \'Lower Deck CIS Failed (calibrating uv)\',\r\n    10: \'Upper Deck CIS Failed (calibrating ir)\',\r\n    11: \'Lower Deck CIS Failed (calibrating ir)\',\r\n    12: \'Upper Deck CIS Failed (calibrating watermark)\',\r\n    13: \'Lower Deck CIS Failed (calibrating watermark)\',\r\n    14: \'Upper Deck CIS Failed (calibrating grayscale)\',\r\n    15: \'Lower Deck CIS Failed (calibrating grayscale)\',\r\n    16: \'Corrupted Image During Calibration\',\r\n    17: \'Failed UV Calibration\',\r\n  }\r\n\r\n  return new Promise(async (resolve, reject) => {\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n    try {\r\n      clientStatus.innerHTML = \'Calibrating: Load Sheet <div style=\"background-color:#090;\" id=\"progress\' + index + \'\" class=\"progress\"></div><div id=\"progressText\' + index + \'\" class=\"progressText\"></div>\';\r\n      clientStatus.style.display = \'block\';\r\n      window.selectedProduct.calibrationClients[index].progressStart = Date.now();\r\n      window.selectedProduct.calibrationClients[index].progressMax = 120000;\r\n      showProgress(index);\r\n\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'calibrate\' }, async response => {\r\n        clientStatus.style.display = \'none\';\r\n        if (response.success) {\r\n          if (response.success === 19) {\r\n            reject(\'Failed to calibrate: Never saw paper loaded\');\r\n          }\r\n\r\n          // Get advanced error\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'getAdvancedError\' }, async response => {\r\n            reject(\'Failed to calibrate. Error Code: \' + advancedErrorCodes[response.success]);\r\n          });\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      clientStatus.style.display = \'none\';\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showProgress (index) {\r\n  const progressTimer = setInterval(() => {\r\n    const progress = document.getElementById(\'progress\' + index);\r\n    const progressText = document.getElementById(\'progressText\' + index);\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n\r\n    const progressPercent = Math.round((Date.now() - window.selectedProduct.calibrationClients[index].progressStart) / window.selectedProduct.calibrationClients[index].progressMax * 100);\r\n    progress.style.width = progressPercent + \'%\';\r\n    progressText.innerHTML = progressPercent + \'%\';\r\n\r\n    if (progressPercent >= 100 || window.selectedProduct.calibrationClients[index].inCalibration === false) {\r\n      clearInterval(progressTimer);\r\n      clientStatus.style.display = \'none\';\r\n    }\r\n  }, 100);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function collectCalibrationData (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'collectCalibrationData\', productionId: window.selectedProduct.calibrationClients[index].productionId, serverUrl: window.selectedProduct.serverUrl }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to collect calibration data\');\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function analyticsEntry (timelapsed, testPassed, extAnalyticsProductionId, error) {\r\n  const macAdress = await getMacAddress();\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: timelapsed,\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n          testTitle: \'Calibrate\',\r\n          testId: 9,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: error,\r\n          customError: \'\'\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startCalibration(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n\r\n    try {\r\n      await calibrate(index);\r\n      await collectCalibrationData(index);\r\n\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 1, window.selectedProduct.calibrationClients[index].analyticsProductionId, \'\');\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 0, window.selectedProduct.calibrationClients[index].analyticsProductionId, error);\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(109, '2022-10-11 19:06:34', 9, 3, 'Calibrate Via Calibration Controller', 'Calibrate', NULL, '', 'async function testSetSelected() {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  if (parseInt(testSetId)) {\r\n\r\n    // Get tests for test set\r\n    response = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestsForTestSet\",\r\n          params: {\r\n            testSetId: testSetId,\r\n          },\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" } }\r\n    );\r\n\r\n    if (response.data.success) {\r\n      window.selectedProduct.tests = response.data.tests;\r\n\r\n      // Create shared scripts for all tests\r\n      for (let i = 0; i < window.selectedProduct.tests.length; i++) {\r\n        // Destroy old test script\r\n        const oldScript = document.getElementById(\'testScript\' + i);\r\n        if (oldScript) {\r\n          oldScript.remove();\r\n        }\r\n\r\n        // Create new test script\r\n        let script = document.createElement(\'script\');\r\n        script.id = \'testScript\' + i;\r\n        script.innerHTML = window.selectedProduct.tests[i].script;\r\n        document.body.appendChild(script);\r\n      }\r\n\r\n      window.gsap.to(\"#clientSegment\", { opacity: 1, duration: 0.3 });\r\n    }\r\n  } else {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startTest (index) {\r\n   // Destroy old test script\r\n   const oldScript = document.getElementById(\'testScript\' + index);\r\n   if (oldScript) {\r\n     oldScript.remove();\r\n   }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function indicateFailure (index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].failedCalibration = true;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function cleanUpPassing(index) {\r\n  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n  window.selectedProduct.calibrationClients[index].passedCalibration = true;\r\n\r\n  // Inform tests server that all tests passed\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  // Inform analytics server that all tests passed\r\n  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"productionTracking\",\r\n        action: \"passProduction\",\r\n        params: {\r\n          productionId: window.selectedProduct.calibrationClients[index].productionId\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function loadTests (index) {\r\n  console.log(\'product\', window.selectedProduct);\r\n  try {\r\n    await updateFirmware(index);\r\n    await configureHardware(index);\r\n    await startCalibration(index);\r\n    await cleanUpPassing(index);\r\n  } catch (err) {\r\n    indicateFailure(index);\r\n    failTest(err);\r\n    console.log(err);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function clientSelected (index) {\r\n  let testSetId = document.getElementById(\"testSetSelect\").value;\r\n  window.selectedProduct.selectedTestSetTitle = document.getElementById(\"testSetSelect\").options[document.getElementById(\"testSetSelect\").selectedIndex].text;\r\n  if (parseInt(testSetId) && window.selectedProduct.calibrationClients[index].connected && window.selectedProduct.calibrationClients[index].scannerOnline && window.selectedProduct.calibrationClients[index].isCortex && !window.selectedProduct.calibrationClients[index].inCalibration) {\r\n\r\n    // Blink unit for prompt for barcode\r\n    window.selectedProduct.calibrationClients[index].passedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].failedCalibration = false;\r\n    window.selectedProduct.calibrationClients[index].inCalibration = true;\r\n    window.selectedProduct.calibrationClients[index].sensorStatus = 0;\r\n    redrawSensorStatus(index);\r\n    window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 2, blinkOptions: 2 }, response => {\r\n      if(response.success) {\r\n        // Any number > 0 is a fail\r\n        failTestActions(\'Setting LED failed, code: \' + response.success);\r\n        window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n      } else {\r\n        window.Dialog.create({\r\n          title: \'Barcode Scan\',\r\n          message: \'Please scan the inner barcode on the scanner with the blinking orange LED.\',\r\n          prompt: {\r\n            type: \'text\',\r\n            isValiid: (value) => {\r\n              return value.length === 6;\r\n            }\r\n          }\r\n        }).onOk(async (value) => {\r\n          const barcode = value;\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, async response => {\r\n            if(response.success) {\r\n              // Any number > 0 is a fail\r\n              failTestActions(\'Setting LED failed, code: \' + response.success);\r\n              window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n            } else {\r\n              // Get product config\r\n              const productCfgResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n                {\r\n                  query: {\r\n                    dataset: \"testSets\",\r\n                    action: \"getProductConfigForTestSet\",\r\n                    params: {\r\n                      testSetId: testSetId\r\n                    }\r\n                  }\r\n                },\r\n                { headers: { \"Content-Type\": \"application/json\" }}\r\n              );\r\n\r\n              // Set product config\r\n              if (productCfgResponse.data.success) {\r\n                window.selectedProduct.productConfig = productCfgResponse.data.productConfig;\r\n\r\n                // Start tracking progress\r\n                const macAdress = await getMacAddress();\r\n                const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n                  {\r\n                    query: {\r\n                      dataset: \"productionTracking\",\r\n                      action: \"createInitialTrackingEntry\",\r\n                      params: {\r\n                        productId: window.selectedProduct.productId,\r\n                        testSetId: testSetId,\r\n                        testerName: window.selectedProduct.testerName,\r\n                        macAddress: macAdress,\r\n                        secondarySerialNum: barcode\r\n                      }\r\n                    }\r\n                  },\r\n                  { headers: { \"Content-Type\": \"application/json\" }}\r\n                );\r\n            \r\n                if (response.data.success) {\r\n                  window.selectedProduct.calibrationClients[index].productionId = response.data.productionId;\r\n\r\n                  // Set up start entry in analytics database\r\n                  const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n                    {\r\n                      query: {\r\n                        dataset: \"productionTracking\",\r\n                        action: \"createInitialTrackingEntry\",\r\n                        params: {\r\n                          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n                          productId: window.selectedProduct.productId,\r\n                          productTitle: window.selectedProduct.productTitle,\r\n                          testSetId: testSetId,\r\n                          testSetTitle: \'Calibration\',\r\n                          testerName: window.selectedProduct.testerName,\r\n                          macAddress: macAdress,\r\n                          productionId: window.selectedProduct.calibrationClients[index].productionId,\r\n                          secondarySerialNum: barcode\r\n                        }\r\n                      }\r\n                    },\r\n                    { headers: { \"Content-Type\": \"application/json\" }}\r\n                  );\r\n\r\n                  if (analyticsResponse.data.success) {\r\n                    window.selectedProduct.calibrationClients[index].analyticsProductionId = analyticsResponse.data.analyticsProductionId;\r\n                  }\r\n\r\n                  // Load test set\r\n                  await loadTests(index);\r\n                } else {\r\n                  failTestActions(\'Getting product config failed, code\');\r\n                  window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n                }\r\n              } else {\r\n                failTestActions(\'Getting product config failed, code\');\r\n                window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n              }\r\n            }\r\n          });\r\n        }).onCancel(() => {\r\n          // Stop blinking\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'controlLEDBlink\', color: 0, blinkOptions: 0 }, response => {});\r\n          window.selectedProduct.calibrationClients[index].inCalibration = false;\r\n        });\r\n      }\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function passTest () {\r\n  console.log(\'passTest\');\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function failTest (err) {\r\n  await promptUser(err);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function redrawSensorStatus (index) {\r\n  let sensorStatus = window.selectedProduct.calibrationClients[index].sensorStatus;\r\n  let sensors = document.getElementById(`clientSensors${index}`);\r\n  sensors.innerHTML = `\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 16 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 16 ? \'visible\' : \'\')}\">Door</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 8 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 8 ? \'visible\' : \'\')}\">Inner Left</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 32 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 32 ? \'visible\' : \'\')}\">Midfield</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 2 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 2 ? \'visible\' : \'\')}\">Inner Right</span></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 4 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 4 ? \'visible\' : \'\')}\">Entry Left</span></div>\r\n    <div class=\"sensorCell\"></div>\r\n    <div class=\"sensorCell ${(sensorStatus & 1 ? \'sensorCellMarked\' : \'\')}\"><span class=\"sensorCellActive ${(sensorStatus & 1 ? \'visible\' : \'\')}\">Entry Right</span></div>\r\n  `;\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function connectionMonitor() {\r\n  const pollingTimer = setInterval(() => {\r\n    if (window.selectedProduct.calibrationClients) {\r\n      window.selectedProduct.calibrationClients.forEach(async (client, index) => {\r\n        if (!client.inCalibration) {\r\n          if (client.readyForCommand) {\r\n            if (client.reconnectCountdown) {\r\n              client.reconnectCountdown--;\r\n            } else {\r\n              client.readyForCommand = false;\r\n              if (!client.responsePending) {\r\n                client.responsePending = true;\r\n\r\n                window.messenger.request(index, \'scannerRequest\', { mode: \'polledStatus\' }, response => {\r\n                  client.responsePending = false;\r\n                  if (response.error === -1) {\r\n                    client.connected = false;\r\n                    client.scannerIsCortex = false;\r\n                    client.scannerOnline = false;\r\n                    client.sensorStatus = 0;\r\n                    client.reconnectCountdown = 5;\r\n                  } else {\r\n                    client.connected = true;\r\n                    client.scannerOnline = response.online;\r\n                    if (response.online) {\r\n                      client.isCortex = response.scannerIsCortex;\r\n                      client.sensorStatus = response.status.ub_sens;\r\n                    } else {\r\n                      client.isCortex = false;\r\n                      client.sensorStatus = 0;\r\n                    }\r\n                  }\r\n\r\n                  //Update UI\r\n                  let bgImg = \'no-connection\';\r\n                  if (client.connected) {\r\n                    if (client.scannerOnline) {\r\n                      if (client.isCortex) {\r\n                        if(client.passedCalibration) {\r\n                          bgImg = \'passed\';\r\n                        } else if (client.failedCalibration) {\r\n                          bgImg = \'failed\';\r\n                        } else {\r\n                          bgImg = \'online\';\r\n                        }\r\n                      } else {\r\n                        bgImg = \'zoran\';\r\n                      }\r\n                    } else {\r\n                      bgImg = \'offline\';\r\n                    }\r\n                  }\r\n\r\n                  let container = document.getElementById(`client${index}`);\r\n                  container.style.backgroundImage = \'url(\' + window.selectedProduct.serverUrl + bgImg + \'.png)\';\r\n\r\n                  redrawSensorStatus(index);\r\n                })\r\n              }\r\n            }\r\n          } else {\r\n              // Attempt connection\r\n              window.messenger.createSpeaker(index, client.ipAddress + \':2600\');\r\n              client.readyForCommand = true;\r\n              client.responsePending = false;\r\n            \r\n          }\r\n        }\r\n      });\r\n    } else {\r\n      clearInterval(pollingTimer);\r\n    }\r\n  }, 300);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    window.gsap.set(\"#clientSegment\", { opacity: 0 });\r\n    window.gsap.to(\"#templateWrapper\", { opacity: 1, duration: 0.3 });\r\n    document.getElementById(\'toolbarSegment\').innerHTML = window.selectedProduct.testerName + \' on \' + window.selectedProduct.productTitle + \' \' + window.selectedProduct.subStageTitle;\r\n\r\n    // Get the list of tests\r\n    const testSetResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"testSets\",\r\n          action: \"getTestSetsForSubStage\",\r\n          params: {\r\n            subStageId: window.selectedProduct.subStageId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (testSetResponse.data.success) {\r\n      let preProcess = \'<select id=\"testSetSelect\" onchange=\"testSetSelected()\"><option value=\"0\">---- Select One ----</option>\';\r\n      for (let i = 0; i < testSetResponse.data.testSets.length; i++) {\r\n        preProcess += \'<option value=\"\' + testSetResponse.data.testSets[i].testSetId + \'\">\' + testSetResponse.data.testSets[i].title + \'</option>\';\r\n      }\r\n      preProcess += \'</select>\';\r\n      document.getElementById(\'testSetSegment\').innerHTML = preProcess;\r\n    }\r\n    \r\n    // Get the clients list\r\n    const clientResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"scanner6100\",\r\n          action: \"getCalibrationClients\",\r\n          params: { }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    if (clientResponse.data.success) {\r\n      window.selectedProduct.calibrationClients = clientResponse.data.clients;\r\n\r\n      // Prepare each client in list for connection control\r\n      for (let i = 0; i < window.selectedProduct.calibrationClients.length; i++) {\r\n        window.selectedProduct.calibrationClients[i].connected = false;\r\n        window.selectedProduct.calibrationClients[i].readyForCommand = false;\r\n        window.selectedProduct.calibrationClients[i].scannerOnline = false;\r\n        window.selectedProduct.calibrationClients[i].isCortex = false;\r\n        window.selectedProduct.calibrationClients[i].sensorStatus = 0;\r\n        window.selectedProduct.calibrationClients[i].inCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].passedCalibration = false;\r\n        window.selectedProduct.calibrationClients[i].failedCalibration = false;\r\n      }\r\n\r\n      let preProcess = \'<div class=\"client\">\';\r\n      for (let i = 0; i < clientResponse.data.clients.length; i++) {\r\n        preProcess += `\r\n          <div class=\"clientItem\" id=\"client${i}\" onclick=\"clientSelected(${i})\" style=\"background-image:url(${window.selectedProduct.serverUrl}uploads/calibration-controller/no-connection.png);\">\r\n            <div class=\"clientTitle\" style=\"background-color:${clientResponse.data.clients[i].color}\">${clientResponse.data.clients[i].title}</div>\r\n            <div class=\"clientSensors\" id=\"clientSensors${i}\"></div>\r\n            <div class=\"clientStatus\" id=\"clientStatus${i}\"></div>\r\n          </div>`;\r\n      }\r\n      preProcess += \'</div>\';\r\n      document.getElementById(\'clientSegment\').innerHTML = preProcess;\r\n\r\n      // Start communications with the clients\r\n      connectionMonitor();\r\n    }\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests_archive` (`archiveId`, `generatedDateTime`, `testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(110, '2022-10-11 19:08:13', 9, 3, 'Calibrate Via Calibration Controller', 'Calibrate', NULL, '', 'async function calibrate (index) {\r\n  const advancedErrorCodes = {\r\n    0: \'No Detailed Error\',\r\n    1: \'Bad CIS Signal (verify connectivity to both CIS)\',\r\n    2: \'Upper Deck CIS Failed (calibrating red)\',\r\n    3: \'Lower Deck CIS Failed (calibrating red)\',\r\n    4: \'Upper Deck CIS Failed (calibrating green)\',\r\n    5: \'Lower Deck CIS Failed (calibrating green)\',\r\n    6: \'Upper Deck CIS Failed (calibrating blue)\',\r\n    7: \'Lower Deck CIS Failed (calibrating blue)\',\r\n    8: \'Upper Deck CIS Failed (calibrating uv)\',\r\n    9: \'Lower Deck CIS Failed (calibrating uv)\',\r\n    10: \'Upper Deck CIS Failed (calibrating ir)\',\r\n    11: \'Lower Deck CIS Failed (calibrating ir)\',\r\n    12: \'Upper Deck CIS Failed (calibrating watermark)\',\r\n    13: \'Lower Deck CIS Failed (calibrating watermark)\',\r\n    14: \'Upper Deck CIS Failed (calibrating grayscale)\',\r\n    15: \'Lower Deck CIS Failed (calibrating grayscale)\',\r\n    16: \'Corrupted Image During Calibration\',\r\n    17: \'Failed UV Calibration\',\r\n  }\r\n\r\n  return new Promise(async (resolve, reject) => {\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n    try {\r\n      clientStatus.innerHTML = \'Calibrating: Load Sheet <div style=\"background-color:#090;\" id=\"progress\' + index + \'\" class=\"progress\"></div><div id=\"progressText\' + index + \'\" class=\"progressText\"></div>\';\r\n      clientStatus.style.display = \'block\';\r\n      window.selectedProduct.calibrationClients[index].progressStart = Date.now();\r\n      window.selectedProduct.calibrationClients[index].progressMax = 120000;\r\n      showProgress(index);\r\n\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'calibrate\' }, async response => {\r\n        clientStatus.style.display = \'none\';\r\n        if (response.success) {\r\n          if (response.success === 19) {\r\n            reject(\'Failed to calibrate: Never saw paper loaded\');\r\n          }\r\n\r\n          // Get advanced error\r\n          window.messenger.request(index, \'scannerRequest\', { mode: \'getAdvancedError\' }, async response => {\r\n            reject(\'Failed to calibrate. Error Code: \' + advancedErrorCodes[response.success]);\r\n          });\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      clientStatus.style.display = \'none\';\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showProgress (index) {\r\n  const progressTimer = setInterval(() => {\r\n    const progress = document.getElementById(\'progress\' + index);\r\n    const progressText = document.getElementById(\'progressText\' + index);\r\n    const clientStatus = document.getElementById(\'clientStatus\' + index)\r\n\r\n    const progressPercent = Math.round((Date.now() - window.selectedProduct.calibrationClients[index].progressStart) / window.selectedProduct.calibrationClients[index].progressMax * 100);\r\n    progress.style.width = progressPercent + \'%\';\r\n    progressText.innerHTML = progressPercent + \'%\';\r\n\r\n    if (progressPercent >= 100 || window.selectedProduct.calibrationClients[index].inCalibration === false) {\r\n      clearInterval(progressTimer);\r\n      clientStatus.style.display = \'none\';\r\n    }\r\n  }, 100);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function collectCalibrationData (index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.messenger.request(index, \'scannerRequest\', { mode: \'collectCalibrationData\', productionId: window.selectedProduct.calibrationClients[index].productionId, serverUrl: window.selectedProduct.serverUrl }, async response => {\r\n        if (response.success) {\r\n          reject(\'Failed to collect calibration data\');\r\n        } else {\r\n          resolve();\r\n        }\r\n      });\r\n    } catch (error) {\r\n      reject(error);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function analyticsEntry (timelapsed, testPassed, extAnalyticsProductionId, error) {\r\n  const macAdress = await getMacAddress();\r\n  const response = await window.axios.post(window.analyticsServer,\r\n    {\r\n      query: {\r\n        dataset: \"timings\",\r\n        action: \"setTestTiming\",\r\n        params: {\r\n          timelapsed: timelapsed,\r\n          productTitle: window.selectedProduct.productTitle,\r\n          selectedTestSetTitle: window.selectedProduct.selectedTestSetTitle,\r\n          testTitle: \'Calibrate\',\r\n          testId: 9,\r\n          testerName: window.selectedProduct.testerName,\r\n          testPassed: testPassed,\r\n          serverFriendlyName: window.selectedProduct.serverFriendlyName,\r\n          macAddress: macAdress,\r\n          extAnalyticsProductionId: extAnalyticsProductionId,\r\n          failMsg: error,\r\n          customError: \'\'\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.message) {\r\n    promptUser(response.data.message);\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function startCalibration(index) {\r\n  return new Promise(async (resolve, reject) => {\r\n    const startTime = Date.now();\r\n\r\n    try {\r\n      await calibrate(index);\r\n      await collectCalibrationData(index);\r\n\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 1, window.selectedProduct.calibrationClients[index].analyticsProductionId, \'\');\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      resolve();\r\n    } catch (error) {\r\n      // Create analytics entry\r\n      analyticsEntry(Date.now() - startTime, 0, window.selectedProduct.calibrationClients[index].analyticsProductionId, error);\r\n\r\n       // Eject document\r\n       window.messenger.request(index, \'scannerRequest\', { mode: \'ejectDocument\', direction: 1 });\r\n\r\n      reject(error);\r\n    }\r\n  });\r\n}', 1),
(111, '2022-10-11 20:11:47', 10, 3, 'Verify Config', 'Verify Config', NULL, '', 'console.log(\'tst\')', 1),
(112, '2022-10-11 20:13:21', 10, 3, 'Verify Config', 'Verify Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify the hardware and software configuration in the device matches the TLA.</p>', 'console.log(\'tst\')', 1),
(113, '2022-10-11 20:18:44', 10, 3, 'Verify Config', 'Verify Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify the hardware and software configuration in the device matches the TLA.</p>', 'async function checkHardware() {\r\n  const deviceHardware = await window.api6100.cortexGetScannerHardware();\r\n  console.log(deviceHardware);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await checkHardware();\r\n    await window.api6100.closeDevice();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(114, '2022-10-11 20:20:11', 10, 3, 'Verify Config', 'Verify Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify the hardware and software configuration in the device matches the TLA.</p>', 'async function checkHardware() {\r\n  const deviceHardware = await window.api6100.cortexGetScannerHardware();\r\n\r\n  console.log(window.selectedProduct);\r\n  console.log(deviceHardware);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await checkHardware();\r\n    await window.api6100.closeDevice();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(115, '2022-10-11 20:49:12', 10, 3, 'Verify Config', 'Verify Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify the hardware and software configuration in the device matches the TLA.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n\r\n    // Check hardware\r\n    const deviceHardware = await window.api6100.cortexGetScannerHardware();\r\n    if (\r\n      deviceHardware[0] !== 1 ||\r\n      deviceHardware[1] !== parseInt(window.selectedProduct.productConfig.topCis) ||\r\n      deviceHardware[2] !== parseInt(window.selectedProduct.productConfig.bottomCis) ||\r\n      deviceHardware[3] !== parseInt(window.selectedProduct.productConfig.hasMicr) ||\r\n      deviceHardware[4] !== parseInt(window.selectedProduct.productConfig.hasStamp) ||\r\n      deviceHardware[5] !== parseInt(window.selectedProduct.productConfig.hasWatermark) ||\r\n      deviceHardware[7] !== parseInt(window.selectedProduct.productConfig.entrySensorType)\r\n    ) {\r\n      throw new Error(\r\n        `The scanner hardware config does not match the selected TLA.`\r\n      );\r\n    }\r\n    \r\n    // Check software\r\n    const deviceSoftware = await window.api6100.cortexGetScannerSoftware();\r\n    if (\r\n      deviceSoftware[1] !== parseInt(window.selectedProduct.productConfig.hasEncryption)\r\n    ) {\r\n      throw new Error(\r\n        `The scanner software config does not match the selected TLA.`\r\n      );\r\n    }\r\n\r\n    // Check firmware\r\n    const firmwareVersion = await getFirmwareVersion();\r\n    if (firmwareVersion !== window.selectedProduct.productConfig.firmwareVersion) {\r\n      throw new Error(\r\n        `The scanner firmware version does not match the selected TLA.`\r\n      );\r\n    }\r\n\r\n    // Set TLA\r\n    await window.api6100.cortexSetTLA(window.selectedProduct.productConfig.tlaNumber);\r\n\r\n    // Set USB Descriptor\r\n    await window.api6100.cortexSetUSBDescriptorMode(parseInt(window.selectedProduct.productConfig.usbDescriptor));\r\n\r\n    // Set Skew Tolerance/Reject\r\n    await window.api6100.cortexSetSkew(parseInt(window.selectedProduct.productConfig.skewTolerance), parseInt(window.selectedProduct.productConfig.skewReject));\r\n\r\n    // Get scanner config\r\n    const scannerConfig = await window.api6100.xfn(0x49);\r\n\r\n    // Update results\r\n    window.selectedProduct.productionResults.deviceHardware = deviceHardware;\r\n    window.selectedProduct.productionResults.deviceSoftware = deviceSoftware;\r\n    window.selectedProduct.productionResults.firmwareVersion = firmwareVersion;\r\n    window.selectedProduct.productionResults.scannerConfig = scannerConfig;\r\n\r\n    await window.api6100.closeDevice();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(116, '2022-10-11 20:51:05', 10, 3, 'Verify Config', 'Verify Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify the hardware and software configuration in the device matches the TLA.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n\r\n    // Check hardware\r\n    const deviceHardware = await window.api6100.cortexGetScannerHardware();\r\n    console.log(\'deviceHardware\', deviceHardware);\r\n    console.log(\'productConfig\', window.selectedProduct.productConfig);\r\n    if (\r\n      deviceHardware[0] !== 1 ||\r\n      deviceHardware[1] !== parseInt(window.selectedProduct.productConfig.topCis) ||\r\n      deviceHardware[2] !== parseInt(window.selectedProduct.productConfig.bottomCis) ||\r\n      deviceHardware[3] !== parseInt(window.selectedProduct.productConfig.hasMicr) ||\r\n      deviceHardware[4] !== parseInt(window.selectedProduct.productConfig.hasStamp) ||\r\n      deviceHardware[5] !== parseInt(window.selectedProduct.productConfig.hasWatermark) ||\r\n      deviceHardware[7] !== parseInt(window.selectedProduct.productConfig.entrySensorType)\r\n    ) {\r\n      throw new Error(\r\n        `The scanner hardware config does not match the selected TLA.`\r\n      );\r\n    }\r\n    \r\n    // Check software\r\n    const deviceSoftware = await window.api6100.cortexGetScannerSoftware();\r\n    if (\r\n      deviceSoftware[1] !== parseInt(window.selectedProduct.productConfig.hasEncryption)\r\n    ) {\r\n      throw new Error(\r\n        `The scanner software config does not match the selected TLA.`\r\n      );\r\n    }\r\n\r\n    // Check firmware\r\n    const firmwareVersion = await getFirmwareVersion();\r\n    if (firmwareVersion !== window.selectedProduct.productConfig.firmwareVersion) {\r\n      throw new Error(\r\n        `The scanner firmware version does not match the selected TLA.`\r\n      );\r\n    }\r\n\r\n    // Set TLA\r\n    await window.api6100.cortexSetTLA(window.selectedProduct.productConfig.tlaNumber);\r\n\r\n    // Set USB Descriptor\r\n    await window.api6100.cortexSetUSBDescriptorMode(parseInt(window.selectedProduct.productConfig.usbDescriptor));\r\n\r\n    // Set Skew Tolerance/Reject\r\n    await window.api6100.cortexSetSkew(parseInt(window.selectedProduct.productConfig.skewTolerance), parseInt(window.selectedProduct.productConfig.skewReject));\r\n\r\n    // Get scanner config\r\n    const scannerConfig = await window.api6100.xfn(0x49);\r\n\r\n    // Update results\r\n    window.selectedProduct.productionResults.deviceHardware = deviceHardware;\r\n    window.selectedProduct.productionResults.deviceSoftware = deviceSoftware;\r\n    window.selectedProduct.productionResults.firmwareVersion = firmwareVersion;\r\n    window.selectedProduct.productionResults.scannerConfig = scannerConfig;\r\n\r\n    await window.api6100.closeDevice();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
