(242, '2022-10-19 15:07:37', 29, 4, 'Unlock Vault Via Serial', 'Unlock Vault', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will unlock the vault over serial. This test is dependent on \"Connect Via Serial\" already being performed.</p>', 's', 1),
(243, '2022-10-19 15:11:28', 29, 4, 'Unlock Vault Via Serial', 'Unlock Vault', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will unlock the vault over serial. This test is dependent on \"Connect Via Serial\" already being performed.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort) {\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n      const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n\r\n      // Have user determine if correct\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did the vault unlock?\', \'User failed test\');\r\n    } else {\r\n      await failTestActions(\'Device has yet to be found on serial.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(244, '2022-10-19 15:32:06', 29, 4, 'Unlock Vault Via Serial', 'Unlock Vault', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will unlock the vault over serial. This test is dependent on \"Connect Via Serial\" already being performed.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort) {\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n      const securityResult = await getSecurityBytesSerial(\'feederKey\');\r\n      await window.genericRS232.sendBytes([0x1B, 0x55, 0x33, securityResult[0], securityResult[1]]);\r\n\r\n      // Have user determine if correct\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did the vault unlock?\', \'User failed test\');\r\n    } else {\r\n      await failTestActions(\'Device has yet to be found on serial.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
