(251, '2022-10-20 10:00:18', 31, 4, 'Find Burster Sensor Test Fixture', 'Find Fixture', NULL, '<p>Please ensure fixture is connected to PC prior to starting.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    const response = await isFixtureOnSerial();\r\n    if (response.foundFixture) {\r\n      window.selectedProduct.comPort = foundDevice.fixtureCom;\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Could not find the fixture attached to the computer.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(252, '2022-10-20 10:09:20', 31, 4, 'Find Burster Sensor Test Fixture', 'Find Fixture', NULL, '<p>Please ensure fixture is connected to PC prior to starting.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    const response = await isFixtureOnSerial();\r\n    if (response.foundFixture) {\r\n      window.selectedProduct.comPort = response.fixtureCom;\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Could not find the fixture attached to the computer.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(253, '2022-10-20 10:30:16', 31, 4, 'Find Burster Sensor Test Fixture', 'Find Fixture', NULL, '<p>Please ensure fixture is connected to PC prior to starting.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    const response = await isFixtureOnSerial();\r\n    if (response.foundFixture) {\r\n      window.selectedProduct.comPort = response.fixtureCom;\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n\r\n      if (!window.selectedProduct.fixtureSerialNumber) {\r\n        window.selectedProduct.fixtureSerialNumber = await getFixtureSerialNumber();\r\n        await configureFixture();\r\n        console.log(window.selectedProduct.fixtureSerialNumber);\r\n      }\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Could not find the fixture attached to the computer.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(254, '2022-10-20 10:59:59', 31, 4, 'Find Burster Sensor Test Fixture', 'Find Fixture', NULL, '<p>Please ensure fixture is connected to PC prior to starting.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    const response = await isFixtureOnSerial();\r\n    if (response.foundFixture) {\r\n      window.selectedProduct.comPort = response.fixtureCom;\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n\r\n      if (!window.selectedProduct.fixtureSerialNumber) {\r\n        window.selectedProduct.fixtureSerialNumber = await getFixtureSerialNumber();\r\n        await configureFixture();\r\n      }\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Could not find the fixture attached to the computer.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
