(256, '2022-10-20 11:02:00', 32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', 's', 1),
(257, '2022-10-20 11:04:53', 32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      await checkForVoltageIssues();\r\n      \r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(258, '2022-10-20 11:16:14', 32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      await checkForVoltageIssues();\r\n\r\n      let isSensorConnected = await isSensorConnected();\r\n      console.log(\'isSensorConnected\', isSensorConnected);\r\n      \r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests_archive` (`archiveId`, `generatedDateTime`, `testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(259, '2022-10-20 11:17:07', 32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      await checkForVoltageIssues();\r\n\r\n      let isSensorConnectedResult = await isSensorConnected();\r\n      console.log(\'isSensorConnected\', isSensorConnectedResult);\r\n      \r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(260, '2022-10-20 11:31:47', 32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', 'function lookForSensorConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to be connected to fixture. (\' + (countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        if(await isSensorConnected()) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve();\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      await checkForVoltageIssues();\r\n\r\n      await lookForSensorConnected(15);\r\n      \r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(261, '2022-10-20 11:34:01', 32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', 'function lookForSensorConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to be connected to fixture. (\' + Math.round(countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        if(await isSensorConnected()) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve();\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      await checkForVoltageIssues();\r\n\r\n      await lookForSensorConnected(15);\r\n      \r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(262, '2022-10-20 11:35:02', 32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', 'function lookForSensorConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to be connected to fixture. (\' + Math.round(countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        if(await isSensorConnected()) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve();\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      await checkForVoltageIssues();\r\n\r\n      await lookForSensorConnected(30);\r\n      \r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(263, '2022-10-20 12:49:46', 32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', 'function lookForSensorConnected(secondsToLook, lookingForSensorToBeConnected) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for sensor to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n        if(!lookingForSensorToBeConnected) {\r\n          message = \'Waiting for sensor to be disconnected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorConnectedResponse = await isSensorConnected();\r\n        if(sensorConnectedResponse.sensorConnected === lookingForSensorToBeConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorConnectedResponse.ledValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForSensorNotBlocked(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to NOT be blocked. (\' + Math.round(countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorBlockedResponse = await isSensorBlocked();\r\n        if(sensorBlockedResponse.sensorNotBlocked) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorBlockedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForSensorBlocked(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to be blocked. (\' + Math.round(countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorBlockedResponse = await isSensorBlocked();\r\n        if(sensorBlockedResponse.sensorBlocked) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorBlockedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      await checkForVoltageIssues();\r\n\r\n      window.selectedProduct.productionResults.ledVoltage = await lookForSensorConnected(30, true);\r\n      window.selectedProduct.productionResults.sensorNotBlocked = await lookForSensorNotBlocked(30);\r\n      window.selectedProduct.productionResults.sensorBlocked = await lookForSensorBlocked(30);\r\n      window.selectedProduct.productionResults.ledVoltage = await lookForSensorConnected(30, false);\r\n      \r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(264, '2022-10-20 12:53:10', 32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', 'function lookForSensorConnected(secondsToLook, lookingForSensorToBeConnected) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for sensor to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n        if(!lookingForSensorToBeConnected) {\r\n          message = \'Waiting for sensor to be disconnected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorConnectedResponse = await isSensorConnected();\r\n        if(sensorConnectedResponse.sensorConnected === lookingForSensorToBeConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorConnectedResponse.ledValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForSensorNotBlocked(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to NOT be blocked. (\' + Math.round(countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorBlockedResponse = await isSensorBlocked();\r\n        if(sensorBlockedResponse.sensorNotBlocked) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorBlockedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForSensorBlocked(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to be blocked. (\' + Math.round(countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorBlockedResponse = await isSensorBlocked();\r\n        if(sensorBlockedResponse.sensorBlocked) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorBlockedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      await checkForVoltageIssues();\r\n\r\n      window.selectedProduct.productionResults.ledVoltage = await lookForSensorConnected(30, true);\r\n      window.selectedProduct.productionResults.sensorNotBlocked = await lookForSensorNotBlocked(30);\r\n      window.selectedProduct.productionResults.sensorBlocked = await lookForSensorBlocked(30);\r\n      window.selectedProduct.productionResults.ledVoltage = await lookForSensorConnected(30, false);\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n      \r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(265, '2022-10-20 13:15:32', 32, 4, 'Test Burster Sensor', 'Test Sensor', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will verify that the burster sensor is wired properly. This test is dependent on \"Find Fixture\" already being performed.</p>', 'function lookForSensorConnected(secondsToLook, lookingForSensorToBeConnected) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for sensor to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n        if(!lookingForSensorToBeConnected) {\r\n          message = \'Waiting for sensor to be disconnected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorConnectedResponse = await isSensorConnected();\r\n        if(sensorConnectedResponse.sensorConnected === lookingForSensorToBeConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorConnectedResponse.ledValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForSensorNotBlocked(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to NOT be blocked. (\' + Math.round(countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorBlockedResponse = await isSensorBlocked();\r\n        if(sensorBlockedResponse.sensorNotBlocked) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorBlockedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForSensorBlocked(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n        window.Loading.show({\r\n          message: \'Waiting for sensor to be blocked. (\' + Math.round(countDown / 10) + \' seconds remaining)\'\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No sensor detected\');\r\n        }\r\n\r\n        let sensorBlockedResponse = await isSensorBlocked();\r\n        if(sensorBlockedResponse.sensorBlocked) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(sensorBlockedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      await checkForVoltageIssues();\r\n\r\n      window.selectedProduct.productionResults.ledVoltage = await lookForSensorConnected(30, true);\r\n      window.selectedProduct.productionResults.sensorNotBlocked = await lookForSensorNotBlocked(30);\r\n      window.selectedProduct.productionResults.sensorBlocked = await lookForSensorBlocked(30);\r\n      window.selectedProduct.productionResults.ledVoltage = await lookForSensorConnected(30, false);\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n      \r\n      await passTestActions();\r\n\r\n      // Rerun the test\r\n      await reRunTests();\r\n      startTest();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(266, '2022-10-24 10:15:30', 33, 4, 'Find VCSEL Test Fixture', 'Find Fixture', NULL, '<p>Please ensure fixture is connected to PC prior to starting.</p>', 'a', 1),
(267, '2022-10-24 10:16:38', 33, 4, 'Find VCSEL Test Fixture', 'Find Fixture', NULL, '<p>Please ensure fixture is connected to PC prior to starting.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    const response = await isFixtureOnSerial();\r\n    if (response.foundFixture) {\r\n      window.selectedProduct.comPort = response.fixtureCom;\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n\r\n      if (!window.selectedProduct.fixtureSerialNumber) {\r\n        window.selectedProduct.fixtureSerialNumber = await getFixtureSerialNumber();\r\n        await configureFixture();\r\n      }\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Could not find the fixture attached to the computer.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(268, '2022-10-24 10:25:23', 34, 4, 'Read VCSEL Config', 'Read Config', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will read the current configuration of the VCSEL.</p>', 'a', 1),
