(282, '2022-10-24 14:00:10', 35, 4, 'VCSEL Manual Set', 'Manual Set', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will read the current configuration of the VCSEL and allow for manually setting values.</p>', 'function lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction updateVolatilePots() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setCollectorPot(parseInt(document.getElementById(\'collectorValue\').value));\r\n      await setTransmitterPot(parseInt(document.getElementById(\'emitterValue\').value));\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.serialNumber = await getSerialNumber();\r\n      window.selectedProduct.productionResults.currentCollectorValue = await getCurrentCollectorValue();\r\n      window.selectedProduct.productionResults.currentTransmitterValue = await getCurrentTransmitterValue();\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      // Show results\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div class=\"testResults\">\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Serial Number:</strong> ${window.selectedProduct.productionResults.serialNumber}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Collector Value:</strong> ${window.selectedProduct.productionResults.currentCollectorValue}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Transmitter Value:</strong> ${window.selectedProduct.productionResults.currentTransmitterValue}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Collector Voltage Reading:</strong> ${window.selectedProduct.productionResults.currentCollectorVoltageReading}</div>\r\n          </div>\r\n        </div>\r\n\r\n        ${drawGauge (window.selectedProduct.productionResults.currentTransmitterValue, window.selectedProduct.productionResults.currentCollectorValue, window.selectedProduct.productionResults.currentCollectorVoltageReading)}\r\n      \r\n        <form onsubmit=\"return false;\">\r\n          Emitter: <input type=\"text\" id=\"emitterValue\" value=\"${window.selectedProduct.productionResults.currentTransmitterValue}\" />\r\n          Collector: <input type=\"text\" id=\"collectorValue\" value=\"${window.selectedProduct.productionResults.currentCollectorValue}\" />\r\n          <input type=\"submit\" value=\"Submit\" onclick=\"updateVolatilePots()\" />\r\n        </form>\r\n      `;\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests_archive` (`archiveId`, `generatedDateTime`, `testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(283, '2022-10-24 14:10:34', 35, 4, 'VCSEL Manual Set', 'Manual Set', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will read the current configuration of the VCSEL and allow for manually setting values.</p>', 'function lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction updateVolatilePots() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      await setCollectorPot(parseInt(document.getElementById(\'collectorValue\').value));\r\n      await setTransmitterPot(parseInt(document.getElementById(\'emitterValue\').value));\r\n      await waitForReadingToStabilize(3);\r\n      await drawResults();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawResults() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.selectedProduct.productionResults.currentCollectorValue = await getCurrentCollectorValue();\r\n      window.selectedProduct.productionResults.currentTransmitterValue = await getCurrentTransmitterValue();\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Show results\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div class=\"testResults\">\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Serial Number:</strong> ${window.selectedProduct.productionResults.serialNumber}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Collector Value:</strong> ${window.selectedProduct.productionResults.currentCollectorValue}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Transmitter Value:</strong> ${window.selectedProduct.productionResults.currentTransmitterValue}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Collector Voltage Reading:</strong> ${window.selectedProduct.productionResults.currentCollectorVoltageReading}</div>\r\n          </div>\r\n        </div>\r\n\r\n        ${drawGauge (window.selectedProduct.productionResults.currentTransmitterValue, window.selectedProduct.productionResults.currentCollectorValue, window.selectedProduct.productionResults.currentCollectorVoltageReading)}\r\n      \r\n        <form onsubmit=\"return false;\" style=\"margin-top: 50px;\">\r\n          Emitter: <input type=\"text\" id=\"emitterValue\" value=\"${window.selectedProduct.productionResults.currentTransmitterValue}\" /><br/>\r\n          Collector: <input type=\"text\" id=\"collectorValue\" value=\"${window.selectedProduct.productionResults.currentCollectorValue}\" /><br/>\r\n          <input type=\"submit\" value=\"Submit\" onclick=\"updateVolatilePots()\" />\r\n        </form>\r\n      `;\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.serialNumber = await getSerialNumber();\r\n      window.selectedProduct.productionResults.currentCollectorValue = await getCurrentCollectorValue();\r\n      window.selectedProduct.productionResults.currentTransmitterValue = await getCurrentTransmitterValue();\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      // Show results\r\n      drawResults();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(284, '2022-10-24 14:21:37', 35, 4, 'VCSEL Manual Set', 'Manual Set', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will read the current configuration of the VCSEL and allow for manually setting values.</p>', 'function lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction updateVolatilePots() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.gsap.set(\'#cfgFrm\', {display: \'none\'});\r\n      await setCollectorPot(parseInt(document.getElementById(\'collectorValue\').value));\r\n      await setTransmitterPot(parseInt(document.getElementById(\'emitterValue\').value));\r\n      await waitForReadingToStabilize(3);\r\n      await drawResults();\r\n      resolve();\r\n    } catch (err) {\r\n      promptUser(err.toString());\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawResults() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.selectedProduct.productionResults.currentCollectorValue = await getCurrentCollectorValue();\r\n      window.selectedProduct.productionResults.currentTransmitterValue = await getCurrentTransmitterValue();\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Show results\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div class=\"testResults\">\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Serial Number:</strong> ${window.selectedProduct.productionResults.serialNumber}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Collector Value:</strong> ${window.selectedProduct.productionResults.currentCollectorValue}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Transmitter Value:</strong> ${window.selectedProduct.productionResults.currentTransmitterValue}</div>\r\n          </div>\r\n          <div class=\"testResult\">\r\n            <div class=\"testResultLabel\"><strong>Current Collector Voltage Reading:</strong> ${window.selectedProduct.productionResults.currentCollectorVoltageReading}</div>\r\n          </div>\r\n        </div>\r\n\r\n        ${drawGauge (window.selectedProduct.productionResults.currentTransmitterValue, window.selectedProduct.productionResults.currentCollectorValue, window.selectedProduct.productionResults.currentCollectorVoltageReading)}\r\n      \r\n        <form onsubmit=\"return false;\" style=\"margin-top: 50px;\" id=\"cfgFrm\">\r\n          Emitter: <input type=\"text\" id=\"emitterValue\" value=\"${window.selectedProduct.productionResults.currentTransmitterValue}\" /><br/><br/>\r\n          Collector: <input type=\"text\" id=\"collectorValue\" value=\"${window.selectedProduct.productionResults.currentCollectorValue}\" /><br/><br/>\r\n          <input type=\"submit\" value=\"Submit\" onclick=\"updateVolatilePots()\" />\r\n        </form>\r\n      `;\r\n\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.serialNumber = await getSerialNumber();\r\n      window.selectedProduct.productionResults.currentCollectorValue = await getCurrentCollectorValue();\r\n      window.selectedProduct.productionResults.currentTransmitterValue = await getCurrentTransmitterValue();\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      // Show results\r\n      drawResults();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
