(295, '2022-10-24 15:46:18', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', 'a', 1);
INSERT INTO `prod_v2_tests_archive` (`archiveId`, `generatedDateTime`, `testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(296, '2022-10-24 16:05:23', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', 'const IDEAL_VOLTAGE = 1.65;\r\nconst MIN_COLLECTOR_VAL = 100;\r\nconst MAX_COLLECTOR_VAL = 127;\r\nconst MIN_TRANSMITTER_VAL = 110;\r\nconst MAX_TRANSMITTER_VAL = 127;\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        resolve(findTransmitterValue(transmitterValue--));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(297, '2022-10-24 16:07:16', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', 'const IDEAL_VOLTAGE = 1.65;\r\nconst MIN_COLLECTOR_VAL = 100;\r\nconst MAX_COLLECTOR_VAL = 127;\r\nconst MIN_TRANSMITTER_VAL = 110;\r\nconst MAX_TRANSMITTER_VAL = 127;\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        resolve(await findTransmitterValue(transmitterValue--));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(298, '2022-10-24 16:08:04', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', 'let IDEAL_VOLTAGE = 1.65;\r\nlet MIN_COLLECTOR_VAL = 100;\r\nlet MAX_COLLECTOR_VAL = 127;\r\nlet MIN_TRANSMITTER_VAL = 110;\r\nlet MAX_TRANSMITTER_VAL = 127;\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        resolve(await findTransmitterValue(transmitterValue--));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(299, '2022-10-24 16:14:39', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', '\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        resolve(await findTransmitterValue(transmitterValue--));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(300, '2022-10-24 16:16:38', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', '\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      console.log(\'set transmitter value to \' + transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      console.log(\'stable\');\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        resolve(await findTransmitterValue(transmitterValue--));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(301, '2022-10-24 16:17:49', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', '\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      console.log(\'set transmitter value to \' + transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      console.log(\'stable\');\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(302, '2022-10-24 16:21:52', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', '\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      console.log(\'set transmitter value to \' + transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      console.log(\'stable\');\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(303, '2022-10-24 16:30:20', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', '\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findCollectorValue (collectorValue, lastVoltage) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (collectorValue < MIN_COLLECTOR_VAL || collectorValue > MAX_COLLECTOR_VAL) {\r\n        reject(\'Could not find good collector value\');\r\n      }\r\n\r\n      await setCollectorPot(collectorValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = collectorValue + 1;\r\n        resolve(await findCollectorValue(newValue, voltage));\r\n      } else {\r\n        // Determine if last reading was closer to ideal voltage\r\n        if (Math.abs(IDEAL_VOLTAGE - lastVoltage) < Math.abs(voltage - IDEAL_VOLTAGE)) {\r\n          // Last reading was closer to ideal voltage\r\n          const oldValue = collectorValue - 1;\r\n          await setCollectorPot(oldValue);\r\n          await waitForReadingToStabilize(3);\r\n          await drawProcessing();\r\n          resolve(oldValue);\r\n        } else {\r\n          resolve(collectorValue);\r\n        }\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n      let collectorValue = await findCollectorValue(MIN_COLLECTOR_VAL, voltage);\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(304, '2022-10-24 16:32:50', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', '\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findCollectorValue (collectorValue, lastVoltage) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (collectorValue < MIN_COLLECTOR_VAL || collectorValue > MAX_COLLECTOR_VAL) {\r\n        reject(\'Could not find good collector value\');\r\n      }\r\n\r\n      await setCollectorPot(collectorValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = collectorValue + 1;\r\n        resolve(await findCollectorValue(newValue, voltage));\r\n      } else {\r\n        // Determine if last reading was closer to ideal voltage\r\n        if (Math.abs(IDEAL_VOLTAGE - lastVoltage) < Math.abs(voltage - IDEAL_VOLTAGE)) {\r\n          // Last reading was closer to ideal voltage\r\n          const oldValue = collectorValue - 1;\r\n          await setCollectorPot(oldValue);\r\n          await waitForReadingToStabilize(3);\r\n          await drawProcessing();\r\n          resolve(oldValue);\r\n        } else {\r\n          resolve(collectorValue);\r\n        }\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: collector,\r\n        transmitter: emitter,\r\n        voltage: voltage\r\n      });\r\n\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.testsRan = [];\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n      let collectorValue = await findCollectorValue(MIN_COLLECTOR_VAL, voltage);\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(305, '2022-10-24 16:35:33', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', '\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findCollectorValue (collectorValue, lastVoltage) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (collectorValue < MIN_COLLECTOR_VAL || collectorValue > MAX_COLLECTOR_VAL) {\r\n        reject(\'Could not find good collector value\');\r\n      }\r\n\r\n      await setCollectorPot(collectorValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = collectorValue + 1;\r\n        resolve(await findCollectorValue(newValue, voltage));\r\n      } else {\r\n        // Determine if last reading was closer to ideal voltage\r\n        if (Math.abs(IDEAL_VOLTAGE - lastVoltage) < Math.abs(voltage - IDEAL_VOLTAGE)) {\r\n          // Last reading was closer to ideal voltage\r\n          const oldValue = collectorValue - 1;\r\n          await setCollectorPot(oldValue);\r\n          await waitForReadingToStabilize(3);\r\n          await drawProcessing();\r\n          resolve(oldValue);\r\n        } else {\r\n          resolve(collectorValue);\r\n        }\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: collector,\r\n        transmitter: emitter,\r\n        voltage: voltage\r\n      });\r\n\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.testsRan = [];\r\n\r\n      window.selectedProduct.productionResults.collectorNV = await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n      let collectorValue = await findCollectorValue(MIN_COLLECTOR_VAL, voltage);\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(306, '2022-10-24 16:41:21', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', '\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findCollectorValue (collectorValue, lastVoltage) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (collectorValue < MIN_COLLECTOR_VAL || collectorValue > MAX_COLLECTOR_VAL) {\r\n        reject(\'Could not find good collector value\');\r\n      }\r\n\r\n      await setCollectorPot(collectorValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = collectorValue + 1;\r\n        if (voltage < 1.2) {\r\n          newValue+=2; // Extra increment to speed up when far off ideal\r\n        } else if (voltage < 1.4) {\r\n          newValue++; // Extra increment to speed up when far off ideal\r\n        }\r\n        resolve(await findCollectorValue(newValue, voltage));\r\n      } else {\r\n        // Determine if last reading was closer to ideal voltage\r\n        if (Math.abs(IDEAL_VOLTAGE - lastVoltage) < Math.abs(voltage - IDEAL_VOLTAGE)) {\r\n          // Last reading was closer to ideal voltage\r\n          const oldValue = collectorValue - 1;\r\n          await setCollectorPot(oldValue);\r\n          await waitForReadingToStabilize(3);\r\n          await drawProcessing();\r\n          resolve(oldValue);\r\n        } else {\r\n          resolve(collectorValue);\r\n        }\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: collector,\r\n        transmitter: emitter,\r\n        voltage: voltage\r\n      });\r\n\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.testsRan = [];\r\n\r\n      await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n      let collectorValue = await findCollectorValue(MIN_COLLECTOR_VAL, voltage);\r\n\r\n      // Found good value, save to NV RAM\r\n      await setTransmitterPotNV(transmitterValue);\r\n      await setCollectorPotNV(collectorValue);\r\n\r\n      // Perform serialization\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
