voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findCollectorValue (collectorValue, lastVoltage) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (collectorValue < MIN_COLLECTOR_VAL || collectorValue > MAX_COLLECTOR_VAL) {\r\n        reject(\'Could not find good collector value\');\r\n      }\r\n\r\n      await setCollectorPot(collectorValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        let newValue = collectorValue + 1;\r\n        if (voltage < 1.2) {\r\n          newValue+=2; // Extra increment to speed up when far off ideal\r\n        } else if (voltage < 1.4) {\r\n          newValue++; // Extra increment to speed up when far off ideal\r\n        }\r\n        resolve(await findCollectorValue(newValue, voltage));\r\n      } else {\r\n        // Determine if last reading was closer to ideal voltage\r\n        if (Math.abs(IDEAL_VOLTAGE - lastVoltage) < Math.abs(voltage - IDEAL_VOLTAGE)) {\r\n          // Last reading was closer to ideal voltage\r\n          const oldValue = collectorValue - 1;\r\n          await setCollectorPot(oldValue);\r\n          await waitForReadingToStabilize(3);\r\n          await drawProcessing();\r\n          resolve(oldValue);\r\n        } else {\r\n          resolve(collectorValue);\r\n        }\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: collector,\r\n        transmitter: emitter,\r\n        voltage: voltage\r\n      });\r\n\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.testsRan = [];\r\n\r\n      await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n      let collectorValue = await findCollectorValue(MIN_COLLECTOR_VAL, voltage);\r\n\r\n      // Found good value, save to NV RAM\r\n      await setTransmitterPotNV(transmitterValue);\r\n      await setCollectorPotNV(collectorValue);\r\n\r\n      // Perform serialization\r\n      let serialNumber = await getSerialNumber();\r\n      if (serialNumber == 0) {\r\n        // Request new serial number from server\r\n\r\n        // Set Serial Number\r\n\r\n        // Get Serial Number\r\n        serialNumber = await getSerialNumber();\r\n      }\r\n\r\n      window.selectedProduct.productionResults.serialNumber = serialNumber;\r\n      window.selectedProduct.productionResults.collectorNV = await getCollectorPotNV();\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.currentCollectorValue = collectorValue;\r\n      window.selectedProduct.productionResults.currentTransmitterValue = transmitterValue;\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
