ideal voltage\r\n        if (Math.abs(IDEAL_VOLTAGE - lastVoltage) < Math.abs(voltage - IDEAL_VOLTAGE)) {\r\n          // Last reading was closer to ideal voltage\r\n          const oldValue = collectorValue - 1;\r\n          await setCollectorPot(oldValue);\r\n          await waitForReadingToStabilize(3);\r\n          await drawProcessing();\r\n          resolve(oldValue);\r\n        } else {\r\n          resolve(collectorValue);\r\n        }\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: collector,\r\n        transmitter: emitter,\r\n        voltage: voltage\r\n      });\r\n\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.testsRan = [];\r\n\r\n      await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n\r\n\r\n      // Found good value, save to NV RAM\r\n      await setTransmitterPotNV(transmitterValue);\r\n      await setCollectorPotNV(collectorValue);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n      let collectorValue = await findCollectorValue(MIN_COLLECTOR_VAL, voltage);\r\n\r\n      // Perform serialization\r\n      let serialNumber = await getSerialNumber();\r\n      if (serialNumber == 0) {\r\n        // Request new serial number from server\r\n        const serialResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"printer7680\",\r\n              action: \"getNextVcselSerialNumber\",\r\n              params: {}\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (serialResponse.data.success) {\r\n          // Set Serial Number\r\n          await setSerialNumber(serialResponse.data.serialNumber);\r\n\r\n          // Get Serial Number\r\n          serialNumber = await getSerialNumber();\r\n        } else {\r\n          throw new Error(\'Could not get serial number from server\');\r\n        }\r\n      }\r\n\r\n      window.selectedProduct.productionResults.serialNumber = serialNumber;\r\n      window.selectedProduct.productionResults.collectorNV = await getCollectorPotNV();\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.currentCollectorValue = collectorValue;\r\n      window.selectedProduct.productionResults.currentTransmitterValue = transmitterValue;\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n\r\n      // Rerun the test\r\n      await reRunTests();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(317, '2022-10-25 09:00:58', 38, 4, 'OGR (Serial)', 'OGR', NULL, '', 's', 1),
(318, '2022-10-25 09:01:47', 38, 4, 'OGR (Serial)', 'OGR', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will send the OGR test command over serial. This test is dependent on \"Connect Via Serial\" already being performed.</p>', 's', 1),
(319, '2022-10-25 09:05:14', 38, 4, 'OGR (Serial)', 'OGR', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will send the OGR test command over serial. This test is dependent on \"Connect Via Serial\" already being performed.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort) {\r\n      await connectToSerial(window.selectedProduct.comPort);\r\n      await window.genericRS232.sendBytes([0x1B, 0x4E, 0xFA]);\r\n\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Device has yet to be found on serial.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(320, '2022-10-25 09:29:48', 39, 4, 'Connect USB w/Extended Status', 'Connect', NULL, '<p>Make sure printer has ribbon, forms, and vault installed. Connect USB, Serial, and HyperComm Test Box.</p>', 'a', 1),
(321, '2022-10-25 09:31:00', 39, 4, 'Connect USB w/Extended Status', 'Connect Via USB', NULL, '<p>Make sure printer has ribbon, forms, and vault installed. Connect USB, Serial, and HyperComm Test Box.</p>', 'a', 1),
(322, '2022-10-25 09:51:38', 39, 4, 'Connect USB w/Extended Status', 'Connect Via USB', NULL, '<p>Make sure printer has ribbon, forms, and vault installed. Connect USB, Serial, and HyperComm Test Box.</p>', 'const { fail } = require(\"assert\");\r\n\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n    const status = await getExtendedStatusUsb();\r\n    await disconnectFromUsb();\r\n\r\n    let errorString = \'\';\r\n\r\n    console.log(status);\r\n\r\n    if (errorString === \'\') {\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'The following issues were found: \' + errorString);\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(323, '2022-10-25 09:52:32', 39, 4, 'Connect USB w/Extended Status', 'Connect Via USB', NULL, '<p>Make sure printer has ribbon, forms, and vault installed. Connect USB, Serial, and HyperComm Test Box.</p>', '\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n    const status = await getExtendedStatusUsb();\r\n    await disconnectFromUsb();\r\n\r\n    let errorString = \'\';\r\n\r\n    console.log(status);\r\n\r\n    if (errorString === \'\') {\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'The following issues were found: \' + errorString);\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(324, '2022-10-25 09:56:17', 39, 4, 'Connect USB w/Extended Status', 'Connect Via USB', NULL, '<p>Make sure printer has ribbon, forms, and vault installed. Connect USB, Serial, and HyperComm Test Box.</p>', '\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n    const status = await getExtendedStatusUsb();\r\n    await disconnectFromUsb();\r\n\r\n    let errorString = \'\';\r\n\r\n    if(status.carriageHomeSensorInError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Carriage Home Sensor\'\r\n    }\r\n    if(status.bursterHomeSensorInError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Burster Home Sensor\'\r\n    }\r\n    if(status.paperOut) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Paper Out\'\r\n    }\r\n    if(status.paperLoadingError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Paper Loading\'\r\n    }\r\n    if(status.failedTopOfFormMark) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Failed Top Of Form\'\r\n    }\r\n    if(status.burstError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Burst\'\r\n    }\r\n    if(status.checksumError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Checksum\'\r\n    }\r\n    if(status.feederNotPresent) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Feeder Missing\'\r\n    }\r\n    if(status.burstSensorDefective) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Burst Sensor\'\r\n    }\r\n    if(status.ejectFailed) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Eject\'\r\n    }\r\n\r\n    if (errorString === \'\') {\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'The following issues were found: \' + errorString);\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(325, '2022-10-25 10:00:36', 39, 4, 'Connect USB w/Extended Status', 'Connect Via USB', NULL, '<p>Make sure printer has ribbon, forms, and vault installed. Connect USB, Serial, and HyperComm Test Box.</p>', '\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n    const status = await getExtendedStatusUsb();\r\n    await disconnectFromUsb();\r\n\r\n    let errorString = \'\';\r\n\r\n    if(status.carriageHomeSensorInError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Carriage Home Sensor\'\r\n    }\r\n    if(status.bursterHomeSensorInError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Burster Home Sensor\'\r\n    }\r\n    if(status.paperOut) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Paper Out\'\r\n    }\r\n    if(status.paperLoadingError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Paper Loading\'\r\n    }\r\n    if(status.failedTopOfFormMark) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Failed Top Of Form\'\r\n    }\r\n    if(status.burstError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Burst\'\r\n    }\r\n    if(status.checksumError) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Checksum\'\r\n    }\r\n    if(status.feederNotPresent) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Feeder Missing\'\r\n    }\r\n    if(status.burstSensorDefective) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Burst Sensor\'\r\n    }\r\n    if(status.ejectFailed) {\r\n      errorString += (errorString === \'\'?\'\':\', \') + \'Eject\'\r\n    }\r\n\r\n    if (errorString === \'\') {\r\n      await passTestActions();\r\n    } else {\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.onConnectExtendedStatus = status;\r\n\r\n        await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await failTestActions(\'The following issues were found: \' + errorString);\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(326, '2022-10-25 10:28:18', 40, 4, 'Firmware Update', 'Firmware Update', NULL, '', 'a', 1),
(327, '2022-10-25 10:30:53', 40, 4, 'Firmware Update', 'Firmware Update', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will check the current firmware version and update if necessary.</p>', 'a', 1),
(328, '2022-10-25 10:46:53', 40, 4, 'Firmware Update', 'Firmware Update', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will check the current firmware version and update if necessary.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Check current version against desired version\r\n    const currentVersion = await getFirmwareVersionUsb();\r\n    let returnFw = currentVersion.split(\'\');\r\n    const targetFw = window.selectedProduct.productConfig.firmwareVersion.split(\'\');\r\n\r\n    // Check boot first (fail out if boot wrong) (v3.02A)\r\n    if(returnFw[0]!==\'3\' || returnFw[2]!==\'0\' || returnFw[3]!==\'2\' || returnFw[4]!==\'A\') {\r\n      await disconnectFromUsb();\r\n      await failTestActions(\'Boot Firmware Invalid\');\r\n    } else if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n      // Update not needed\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } else {\r\n      // Update needed\r\n      window.Loading.show({\r\n        message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n      });\r\n      const fwVersion = await updateFirmware (window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n      returnFw = fwVersion.split(\'\');\r\n      await disconnectFromUsb();\r\n      window.Loading.hide();\r\n\r\n      if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n        await passTestActions();\r\n      } else {\r\n        await failTestActions(\'Firmware update failed.\');\r\n      }\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(329, '2022-10-25 10:48:25', 40, 4, 'Firmware Update', 'Firmware Update', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will check the current firmware version and update if necessary.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Check current version against desired version\r\n    const currentVersion = await getFirmwareVersionUsb();\r\n    let returnFw = currentVersion.split(\'\');\r\n    const targetFw = window.selectedProduct.productConfig.firmwareVersion.split(\'\');\r\n\r\n    // Check boot first (fail out if boot wrong) (v3.02A)\r\n    console.log(returnFw);\r\n    if(returnFw[0]!==\'3\' || returnFw[2]!==\'0\' || returnFw[3]!==\'2\' || returnFw[4]!==\'A\') {\r\n      await disconnectFromUsb();\r\n      await failTestActions(\'Boot Firmware Invalid\');\r\n    } else if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n      // Update not needed\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } else {\r\n      // Update needed\r\n      window.Loading.show({\r\n        message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n      });\r\n      const fwVersion = await updateFirmware (window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n      returnFw = fwVersion.split(\'\');\r\n      await disconnectFromUsb();\r\n      window.Loading.hide();\r\n\r\n      if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n        await passTestActions();\r\n      } else {\r\n        await failTestActions(\'Firmware update failed.\');\r\n      }\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests_archive` (`archiveId`, `generatedDateTime`, `testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(330, '2022-10-25 10:49:45', 40, 4, 'Firmware Update', 'Firmware Update', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will check the current firmware version and update if necessary.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Check current version against desired version\r\n    const currentVersion = await getFirmwareVersionUsb();\r\n    let returnFw = currentVersion.split(\'\');\r\n    const targetFw = window.selectedProduct.productConfig.firmwareVersion.split(\'\');\r\n\r\n    // Check boot first (fail out if boot wrong) (v3.03A)\r\n    if(returnFw[0]!==\'3\' || returnFw[2]!==\'0\' || returnFw[3]!==\'3\' || returnFw[4]!==\'A\') {\r\n      await disconnectFromUsb();\r\n      await failTestActions(\'Boot Firmware Invalid\');\r\n    } else if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n      // Update not needed\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } else {\r\n      // Update needed\r\n      window.Loading.show({\r\n        message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n      });\r\n      const fwVersion = await updateFirmware (window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n      returnFw = fwVersion.split(\'\');\r\n      await disconnectFromUsb();\r\n      window.Loading.hide();\r\n\r\n      if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n        await passTestActions();\r\n      } else {\r\n        await failTestActions(\'Firmware update failed.\');\r\n      }\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(331, '2022-10-25 10:52:19', 40, 4, 'Firmware Update', 'Firmware Update', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will check the current firmware version and update if necessary.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Check current version against desired version\r\n    const currentVersion = await getFirmwareVersionUsb();\r\n    let returnFw = currentVersion.split(\'\');\r\n    const targetFw = window.selectedProduct.productConfig.firmwareVersion.split(\'\');\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      window.selectedProduct.productionResults.reportedFirmware = currentVersion;\r\n    }\r\n\r\n    // Check boot first (fail out if boot wrong) (v3.03A)\r\n    if(returnFw[0]!==\'3\' || returnFw[2]!==\'0\' || returnFw[3]!==\'3\' || returnFw[4]!==\'A\') {\r\n      await disconnectFromUsb();\r\n      await failTestActions(\'Boot Firmware Invalid\');\r\n    } else if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n      // Update not needed\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } else {\r\n      // Update needed\r\n      window.Loading.show({\r\n        message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n      });\r\n      const fwVersion = await updateFirmware (window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n      returnFw = fwVersion.split(\'\');\r\n      await disconnectFromUsb();\r\n      window.Loading.hide();\r\n\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.reportedFirmware = fwVersion;\r\n      }\r\n\r\n      if(targetFw[0] === returnFw[6] && targetFw[1] === returnFw[7] && targetFw[2] === returnFw[8] && targetFw[3] === returnFw[9] && targetFw[11] === returnFw[10]) {\r\n        await passTestActions();\r\n      } else {\r\n        await failTestActions(\'Firmware update failed.\');\r\n      }\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(332, '2022-10-25 10:55:05', 41, 4, 'Configure For TLA', 'Configure For TLA', NULL, '', 'a', 1),
(333, '2022-10-25 10:56:06', 41, 4, 'Configure For TLA', 'Configure For TLA', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will configure the printer to the TLA settings.</p>', 'a', 1),
(334, '2022-10-25 10:59:45', 41, 4, 'Configure For TLA', 'Configure For TLA', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will configure the printer to the TLA settings.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Set configuration\r\n    console.log(window.selectedProduct)\r\n\r\n    // Verify configuration\r\n    \r\n    await disconnectFromUsb();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(335, '2022-10-25 11:05:09', 41, 4, 'Configure For TLA', 'Configure For TLA', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will configure the printer to the TLA settings.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Set configuration\r\n    const isWideVault = parseInt(window.selectedProduct.productConfig.wideVault) === 0 ? false : true;\r\n    if (isWideVault) {\r\n      await window.genericUSB.sendBytes([0x1B, 0x2D, 0x00, 0xA6, 0x00, 0x44, 0x1B, 0x2C, 0x01]); // Wide Vault\r\n    } else {\r\n      await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, 0x44, 0x1B, 0x2C, 0x00]); // Normal Vault\r\n    }\r\n\r\n    // Verify configuration\r\n    await window.genericUSB.sendBytes([0x1B, 0x59]);\r\n    const response = await window.genericUSB.getBytes(128);\r\n\r\n    console.log(response);\r\n    \r\n    await disconnectFromUsb();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(336, '2022-10-25 11:09:49', 41, 4, 'Configure For TLA', 'Configure For TLA', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will configure the printer to the TLA settings.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Set configuration\r\n    const isWideVault = parseInt(window.selectedProduct.productConfig.wideVault) === 0 ? false : true;\r\n    if (isWideVault) {\r\n      await window.genericUSB.sendBytes([0x1B, 0x2D, 0x00, 0xA6, 0x00, 0x44, 0x1B, 0x2C, 0x01]); // Wide Vault\r\n    } else {\r\n      await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, 0x44, 0x1B, 0x2C, 0x00]); // Normal Vault\r\n    }\r\n\r\n    // Verify configuration\r\n    await window.genericUSB.sendBytes([0x1B, 0x59]);\r\n    const response = await window.genericUSB.getBytes(128);\r\n    await disconnectFromUsb();\r\n\r\n    if ((isWideVault && response[12]) || (!isWideVault && !response[12])) {\r\n      // Properly configured\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.isWideVault = isWideVault;\r\n      }\r\n\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Failed to configure for TLA\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(337, '2022-10-25 11:10:45', 41, 4, 'Configure For TLA', 'Configure For TLA', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will configure the printer to the TLA settings.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Set configuration\r\n    const isWideVault = parseInt(window.selectedProduct.productConfig.wideVault) === 0 ? false : true;\r\n    if (isWideVault) {\r\n      await window.genericUSB.sendBytes([0x1B, 0x2D, 0x00, 0xA6, 0x00, 0x44, 0x1B, 0x2C, 0x01]); // Wide Vault\r\n    } else {\r\n      await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, 0x44, 0x1B, 0x2C, 0x00]); // Normal Vault\r\n    }\r\n\r\n    // Verify configuration\r\n    await window.genericUSB.sendBytes([0x1B, 0x59]);\r\n    const response = await window.genericUSB.getBytes(128);\r\n    await disconnectFromUsb();\r\n\r\n    if ((isWideVault && response[12]) || (!isWideVault && !response[12])) {\r\n      // Properly configured\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.isWideVault = isWideVault ? \'true\' : \'false\';\r\n      }\r\n\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Failed to configure for TLA\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(338, '2022-10-25 11:11:36', 41, 4, 'Configure For TLA', 'Configure For TLA', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will configure the printer to the TLA settings.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    // Set configuration\r\n    const isWideVault = parseInt(window.selectedProduct.productConfig.wideVault) === 0 ? false : true;\r\n    if (isWideVault) {\r\n      await window.genericUSB.sendBytes([0x1B, 0x2D, 0x00, 0xA6, 0x00, 0x44, 0x1B, 0x2C, 0x01]); // Wide Vault\r\n    } else {\r\n      await window.genericUSB.sendBytes([0x1B, 0x2D, 0x01, 0x68, 0x00, 0x44, 0x1B, 0x2C, 0x00]); // Normal Vault\r\n    }\r\n\r\n    // Verify configuration\r\n    await window.genericUSB.sendBytes([0x1B, 0x59]);\r\n    const response = await window.genericUSB.getBytes(128);\r\n    await disconnectFromUsb();\r\n\r\n    if ((isWideVault && response[12]) || (!isWideVault && !response[12])) {\r\n      // Properly configured\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.isWideVault = isWideVault ? \'True\' : \'False\';\r\n      }\r\n\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Failed to configure for TLA\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(339, '2022-10-25 11:15:02', 42, 4, 'FCT Test', 'FCT Test', NULL, '', 'a', 1),
(340, '2022-10-25 11:16:22', 42, 4, 'FCT Test', 'FCT Test', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will check the FCT bit that verifies that the board was tested in PCBA.</p>', 'a', 1),
(341, '2022-10-25 12:35:21', 42, 4, 'FCT Test', 'FCT Test', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will check the FCT bit that verifies that the board was tested in PCBA.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    const returnResponse = {\r\n      success: false,\r\n      message: \'\'\r\n    }\r\n\r\n    // Verify configuration\r\n    await window.genericUSB.sendBytes([0x1B, 0x59]);\r\n    const response = await window.genericUSB.getBytes(128);\r\n\r\n    switch (response[0]) {\r\n      case 0x03:\r\n        // Clear bit\r\n        const securityResult = await getSecurityBytesUsb(\'fctKey\');\r\n        await window.genericUSB.sendBytes([0x1B, 0x79, 0x00, securityResult[0], securityResult[1]]);\r\n        returnResponse.success = true;\r\n      break;\r\n      case 0x02:\r\n        returnResponse.message = \'Self test was attempted but failed.\';\r\n      break;\r\n      default:\r\n        returnResponse.message = \'Self test was NOT attempted.\';\r\n      break;\r\n    }\r\n\r\n    await disconnectFromUsb();\r\n\r\n    if (returnResponse.success) {\r\n      await passTestActions();\r\n    } else {\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.fctReportedIssue = returnResponse.message;\r\n        await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n      document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(returnResponse.message + \' Continue?\', \'User failed test\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(342, '2022-10-25 12:40:18', 43, 4, 'HyperComm Power Test', 'HyperComm Power Test', NULL, '', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    \r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Is LED lit on HyperComm Test Box?\', \'User failed test\');\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
