(409, '2022-11-02 12:59:18', 57, 1, 'Connect To Boot Firmware', 'Connect To Boot Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Please connect USB, serial, cash box, and power. Turn on device and start the test.</p>', 'a', 1),
(410, '2022-11-02 13:04:42', 57, 1, 'Connect To Boot Firmware', 'Connect To Boot Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Please connect USB, serial, cash box, and power. Turn on device and start the test.</p>', 'a', 1),
(411, '2022-11-02 13:06:21', 57, 1, 'Connect To Boot Firmware', 'Connect To Boot Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Please connect USB, serial, cash box, and power. Turn on device and start the test.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    try {\r\n      await connectToUsbInBoot();\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } catch (e) {\r\n      // Change over to boot if possible\r\n      await connectToUsb();\r\n\r\n      // Change to boot mode\r\n      window.Loading.show({\r\n        message: \'Switching to boot mode...\'\r\n      });\r\n      await window.genericUSB.sendBytes([0x1B, 0x5B, 0x7A]);\r\n\r\n      await disconnectFromUsb();\r\n\r\n      // wait for 6 seconds and attempt to reconnect to boot\r\n      await new Promise(resolve => setTimeout(resolve, 6000));\r\n      await connectToUsbInBoot();\r\n      await disconnectFromUsb();\r\n\r\n      window.Loading.hide();\r\n      await passTestActions();\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(412, '2022-11-02 13:07:10', 57, 1, 'Connect To Boot Firmware', 'Connect To Boot Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Please connect USB, serial, cash box, and power. Turn on device and start the test.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    try {\r\n      await connectToUsbInBoot();\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } catch (e) {\r\n      // Change over to boot if possible\r\n      await connectToUsb();\r\n\r\n      // Change to boot mode\r\n      window.Loading.show({\r\n        message: \'Switching to boot mode...\'\r\n      });\r\n      await window.genericUSB.sendBytes([0x1B, 0x5B, 0x7A]);\r\n\r\n      await disconnectFromUsb();\r\n\r\n      // wait for 2 seconds and attempt to reconnect to boot\r\n      await new Promise(resolve => setTimeout(resolve, 2000));\r\n      await connectToUsbInBoot();\r\n      await disconnectFromUsb();\r\n\r\n      window.Loading.hide();\r\n      await passTestActions();\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(413, '2022-11-02 13:17:17', 58, 1, 'Install Main Firmware', 'Install Main Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will install the main firmware onto the device.</p>', 'a', 1),
(414, '2022-11-02 13:37:57', 58, 1, 'Install Main Firmware', 'Install Main Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will install the main firmware onto the device.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsbInBoot();\r\n\r\n    window.Loading.show({\r\n      message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n    });\r\n\r\n    await updateFirmware (window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n\r\n    const readFirmware = await getFirmwareVersionAclUsb();\r\n    console.log(\'readFirmware\', readFirmware);\r\n\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n\r\n    if(window.selectedProduct.productConfig.firmwareVersion === readFirmware) {\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Firmware version does NOT match targetted version.\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(415, '2022-11-02 13:38:58', 58, 1, 'Install Main Firmware', 'Install Main Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will install the main firmware onto the device.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsbInBoot();\r\n\r\n    window.Loading.show({\r\n      message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n    });\r\n\r\n    await updateFirmwareFromBootUsb(window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n\r\n    const readFirmware = await getFirmwareVersionAclUsb();\r\n    console.log(\'readFirmware\', readFirmware);\r\n\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n\r\n    if(window.selectedProduct.productConfig.firmwareVersion === readFirmware) {\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Firmware version does NOT match targetted version.\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
