(419, '2022-11-02 14:14:01', 58, 1, 'Install Main Firmware', 'Install Main Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will install the main firmware onto the device.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsbInBoot();\r\n\r\n    window.Loading.show({\r\n      message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n    });\r\n\r\n    await updateFirmwareFromBootUsb(window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n\r\n    await switchToAclUsb();\r\n\r\n    const readFirmware = await getFirmwareVersionAclUsb();\r\n\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n\r\n    if(window.selectedProduct.productConfig.firmwareVersion == readFirmware) {\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Firmware version does NOT match targetted version.\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(420, '2022-11-02 14:16:03', 58, 1, 'Install Main Firmware', 'Install Main Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will install the main firmware onto the device.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsbInBoot();\r\n\r\n    window.Loading.show({\r\n      message: \'Updating firmware to \' + window.selectedProduct.productConfig.firmwareVersion\r\n    });\r\n\r\n    await updateFirmwareFromBootUsb(window.selectedProduct.serverUrl + \'uploads/firmwares/\' + window.selectedProduct.productConfig.firmware);\r\n\r\n    await switchToAclUsb();\r\n\r\n    const readFirmware = await getFirmwareVersionAclUsb();\r\n\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n\r\n    if(window.selectedProduct.productConfig.firmwareVersion == readFirmware) {\r\n      window.selectedProduct.productionResults.firmwareVersion = readFirmware;\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Firmware version does NOT match targetted version.\');\r\n    }\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(421, '2022-11-02 14:33:39', 59, 1, 'Configure Printer for Tests', 'Configure Printer for Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', 'a', 1),
(422, '2022-11-02 14:38:36', 59, 1, 'Configure Printer for Tests', 'Configure Printer for Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    console.log(window.selectedProduct.productConfig)\r\n\r\n    //await config\r\n\r\n    await disconnectFromUsb();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
