(424, '2022-11-02 14:59:26', 59, 1, 'Configure Printer for Tests', 'Configure Printer for Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n\r\n    await disconnectFromUsb();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(425, '2022-11-02 15:07:19', 59, 1, 'Configure Printer for Tests', 'Configure Printer for Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await disconnectFromUsb();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(426, '2022-11-02 15:13:18', 60, 1, 'Print on Receipt', 'Print on Receipt', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print on the receipt paper.</p>', 'a', 1),
(427, '2022-11-02 15:38:43', 60, 1, 'Print on Receipt', 'Print on Receipt', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print on the receipt paper.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await printLineViaUsb(\"PC Load Letter\", \'center\');\r\n    await window.genericUsb.sendBytes([0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A]);\r\n\r\n    await disconnectFromUsb();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(428, '2022-11-02 15:39:47', 60, 1, 'Print on Receipt', 'Print on Receipt', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print on the receipt paper.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await printLineViaUsb(\"PC Load Letter\", \'center\');\r\n    await window.genericUSB.sendBytes([0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A]);\r\n\r\n    await disconnectFromUsb();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(429, '2022-11-02 15:53:11', 60, 1, 'Print on Receipt', 'Print on Receipt', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print on the receipt paper.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await printLineViaUsb(\"PC Load Letter\", \'center\');\r\n    await window.genericUSB.sendBytes([0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A]);\r\n\r\n    await disconnectFromUsb();\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    // Have user determine if correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did \"PC Load Letter\" print on the receipt paper?\', \'User failed test\');\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(430, '2022-11-02 15:58:36', 61, 1, 'Switch To Serial', 'Switch To Serial', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will look for device on serial.</p>', 'a', 1),
(431, '2022-11-02 15:58:51', 59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await disconnectFromUsb();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(432, '2022-11-02 15:59:06', 60, 1, 'Print On Receipt', 'Print On Receipt', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print on the receipt paper.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await printLineViaUsb(\"PC Load Letter\", \'center\');\r\n    await window.genericUSB.sendBytes([0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A]);\r\n\r\n    await disconnectFromUsb();\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    // Have user determine if correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did \"PC Load Letter\" print on the receipt paper?\', \'User failed test\');\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(433, '2022-11-02 16:24:15', 61, 1, 'Switch To Serial', 'Switch To Serial', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will look for device on serial.</p>', 'function findDeviceOnSerial (attemptTimeInSec) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let timeLeft = attemptTimeInSec;\r\n      const attemptInterval = setInterval(async () => {\r\n        timeLeft--;\r\n        window.Loading.show({\r\n          message: \'Please disconnect USB and ensure serial is connected. Looking for device on serial. (\' + timeLeft + \' seconds remaining)\'\r\n        });\r\n\r\n        try {\r\n          let foundDevice = await isPrinterOnSerialAcl();\r\n          if (foundDevice.foundPrinter) {\r\n            clearInterval(attemptInterval);\r\n            window.selectedProduct.comPort = foundDevice.printerCom;\r\n            window.Loading.hide();\r\n            resolve();\r\n          }\r\n        } catch (e) {\r\n          window.Loading.hide();\r\n          clearInterval(attemptInterval);\r\n          reject(e);\r\n        }\r\n\r\n        if (timeLeft <= 0) {\r\n          clearInterval(attemptInterval);\r\n          window.Loading.hide();\r\n          reject(\'Never saw device on serial\')\r\n        }\r\n      }, 1000)\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await findDeviceOnSerial(30);\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(434, '2022-11-02 16:35:18', 59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(3, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await disconnectFromUsb();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(435, '2022-11-03 07:57:25', 59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(3, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await new Promise(resolve => setTimeout(resolve, 1000));\r\n    await window.genericRS232.sendBytes([0x10, 0x40]); // Reboot\r\n    await disconnectFromUsb();\r\n    await new Promise(resolve => setTimeout(resolve, 2000));\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
