(438, '2022-11-03 08:18:44', 59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await new Promise(resolve => setTimeout(resolve, 1000));\r\n    await window.genericRS232.sendBytes([0x10, 0x40]); // Reboot\r\n    await disconnectFromUsb();\r\n    await new Promise(resolve => setTimeout(resolve, 1000));\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(439, '2022-11-03 08:42:09', 61, 1, 'Switch To Serial', 'Switch To Serial', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will look for device on serial.</p>', 'function findDeviceOnSerial (attemptTimeInSec) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let timeLeft = attemptTimeInSec;\r\n      const attemptInterval = setInterval(async () => {\r\n        timeLeft--;\r\n        window.Loading.show({\r\n          message: \'Please disconnect USB and ensure serial is connected. Looking for device on serial. (\' + timeLeft + \' seconds remaining)\'\r\n        });\r\n\r\n        try {\r\n          let foundDevice = await isPrinterOnSerialAcl();\r\n          if (foundDevice.foundPrinter) {\r\n            clearInterval(attemptInterval);\r\n            window.selectedProduct.comPort = foundDevice.printerCom;\r\n            window.Loading.hide();\r\n            resolve();\r\n          }\r\n        } catch (e) {\r\n          window.Loading.hide();\r\n          clearInterval(attemptInterval);\r\n          reject(e);\r\n        }\r\n\r\n        if (timeLeft <= 0) {\r\n          clearInterval(attemptInterval);\r\n          window.Loading.hide();\r\n          reject(\'Never saw device on serial\')\r\n        }\r\n      }, 1000)\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await findDeviceOnSerial(30);\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(440, '2022-11-03 08:43:55', 61, 1, 'Switch To Serial', 'Switch To Serial', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will look for device on serial.</p>', 'function findDeviceOnSerial (attemptTimeInSec) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let timeLeft = attemptTimeInSec;\r\n      const attemptInterval = setInterval(async () => {\r\n        timeLeft--;\r\n        window.Loading.show({\r\n          message: \'Please disconnect USB and ensure serial is connected. Looking for device on serial. (\' + timeLeft + \' seconds remaining)\'\r\n        });\r\n\r\n        try {\r\n          let foundDevice = await isPrinterOnSerialAcl();\r\n          if (foundDevice.foundPrinter) {\r\n            clearInterval(attemptInterval);\r\n            window.selectedProduct.comPort = foundDevice.printerCom;\r\n            window.Loading.hide();\r\n            resolve();\r\n          }\r\n        } catch (e) {\r\n          window.Loading.hide();\r\n          clearInterval(attemptInterval);\r\n          reject(e);\r\n        }\r\n\r\n        if (timeLeft <= 0) {\r\n          clearInterval(attemptInterval);\r\n          window.Loading.hide();\r\n          reject(\'Never saw device on serial\')\r\n        }\r\n      }, 1000)\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await findDeviceOnSerial(30);\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(441, '2022-11-03 08:58:44', 57, 1, 'Connect To Boot Firmware', 'Connect To Boot Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Please connect USB, serial, cash box, and power. Turn on device and start the test.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    try {\r\n      await connectToUsbInBoot();\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } catch (e) {\r\n      // Change over to boot if possible\r\n      await connectToUsb();\r\n\r\n      // Change to boot mode\r\n      window.Loading.show({\r\n        message: \'Switching to boot mode...\'\r\n      });\r\n      await window.genericUSB.sendBytes([0x1B, 0x5B, 0x7A]);\r\n\r\n      await disconnectFromUsb();\r\n\r\n      // wait for 3 seconds and attempt to reconnect to boot\r\n      await new Promise(resolve => setTimeout(resolve, 3000));\r\n      await connectToUsbInBoot();\r\n      await disconnectFromUsb();\r\n\r\n      window.Loading.hide();\r\n      await passTestActions();\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(442, '2022-11-03 09:04:37', 59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    console.log(\'p1\')\r\n\r\n    await configCarriageReturnUsage(1);\r\n    console.log(\'p2\')\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await new Promise(resolve => setTimeout(resolve, 1000));\r\n    await window.genericRS232.sendBytes([0x10, 0x40]); // Reboot\r\n    await disconnectFromUsb();\r\n    await new Promise(resolve => setTimeout(resolve, 1000));\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
