(444, '2022-11-03 09:07:23', 59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await new Promise(resolve => setTimeout(resolve, 500));\r\n    await window.genericUSB.sendBytes([0x10, 0x40]); // Reboot\r\n    await disconnectFromUsb();\r\n    await new Promise(resolve => setTimeout(resolve, 2000));\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(445, '2022-11-03 09:13:42', 60, 1, 'Print On Receipt', 'Print On Receipt', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print on the receipt paper.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await printLineViaUsb(\"PC Load Letter\", \'center\');\r\n    await window.genericUSB.sendBytes([0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A]);\r\n\r\n    await disconnectFromUsb();\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    // Have user determine if correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did \"PC Load Letter\" print on the receipt paper?\', \'User failed test\');\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(446, '2022-11-03 09:17:07', 59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await new Promise(resolve => setTimeout(resolve, 500));\r\n    console.log(\'send reboot\')\r\n    await window.genericUSB.sendBytes([0x10, 0x40]); // Reboot\r\n    await disconnectFromUsb();\r\n    await new Promise(resolve => setTimeout(resolve, 2000));\r\n    console.log(\'after reboot\')\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(447, '2022-11-03 09:19:33', 59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Updating configuration and performing reboot\'\r\n    });\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await new Promise(resolve => setTimeout(resolve, 500));\r\n    console.log(\'send reboot\')\r\n    await window.genericUSB.sendBytes([0x10, 0x40]); // Reboot\r\n    await disconnectFromUsb();\r\n    await new Promise(resolve => setTimeout(resolve, 6000));\r\n    console.log(\'after reboot\')\r\n    window.Loading.hide();\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(448, '2022-11-03 09:20:46', 59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Updating configuration and performing reboot\'\r\n    });\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await new Promise(resolve => setTimeout(resolve, 500));\r\n    await window.genericUSB.sendBytes([0x10, 0x40]); // Reboot\r\n    await disconnectFromUsb();\r\n    await new Promise(resolve => setTimeout(resolve, 9000));\r\n    window.Loading.hide();\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(449, '2022-11-03 09:22:17', 60, 1, 'Print On Receipt', 'Print On Receipt', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print on the receipt paper.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    await printLineViaUsb(\"PC Load Letter\", \'center\');\r\n    await window.genericUSB.sendBytes([0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A,0x0A]);\r\n\r\n    await disconnectFromUsb();\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    // Have user determine if correct\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did \"PC Load Letter\" print on the receipt paper?\', \'User failed test\');\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(450, '2022-11-03 09:23:00', 59, 1, 'Configure Printer For Tests', 'Configure Printer For Tests', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure printer is set to a generic ACL mode.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Updating configuration and performing reboot\'\r\n    });\r\n\r\n    await configCarriageReturnUsage(1);\r\n    await configSoftFaultRecovery(0);\r\n    await configDefaultFont(0);\r\n    await configDefaultFontQuality(0);\r\n    await configDefaultInternationalCharacterSubstitution(0);\r\n    await configDefaultFontLarge(0);\r\n    await configDefaultCodePage(0);\r\n    await configDefaultLpi(17);\r\n    await configCommunications(6, 0, 0, 0, 1, 0, 2, 1);\r\n    await configMechType(parseInt(window.selectedProduct.productConfig.mechanismType));\r\n    await configOptionalFormTakenSensor(parseInt(window.selectedProduct.productConfig.hasFormTakenSensor));\r\n    await configFormInsertionWaitTime(0);\r\n    await configDefaultClampDelay(0);\r\n    await configWidePrintField(1);\r\n    await configInkjetDotCountReset(1);\r\n    await configVirtualDocumentStop(252);\r\n\r\n    await window.genericUSB.sendBytes([0x10, 0x40]); // Reboot\r\n    await disconnectFromUsb();\r\n    await new Promise(resolve => setTimeout(resolve, 9000));\r\n    window.Loading.hide();\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(451, '2022-11-03 09:24:01', 57, 1, 'Connect To Boot Firmware', 'Connect To Boot Firmware', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Please connect USB, serial, cash box, and power. Turn on device and start the test.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    try {\r\n      await connectToUsbInBoot();\r\n      await disconnectFromUsb();\r\n      await passTestActions();\r\n    } catch (e) {\r\n      // Change over to boot if possible\r\n      await connectToUsb();\r\n\r\n      // Change to boot mode\r\n      window.Loading.show({\r\n        message: \'Switching to boot mode...\'\r\n      });\r\n      await window.genericUSB.sendBytes([0x1B, 0x5B, 0x7A]);\r\n\r\n      await disconnectFromUsb();\r\n\r\n      // wait for 4 seconds and attempt to reconnect to boot\r\n      await new Promise(resolve => setTimeout(resolve, 4000));\r\n      await connectToUsbInBoot();\r\n      await disconnectFromUsb();\r\n\r\n      window.Loading.hide();\r\n      await passTestActions();\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(452, '2022-11-03 09:34:14', 62, 1, 'Print Validation', 'Print Validation', NULL, 'a', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await window.genericRS232.sendBytes([0x1B, 0x63, 0x30, 0x08]); // Validation form\r\n    await printLineViaSerial(\'All work and no play\');\r\n    await printLineViaSerial(\'makes Jack a dull boy\');\r\n    await printLineViaSerial(\'All work and no play\');\r\n    await printLineViaSerial(\'makes Jack a dull boy\');\r\n\r\n    await window.genericRS232.sendBytes([0x0C]) // Eject form\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(453, '2022-11-03 09:34:49', 62, 1, 'Print Validation', 'Print Validation', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print via validation.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    await window.genericRS232.sendBytes([0x1B, 0x63, 0x30, 0x08]); // Validation form\r\n    await printLineViaSerial(\'All work and no play\');\r\n    await printLineViaSerial(\'makes Jack a dull boy\');\r\n    await printLineViaSerial(\'All work and no play\');\r\n    await printLineViaSerial(\'makes Jack a dull boy\');\r\n\r\n    await window.genericRS232.sendBytes([0x0C]) // Eject form\r\n    \r\n    await passTestActions();\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
