(476, '2022-11-03 13:19:53', 63, 1, 'Cash Drawer', 'Cash Drawer', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will ensure the cash drawer port is operating as expected.</p>', 'function lookForCashDrawerSwitchPosition(desiredPosition, failAfterTimestamp, ledMessage) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // wait for 100ms\r\n      await new Promise(resolve => setTimeout(resolve, 100));\r\n\r\n      const currentTimestamp = Date.now();\r\n      if (currentTimestamp > failAfterTimestamp) {\r\n        window.Loading.hide();\r\n        reject(\'Never saw the cash drawer switch to the desired position\');\r\n      }\r\n\r\n      // get the current position of the cash drawer switch\r\n      await window.genericRS232.sendBytes([0x10, 0x04, 0x01]);\r\n      const response = await window.genericRS232.getBytes(1);\r\n      if (desiredPosition && (response[0] & 0x04)) {\r\n        resolve();\r\n      } else if (!desiredPosition && !(response[0] & 0x04)) {\r\n        resolve();\r\n      } else {\r\n        window.Loading.show({\r\n          message: `While looking for the ${ledMessage} LED, please flip the cash drawer switch`\r\n        });\r\n        try {\r\n          resolve(await lookForCashDrawerSwitchPosition(desiredPosition, failAfterTimestamp, ledMessage));\r\n        } catch (e) {\r\n          window.Loading.hide();\r\n          reject(e);\r\n        }\r\n      }\r\n    } catch (e) {\r\n      window.Loading.hide();\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Determine switch position\r\n    await window.genericRS232.sendBytes([0x10, 0x04, 0x01]);\r\n    const response = await window.genericRS232.getBytes(1);\r\n    let targetPosition = response[0] & 0x04 ? 0 : 1;\r\n\r\n    // Get current timestamp and add 15 seconds to it\r\n    let failAfterTimestamp = Date.now() + 15000;\r\n    await lookForCashDrawerSwitchPosition(targetPosition, failAfterTimestamp, \'Red\');\r\n\r\n    // Blink the red LED\r\n    await window.genericRS232.sendBytes([0x10, 0x14, 0x00, 0x0A, 0x0A]);\r\n\r\n    // Look for switch to change position\r\n    failAfterTimestamp = Date.now() + 15000;\r\n    await lookForCashDrawerSwitchPosition(targetPosition ? 0 : 1, failAfterTimestamp, \'Green\');\r\n\r\n    // Blink the green LED\r\n    await window.genericRS232.sendBytes([0x10, 0x14, 0x01, 0x0A, 0x0A]);\r\n    window.Loading.hide();\r\n\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n    `;\r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did both LEDs blink?\', \'User failed test\');\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n      await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
