(522, '2022-11-07 10:19:42', 72, 1, 'Close Up', 'Close Up', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will collect the bottom barcode, program serial number, and collect any tester notes.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please attach the barcode label to the bottom of the unit and then scan the serial number.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              const regex = /^[0-9]{8}$/;\r\n              return value.length === 8 && regex.test(value);\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function getTesterNotes() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Tester Notes\',\r\n        message: \'Please enter any notes about the unit being tested.\',\r\n        prompt: {\r\n          type: \'textarea\'\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled tester notes prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction programSerialNumber(serialNumber) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Determine USB driver class\r\n      if (parseInt(window.selectedProduct.productConfig.usbDriverClass) === 0) {\r\n        // Print driver\r\n        await connectToUsb();\r\n\r\n        // Determine PCL\r\n        if (parseInt(window.selectedProduct.productConfig.printerControlLanguage) === 1) {\r\n          // A470 Print Driver\r\n          await window.genericUSB.sendBytes([0x08, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericUSB.sendAndReceiveBytes([0x08, 0x49, 0x44], 10); // Get serial number back\r\n          if (rawBytes[0] === 0x20 && rawBytes[1] === 0x20 && rawBytes[2] === serialNumber.charCodeAt(0) && rawBytes[3] === serialNumber.charCodeAt(1) && rawBytes[4] === serialNumber.charCodeAt(2) && rawBytes[5] === serialNumber.charCodeAt(3) && rawBytes[6] === serialNumber.charCodeAt(4) && rawBytes[7] === serialNumber.charCodeAt(5) && rawBytes[8] === serialNumber.charCodeAt(6) && rawBytes[9] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        } else {\r\n          // ACL Print Driver\r\n          await window.genericUSB.sendBytes([0x1D, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericUSB.sendAndReceiveBytes([0x1D, 0x49, 0x23], 12); // Get serial number back\r\n          if (rawBytes[1] === 0x20 && rawBytes[2] === 0x20 && rawBytes[3] === serialNumber.charCodeAt(0) && rawBytes[4] === serialNumber.charCodeAt(1) && rawBytes[5] === serialNumber.charCodeAt(2) && rawBytes[6] === serialNumber.charCodeAt(3) && rawBytes[7] === serialNumber.charCodeAt(4) && rawBytes[8] === serialNumber.charCodeAt(5) && rawBytes[9] === serialNumber.charCodeAt(6) && rawBytes[10] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        }\r\n\r\n        await disconnectFromUsb();\r\n      } else {\r\n        // VirtualCom driver\r\n        await connectToVirtualCom();\r\n\r\n        // Determine PCL\r\n        if (parseInt(window.selectedProduct.productConfig.printerControlLanguage) === 1) {\r\n          // A470 VirtualCom\r\n          await window.genericRS232.sendBytes([0x08, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericRS232.sendAndReceiveBytes([0x08, 0x49, 0x44], 10); // Get serial number back\r\n          if (rawBytes[0] === 0x20 && rawBytes[1] === 0x20 && rawBytes[2] === serialNumber.charCodeAt(0) && rawBytes[3] === serialNumber.charCodeAt(1) && rawBytes[4] === serialNumber.charCodeAt(2) && rawBytes[5] === serialNumber.charCodeAt(3) && rawBytes[6] === serialNumber.charCodeAt(4) && rawBytes[7] === serialNumber.charCodeAt(5) && rawBytes[8] === serialNumber.charCodeAt(6) && rawBytes[9] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        } else {\r\n          // ACL VirtualCom\r\n          await window.genericRS232.sendBytes([0x1D, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericRS232.sendAndReceiveBytes([0x1D, 0x49, 0x23], 12); // Get serial number back\r\n          if (rawBytes[1] === 0x20 && rawBytes[2] === 0x20 && rawBytes[3] === serialNumber.charCodeAt(0) && rawBytes[4] === serialNumber.charCodeAt(1) && rawBytes[5] === serialNumber.charCodeAt(2) && rawBytes[6] === serialNumber.charCodeAt(3) && rawBytes[7] === serialNumber.charCodeAt(4) && rawBytes[8] === serialNumber.charCodeAt(5) && rawBytes[9] === serialNumber.charCodeAt(6) && rawBytes[10] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        }\r\n      }\r\n\r\n      // Get tester notes\r\n      window.selectedProduct.productionResults.testerNotes = await getTesterNotes();\r\n\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        // Update results\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                primarySerialNum: serialNumber,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                primarySerialNum: serialNumber,\r\n                analyticsResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n    } catch (e) {\r\n      if (parseInt(window.selectedProduct.productConfig.usbDriverClass) === 0) {\r\n        // Disconnect USB\r\n        await disconnectFromUsb();\r\n      }\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get bottom serial number\r\n    const serialNumber = await getBarcode();\r\n\r\n    // Prompt user to turn unit back on w/USB to program serial number\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div class=\"text-h5\">Instructions:</div>\r\n      <p>Please connect printer to computer via USB and ensure printer is turned on; then click \"Program Serial Number on Unit\" below.</p>\r\n      <div style=\"text-align: center; margin-top: 20px;\">\r\n        <button style=\"padding:5px 20px; margin:0 5px;\" onclick=\"programSerialNumber(\'${serialNumber}\')\">Program Serial Number on Unit</button>\r\n      </div>\r\n    `;\r\n  } catch (err) {\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(523, '2022-11-07 10:23:51', 62, 1, 'Print Validation (Serial)', 'Print Validation', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform a print via validation.</p>', 'function lookForFormTakenSensorChanges (failAfterTimestamp) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      let foundPaperInSensor = false;\r\n      let foundPaperRemovedFromSensor = false;\r\n\r\n      let checkInterval = setInterval(async () => {\r\n        let currentTimestamp = new Date().getTime();\r\n        if (currentTimestamp > failAfterTimestamp) {\r\n          clearInterval(checkInterval);\r\n          reject(\'Never found the form taken sensor changes\');\r\n        } else {\r\n          await window.genericRS232.sendBytes([0x10, 0x04, 0x0B]) // Request form taken status\r\n          const response = await window.genericRS232.getBytes(1);\r\n          if (!foundPaperInSensor && (response[0] & 0x20)) {\r\n            foundPaperInSensor = true;\r\n            window.Loading.show({\r\n              message: \'Looking for form to be taken...\'\r\n            });\r\n          } else if (foundPaperInSensor && !(response[0] & 0x20)) {\r\n            foundPaperRemovedFromSensor = true;\r\n          }\r\n\r\n          if (foundPaperInSensor && foundPaperRemovedFromSensor) {\r\n            clearInterval(checkInterval);\r\n            resolve();\r\n          }\r\n        }\r\n      }, 100);\r\n    } catch (e) {\r\n      reject(e)\r\n    }\r\n  })\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (parseInt(window.selectedProduct.productConfig.hasFormTakenSensor)) {\r\n      // This read should happen before form load, if it thinks a form is already loaded, sensor not working\r\n      await window.genericRS232.sendBytes([0x10, 0x04, 0x0B]) // Request form taken status\r\n      const response = await window.genericRS232.getBytes(1);\r\n      if (response[0] & 0x20) {\r\n        throw new Error(\'Form taken sensor already thinks a form is in its path. Is sensor present?\');\r\n      }\r\n    }\r\n\r\n    await window.genericRS232.sendBytes([0x1B, 0x63, 0x30, 0x08]); // Validation form\r\n    await printLineViaSerial(\'All work and no play\');\r\n    await printLineViaSerial(\'makes Jack a dull boy\');\r\n    await printLineViaSerial(\'All work and no play\');\r\n    await printLineViaSerial(\'makes Jack a dull boy\');\r\n\r\n    await window.genericRS232.sendBytes([0x0C]) // Eject form\r\n\r\n    if (parseInt(window.selectedProduct.productConfig.hasFormTakenSensor)) {\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div style=\"margin-top:30vh\">\r\n          <div class=\"text-h5\">Instructions:</div>\r\n          1. Load Form (will print text and eject)<br/>\r\n          2. Verify clamp opens only after form is removed.<br/>\r\n          3. Verify print quality\r\n        </div>\r\n\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n\r\n      // Get current timestamp and add 15 seconds to it\r\n      const failAfterTimestamp = Date.now() + 15000;\r\n      await lookForFormTakenSensorChanges(failAfterTimestamp);\r\n      window.Loading.hide();\r\n\r\n    } else {\r\n      document.getElementById(\'testWrapper\').innerHTML = `\r\n        <div style=\"margin-top:30vh\">\r\n          <div class=\"text-h5\">Instructions:</div>\r\n          1. Load Form (will print text and eject)<br/>\r\n          2. Verify print quality\r\n        </div>\r\n\r\n        <div id=\"userDecision\" style=\"text-align: center; font-size: 18px; font-family: ui-monospace; margin-top: 10px;\"></div>\r\n      `;\r\n    }\r\n    \r\n    document.getElementById(\'userDecision\').innerHTML = await userDecisionPrompt(\'Did text properly print on the loaded slip?\', \'User failed test\');\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n      await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(524, '2022-11-07 10:30:32', 67, 1, 'Load Cart and Paper', 'Load Cart and Paper', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Monitors sensors while user loads paper and ink cart.</p>', 'function checkDoorAndPaperSensors (timeoutValue) {\r\n  return new Promise (async (resolve, reject) => {\r\n    try {\r\n      let coverOpenFound = false;\r\n      let coverClosedFound = false;\r\n      let paperOutFound = false;\r\n      let paperInFound = false;\r\n\r\n      while (new Date().getTime() < timeoutValue && (!coverOpenFound || !coverClosedFound || !paperOutFound || !paperInFound)) {\r\n        // read sensors\r\n        const coverResponse = await window.genericUSB.sendAndReceiveBytes([0x10, 0x04, 0x02], 1);\r\n        if (coverResponse[0] & 0x04) {\r\n          coverOpenFound = true;\r\n        } else if (coverOpenFound) {\r\n          coverClosedFound = true;\r\n        }\r\n\r\n        const paperResponse = await window.genericUSB.sendAndReceiveBytes([0x10, 0x04, 0x04], 1);\r\n        if (paperResponse[0] & 0x20) {\r\n          paperOutFound = true;\r\n        } else if (paperOutFound) {\r\n          paperInFound = true;\r\n        }\r\n\r\n        // Wait 300 ms\r\n        await new Promise(resolve => setTimeout(resolve, 300));\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Please load ink cart and paper roll; if loading ribbon, verify that the ribbon moves.\'\r\n    });\r\n\r\n    await checkDoorAndPaperSensors(new Date().getTime() + 15000);\r\n    \r\n    await disconnectFromUsb();\r\n\r\n    // Wait for door close operations\r\n    await new Promise(resolve => setTimeout(resolve, 2000));\r\n\r\n    window.Loading.hide();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(525, '2022-11-07 12:15:02', 24, 3, 'Calibrate Double Feed', 'Calibrate Double Feed', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will calibrate the double feed sensor based upon customer target checks.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n    await window.api6100.openDevice();\r\n    await window.api6100.cortexSetDoubleFeedDetection(1);\r\n\r\n    // Find without paper loaded first\r\n    window.Loading.show({\r\n      message: \'Finding double feed sensor threshold...\'\r\n    });\r\n\r\n    const TARGET_NO_PAPER_MIN = 1\r\n    const TARGET_NO_PAPER_MAX = 0x28 // Default for single paper presence\r\n\r\n    let noPaperCutoff = TARGET_NO_PAPER_MAX; \r\n    let foundNoPaperCutoff = false;\r\n\r\n    while(!foundNoPaperCutoff && noPaperCutoff > TARGET_NO_PAPER_MIN) {\r\n      await window.api6100.cortexSetDoubleFeedTolerances(noPaperCutoff, 0x190, 0x12C, 0x00, 0x00); // 0x12C\r\n      let response = await window.api6100.getStatus();\r\n      if (response.ub_sens & 0b00100000) {\r\n        noPaperCutoff+=10 // Shift up to be trigger for single paper edge case\r\n        foundNoPaperCutoff = true; \r\n        break;\r\n      }\r\n      noPaperCutoff--;\r\n    }\r\n    window.Loading.hide();\r\n\r\n    if(foundNoPaperCutoff) {\r\n      // Good to find actual avg\r\n      // Set very wide window of acceptability to scan a single doc and a double doc\r\n      await window.api6100.cortexSetDoubleFeedTolerances(noPaperCutoff, 0x3FF, 0x12C, 0x00, 0x00);\r\n\r\n      // Single doc\r\n      await waitForDocumentLoad(true, \'Please load single check on right of the scan deck.\');\r\n      await window.api6100.performScan(0, 300, 0, 300);\r\n      await window.api6100.waitForScanComplete();\r\n      const response = await window.api6100.cortexGetDoubleFeedSensorScanAvg();\r\n      let midPoint = response.avgSensorValue\r\n      //let singlePaperValue = midPoint - ((midPoint - noPaperCutoff) >> 1)\r\nlet singlePaperValue = (noPaperCutoff - 10) + ((midPoint + (noPaperCutoff - 10)) >> 3)\r\n\r\n      // Double doc\r\n      await waitForDocumentLoad(true, \'Please load double stacked check on right of the scan deck.\');\r\n      await window.api6100.performScan(0, 300, 0, 300);\r\n      await window.api6100.waitForScanComplete();\r\n      const responseDouble = await window.api6100.cortexGetDoubleFeedSensorScanAvg();\r\n      let doublePaperValue = responseDouble.avgSensorValue - ((responseDouble.avgSensorValue - midPoint) >> 2)\r\n\r\n      // Set config\r\n      await window.api6100.cortexSetDoubleFeedTolerances(singlePaperValue, doublePaperValue, 0x12C, 0x00, 0x00);\r\n\r\n      await window.api6100.ejectDocument(0);\r\n\r\n      await window.api6100.closeDevice();\r\n\r\n      // Save cfg to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        window.selectedProduct.productionResults.doubleFeed = {\r\n          noPaperCutoff: (noPaperCutoff - 10),\r\n          singleAvg: midPoint,\r\n          doubleAvg: responseDouble.avgSensorValue,\r\n          singlePaperValue: singlePaperValue,\r\n          doublePaperValue: doublePaperValue\r\n        }\r\n        await window.axios.post(window.selectedProduct.serverUrl, \r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\nconst analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      }\r\n\r\n      //Pass test\r\n      await passTestActions();\r\n    } else {\r\n      await failTestActions(\'Unable to find double feed sensor threshold.\');\r\n    }\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_tests_archive` (`archiveId`, `generatedDateTime`, `testId`, `extProductId`, `title`, `appTitle`, `notes`, `codeset`, `script`, `active`) VALUES
(526, '2022-11-07 12:19:47', 2, 3, 'Configure For Board Test (Holtek Shading)', 'Configure For Board Test', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will set the hardware and software configuration in the device. At this stage the population specific config for the PCBA is set. A generic calibration table will be sent to the device in preparation of scanning documents.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Prepare configs\r\n    const hardwareConfig = [\r\n      1,\r\n      parseInt(window.selectedProduct.productConfig.topCis),\r\n      parseInt(window.selectedProduct.productConfig.bottomCis),\r\n      parseInt(window.selectedProduct.productConfig.hasMicr),\r\n      parseInt(window.selectedProduct.productConfig.hasStamp),\r\n      parseInt(window.selectedProduct.productConfig.hasWatermark),\r\n      0,\r\n      parseInt(window.selectedProduct.productConfig.entrySensorType),\r\n      parseInt(window.selectedProduct.productConfig.midfieldType) | parseInt(window.selectedProduct.productConfig.holtekType) | parseInt(window.selectedProduct.productConfig.stepperType),\r\n      0\r\n    ];\r\n\r\n    const softwareConfig = [\r\n      0,\r\n      parseInt(window.selectedProduct.productConfig.hasEncryption),\r\n      0,\r\n      0,\r\n      0,\r\n      0,\r\n      0,\r\n      0\r\n    ];\r\n\r\n    window.Loading.show({\r\n      message: \'Configuring hardware...\'\r\n    });\r\n\r\n    await window.api6100.openDevice();\r\n    await window.api6100.cortexSetScannerHardware(hardwareConfig);\r\n    await window.api6100.cortexSetScannerSoftware(softwareConfig);\r\n    await window.api6100.cortexSetUSBDescriptorMode(parseInt(window.selectedProduct.productConfig.usbDescriptor));\r\n    await window.api6100.cortexSetSkew(parseInt(window.selectedProduct.productConfig.skewTolerance), parseInt(window.selectedProduct.productConfig.skewReject));\r\n\r\n    // Pull generic shading tables\r\n    await setCalibrationTable(window.selectedProduct.serverUrl + \'uploads/calibrations/pcba.dat\');\r\n\r\n    await window.api6100.closeDevice();\r\n    window.Loading.hide();\r\n    document.getElementById(\'testWrapper\').innerHTML = \'<p>Configured scanner.</p>\';\r\n    passTestActions();\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    failTestActions(err);\r\n  }\r\n})();', 1),
(527, '2022-11-07 12:21:04', 73, 3, 'Configure For Board Test (AD Shading)', 'Configure For Board Test', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will set the hardware and software configuration in the device. At this stage the population specific config for the PCBA is set. A generic calibration table will be sent to the device in preparation of scanning documents.</p>', 'a', 1),
(528, '2022-11-07 12:21:42', 73, 3, 'Configure For Board Test (AD Shading)', 'Configure For Board Test', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will set the hardware and software configuration in the device. At this stage the population specific config for the PCBA is set. A generic calibration table will be sent to the device in preparation of scanning documents.</p>', '(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Prepare configs\r\n    const hardwareConfig = [\r\n      1,\r\n      parseInt(window.selectedProduct.productConfig.topCis),\r\n      parseInt(window.selectedProduct.productConfig.bottomCis),\r\n      parseInt(window.selectedProduct.productConfig.hasMicr),\r\n      parseInt(window.selectedProduct.productConfig.hasStamp),\r\n      parseInt(window.selectedProduct.productConfig.hasWatermark),\r\n      0,\r\n      parseInt(window.selectedProduct.productConfig.entrySensorType),\r\n      parseInt(window.selectedProduct.productConfig.midfieldType) | parseInt(window.selectedProduct.productConfig.holtekType) | parseInt(window.selectedProduct.productConfig.stepperType),\r\n      0\r\n    ];\r\n\r\n    const softwareConfig = [\r\n      0,\r\n      parseInt(window.selectedProduct.productConfig.hasEncryption),\r\n      0,\r\n      0,\r\n      0,\r\n      0,\r\n      0,\r\n      0\r\n    ];\r\n\r\n    window.Loading.show({\r\n      message: \'Configuring hardware...\'\r\n    });\r\n\r\n    await window.api6100.openDevice();\r\n    await window.api6100.cortexSetScannerHardware(hardwareConfig);\r\n    await window.api6100.cortexSetScannerSoftware(softwareConfig);\r\n    await window.api6100.cortexSetUSBDescriptorMode(parseInt(window.selectedProduct.productConfig.usbDescriptor));\r\n    await window.api6100.cortexSetSkew(parseInt(window.selectedProduct.productConfig.skewTolerance), parseInt(window.selectedProduct.productConfig.skewReject));\r\n\r\n    // Pull generic shading tables\r\n    await setCalibrationTable(window.selectedProduct.serverUrl + \'uploads/calibrations/pcba-pop1.dat\');\r\n\r\n    await window.api6100.closeDevice();\r\n    window.Loading.hide();\r\n    document.getElementById(\'testWrapper\').innerHTML = \'<p>Configured scanner.</p>\';\r\n    passTestActions();\r\n  } catch (err) {\r\n    window.Loading.hide();\r\n    failTestActions(err);\r\n  }\r\n})();', 1),
(529, '2022-11-07 14:42:31', 72, 1, 'Close Up', 'Close Up', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will collect the bottom barcode, program serial number, and collect any tester notes.</p>', 'async function getBarcode() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Barcode Scan\',\r\n        message: \'Please attach the barcode label to the bottom of the unit and then scan the serial number.\',\r\n        prompt: {\r\n          type: \'text\',\r\n          isValid: (value) => {\r\n            if (value) {\r\n              const regex = /^[0-9]{8}$/;\r\n              return value.length === 8 && regex.test(value);\r\n            } else {\r\n              return false;\r\n            }\r\n          }\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled barcode prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function getTesterNotes() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Tester Notes\',\r\n        message: \'Please enter any notes about the unit being tested.\',\r\n        prompt: {\r\n          type: \'textarea\'\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled tester notes prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nfunction programSerialNumber(serialNumber) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      // Determine USB driver class\r\n      if (parseInt(window.selectedProduct.productConfig.usbDriverClass) === 0) {\r\n        // Print driver\r\n        await connectToUsb();\r\n\r\n        // Determine PCL\r\n        if (parseInt(window.selectedProduct.productConfig.printerControlLanguage) === 1) {\r\n          // A470 Print Driver\r\n          await window.genericUSB.sendBytes([0x08, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericUSB.sendAndReceiveBytes([0x08, 0x49, 0x44], 10); // Get serial number back\r\n          if (rawBytes[0] === 0x20 && rawBytes[1] === 0x20 && rawBytes[2] === serialNumber.charCodeAt(0) && rawBytes[3] === serialNumber.charCodeAt(1) && rawBytes[4] === serialNumber.charCodeAt(2) && rawBytes[5] === serialNumber.charCodeAt(3) && rawBytes[6] === serialNumber.charCodeAt(4) && rawBytes[7] === serialNumber.charCodeAt(5) && rawBytes[8] === serialNumber.charCodeAt(6) && rawBytes[9] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        } else {\r\n          // ACL Print Driver\r\n          await window.genericUSB.sendBytes([0x1D, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericUSB.sendAndReceiveBytes([0x1D, 0x49, 0x23], 12); // Get serial number back\r\n          if (rawBytes[1] === 0x20 && rawBytes[2] === 0x20 && rawBytes[3] === serialNumber.charCodeAt(0) && rawBytes[4] === serialNumber.charCodeAt(1) && rawBytes[5] === serialNumber.charCodeAt(2) && rawBytes[6] === serialNumber.charCodeAt(3) && rawBytes[7] === serialNumber.charCodeAt(4) && rawBytes[8] === serialNumber.charCodeAt(5) && rawBytes[9] === serialNumber.charCodeAt(6) && rawBytes[10] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        }\r\n\r\n        await disconnectFromUsb();\r\n      } else {\r\n        // VirtualCom driver\r\n        await connectToVirtualCom();\r\n\r\n        // Determine PCL\r\n        if (parseInt(window.selectedProduct.productConfig.printerControlLanguage) === 1) {\r\n          // A470 VirtualCom\r\n          await window.genericRS232.sendBytes([0x08, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericRS232.sendAndReceiveBytes([0x08, 0x49, 0x44], 10); // Get serial number back\r\n          if (rawBytes[0] === 0x20 && rawBytes[1] === 0x20 && rawBytes[2] === serialNumber.charCodeAt(0) && rawBytes[3] === serialNumber.charCodeAt(1) && rawBytes[4] === serialNumber.charCodeAt(2) && rawBytes[5] === serialNumber.charCodeAt(3) && rawBytes[6] === serialNumber.charCodeAt(4) && rawBytes[7] === serialNumber.charCodeAt(5) && rawBytes[8] === serialNumber.charCodeAt(6) && rawBytes[9] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        } else {\r\n          // ACL VirtualCom\r\n          await window.genericRS232.sendBytes([0x1D, 0x49, 0x21, 0x20, 0x20, serialNumber.charCodeAt(0), serialNumber.charCodeAt(1), serialNumber.charCodeAt(2), serialNumber.charCodeAt(3), serialNumber.charCodeAt(4), serialNumber.charCodeAt(5), serialNumber.charCodeAt(6), serialNumber.charCodeAt(7)]); // Set serial number\r\n          const rawBytes = await window.genericRS232.sendAndReceiveBytes([0x1D, 0x49, 0x23], 12); // Get serial number back\r\n          if (rawBytes[1] === 0x20 && rawBytes[2] === 0x20 && rawBytes[3] === serialNumber.charCodeAt(0) && rawBytes[4] === serialNumber.charCodeAt(1) && rawBytes[5] === serialNumber.charCodeAt(2) && rawBytes[6] === serialNumber.charCodeAt(3) && rawBytes[7] === serialNumber.charCodeAt(4) && rawBytes[8] === serialNumber.charCodeAt(5) && rawBytes[9] === serialNumber.charCodeAt(6) && rawBytes[10] === serialNumber.charCodeAt(7)) {\r\n            resolve();\r\n          } else {\r\n            throw new Error(\'Failed to program serial number\');\r\n          }\r\n        }\r\n      }\r\n\r\n      // Get tester notes\r\n      window.selectedProduct.productionResults.testerNotes = await getTesterNotes();\r\n\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        // Update results\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                primarySerialNum: serialNumber,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tla: window.selectedProduct.productConfig.tla\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                primarySerialNum: serialNumber,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tla: window.selectedProduct.productConfig.tla\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n    } catch (e) {\r\n      if (parseInt(window.selectedProduct.productConfig.usbDriverClass) === 0) {\r\n        // Disconnect USB\r\n        await disconnectFromUsb();\r\n      }\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get bottom serial number\r\n    const serialNumber = await getBarcode();\r\n\r\n    // Prompt user to turn unit back on w/USB to program serial number\r\n    document.getElementById(\'testWrapper\').innerHTML = `\r\n      <div class=\"text-h5\">Instructions:</div>\r\n      <p>Please connect printer to computer via USB and ensure printer is turned on; then click \"Program Serial Number on Unit\" below.</p>\r\n      <div style=\"text-align: center; margin-top: 20px;\">\r\n        <button style=\"padding:5px 20px; margin:0 5px;\" onclick=\"programSerialNumber(\'${serialNumber}\')\">Program Serial Number on Unit</button>\r\n      </div>\r\n    `;\r\n  } catch (err) {\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(530, '2022-11-08 08:09:19', 74, 1, 'Load Cart (Validation Only)', 'Load Cart', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>Monitors sensors while user loads ink cart.</p>', 'function checkDoorSensor (timeoutValue) {\r\n  return new Promise (async (resolve, reject) => {\r\n    try {\r\n      let coverOpenFound = false;\r\n      let coverClosedFound = false;\r\n\r\n      while (new Date().getTime() < timeoutValue && (!coverOpenFound || !coverClosedFound)) {\r\n        // read sensors\r\n        const coverResponse = await window.genericUSB.sendAndReceiveBytes([0x10, 0x04, 0x02], 1);\r\n        if (coverResponse[0] & 0x04) {\r\n          coverOpenFound = true;\r\n        } else if (coverOpenFound) {\r\n          coverClosedFound = true;\r\n        }\r\n\r\n        // Wait 300 ms\r\n        await new Promise(resolve => setTimeout(resolve, 300));\r\n      }\r\n      resolve();\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n    await connectToUsb();\r\n\r\n    window.Loading.show({\r\n      message: \'Please load ink cart; if loading ribbon, verify that the ribbon moves.\'\r\n    });\r\n\r\n    await checkDoorSensor(new Date().getTime() + 15000);\r\n    \r\n    await disconnectFromUsb();\r\n\r\n    // Wait for door close operations\r\n    await new Promise(resolve => setTimeout(resolve, 2000));\r\n\r\n    window.Loading.hide();\r\n    await passTestActions();\r\n  } catch (err) {\r\n    await disconnectFromUsb();\r\n    window.Loading.hide();\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(531, '2022-11-08 09:26:46', 75, 4, 'Tester Notes', 'Tester Notes', NULL, '', '// ---------------------------------------------------------- //\r\nasync function getTesterNotes() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Tester Notes\',\r\n        message: \'Please enter any notes about the unit being tested.\',\r\n        prompt: {\r\n          type: \'textarea\'\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled tester notes prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get tester notes\r\n    window.selectedProduct.productionResults.testerNotes = await getTesterNotes();\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              primarySerialNum: serialNumber,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              primarySerialNum: serialNumber,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(532, '2022-11-08 09:27:15', 75, 4, 'Tester Notes', 'Tester Notes', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will any notes from the tester.</p>', '// ---------------------------------------------------------- //\r\nasync function getTesterNotes() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      window.Dialog.create({\r\n        title: \'Tester Notes\',\r\n        message: \'Please enter any notes about the unit being tested.\',\r\n        prompt: {\r\n          type: \'textarea\'\r\n        }\r\n      }).onOk(async (value) => {\r\n        resolve(value);\r\n      }).onCancel(() => {\r\n        reject(\'User cancelled tester notes prompt\');\r\n      });\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    // Get tester notes\r\n    window.selectedProduct.productionResults.testerNotes = await getTesterNotes();\r\n\r\n    if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n      // Update results\r\n      const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              productionId: window.selectedProduct.productionId,\r\n              primarySerialNum: serialNumber,\r\n              productionResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n      const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n        {\r\n          query: {\r\n            dataset: \"productionTracking\",\r\n            action: \"updateProduction\",\r\n            params: {\r\n              analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n              primarySerialNum: serialNumber,\r\n              analyticsResults: window.selectedProduct.productionResults\r\n            }\r\n          }\r\n        },\r\n        { headers: { \"Content-Type\": \"application/json\" }}\r\n      );\r\n    }\r\n\r\n    await passTestActions();\r\n  } catch (err) {\r\n    if (err.message) {\r\n      await failTestActions(err.message);\r\n    } else {\r\n     await failTestActions(err);\r\n    }\r\n  }\r\n})();', 1),
(533, '2022-11-08 11:28:59', 36, 4, 'Calibrate VCSEL (Potentiometer)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', 'IDEAL_VOLTAGE = 1.65;\r\nMIN_COLLECTOR_VAL = 100;\r\nMAX_COLLECTOR_VAL = 127;\r\nMIN_TRANSMITTER_VAL = 110;\r\nMAX_TRANSMITTER_VAL = 127;\r\n\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findCollectorValue (collectorValue, lastVoltage) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (collectorValue < MIN_COLLECTOR_VAL || collectorValue > MAX_COLLECTOR_VAL) {\r\n        reject(\'Could not find good collector value\');\r\n      }\r\n\r\n      await setCollectorPot(collectorValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        let newValue = collectorValue + 1;\r\n        if (voltage < 1.2) {\r\n          newValue+=2; // Extra increment to speed up when far off ideal\r\n        } else if (voltage < 1.4) {\r\n          newValue++; // Extra increment to speed up when far off ideal\r\n        }\r\n        resolve(await findCollectorValue(newValue, voltage));\r\n      } else {\r\n        // Determine if last reading was closer to ideal voltage\r\n        if (Math.abs(IDEAL_VOLTAGE - lastVoltage) < Math.abs(voltage - IDEAL_VOLTAGE)) {\r\n          // Last reading was closer to ideal voltage\r\n          const oldValue = collectorValue - 1;\r\n          await setCollectorPot(oldValue);\r\n          await waitForReadingToStabilize(3);\r\n          await drawProcessing();\r\n          resolve(oldValue);\r\n        } else {\r\n          resolve(collectorValue);\r\n        }\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: collector,\r\n        transmitter: emitter,\r\n        voltage: voltage\r\n      });\r\n\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.testsRan = [];\r\n\r\n      await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n      let collectorValue = await findCollectorValue(MIN_COLLECTOR_VAL, voltage);\r\n\r\n      // Found good value, save to NV RAM\r\n      await setTransmitterPotNV(transmitterValue);\r\n      await setCollectorPotNV(collectorValue);\r\n\r\n      // Perform serialization\r\n      let serialNumber = await getSerialNumber();\r\n      if (serialNumber == 0) {\r\n        // Request new serial number from server\r\n        const serialResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"printer7680\",\r\n              action: \"getNextVcselSerialNumber\",\r\n              params: {}\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (serialResponse.data.success) {\r\n          // Set Serial Number\r\n          await setSerialNumber(parseInt(serialResponse.data.serialNumber));\r\n\r\n          // Get Serial Number\r\n          serialNumber = await getSerialNumber();\r\nif (serialNumber !== parseInt(serialResponse.data.serialNumber)) {\r\nthrow new Error(\'Could not program serial number\');\r\n}\r\n        } else {\r\n          throw new Error(\'Could not get serial number from server\');\r\n        }\r\n      }\r\n\r\n      window.selectedProduct.productionResults.serialNumber = serialNumber;\r\n      window.selectedProduct.productionResults.collectorNV = await getCollectorPotNV();\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.currentCollectorValue = collectorValue;\r\n      window.selectedProduct.productionResults.currentTransmitterValue = transmitterValue;\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n\r\n      // Rerun the test\r\n      await reRunTests();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1),
(534, '2022-11-08 11:29:26', 37, 4, 'Calibrate VCSEL (Rheostat)', 'Calibrate VCSEL', NULL, '<div class=\"text-h5\">Overview:</div>\r\n<p>This test will perform calibration of the VCSEL.</p>', 'IDEAL_VOLTAGE = 1.65;\r\nMIN_COLLECTOR_VAL = 27;\r\nMAX_COLLECTOR_VAL = 0;\r\nMIN_TRANSMITTER_VAL = 110;\r\nMAX_TRANSMITTER_VAL = 127;\r\n\r\n// -------------------------------------------------------- //\r\nfunction findTransmitterValue (transmitterValue) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (transmitterValue < MIN_TRANSMITTER_VAL || transmitterValue > MAX_TRANSMITTER_VAL) {\r\n        reject(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        const newValue = transmitterValue - 1;\r\n        resolve(await findTransmitterValue(newValue));\r\n      } else {\r\n        resolve(transmitterValue);\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction findCollectorValue (collectorValue, lastVoltage) { // Note: Reverse direction of values for Rheostat\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      if (collectorValue < MIN_COLLECTOR_VAL || collectorValue > MAX_COLLECTOR_VAL) {\r\n        reject(\'Could not find good collector value\');\r\n      }\r\n\r\n      await setCollectorPot(collectorValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      if (voltage < IDEAL_VOLTAGE) {\r\n        let newValue = collectorValue - 1;\r\n        if (voltage < 1.2) {\r\n          newValue-=2; // Extra increment to speed up when far off ideal\r\n        } else if (voltage < 1.4) {\r\n          newValue--; // Extra increment to speed up when far off ideal\r\n        }\r\n        resolve(await findCollectorValue(newValue, voltage));\r\n      } else {\r\n        // Determine if last reading was closer to ideal voltage\r\n        if (Math.abs(IDEAL_VOLTAGE - lastVoltage) < Math.abs(voltage - IDEAL_VOLTAGE)) {\r\n          // Last reading was closer to ideal voltage\r\n          const oldValue = collectorValue - 1;\r\n          await setCollectorPot(oldValue);\r\n          await waitForReadingToStabilize(3);\r\n          await drawProcessing();\r\n          resolve(oldValue);\r\n        } else {\r\n          resolve(collectorValue);\r\n        }\r\n      }\r\n\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction drawProcessing () {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const collector = await getCurrentCollectorValue();\r\n      const emitter = await getCurrentTransmitterValue();\r\n      const voltage = await getCollectorVoltage();\r\n      document.getElementById(\'testWrapper\').innerHTML = drawGauge(emitter, collector, voltage);\r\n\r\n      window.selectedProduct.productionResults.testsRan.push({\r\n        collector: collector,\r\n        transmitter: emitter,\r\n        voltage: voltage\r\n      });\r\n\r\n      resolve(voltage);\r\n    } catch (err) {\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\nfunction lookForBoardConnected(secondsToLook) {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      let countDown = secondsToLook * 10;\r\n      const watchInterval = setInterval(async () => {\r\n        if (!window.selectedProduct.comPort) { // This occurs when user goes back to the products page\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'Test Aborted\');\r\n        }\r\n\r\n\r\n        let message = \'Waiting for board to be connected. (\' + Math.round(countDown / 10) + \' seconds remaining)\';\r\n\r\n        window.Loading.show({\r\n          message: message\r\n        });\r\n\r\n        if (countDown === 0) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          reject(\'No board detected\');\r\n        }\r\n\r\n        let boardConnectedResponse = await isBoardConnected();\r\n        if(boardConnectedResponse.boardConnected) {\r\n          clearInterval(watchInterval);\r\n          window.Loading.hide();\r\n          resolve(boardConnectedResponse.collectorValue);\r\n        }\r\n\r\n        countDown -= 1;\r\n      }, 100);\r\n    } catch (err) {\r\n      window.Loading.hide();\r\n      reject(err);\r\n    }\r\n  });\r\n}\r\n// -------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    startTestActions();\r\n\r\n    if (window.selectedProduct.comPort && window.selectedProduct.fixtureSerialNumber) {\r\n      window.selectedProduct.productionResults.fixtureSerialNumber = window.selectedProduct.fixtureSerialNumber;\r\n\r\n      window.selectedProduct.productionResults.testsRan = [];\r\n\r\n      await lookForBoardConnected(30);\r\n      await setCollectorPot(MIN_COLLECTOR_VAL);\r\n\r\n\r\n\r\n      // Found good value, save to NV RAM\r\n      await setTransmitterPotNV(transmitterValue);\r\n      await setCollectorPotNV(collectorValue);\r\n\r\n      // Shift transmitter value until above ideal voltage\r\n      let transmitterValue = await findTransmitterValue(MAX_TRANSMITTER_VAL);\r\n      if (transmitterValue === MAX_TRANSMITTER_VAL) {\r\n        throw new Error(\'Could not find good transmitter value\');\r\n      }\r\n\r\n      // Shift transmitter up one back to good value\r\n      transmitterValue += 1;\r\n      await setTransmitterPot(transmitterValue);\r\n      await waitForReadingToStabilize(3);\r\n      const voltage = await drawProcessing();\r\n\r\n      // Shift collector value until as close to ideal voltage as possible\r\n      let collectorValue = await findCollectorValue(MIN_COLLECTOR_VAL, voltage);\r\n\r\n      // Perform serialization\r\n      let serialNumber = await getSerialNumber();\r\n      if (serialNumber == 0) {\r\n        // Request new serial number from server\r\n        const serialResponse = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"printer7680\",\r\n              action: \"getNextVcselSerialNumber\",\r\n              params: {}\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n\r\n        if (serialResponse.data.success) {\r\n          // Set Serial Number\r\n          await setSerialNumber(parseInt(serialResponse.data.serialNumber));\r\n\r\n          // Get Serial Number\r\n          serialNumber = await getSerialNumber();\r\nif (serialNumber !== parseInt(serialResponse.data.serialNumber)) {\r\nthrow new Error(\'Could not program serial number\');\r\n}\r\n        } else {\r\n          throw new Error(\'Could not get serial number from server\');\r\n        }\r\n      }\r\n\r\n      window.selectedProduct.productionResults.serialNumber = serialNumber;\r\n      window.selectedProduct.productionResults.collectorNV = await getCollectorPotNV();\r\n      window.selectedProduct.productionResults.transmitterNV = await getTransmitterPotNV();\r\n      window.selectedProduct.productionResults.currentCollectorValue = collectorValue;\r\n      window.selectedProduct.productionResults.currentTransmitterValue = transmitterValue;\r\n      window.selectedProduct.productionResults.currentCollectorVoltageReading = await getCollectorVoltage();\r\n\r\n      // Save info to server\r\n      if (window.selectedProduct.productionId && window.selectedProduct.productionId > 0) {\r\n        const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                productionId: window.selectedProduct.productionId,\r\n                productionResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n        const analyticsResponse = await window.axios.post(window.analyticsServer,\r\n          {\r\n            query: {\r\n              dataset: \"productionTracking\",\r\n              action: \"updateProduction\",\r\n              params: {\r\n                analyticsProductionId: window.selectedProduct.analyticsProductionId,\r\n                analyticsResults: window.selectedProduct.productionResults,\r\n                tertiarySerialNum: window.selectedProduct.productionResults.serialNumber\r\n              }\r\n            }\r\n          },\r\n          { headers: { \"Content-Type\": \"application/json\" }}\r\n        );\r\n      }\r\n\r\n      await passTestActions();\r\n\r\n      // Rerun the test\r\n      await reRunTests();\r\n    } else {\r\n      await failTestActions(\'Fixture has not been found yet.\');\r\n    }\r\n  } catch (err) {\r\n    await failTestActions(err);\r\n  }\r\n})();', 1);
INSERT INTO `prod_v2_test_sets` (`testSetId`, `extProductId`, `title`, `extTemplateId`, `extApiId`, `configureProduct`, `extFirmwareId`, `productConfig`, `description`, `script`, `active`) VALUES
(1, 3, 'PCB Rev 4-6 Population 0', 4, 2, 1, 4, '{\"topCis\":\"6\",\"bottomCis\":\"6\",\"hasMicr\":\"1\",\"hasStamp\":\"1\",\"hasWatermark\":\"0\",\"entrySensorType\":\"0\",\"hasEncryption\":\"0\",\"usbDescriptor\":\"0\",\"skewTolerance\":\"1\",\"skewReject\":\"0\",\"holtekType\":\"0\",\"midfieldType\":\"0\",\"stepperType\":\"0\",\"tlaNumber\":\"612611-030C\"}', '<p>This will test a board that is populated with:</p>\r\n<ul>\r\n<li>Holtek Imaging Sensor</li>\r\n<li>Allegro A4984 Stepper Driver</li>\r\n<li>Standard Mid-Field Sensor</li>\r\n</ul>', '', 1),
(2, 3, 'PCB Rev 4-6 Population 1', 4, 2, 1, 4, '{\"topCis\":\"6\",\"bottomCis\":\"6\",\"hasMicr\":\"1\",\"hasStamp\":\"1\",\"hasWatermark\":\"0\",\"entrySensorType\":\"0\",\"hasEncryption\":\"0\",\"usbDescriptor\":\"0\",\"skewTolerance\":\"1\",\"skewReject\":\"0\",\"holtekType\":\"2\",\"midfieldType\":\"0\",\"stepperType\":\"4\",\"tlaNumber\":\"612611-030C\"}', '<p>This will test a board that is populated with:</p>\r\n<ul>\r\n<li>AD9822 Imaging Sensor</li>\r\n<li>MPS6500A Stepper Driver</li>\r\n<li>Standard Mid-Field Sensor</li>\r\n</ul>', '', 1),
(3, 3, 'PCB Rev 5-6 Population 2', 4, 2, 1, 12, '{\"topCis\":\"6\",\"bottomCis\":\"6\",\"hasMicr\":\"1\",\"hasStamp\":\"1\",\"hasWatermark\":\"0\",\"entrySensorType\":\"0\",\"hasEncryption\":\"0\",\"usbDescriptor\":\"0\",\"skewTolerance\":\"1\",\"skewReject\":\"0\",\"holtekType\":\"2\",\"midfieldType\":\"1\",\"stepperType\":\"4\",\"tlaNumber\":\"612611-032C\"}', '<p>This will test a board that is populated with:</p>\r\n<ul>\r\n<li>AD9822 Imaging Sensor</li>\r\n<li>MPS6500A Stepper Driver</li>\r\n<li>Double Feed Mid-Field Sensor</li>\r\n</ul>', '', 1),
(4, 3, 'PCB Rev 5-6 Population 3', 4, 2, 1, 12, '{\"topCis\":\"6\",\"bottomCis\":\"6\",\"hasMicr\":\"1\",\"hasStamp\":\"1\",\"hasWatermark\":\"0\",\"entrySensorType\":\"0\",\"hasEncryption\":\"0\",\"usbDescriptor\":\"0\",\"skewTolerance\":\"1\",\"skewReject\":\"0\",\"holtekType\":\"0\",\"midfieldType\":\"1\",\"stepperType\":\"0\",\"tlaNumber\":\"612611-032C\"}', '<p>This will test a board that is populated with:</p>\r\n<ul>\r\n<li>Holtek Imaging Sensor</li>\r\n<li>Allegro A4984 Stepper Driver</li>\r\n<li>Double Feed Mid-Field Sensor</li>\r\n</ul>', '', 1),
(5, 3, 'PCB Rev 7', 4, 2, 0, 0, '[]', '<p>This will test a revision 7 board.</p>', '', 0),
(8, 3, 'Calibrate 612611-030C', 3, 2, 1, 4, '{\"topCis\":\"6\",\"bottomCis\":\"6\",\"hasMicr\":\"1\",\"hasStamp\":\"1\",\"hasWatermark\":\"0\",\"entrySensorType\":\"0\",\"hasEncryption\":\"0\",\"usbDescriptor\":\"0\",\"skewTolerance\":\"2\",\"skewReject\":\"0\",\"holtekType\":\"0\",\"midfieldType\":\"0\",\"stepperType\":\"0\",\"tlaNumber\":\"612611-030C\"}', '', '', 1),
(9, 3, 'Final Test: 612611-030C', 4, 2, 1, 4, '{\"topCis\":\"6\",\"bottomCis\":\"6\",\"hasMicr\":\"1\",\"hasStamp\":\"1\",\"hasWatermark\":\"0\",\"entrySensorType\":\"0\",\"hasEncryption\":\"0\",\"usbDescriptor\":\"0\",\"skewTolerance\":\"2\",\"skewReject\":\"0\",\"holtekType\":\"0\",\"midfieldType\":\"0\",\"stepperType\":\"0\",\"tlaNumber\":\"612611-030C\"}', '<p>This will perform the final test of the selected TLA.</p>', '', 1),
(10, 3, '6100 Generate Label', 5, 5, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 10) {\r\n    window.Dialog.create({\r\n      title: \"TLA is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 10 digits.\",\r\n    });\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 9) {\r\n    window.Dialog.create({\r\n      title: \"Serial number is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 9 digits.\",\r\n    });\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"scanner6100\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          serial: window.selectedProduct.scanInfo.serial,\r\n          tla: window.selectedProduct.scanInfo.tla\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    await printLabel();\r\n\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    showTlaPrompt();\r\n  } else {\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n    showTlaPrompt();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function printLabel() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.serial);\r\n      const tlaImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.tla);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(tlaImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'TLA: \', 10, 72);\r\n      window.pdf.text(window.selectedProduct.scanInfo.tla, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 179, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 241);\r\n      window.pdf.text(window.selectedProduct.scanInfo.serial, 84, 241, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n      <button onclick=\"submitSerial()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'serial\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showTlaPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(11, 3, '6100 Generate Label (RMA)', 5, 5, 0, 0, '[]', 'Will generate a packing label for units that have been through the RMA process.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 10) {\r\n    window.Dialog.create({\r\n      title: \"TLA is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 10 digits.\",\r\n    });\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 9) {\r\n    window.Dialog.create({\r\n      title: \"Serial number is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 9 digits.\",\r\n    });\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  await printLabel();\r\n\r\n  showTlaPrompt();\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function printLabel() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.serial);\r\n      const tlaImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.tla);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(tlaImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'TLA: \', 10, 72);\r\n      window.pdf.text(window.selectedProduct.scanInfo.tla, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 179, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 241);\r\n      window.pdf.text(window.selectedProduct.scanInfo.serial, 84, 241, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n      <button onclick=\"submitSerial()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'serial\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showTlaPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
