(42, 4, 'Main Board Test', 4, 4, 1, 8, '{\"wideVault\":\"0\"}', 'This will test the main board after the boot firmware has been loaded in it. Please ensure the device vault has 5 or more forms loaded, the vault is attached, and a ribbon is loaded.', '', 1),
(43, 4, 'Read VCSEL', 4, 6, 0, 0, '[]', '<p>This will read the current configuration and serial number of the VCSEL.</p>', '', 1),
(44, 4, '101219-071 (Burster Home)', 4, 7, 0, 0, '[]', '<p>This will test the burster home sensor.</p>', '', 1),
(45, 4, 'Manual Set VCSEL', 4, 6, 0, 0, NULL, '<p>This will read the current configuration and serial number of the VCSEL and allow manual changing of the configuration.</p>', '', 1),
(46, 4, '108844-300E (VCSEL w/Potentiometer)', 4, 6, 0, 0, '[]', '<p>This will calibrate and serialize a VCSEL board that is equipped with potentiometers.</p>', 'let IDEAL_VOLTAGE = 1.65;\r\nlet MIN_COLLECTOR_VAL = 100;\r\nlet MAX_COLLECTOR_VAL = 127;\r\nlet MIN_TRANSMITTER_VAL = 110;\r\nlet MAX_TRANSMITTER_VAL = 127;', 1),
(47, 4, '108844-300E (VCSEL w/Rheostat)', 4, 6, 0, 0, '[]', '<p>This will calibrate and serialize a VCSEL board that is equipped with rheostats.</p>', 'let IDEAL_VOLTAGE = 1.65;\r\nlet MIN_COLLECTOR_VAL = 27;\r\nlet MAX_COLLECTOR_VAL = 0;\r\nlet MIN_TRANSMITTER_VAL = 110;\r\nlet MAX_TRANSMITTER_VAL = 127;', 1),
(48, 4, 'OGR (Serial)', 4, 4, 0, 0, '[]', 'This will perform an OGR test. Please ensure the device vault has 400 forms loaded, the vault is attached, and a ribbon is loaded.', '', 1),
(49, 4, '768000-001 (Final Test)', 4, 4, 1, 8, '{\"wideVault\":\"0\"}', 'This will perform the final test of the selected TLA.', '', 1),
(50, 4, '768000-001 (RMA Test)', 4, 4, 1, 8, '{\"wideVault\":\"0\"}', 'This will perform an RMA test of the selected TLA.', '', 1),
(51, 4, 'Palletize', 7, 3, 0, 0, '[]', '<p>This will track units that have been placed on pallet.</p>', '', 1),
(52, 4, '7680 Packing Label (w/QRM)', 5, 5, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function printLabel(labelValues) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', labelValues.primarySerialNum);\r\n      const vaultBarcodeImg = window.rescode.create(\'code39\', labelValues.secondarySerialNum);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.text(\'QRM\', 10, 10);\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 72);\r\n      window.pdf.text(labelValues.primarySerialNum, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.fontSize(18);\r\n      window.pdf.text(\'P/N:\', 10, 130);\r\n      window.pdf.text(\'768000-001A\' + \' (\' + labelValues.firmwareVersion + \')\', 84, 130, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(vaultBarcodeImg.buffer, 84, 179, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 241);\r\n      window.pdf.text(labelValues.secondarySerialNum, 84, 241, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitToServerForValidation() {\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0 });\r\n  const mainBarcode = document.getElementById(\"mainBarcode\").value;\r\n  const vaultBarcode = document.getElementById(\"vaultBarcode\").value;\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"printer7680\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          primarySerialNum: mainBarcode,\r\n          secondarySerialNum: vaultBarcode\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    await printLabel(response.data.labelValues);\r\n\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    showSerialPrompt();\r\n  } else {\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitBarcodes() {\r\n  const regExp = /^5785[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'vaultBarcode\');\r\n  const vaultBarcode = formElement.value;\r\n  if (!regExp.test(vaultBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Vault Barcode\",\r\n      message: \"The barcode scanned was not a valid vault barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    submitToServerForValidation();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function advanceToVault() {\r\n  const regExp = /^7680[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'mainBarcode\');\r\n  const mainBarcode = formElement.value;\r\n  if (!regExp.test(mainBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Main Barcode\",\r\n      message: \"The barcode scanned was not a valid main barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    document.getElementById(\'vaultBarcode\').focus();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Scan main barcode then vault barcode to generate label.</p>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"mainBarcode\">Main Barcode: </label><input type=\"text\" id=\"mainBarcode\" />\r\n      <button onclick=\"advanceToVault()\" style=\"opacity:0;\">Submit</button>\r\n    </form>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"vaultBarcode\">Vault Barcode: </label><input type=\"text\" id=\"vaultBarcode\" />\r\n      <button onclick=\"submitBarcodes()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'mainBarcode\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showSerialPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(53, 4, '7680 RMA Label (Main and Vault)', 5, 5, 0, 0, '[]', 'Will generate an RMA label for units that have been repaired.', 'async function printLabel(labelValues) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', labelValues.primarySerialNum);\r\n      const vaultBarcodeImg = window.rescode.create(\'code39\', labelValues.secondarySerialNum);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 72);\r\n      window.pdf.text(labelValues.primarySerialNum, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.fontSize(18);\r\n      window.pdf.text(\'P/N:\', 10, 130);\r\n      window.pdf.text(\'768000-001A RMA\' + \' (\' + labelValues.firmwareVersion + \')\', 84, 130, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(vaultBarcodeImg.buffer, 84, 179, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 241);\r\n      window.pdf.text(labelValues.secondarySerialNum, 84, 241, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitToServerForValidation() {\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0 });\r\n  const mainBarcode = document.getElementById(\"mainBarcode\").value;\r\n  const vaultBarcode = document.getElementById(\"vaultBarcode\").value;\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"printer7680\",\r\n        action: \"verifyPassRmaMainAndVaultAndNotPacked\",\r\n        params: {\r\n          primarySerialNum: mainBarcode,\r\n          secondarySerialNum: vaultBarcode\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    await printLabel(response.data.labelValues);\r\n\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    showSerialPrompt();\r\n  } else {\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitBarcodes() {\r\n  const regExp = /^5785[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'vaultBarcode\');\r\n  const vaultBarcode = formElement.value;\r\n  if (!regExp.test(vaultBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Vault Barcode\",\r\n      message: \"The barcode scanned was not a valid vault barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    submitToServerForValidation();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function advanceToVault() {\r\n  const regExp = /^7680[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'mainBarcode\');\r\n  const mainBarcode = formElement.value;\r\n  if (!regExp.test(mainBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Main Barcode\",\r\n      message: \"The barcode scanned was not a valid main barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    document.getElementById(\'vaultBarcode\').focus();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Scan main barcode then vault barcode to generate label.</p>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"mainBarcode\">Main Barcode: </label><input type=\"text\" id=\"mainBarcode\" />\r\n      <button onclick=\"advanceToVault()\" style=\"opacity:0;\">Submit</button>\r\n    </form>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"vaultBarcode\">Vault Barcode: </label><input type=\"text\" id=\"vaultBarcode\" />\r\n      <button onclick=\"submitBarcodes()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'mainBarcode\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showSerialPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(54, 4, '7680 RMA Label (Main Only)', 5, 5, 0, 0, '[]', 'Will generate an RMA label for units that have been repaired.', 'async function printLabel(labelValues) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', labelValues.primarySerialNum);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 72);\r\n      window.pdf.text(labelValues.primarySerialNum, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.fontSize(18);\r\n      window.pdf.text(\'P/N:\', 10, 130);\r\n      window.pdf.text(\'768000-001A RMA\' + \' (\' + labelValues.firmwareVersion + \')\', 84, 130, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitToServerForValidation() {\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0 });\r\n  const mainBarcode = document.getElementById(\"mainBarcode\").value;\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"printer7680\",\r\n        action: \"verifyPassRmaMainOnlyAndNotPacked\",\r\n        params: {\r\n          primarySerialNum: mainBarcode,\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    await printLabel(response.data.labelValues);\r\n\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    showSerialPrompt();\r\n  } else {\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitBarcodes() {\r\n  const regExp = /^7680[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'mainBarcode\');\r\n  const mainBarcode = formElement.value;\r\n  if (!regExp.test(mainBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Main Barcode\",\r\n      message: \"The barcode scanned was not a valid main barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    submitToServerForValidation();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Scan main barcode then vault barcode to generate label.</p>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"mainBarcode\">Main Barcode: </label><input type=\"text\" id=\"mainBarcode\" />\r\n      <button onclick=\"submitBarcodes()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'mainBarcode\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showSerialPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(55, 4, 'Do Not Double Stack Label', 5, 5, 0, 0, '[]', 'Will print label that says \"Do Not Double Stack\".', 'async function submitPrint() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const printCount = parseInt(document.getElementById(\"qty\").value);\r\n      if (printCount > 0) {\r\n        await generate4x5Landscape();\r\n\r\n        // Note: Measurements are in 72dpi\r\n        window.pdf.fontSize(72);\r\n        window.pdf.text(\'DO NOT\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'DOUBLE\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'STACK\', { width: 320, align: \'center\' });\r\n\r\n        window.pdf.end();\r\n\r\n        await performPrintWithQty(printCount);\r\n      } else {\r\n        window.Notify.create(\'Invalid quantity\');\r\n      }\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      window.Notify.create(\'Failed to print\');\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    document.getElementById(\'instructions\').innerHTML = `\r\n      <p>Please enter the quantity of labels to print.</p>\r\n      <form onsubmit=\"return false;\">\r\n        <label for=\"qty\">Quantity: </label><input type=\"text\" id=\"qty\" value=\"1\" />\r\n        <button onclick=\"submitPrint()\">Submit</button>\r\n      </form>\r\n    `;\r\n    document.getElementById(\'qty\').focus();\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(56, 1, 'Board Test', 4, 8, 1, 20, '{\"printerControlLanguage\":\"0\",\"carriageReturnUsage\":\"1\",\"softFaultRecovery\":\"0\",\"font\":\"0\",\"fontQuality\":\"0\",\"internationalCharacterSet\":\"0\",\"defaultToFontLarge\":\"0\",\"codePage\":\"0\",\"journalLinesPerInch\":\"1\",\"validationLinesPerInch\":\"16\",\"serialBaud\":\"6\",\"serialStopBits\":\"0\",\"serialParityType\":\"0\",\"serialParity\":\"1\",\"serialFlowControl\":\"1\",\"usbDriverClass\":\"0\",\"usbDescriptor\":\"2\",\"usbDeviceIdEnabled\":\"1\",\"mechanismType\":\"0\",\"hasFormTakenSensor\":\"0\",\"formInsertWaitTime\":\"1\",\"clampDelay\":\"0\",\"widePrintFieldEnabled\":\"1\",\"inkjetDotResetMode\":\"1\",\"virtualDocumentStop\":\"252\",\"a470ClampDefault\":\"0\",\"a470DefaultPitch\":\"2\"}', '<p>This will test a board that is populated with a cash drawer port.</p>', '', 1),
(57, 1, 'Board Test (No Cash Drawer)', 4, 8, 1, 20, '{\"printerControlLanguage\":\"0\",\"carriageReturnUsage\":\"1\",\"softFaultRecovery\":\"0\",\"font\":\"0\",\"fontQuality\":\"0\",\"internationalCharacterSet\":\"0\",\"defaultToFontLarge\":\"0\",\"codePage\":\"0\",\"journalLinesPerInch\":\"1\",\"validationLinesPerInch\":\"16\",\"serialBaud\":\"6\",\"serialStopBits\":\"0\",\"serialParityType\":\"0\",\"serialParity\":\"1\",\"serialFlowControl\":\"1\",\"usbDriverClass\":\"0\",\"usbDescriptor\":\"2\",\"usbDeviceIdEnabled\":\"1\",\"mechanismType\":\"0\",\"hasFormTakenSensor\":\"0\",\"formInsertWaitTime\":\"1\",\"clampDelay\":\"0\",\"widePrintFieldEnabled\":\"1\",\"inkjetDotResetMode\":\"1\",\"virtualDocumentStop\":\"252\",\"a470ClampDefault\":\"0\",\"a470DefaultPitch\":\"2\"}', '<p>This will test a board that is NOT populated with a cash drawer port.</p>', '', 1),
(58, 1, 'Read Current Config and Default USB', 4, 8, 0, 0, '[]', '<p>This will find the device on USB, print config, and reconfigure back to standard USB if needed.</p>', '', 1),
(59, 1, 'Final Test: 535100-001E', 4, 8, 1, 20, '{\"printerControlLanguage\":\"0\",\"carriageReturnUsage\":\"1\",\"softFaultRecovery\":\"0\",\"font\":\"0\",\"fontQuality\":\"0\",\"internationalCharacterSet\":\"0\",\"defaultToFontLarge\":\"0\",\"codePage\":\"0\",\"journalLinesPerInch\":\"1\",\"validationLinesPerInch\":\"16\",\"serialBaud\":\"6\",\"serialStopBits\":\"0\",\"serialParityType\":\"0\",\"serialParity\":\"1\",\"serialFlowControl\":\"1\",\"usbDriverClass\":\"0\",\"usbDescriptor\":\"2\",\"usbDeviceIdEnabled\":\"0\",\"mechanismType\":\"0\",\"hasFormTakenSensor\":\"1\",\"formInsertWaitTime\":\"0\",\"clampDelay\":\"2\",\"widePrintFieldEnabled\":\"0\",\"inkjetDotResetMode\":\"1\",\"virtualDocumentStop\":\"252\",\"a470ClampDefault\":\"0\",\"a470DefaultPitch\":\"2\",\"tla\":\"535100-001E\"}', 'This will perform the final test of the selected TLA.', '', 1);
INSERT INTO `prod_v2_test_sets` (`testSetId`, `extProductId`, `title`, `extTemplateId`, `extApiId`, `configureProduct`, `extFirmwareId`, `productConfig`, `description`, `script`, `active`) VALUES
(60, 1, '5300 Generate Label', 5, 5, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 11) {\r\n    window.Dialog.create({\r\n      title: \"TLA is invalid.\",\r\n      message: \"Number selected did not match the expected length of 11 characters.\",\r\n    });\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 8) {\r\n    window.Dialog.create({\r\n      title: \"Serial number is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 8 digits.\",\r\n    });\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"printer5300\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          serial: window.selectedProduct.scanInfo.serial,\r\n          tla: window.selectedProduct.scanInfo.tla\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    await printLabel();\r\n\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    showTlaPrompt();\r\n  } else {\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n    showTlaPrompt();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function printLabel() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.serial);\r\n      const tlaImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.tla);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(tlaImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'TLA: \', 10, 72);\r\n      window.pdf.text(window.selectedProduct.scanInfo.tla, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 179, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 241);\r\n      window.pdf.text(window.selectedProduct.scanInfo.serial, 84, 241, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  // Get TLAs\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"printer5300\",\r\n        action: \"getTLAs\",\r\n        params: {}\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  let tlaOptions = \'\';\r\n\r\n  if (response.data.success) {\r\n    response.data.tlas.forEach(tla => {\r\n      tlaOptions += `<option value=\"${tla.tlaNumber}\">${tla.tlaNumber}</option>`;\r\n    });\r\n  }\r\n\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please select the TLA that matches on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label>\r\n      <select id=\"tla\" style=\"padding:5px;\">\r\n        ${tlaOptions}\r\n      </select>\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n      <button onclick=\"submitSerial()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'serial\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showTlaPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(61, 1, '5300 Generate Label (RMA)', 5, 5, 0, 0, NULL, 'Will generate a packing label for units that have been through the RMA process.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 11) {\r\n    window.Dialog.create({\r\n      title: \"TLA is invalid.\",\r\n      message: \"Number selected did not match the expected length of 11 characters.\",\r\n    });\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 8) {\r\n    window.Dialog.create({\r\n      title: \"Serial number is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 8 digits.\",\r\n    });\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  await printLabel();\r\n\r\n  showTlaPrompt();\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function printLabel() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.serial);\r\n      const tlaImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.tla);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(tlaImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'TLA: \', 10, 72);\r\n      window.pdf.text(window.selectedProduct.scanInfo.tla, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 179, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 241);\r\n      window.pdf.text(window.selectedProduct.scanInfo.serial, 84, 241, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  // Get TLAs\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"printer5300\",\r\n        action: \"getTLAs\",\r\n        params: {}\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  let tlaOptions = \'\';\r\n\r\n  if (response.data.success) {\r\n    response.data.tlas.forEach(tla => {\r\n      tlaOptions += `<option value=\"${tla.tlaNumber}\">${tla.tlaNumber}</option>`;\r\n    });\r\n  }\r\n\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please select the TLA that matches on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label>\r\n      <select id=\"tla\" style=\"padding:5px;\">\r\n        ${tlaOptions}\r\n      </select>\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n      <button onclick=\"submitSerial()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'serial\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showTlaPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
