(52, '2022-10-12 20:09:10', 10, 3, '6100 Generate Label', 5, 2, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  }\r\n  });\r\n  console.log(window.selectedProduct);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    document.getElementById(\'instructions\').innerHTML = `\r\n      <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n      <form onsubmit=\"return false;\">\r\n        <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n        <button onclick=\"submitTLA()\">Submit</button>\r\n      </form>\r\n    `;\r\n    document.getElementById(\'tla\').focus();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(53, '2022-10-12 20:11:47', 10, 3, '6100 Generate Label', 5, 2, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    document.getElementById(\'instructions\').innerHTML = `\r\n      <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n      <form onsubmit=\"return false;\">\r\n        <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n        <button onclick=\"submitSerial()\">Submit</button>\r\n      </form>\r\n    `;\r\n    document.getElementById(\'serial\').focus();\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  }\r\n  });\r\n  console.log(window.selectedProduct);\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n  console.log(window.selectedProduct);\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    document.getElementById(\'instructions\').innerHTML = `\r\n      <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n      <form onsubmit=\"return false;\">\r\n        <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n        <button onclick=\"submitTLA()\">Submit</button>\r\n      </form>\r\n    `;\r\n    document.getElementById(\'tla\').focus();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(54, '2022-10-12 20:25:50', 10, 3, '6100 Generate Label', 5, 2, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 10) {\r\n    window.Dialog.alert(\"TLA number is invalid.\");\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 10) {\r\n    window.Dialog.alert(\"Serial number is invalid.\");\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"scanner6100\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          serial: window.selectedProduct.scanInfo.serial,\r\n          tla: window.selectedProduct.scanInfo.tla\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success) {\r\n    console.log(\'success\');\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n      <button onclick=\"submitSerial()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'serial\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showTlaPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(55, '2022-10-12 20:38:46', 10, 3, '6100 Generate Label', 5, 2, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 10) {\r\n    window.Dialog.create({\r\n      title: \"TLA is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 10 digits.\",\r\n    });\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 9) {\r\n    window.Dialog.create({\r\n      title: \"Serial number is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 9 digits.\",\r\n    });\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"scanner6100\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          serial: window.selectedProduct.scanInfo.serial,\r\n          tla: window.selectedProduct.scanInfo.tla\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success) {\r\n    console.log(\'success\');\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n      <button onclick=\"submitSerial()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'serial\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showTlaPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(56, '2022-10-12 21:34:12', 10, 3, '6100 Generate Label', 5, 2, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 10) {\r\n    window.Dialog.create({\r\n      title: \"TLA is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 10 digits.\",\r\n    });\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 9) {\r\n    window.Dialog.create({\r\n      title: \"Serial number is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 9 digits.\",\r\n    });\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"scanner6100\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          serial: window.selectedProduct.scanInfo.serial,\r\n          tla: window.selectedProduct.scanInfo.tla\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await printLabel();\r\n\r\n    showTlaPrompt();\r\n  } else {\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n    showTlaPrompt();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function printLabel() {\r\n  console.log(\'print\')\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n      <button onclick=\"submitSerial()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'serial\').focus();\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showTlaPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(57, '2022-10-12 21:38:05', 10, 3, '6100 Generate Label', 5, 2, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 10) {\r\n    window.Dialog.create({\r\n      title: \"TLA is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 10 digits.\",\r\n    });\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 9) {\r\n    window.Dialog.create({\r\n      title: \"Serial number is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 9 digits.\",\r\n    });\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"scanner6100\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          serial: window.selectedProduct.scanInfo.serial,\r\n          tla: window.selectedProduct.scanInfo.tla\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await printLabel();\r\n\r\n    showTlaPrompt();\r\n  } else {\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n    showTlaPrompt();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function printLabel() {\r\n  console.log(\'print\')\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n      <button onclick=\"submitSerial()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'serial\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showTlaPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(58, '2022-10-12 21:45:31', 10, 3, '6100 Generate Label', 5, 2, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 10) {\r\n    window.Dialog.create({\r\n      title: \"TLA is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 10 digits.\",\r\n    });\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 9) {\r\n    window.Dialog.create({\r\n      title: \"Serial number is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 9 digits.\",\r\n    });\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"scanner6100\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          serial: window.selectedProduct.scanInfo.serial,\r\n          tla: window.selectedProduct.scanInfo.tla\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await printLabel();\r\n\r\n    showTlaPrompt();\r\n  } else {\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n    showTlaPrompt();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function printLabel() {\r\n  return new Promise((resolve, reject) => {\r\n    try {\r\n      const filename = \'label.pdf\';\r\n      if (window.fs.existsSync(\'./\' + filename)) {\r\n        window.fs.unlinkSync(\'./\' + filename, (err) => {\r\n          if (err) {\r\n            console.error(err);\r\n            reject(err);\r\n          }\r\n        });\r\n\r\n        window.rescode.loadModules([\'code39\']);\r\n        const mainBarcodeImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.serial);\r\n        console.log(\'pass here\');\r\n      }\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n      <button onclick=\"submitSerial()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'serial\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showTlaPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
