ing\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    showTlaPrompt();\r\n  } else {\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n    showTlaPrompt();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function printLabel() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      deleteOldLabel();\r\n\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = await window.rescode.create(\'code39\', window.selectedProduct.scanInfo.serial);\r\n      const tlaImg = await window.rescode.create(\'code39\', window.selectedProduct.scanInfo.tla);\r\n\r\n      generate4x5Landscape();\r\n      console.log(\'pass 1\');\r\n\r\n      // Note: Measurements are in 72dpi\r\n      let tlaB;\r\n      tlaB.setHeader(\"Content-Type\", \"image/png\");\r\n      tlaB.end(tlaImg);\r\n      window.pdf.image(tlaB, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      console.log(\'pass 2\');\r\n\r\n\r\n      window.pdf.end();\r\n      console.log(\'pass 3\');\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the Serial Number barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"serial\">Serial Number: </label><input type=\"text\" id=\"serial\" />\r\n      <button onclick=\"submitSerial()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'serial\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showTlaPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
