INSERT INTO `prod_v2_test_sets_archive` (`archiveId`, `generatedDateTime`, `testSetId`, `extProductId`, `title`, `extTemplateId`, `extApiId`, `configureProduct`, `extFirmwareId`, `productConfig`, `description`, `script`, `active`) VALUES
(157, '2022-10-27 08:40:40', 55, 4, 'Do Not Double Stack Label', 5, 5, 0, 0, '[]', 'Will print label that says \"Do Not Double Stack\".', 'async function submitPrint() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const printCount = parseInt(document.getElementById(\"qty\").value);\r\n      if (printCount > 0) {\r\n        await generate4x5Landscape();\r\n\r\n        // Note: Measurements are in 72dpi\r\n        window.pdf.fontSize(72);\r\n        window.pdf.text(\'DO NOT\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'DOUBLE\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'STACK\', { width: 320, align: \'center\' });\r\n\r\n        window.pdf.end();\r\n\r\n        await performPrint();\r\n      } else {\r\n        window.Notify.create(\'Invalid quantity\');\r\n      }\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      window.Notify.create(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    document.getElementById(\'instructions\').innerHTML = `\r\n      <p>Please the quantity of labels to print.</p>\r\n      <form onsubmit=\"return false;\">\r\n        <label for=\"qty\">Quantity: </label><input type=\"text\" id=\"qty\" value=\"1\" />\r\n        <button onclick=\"submitPrint()\">Submit</button>\r\n      </form>\r\n    `;\r\n    document.getElementById(\'qty\').focus();\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(158, '2022-10-27 08:42:17', 55, 4, 'Do Not Double Stack Label', 5, 5, 0, 0, '[]', 'Will print label that says \"Do Not Double Stack\".', 'async function submitPrint() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const printCount = parseInt(document.getElementById(\"qty\").value);\r\n      if (printCount > 0) {\r\n        await generate4x5Landscape();\r\n\r\n        // Note: Measurements are in 72dpi\r\n        window.pdf.fontSize(72);\r\n        window.pdf.text(\'DO NOT\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'DOUBLE\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'STACK\', { width: 320, align: \'center\' });\r\n\r\n        window.pdf.end();\r\n\r\n        await performPrint();\r\n      } else {\r\n        window.Notify.create(\'Invalid quantity\');\r\n      }\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      window.Notify.create(\'Failed to print\');\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    document.getElementById(\'instructions\').innerHTML = `\r\n      <p>Please the quantity of labels to print.</p>\r\n      <form onsubmit=\"return false;\">\r\n        <label for=\"qty\">Quantity: </label><input type=\"text\" id=\"qty\" value=\"1\" />\r\n        <button onclick=\"submitPrint()\">Submit</button>\r\n      </form>\r\n    `;\r\n    document.getElementById(\'qty\').focus();\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(159, '2022-10-27 08:43:04', 55, 4, 'Do Not Double Stack Label', 5, 5, 0, 0, '[]', 'Will print label that says \"Do Not Double Stack\".', 'async function submitPrint() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const printCount = parseInt(document.getElementById(\"qty\").value);\r\n      if (printCount > 0) {\r\n        await generate4x5Landscape();\r\n\r\n        // Note: Measurements are in 72dpi\r\n        window.pdf.fontSize(72);\r\n        window.pdf.text(\'DO NOT\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'DOUBLE\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'STACK\', { width: 320, align: \'center\' });\r\n\r\n        window.pdf.end();\r\n\r\n        await performPrint();\r\n      } else {\r\n        window.Notify.create(\'Invalid quantity\');\r\n      }\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      window.Notify.create(\'Failed to print\');\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    document.getElementById(\'instructions\').innerHTML = `\r\n      <p>Please enter the quantity of labels to print.</p>\r\n      <form onsubmit=\"return false;\">\r\n        <label for=\"qty\">Quantity: </label><input type=\"text\" id=\"qty\" value=\"1\" />\r\n        <button onclick=\"submitPrint()\">Submit</button>\r\n      </form>\r\n    `;\r\n    document.getElementById(\'qty\').focus();\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(160, '2022-10-27 09:31:15', 55, 4, 'Do Not Double Stack Label', 5, 5, 0, 0, '[]', 'Will print label that says \"Do Not Double Stack\".', 'async function submitPrint() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const printCount = parseInt(document.getElementById(\"qty\").value);\r\n      if (printCount > 0) {\r\n        await generate4x5Landscape();\r\n\r\n        // Note: Measurements are in 72dpi\r\n        window.pdf.fontSize(72);\r\n        window.pdf.text(\'DO NOT\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'DOUBLE\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'STACK\', { width: 320, align: \'center\' });\r\n\r\n        window.pdf.end();\r\n\r\n        await performPrintWithQuantity(printCount);\r\n      } else {\r\n        window.Notify.create(\'Invalid quantity\');\r\n      }\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      window.Notify.create(\'Failed to print\');\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    document.getElementById(\'instructions\').innerHTML = `\r\n      <p>Please enter the quantity of labels to print.</p>\r\n      <form onsubmit=\"return false;\">\r\n        <label for=\"qty\">Quantity: </label><input type=\"text\" id=\"qty\" value=\"1\" />\r\n        <button onclick=\"submitPrint()\">Submit</button>\r\n      </form>\r\n    `;\r\n    document.getElementById(\'qty\').focus();\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(161, '2022-10-27 09:33:48', 55, 4, 'Do Not Double Stack Label', 5, 5, 0, 0, '[]', 'Will print label that says \"Do Not Double Stack\".', 'async function submitPrint() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      const printCount = parseInt(document.getElementById(\"qty\").value);\r\n      if (printCount > 0) {\r\n        await generate4x5Landscape();\r\n\r\n        // Note: Measurements are in 72dpi\r\n        window.pdf.fontSize(72);\r\n        window.pdf.text(\'DO NOT\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'DOUBLE\', { width: 320, align: \'center\' });\r\n        window.pdf.text(\'STACK\', { width: 320, align: \'center\' });\r\n\r\n        window.pdf.end();\r\n\r\n        await performPrintWithQty(printCount);\r\n      } else {\r\n        window.Notify.create(\'Invalid quantity\');\r\n      }\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      window.Notify.create(\'Failed to print\');\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    document.getElementById(\'instructions\').innerHTML = `\r\n      <p>Please enter the quantity of labels to print.</p>\r\n      <form onsubmit=\"return false;\">\r\n        <label for=\"qty\">Quantity: </label><input type=\"text\" id=\"qty\" value=\"1\" />\r\n        <button onclick=\"submitPrint()\">Submit</button>\r\n      </form>\r\n    `;\r\n    document.getElementById(\'qty\').focus();\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(162, '2022-10-27 09:56:50', 52, 4, '7680 Packing Label (w/QRM)', 5, 5, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', '/*async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 10) {\r\n    window.Dialog.create({\r\n      title: \"TLA is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 10 digits.\",\r\n    });\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 9) {\r\n    window.Dialog.create({\r\n      title: \"Serial number is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 9 digits.\",\r\n    });\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"scanner6100\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          serial: window.selectedProduct.scanInfo.serial,\r\n          tla: window.selectedProduct.scanInfo.tla\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    await printLabel();\r\n\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    showTlaPrompt();\r\n  } else {\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n    showTlaPrompt();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function printLabel() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.serial);\r\n      const tlaImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.tla);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(tlaImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'TLA: \', 10, 72);\r\n      window.pdf.text(window.selectedProduct.scanInfo.tla, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 179, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 241);\r\n      window.pdf.text(window.selectedProduct.scanInfo.serial, 84, 241, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}*/\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Scan main barcode then vault barcode to generate label.</p>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"mainBarcode\">Main Barcode: </label><input type=\"text\" id=\"mainBarcode\" />\r\n      <button onclick=\"advanceToVault()\" style=\"opacity:0;\">Submit</button>\r\n    </form>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"vaultBarcode\">Vault Barcode: </label><input type=\"text\" id=\"vaultBarcode\" />\r\n      <button onclick=\"submitBarcodes()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'mainBarcode\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showSerialPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(163, '2022-10-27 10:01:38', 52, 4, '7680 Packing Label (w/QRM)', 5, 5, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', '/*async function submitTLA() {\r\n  window.selectedProduct.scanInfo = [];\r\n  window.selectedProduct.scanInfo.tla = document.getElementById(\"tla\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.tla.length !== 10) {\r\n    window.Dialog.create({\r\n      title: \"TLA is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 10 digits.\",\r\n    });\r\n    showTlaPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0, oncomplete: () => {\r\n    showSerialPrompt();\r\n  }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitSerial() {\r\n  window.selectedProduct.scanInfo.serial = document.getElementById(\"serial\").value;\r\n\r\n  if (window.selectedProduct.scanInfo.serial.length !== 9) {\r\n    window.Dialog.create({\r\n      title: \"Serial number is invalid.\",\r\n      message: \"Number scanned did not match the expected length of 9 digits.\",\r\n    });\r\n    showSerialPrompt();\r\n    return;\r\n  }\r\n\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0});\r\n\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"scanner6100\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          serial: window.selectedProduct.scanInfo.serial,\r\n          tla: window.selectedProduct.scanInfo.tla\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    await printLabel();\r\n\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    showTlaPrompt();\r\n  } else {\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n    showTlaPrompt();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function printLabel() {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.serial);\r\n      const tlaImg = window.rescode.create(\'code39\', window.selectedProduct.scanInfo.tla);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(tlaImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'TLA: \', 10, 72);\r\n      window.pdf.text(window.selectedProduct.scanInfo.tla, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 179, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 241);\r\n      window.pdf.text(window.selectedProduct.scanInfo.serial, 84, 241, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}*/\r\n// ---------------------------------------------------------- //\r\nasync function advanceToVault() {\r\n  const regExp = /^7680[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'mainBarcode\');\r\n  const mainBarcode = formElement.value;\r\n  if (!regExp.test(mainBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid barcode\",\r\n      message: \"The barcode scanned was not a valid main barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    document.getElementById(\'vaultBarcode\').focus();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Scan main barcode then vault barcode to generate label.</p>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"mainBarcode\">Main Barcode: </label><input type=\"text\" id=\"mainBarcode\" />\r\n      <button onclick=\"advanceToVault()\" style=\"opacity:0;\">Submit</button>\r\n    </form>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"vaultBarcode\">Vault Barcode: </label><input type=\"text\" id=\"vaultBarcode\" />\r\n      <button onclick=\"submitBarcodes()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'mainBarcode\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showSerialPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
