     \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showTlaPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Please scan the TLA barcode on the bottom of the unit.</p>\r\n    <form onsubmit=\"return false;\">\r\n      <label for=\"tla\">TLA: </label><input type=\"text\" id=\"tla\" />\r\n      <button onclick=\"submitTLA()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'tla\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}*/\r\n// ---------------------------------------------------------- //\r\nasync function submitToServerForValidation() {\r\n  console.log(\'server\')\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitBarcodes() {\r\n  const regExp = /^5785[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'vaultBarcode\');\r\n  const vaultBarcode = formElement.value;\r\n  if (!regExp.test(vaultBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Vault Barcode\",\r\n      message: \"The barcode scanned was not a valid vault barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    submitToServerForValidation();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function advanceToVault() {\r\n  const regExp = /^7680[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'mainBarcode\');\r\n  const mainBarcode = formElement.value;\r\n  if (!regExp.test(mainBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Main Barcode\",\r\n      message: \"The barcode scanned was not a valid main barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    document.getElementById(\'vaultBarcode\').focus();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Scan main barcode then vault barcode to generate label.</p>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"mainBarcode\">Main Barcode: </label><input type=\"text\" id=\"mainBarcode\" />\r\n      <button onclick=\"advanceToVault()\" style=\"opacity:0;\">Submit</button>\r\n    </form>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"vaultBarcode\">Vault Barcode: </label><input type=\"text\" id=\"vaultBarcode\" />\r\n      <button onclick=\"submitBarcodes()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'mainBarcode\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showSerialPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(165, '2022-10-27 11:05:55', 52, 4, '7680 Packing Label (w/QRM)', 5, 5, 0, 0, '[]', 'Will generate a packing label for units fresh off the manufacturing line.', 'async function printLabel(labelValues) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', labelValues.primarySerialNum);\r\n      const vaultBarcodeImg = window.rescode.create(\'code39\', labelValues.secondarySerialNum);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.text(\'QRM\', 10, 10);\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 72);\r\n      window.pdf.text(labelValues.primarySerialNum, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.fontSize(18);\r\n      window.pdf.text(\'P/N:\', 10, 130);\r\n      window.pdf.text(\'768000-001A\' + \' (\' + labelValues.firmwareVersion + \')\', 84, 130, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(vaultBarcodeImg.buffer, 84, 179, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 241);\r\n      window.pdf.text(labelValues.secondarySerialNum, 84, 241, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitToServerForValidation() {\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0 });\r\n  const mainBarcode = document.getElementById(\"mainBarcode\").value;\r\n  const vaultBarcode = document.getElementById(\"vaultBarcode\").value;\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"printer7680\",\r\n        action: \"verifyPassProductionAndNotPacked\",\r\n        params: {\r\n          primarySerialNum: mainBarcode,\r\n          secondarySerialNum: vaultBarcode\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    await printLabel(response.data.labelValues);\r\n\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    showSerialPrompt();\r\n  } else {\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitBarcodes() {\r\n  const regExp = /^5785[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'vaultBarcode\');\r\n  const vaultBarcode = formElement.value;\r\n  if (!regExp.test(vaultBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Vault Barcode\",\r\n      message: \"The barcode scanned was not a valid vault barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    submitToServerForValidation();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function advanceToVault() {\r\n  const regExp = /^7680[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'mainBarcode\');\r\n  const mainBarcode = formElement.value;\r\n  if (!regExp.test(mainBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Main Barcode\",\r\n      message: \"The barcode scanned was not a valid main barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    document.getElementById(\'vaultBarcode\').focus();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Scan main barcode then vault barcode to generate label.</p>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"mainBarcode\">Main Barcode: </label><input type=\"text\" id=\"mainBarcode\" />\r\n      <button onclick=\"advanceToVault()\" style=\"opacity:0;\">Submit</button>\r\n    </form>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"vaultBarcode\">Vault Barcode: </label><input type=\"text\" id=\"vaultBarcode\" />\r\n      <button onclick=\"submitBarcodes()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'mainBarcode\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showSerialPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
(166, '2022-10-27 11:43:34', 53, 4, '7680 RMA Label (Main and Vault)', 5, 5, 0, 0, '[]', 'Will generate an RMA label for units that have been repaired.', 'async function printLabel(labelValues) {\r\n  return new Promise(async (resolve, reject) => {\r\n    try {\r\n      window.rescode.loadModules([\'code39\']);\r\n      const mainBarcodeImg = window.rescode.create(\'code39\', labelValues.primarySerialNum);\r\n      const vaultBarcodeImg = window.rescode.create(\'code39\', labelValues.secondarySerialNum);\r\n\r\n      await generate4x5Landscape();\r\n\r\n      // Note: Measurements are in 72dpi\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(mainBarcodeImg.buffer, 84, 10, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 72);\r\n      window.pdf.text(labelValues.primarySerialNum, 84, 72, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.fontSize(18);\r\n      window.pdf.text(\'P/N:\', 10, 130);\r\n      window.pdf.text(\'768000-001A RMA\' + \' (\' + labelValues.firmwareVersion + \')\', 84, 130, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.fontSize(25);\r\n      window.pdf.image(vaultBarcodeImg.buffer, 84, 179, { fit: [240, 40], align: \'center\', valign: \'center\' });\r\n      window.pdf.text(\'S/N: \', 10, 241);\r\n      window.pdf.text(labelValues.secondarySerialNum, 84, 241, { width: 240, align: \'center\' });\r\n\r\n      window.pdf.end();\r\n\r\n      await performPrint();\r\n      \r\n      resolve();\r\n    } catch (e) {\r\n      reject(e);\r\n    }\r\n  });\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitToServerForValidation() {\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 0 });\r\n  const mainBarcode = document.getElementById(\"mainBarcode\").value;\r\n  const vaultBarcode = document.getElementById(\"vaultBarcode\").value;\r\n  const response = await window.axios.post(window.selectedProduct.serverUrl,\r\n    {\r\n      query: {\r\n        dataset: \"printer7680\",\r\n        action: \"verifyPassRmaMainAndVaultAndNotPacked\",\r\n        params: {\r\n          primarySerialNum: mainBarcode,\r\n          secondarySerialNum: vaultBarcode\r\n        }\r\n      }\r\n    },\r\n    { headers: { \"Content-Type\": \"application/json\" }}\r\n  );\r\n\r\n  if (response.data.success && response.data.okToPack) {\r\n    await printLabel(response.data.labelValues);\r\n\r\n    // Inform server that item is packed\r\n    await window.axios.post(window.selectedProduct.serverUrl,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n    await window.axios.post(window.analyticsServer,\r\n      {\r\n        query: {\r\n          dataset: \"productionTracking\",\r\n          action: \"markPacked\",\r\n          params: {\r\n            productionId: response.data.productionId\r\n          }\r\n        }\r\n      },\r\n      { headers: { \"Content-Type\": \"application/json\" }}\r\n    );\r\n\r\n    showSerialPrompt();\r\n  } else {\r\n    window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n    window.Dialog.create({\r\n      title: \"Not Ready\",\r\n      message: \"Could not find any record of this unit being ready for packing.\",\r\n    });\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function submitBarcodes() {\r\n  const regExp = /^5785[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'vaultBarcode\');\r\n  const vaultBarcode = formElement.value;\r\n  if (!regExp.test(vaultBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Vault Barcode\",\r\n      message: \"The barcode scanned was not a valid vault barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    submitToServerForValidation();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function advanceToVault() {\r\n  const regExp = /^7680[0-9]{10}$/;\r\n  const formElement = document.getElementById(\'mainBarcode\');\r\n  const mainBarcode = formElement.value;\r\n  if (!regExp.test(mainBarcode)) {\r\n    window.Dialog.create({\r\n      title: \"Invalid Main Barcode\",\r\n      message: \"The barcode scanned was not a valid main barcode.\",\r\n    });\r\n    formElement.value = \'\';\r\n    formElement.focus();\r\n    return;\r\n  } else {\r\n    document.getElementById(\'vaultBarcode\').focus();\r\n  }\r\n}\r\n// ---------------------------------------------------------- //\r\nasync function showSerialPrompt() {\r\n  document.getElementById(\'instructions\').innerHTML = `\r\n    <p>Scan main barcode then vault barcode to generate label.</p>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"mainBarcode\">Main Barcode: </label><input type=\"text\" id=\"mainBarcode\" />\r\n      <button onclick=\"advanceToVault()\" style=\"opacity:0;\">Submit</button>\r\n    </form>\r\n    <form onsubmit=\"return false\" style=\"margin:5px 0;\">\r\n      <label for=\"vaultBarcode\">Vault Barcode: </label><input type=\"text\" id=\"vaultBarcode\" />\r\n      <button onclick=\"submitBarcodes()\">Submit</button>\r\n    </form>\r\n  `;\r\n  document.getElementById(\'mainBarcode\').focus();\r\n  window.gsap.to(\"#instructions\", { duration: 0.2, opacity: 1 });\r\n}\r\n// ---------------------------------------------------------- //\r\n(async () => {\r\n  try {\r\n    showSerialPrompt();\r\n  } catch (err) {\r\n    console.log(err);\r\n    window.Notify.create(err)\r\n  }\r\n})();', 1),
